import React, { useState, useEffect, useRef } from 'react';
import { supabase } from '../lib/supabase';

type Publisher = {
    id: number;
    nombre: string;
};

type Group = {
    id: number;
    nombre: string;
};

type GroupMember = {
    id: number;
    grupo_id: number;
    publicador_nombre: string;
};

type MinistryReport = {
    horas: number | '';
    notas?: string;
};

type ReportsMap = Record<string, MinistryReport>;
type VisitsMap = Record<string, string>;

// Helper for avatar colors
const getAvatarClass = (name: string) => {
    const classes = ['avatar-red', 'avatar-orange', 'avatar-amber', 'avatar-green', 'avatar-teal', 'avatar-blue', 'avatar-indigo', 'avatar-purple', 'avatar-pink'];
    let hash = 0;
    for (let i = 0; i < name.length; i++) {
        hash = name.charCodeAt(i) + ((hash << 5) - hash);
    }
    return classes[Math.abs(hash) % classes.length];
};

const GrupoCongregacion: React.FC = () => {
    // Data State
    const [groups, setGroups] = useState<Group[]>([]);
    const [selectedGroupId, setSelectedGroupId] = useState<number | null>(null);
    const [members, setMembers] = useState<GroupMember[]>([]);
    const [masterPublishers, setMasterPublishers] = useState<Publisher[]>([]); // All publishers from DB

    // UI State
    const [loading, setLoading] = useState(true);
    const [currentMonth, setCurrentMonth] = useState<string>('');
    const [reports, setReports] = useState<ReportsMap>({});
    const [visits, setVisits] = useState<VisitsMap>({});
    const [searchTerm, setSearchTerm] = useState('');
    const [addSearchTerm, setAddSearchTerm] = useState(''); // Search input for adding
    const [showSuggestions, setShowSuggestions] = useState(false);
    const [isCreatingGroup, setIsCreatingGroup] = useState(false);
    const [newGroupName, setNewGroupName] = useState('');
    const [statusMessage, setStatusMessage] = useState<{ text: string; type: 'success' | 'error' | 'info' } | null>(null);

    const suggestionsRef = useRef<HTMLDivElement>(null);

    // Initial Load
    useEffect(() => {
        const now = new Date();
        const yyyy = now.getFullYear();
        const mm = String(now.getMonth() + 1).padStart(2, '0');
        setCurrentMonth(`${yyyy}-${mm}`);

        fetchGroups();
        fetchMasterPublishers();

        // Close suggestions on click outside
        const handleClickOutside = (event: MouseEvent) => {
            if (suggestionsRef.current && !suggestionsRef.current.contains(event.target as Node)) {
                setShowSuggestions(false);
            }
        };
        document.addEventListener('mousedown', handleClickOutside);
        return () => document.removeEventListener('mousedown', handleClickOutside);
    }, []);

    // Load Data Functions
    const fetchGroups = async () => {
        const { data, error } = await supabase.from('grupos').select('*').order('nombre');
        if (error) {
            console.error("Error fetching groups:", error);
        } else if (data) {
            setGroups(data);
            if (data.length > 0 && !selectedGroupId) {
                // Try to find "Grupo 5" first, else default to first
                const defaultGroup = data.find(g => g.nombre.includes('5')) || data[0];
                setSelectedGroupId(defaultGroup.id);
            }
        }
    };

    const fetchMasterPublishers = async () => {
        const { data } = await supabase.from('publicadores').select('id, nombre').order('nombre');
        if (data) setMasterPublishers(data);
    };

    const fetchMembers = async () => {
        if (!selectedGroupId) return;
        setLoading(true);
        const { data, error } = await supabase
            .from('miembros_grupo')
            .select('*')
            .eq('grupo_id', selectedGroupId)
            .order('publicador_nombre');

        if (error) console.error("Error fetching members:", error);
        else setMembers(data || []);
        setLoading(false);
    };

    // Load Members when Group Changes
    useEffect(() => {
        fetchMembers();
    }, [selectedGroupId]);

    // Load Reports/Visits when Members or Month Change
    useEffect(() => {
        if (!currentMonth || members.length === 0) return;

        const fetchData = async () => {
            // Get reports only for current members
            const memberNames = members.map(m => m.publicador_nombre);

            const { data: reportsData } = await supabase
                .from('informes_ministerio')
                .select('publicador_nombre, horas')
                .eq('mes', currentMonth)
                .in('publicador_nombre', memberNames);

            const newReports: ReportsMap = {};
            if (reportsData) {
                reportsData.forEach((r: any) => {
                    newReports[r.publicador_nombre] = { horas: r.horas };
                });
            }
            setReports(newReports);

            const { data: visitsData } = await supabase
                .from('visitas_pastoral')
                .select('publicador_nombre, fecha_visita')
                .in('publicador_nombre', memberNames);

            const newVisits: VisitsMap = {};
            if (visitsData) {
                visitsData.forEach((v: any) => {
                    newVisits[v.publicador_nombre] = v.fecha_visita;
                });
            }
            setVisits(newVisits);
        };

        fetchData();
    }, [currentMonth, members]);

    // --- Actions ---

    const handleCreateGroup = async () => {
        if (!newGroupName.trim()) return;
        const normalizedName = newGroupName.trim();

        const { data, error } = await supabase.from('grupos').insert([{ nombre: normalizedName }]).select();

        if (error) {
            // Check for duplicate key error code (Postgres unique violation)
            if (error.code === '23505') {
                const { data: existingGroup } = await supabase
                    .from('grupos')
                    .select('*')
                    .eq('nombre', normalizedName)
                    .single();

                if (existingGroup) {
                    setGroups(prev => {
                        if (prev.some(g => g.id === existingGroup.id)) return prev;
                        return [...prev, existingGroup].sort((a,b) => a.nombre.localeCompare(b.nombre));
                    });
                    setSelectedGroupId(existingGroup.id);
                    setIsCreatingGroup(false);
                    setNewGroupName('');
                    setStatusMessage({ text: `El grupo "${normalizedName}" ya existe. Seleccionado.`, type: 'info' });
                    setTimeout(() => setStatusMessage(null), 3000);
                    return; 
                }
            }

            console.error("Error creating group:", error);
            setStatusMessage({ text: `Error: ${error.message}`, type: 'error' });
            setTimeout(() => setStatusMessage(null), 4000);
        } else if (data) {
            setGroups(prev => [...prev, data[0]].sort((a,b) => a.nombre.localeCompare(b.nombre)));
            setSelectedGroupId(data[0].id);
            setIsCreatingGroup(false);
            setNewGroupName('');
            setStatusMessage({ text: 'Grupo creado con éxito', type: 'success' });
            setTimeout(() => setStatusMessage(null), 3000);
        }
    };

    const handleDeleteGroup = async () => {
        if (!selectedGroupId) return;
        const groupName = groups.find(g => g.id === selectedGroupId)?.nombre;
        if (!window.confirm(`¿Estás seguro de eliminar el "${groupName}" y todos sus integrantes?`)) return;

        const { error } = await supabase.from('grupos').delete().eq('id', selectedGroupId);
        if (error) {
            console.error("Error deleting group:", error);
            setStatusMessage({ text: `Error al eliminar: ${error.message}`, type: 'error' });
        } else {
            const remaining = groups.filter(g => g.id !== selectedGroupId);
            setGroups(remaining);
            setSelectedGroupId(remaining.length > 0 ? remaining[0].id : null);
            setMembers([]);
            setStatusMessage({ text: 'Grupo eliminado', type: 'success' });
            setTimeout(() => setStatusMessage(null), 3000);
        }
    };

    const handleAddMember = async (name: string) => {
        if (!selectedGroupId || !name.trim()) return;

        // Check local duplicate
        if (members.some(m => m.publicador_nombre.toLowerCase() === name.toLowerCase())) {
            setStatusMessage({ text: 'Esta persona ya está en el grupo', type: 'error' });
            setTimeout(() => setStatusMessage(null), 3000);
            return;
        }

        const { error } = await supabase.from('miembros_grupo').insert([{
            grupo_id: selectedGroupId,
            publicador_nombre: name.trim()
        }]);

        if (error) {
            console.error(error);
            setStatusMessage({ text: `Error al agregar: ${error.message}`, type: 'error' });
        } else {
            setStatusMessage({ text: 'Agregado correctamente', type: 'success' });
            setAddSearchTerm('');
            fetchMembers();
        }
        setTimeout(() => setStatusMessage(null), 3000);
    };

    const handleDeleteMember = async (id: number, name: string) => {
        if (!window.confirm(`¿Quitar a ${name} de este grupo?`)) return;
        const { error } = await supabase.from('miembros_grupo').delete().eq('id', id);
        if (!error) fetchMembers();
        else console.error("Error deleting member:", error);
    };

    const handleReportChange = (name: string, value: string) => {
        setReports(prev => ({
            ...prev,
            [name]: { ...prev[name], horas: value === '' ? '' : Number(value) }
        }));
    };

    const handleVisitChange = (name: string, date: string) => {
        setVisits(prev => ({
            ...prev,
            [name]: date
        }));
    };

    const handleSaveRow = async (publisherName: string) => {
        setStatusMessage(null);
        try {
            const reportVal = reports[publisherName]?.horas;
            if (reportVal !== undefined && reportVal !== '') {
                const { error: reportError } = await supabase
                    .from('informes_ministerio')
                    .upsert({ 
                        publicador_nombre: publisherName, 
                        mes: currentMonth, 
                        horas: reportVal 
                    }, { onConflict: 'publicador_nombre, mes' });
                if (reportError) throw reportError;
            }

            const visitDate = visits[publisherName];
            if (visitDate) {
                const { error: visitError } = await supabase
                    .from('visitas_pastoral')
                    .upsert({ 
                        publicador_nombre: publisherName, 
                        fecha_visita: visitDate 
                    }, { onConflict: 'publicador_nombre' });
                if (visitError) throw visitError;
            }

            setStatusMessage({ text: 'Guardado', type: 'success' });
            setTimeout(() => setStatusMessage(null), 2000);
        } catch (err: any) {
            console.error(err);
            setStatusMessage({ text: 'Error al guardar', type: 'error' });
        }
    };

    // Filter Logic for Main Table
    const filteredMembers = members.filter(m => 
        m.publicador_nombre.toLowerCase().includes(searchTerm.toLowerCase())
    );

    // Filter Logic for Add Suggestions
    const filteredSuggestions = masterPublishers
        .filter(p => p.nombre.toLowerCase().includes(addSearchTerm.toLowerCase()))
        .filter(p => !members.some(m => m.publicador_nombre === p.nombre)) // Exclude already in group
        .slice(0, 6); // Limit results

    const currentGroupName = groups.find(g => g.id === selectedGroupId)?.nombre || 'Sin Grupo';

    return (
        <div className="container mx-auto px-4 py-8 group-container">

            {/* --- TOP BAR: Group Selector & Date --- */}
            <div style={{ display: 'flex', flexDirection: 'column', gap: '1.5rem', marginBottom: '2rem' }}>
                <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', flexWrap: 'wrap', gap: '1rem' }}>
                    <div style={{flex: 1}}>
                        {!isCreatingGroup ? (
                            <div style={{display: 'flex', alignItems: 'center', gap: '10px'}}>
                                <select 
                                    value={selectedGroupId || ''} 
                                    onChange={(e) => setSelectedGroupId(Number(e.target.value))}
                                    className="gc-header-title"
                                    style={{ background: 'transparent', border: 'none', cursor: 'pointer', paddingRight: '20px', outline: 'none' }}
                                >
                                    {groups.length === 0 && <option value="">Crear un grupo...</option>}
                                    {groups.map(g => <option key={g.id} value={g.id}>{g.nombre}</option>)}
                                </select>
                                <button onClick={() => setIsCreatingGroup(true)} style={{background: '#e0e7ff', color: '#4338ca', border: 'none', borderRadius: '50%', width: '32px', height: '32px', cursor: 'pointer', display: 'flex', alignItems: 'center', justifyContent: 'center'}} title="Crear nuevo grupo">
                                    <i className="fas fa-plus"></i>
                                </button>
                                {groups.length > 0 && (
                                    <button onClick={handleDeleteGroup} style={{background: '#fee2e2', color: '#dc2626', border: 'none', borderRadius: '50%', width: '32px', height: '32px', cursor: 'pointer', display: 'flex', alignItems: 'center', justifyContent: 'center', marginLeft: '5px'}} title="Eliminar este grupo">
                                        <i className="fas fa-trash-alt" style={{fontSize: '0.8rem'}}></i>
                                    </button>
                                )}
                            </div>
                        ) : (
                            <div style={{display: 'flex', gap: '10px', alignItems: 'center'}}>
                                <input 
                                    autoFocus
                                    type="text" 
                                    placeholder="Nombre del Grupo (ej. Grupo 1)" 
                                    value={newGroupName}
                                    onChange={(e) => setNewGroupName(e.target.value)}
                                    className="gc-input-add"
                                    style={{width: '250px'}}
                                />
                                <button onClick={handleCreateGroup} className="button" style={{backgroundColor: '#10b981', color: 'white'}}>Guardar</button>
                                <button onClick={() => setIsCreatingGroup(false)} className="button" style={{backgroundColor: '#6b7280', color: 'white'}}>Cancelar</button>
                            </div>
                        )}
                        <p style={{ color: '#6b7280', fontWeight: '500', display: 'flex', alignItems: 'center', gap: '0.5rem', marginTop: '0.5rem' }}>
                            <i className="fas fa-users" style={{ color: '#60a5fa' }}></i>
                            {members.length} Integrantes
                        </p>
                    </div>

                    <div style={{ display: 'flex', gap: '0.75rem', alignItems: 'center', backgroundColor: 'white', padding: '0.5rem', borderRadius: '0.75rem', border: '1px solid #e5e7eb', boxShadow: '0 1px 2px 0 rgba(0,0,0,0.05)' }}>
                        <div style={{ backgroundColor: '#f3f4f6', padding: '0.5rem 0.75rem', borderRadius: '0.5rem', color: '#6b7280' }}>
                            <i className="fas fa-calendar-alt"></i>
                        </div>
                        <input 
                            type="month" 
                            value={currentMonth} 
                            onChange={(e) => setCurrentMonth(e.target.value)}
                            style={{ border: 'none', background: 'transparent', fontWeight: '600', color: '#374151', outline: 'none', cursor: 'pointer' }}
                        />
                    </div>
                </div>
            </div>

            {/* --- ADD MEMBER SECTION (With Autocomplete & Manual Option) --- */}
            {selectedGroupId && (
                <div className="gc-card-add" style={{overflow: 'visible'}}>
                    <div className="gc-label-add">
                        <i className="fas fa-user-plus"></i>
                        Agregar Integrante al {currentGroupName}
                    </div>
                    <div style={{ display: 'flex', flexDirection: 'row', gap: '1rem', flexWrap: 'wrap', position: 'relative' }} ref={suggestionsRef}>
                        <div style={{ position: 'relative', flexGrow: 1 }}>
                            <i className="fas fa-search" style={{ position: 'absolute', left: '1rem', top: '50%', transform: 'translateY(-50%)', color: '#9ca3af', zIndex: 10 }}></i>
                            <input 
                                type="text" 
                                value={addSearchTerm}
                                onChange={(e) => {
                                    setAddSearchTerm(e.target.value);
                                    setShowSuggestions(true);
                                }}
                                onFocus={() => setShowSuggestions(true)}
                                onKeyDown={(e) => {
                                    if (e.key === 'Enter') {
                                        handleAddMember(addSearchTerm);
                                        setShowSuggestions(false);
                                    }
                                }}
                                placeholder="Buscar o escribir nombre nuevo..."
                                className="gc-input-add"
                                autoComplete="off"
                            />
                            {/* Autocomplete Dropdown */}
                            {showSuggestions && addSearchTerm && (
                                <div style={{
                                    position: 'absolute', top: '100%', left: 0, right: 0, 
                                    backgroundColor: 'white', border: '1px solid #e5e7eb', 
                                    borderRadius: '0.75rem', marginTop: '5px', zIndex: 50,
                                    boxShadow: '0 10px 15px -3px rgba(0, 0, 0, 0.1)',
                                    maxHeight: '300px', overflowY: 'auto'
                                }}>
                                    {/* Existing Publishers from DB */}
                                    {filteredSuggestions.map(p => (
                                        <div 
                                            key={p.id}
                                            onClick={() => {
                                                handleAddMember(p.nombre);
                                                setAddSearchTerm(''); 
                                                setShowSuggestions(false);
                                            }}
                                            style={{ padding: '10px 15px', cursor: 'pointer', borderBottom: '1px solid #f3f4f6', display: 'flex', alignItems: 'center', gap: '10px' }}
                                            onMouseEnter={(e) => e.currentTarget.style.backgroundColor = '#f9fafb'}
                                            onMouseLeave={(e) => e.currentTarget.style.backgroundColor = 'white'}
                                        >
                                            <div className={`modern-avatar ${getAvatarClass(p.nombre)}`} style={{width: '24px', height: '24px', fontSize: '0.7rem'}}>
                                                {p.nombre.charAt(0)}
                                            </div>
                                            <span style={{color: '#374151', fontWeight: '500'}}>{p.nombre}</span>
                                            <i className="fas fa-plus" style={{marginLeft: 'auto', color: '#10b981', fontSize: '0.8rem'}}></i>
                                        </div>
                                    ))}

                                    {/* Manual "Add as new" Option (Always visible if text is present) */}
                                    <div 
                                        onClick={() => {
                                            handleAddMember(addSearchTerm);
                                            setAddSearchTerm(''); 
                                            setShowSuggestions(false);
                                        }}
                                        style={{ padding: '10px 15px', cursor: 'pointer', backgroundColor: '#fdf4ff', borderTop: '1px solid #f3f4f6', display: 'flex', alignItems: 'center', gap: '10px' }}
                                        onMouseEnter={(e) => e.currentTarget.style.backgroundColor = '#fce7f3'}
                                        onMouseLeave={(e) => e.currentTarget.style.backgroundColor = '#fdf4ff'}
                                    >
                                        <div style={{width: '24px', height: '24px', display:'flex', alignItems:'center', justifyContent:'center', color: '#d946ef'}}>
                                            <i className="fas fa-pen"></i>
                                        </div>
                                        <div style={{display:'flex', flexDirection:'column'}}>
                                            <span style={{color: '#374151', fontWeight: '600'}}>Agregar "{addSearchTerm}"</span>
                                            <span style={{fontSize: '0.75rem', color: '#d946ef'}}>Nombre manual (no se añade a lista general)</span>
                                        </div>
                                    </div>
                                </div>
                            )}
                        </div>
                        <button 
                            onClick={() => handleAddMember(addSearchTerm)}
                            disabled={!addSearchTerm.trim()}
                            className="gc-btn-add"
                        >
                            <span>Agregar</span>
                            <i className="fas fa-arrow-right"></i>
                        </button>
                    </div>
                </div>
            )}

            {/* Status Toast */}
            {statusMessage && (
                <div style={{ 
                    position: 'fixed', bottom: '1.5rem', right: '1.5rem', zIndex: 100, padding: '1rem 1.5rem', borderRadius: '0.75rem', 
                    boxShadow: '0 10px 15px -3px rgba(0, 0, 0, 0.1)', fontWeight: '600', display: 'flex', alignItems: 'center', gap: '0.75rem',
                    backgroundColor: statusMessage.type === 'success' ? '#059669' : (statusMessage.type === 'info' ? '#3b82f6' : '#dc2626'), color: 'white'
                }}>
                    <i className={`fas ${statusMessage.type === 'success' ? 'fa-check-circle' : (statusMessage.type === 'info' ? 'fa-info-circle' : 'fa-exclamation-circle')}`}></i>
                    {statusMessage.text}
                </div>
            )}

            {/* List Table */}
            {loading ? (
                <div style={{ textAlign: 'center', padding: '5rem 0', color: '#9ca3af' }}>
                    <i className="fas fa-spinner fa-spin fa-3x" style={{ marginBottom: '1rem', color: '#93c5fd' }}></i>
                    <p style={{ fontWeight: '500' }}>Cargando datos...</p>
                </div>
            ) : (
                <div className="modern-card">
                    {/* Desktop Table Header */}
                    <div className="gc-table-header" style={{ display: 'none', gridTemplateColumns: 'repeat(12, minmax(0, 1fr))', borderBottom: '1px solid #e2e8f0', backgroundColor: '#f8fafc' }}>
                        <div style={{ gridColumn: 'span 4', paddingLeft: '1rem' }}>Publicador</div>
                        <div style={{ gridColumn: 'span 3', textAlign: 'center' }}>Horas ({currentMonth.split('-')[1]})</div>
                        <div style={{ gridColumn: 'span 3', textAlign: 'center' }}>Última Visita</div>
                        <div style={{ gridColumn: 'span 2', textAlign: 'center' }}>Acciones</div>
                    </div>
                    <style>{`@media (min-width: 768px) { .gc-table-header { display: grid !important; } }`}</style>

                    <div style={{ display: 'flex', flexDirection: 'column' }}>
                        {filteredMembers.map((m, index) => {
                            const pName = m.publicador_nombre;
                            const hasReport = reports[pName]?.horas !== undefined && reports[pName]?.horas !== '';
                            const visitDate = visits[pName] || '';

                            // Visual cue logic
                            let visitBadgeClass = 'status-badge neutral';
                            let visitLabel = 'Sin registrar';
                            if (visitDate) {
                                const daysSince = (new Date().getTime() - new Date(visitDate).getTime()) / (1000 * 3600 * 24);
                                if (daysSince < 90) { visitBadgeClass = 'status-badge success'; visitLabel = 'Reciente'; } 
                                else if (daysSince < 180) { visitBadgeClass = 'status-badge warning'; visitLabel = 'Atención'; } 
                                else { visitBadgeClass = 'status-badge danger'; visitLabel = 'Urgente'; }
                            }

                            return (
                                <div key={m.id} style={{ 
                                    display: 'grid', gridTemplateColumns: 'repeat(1, minmax(0, 1fr))', gap: '1rem', padding: '1.25rem', 
                                    borderBottom: '1px solid #f1f5f9', alignItems: 'center', transition: 'background-color 0.2s'
                                }}
                                onMouseEnter={(e) => e.currentTarget.style.backgroundColor = '#f8fafc'}
                                onMouseLeave={(e) => e.currentTarget.style.backgroundColor = 'transparent'}
                                className="md:grid-cols-12"
                                >
                                    <style>{`@media (min-width: 768px) { div[key="${m.id}"] { grid-template-columns: repeat(12, minmax(0, 1fr)) !important; } }`}</style>

                                    {/* Name */}
                                    <div style={{ gridColumn: 'span 1', display: 'flex', alignItems: 'center', gap: '1rem' }} className="md:col-span-4">
                                        <div style={{ color: '#9ca3af', fontWeight: '600', minWidth: '1.5rem', textAlign: 'center' }}>
                                            {index + 1}
                                        </div>
                                        <div style={{ fontWeight: '600', color: '#1f2937', fontSize: '1rem' }}>{pName}</div>
                                    </div>

                                    {/* Hours */}
                                    <div style={{ gridColumn: 'span 1', display: 'flex', justifyContent: 'space-between', alignItems: 'center', backgroundColor: '#f9fafb', padding: '0.75rem', borderRadius: '0.5rem' }} className="md:col-span-3 md:bg-transparent md:justify-center md:p-0">
                                        <span className="md:hidden" style={{ color: '#6b7280', fontSize: '0.875rem', fontWeight: '500' }}>Horas:</span>
                                        <div style={{ position: 'relative' }}>
                                            <input 
                                                type="number" min="0" step="0.5"
                                                value={reports[pName]?.horas ?? ''}
                                                onChange={(e) => handleReportChange(pName, e.target.value)}
                                                className={hasReport ? 'input-has-report' : ''}
                                                style={{ 
                                                    width: '6rem', padding: '0.5rem', textAlign: 'center', fontWeight: '700', borderRadius: '0.5rem', 
                                                    border: hasReport ? '2px solid #34d399' : '1px solid #e5e7eb', outline: 'none', transition: 'all 0.2s', color: '#4b5563'
                                                }}
                                                placeholder="-"
                                            />
                                        </div>
                                    </div>

                                    {/* Visit */}
                                    <div style={{ gridColumn: 'span 1', display: 'flex', justifyContent: 'space-between', alignItems: 'center', backgroundColor: '#f9fafb', padding: '0.75rem', borderRadius: '0.5rem' }} className="md:col-span-3 md:bg-transparent md:justify-center md:p-0">
                                        <span className="md:hidden" style={{ color: '#6b7280', fontSize: '0.875rem', fontWeight: '500' }}>Visita:</span>
                                        <div style={{ display: 'flex', flexDirection: 'column', alignItems: 'flex-end', gap: '0.25rem', width: '100%' }} className="md:w-auto md:items-center">
                                            <input 
                                                type="date" value={visitDate}
                                                onChange={(e) => handleVisitChange(pName, e.target.value)}
                                                className="modern-input"
                                                style={{ padding: '0.25rem 0.5rem', fontSize: '0.875rem', width: '100%', color: '#4b5563', fontWeight: '500', textAlign: 'right' }}
                                            />
                                            <span className={visitBadgeClass}>
                                                <i className="fas fa-circle" style={{ fontSize: '0.5rem' }}></i> {visitLabel}
                                            </span>
                                        </div>
                                    </div>

                                    {/* Actions */}
                                    <div style={{ gridColumn: 'span 1', display: 'flex', justifyContent: 'flex-end', gap: '0.75rem', marginTop: '0.5rem' }} className="md:col-span-2 md:justify-center md:mt-0">
                                        <button 
                                            onClick={() => handleSaveRow(pName)}
                                            style={{ background: 'linear-gradient(135deg, #4f46e5 0%, #4338ca 100%)', color: 'white', padding: '0.5rem 1rem', borderRadius: '0.5rem', border: 'none', cursor: 'pointer', display: 'flex', alignItems: 'center', gap: '0.5rem', fontSize: '0.875rem', fontWeight: '600', boxShadow: '0 4px 6px -1px rgba(79, 70, 229, 0.2)' }}
                                            title="Guardar cambios"
                                        >
                                            <i className="fas fa-save"></i> <span className="md:hidden">Guardar</span>
                                        </button>
                                        <button 
                                            onClick={() => handleDeleteMember(m.id, pName)}
                                            style={{ padding: '0.5rem', color: '#9ca3af', backgroundColor: 'transparent', border: '1px solid transparent', borderRadius: '0.5rem', cursor: 'pointer', transition: 'color 0.2s' }}
                                            onMouseEnter={(e) => { e.currentTarget.style.color = '#ef4444'; e.currentTarget.style.backgroundColor = '#fef2f2'; }}
                                            onMouseLeave={(e) => { e.currentTarget.style.color = '#9ca3af'; e.currentTarget.style.backgroundColor = 'transparent'; }}
                                            title="Quitar del grupo"
                                        >
                                            <i className="fas fa-trash-alt"></i>
                                        </button>
                                    </div>
                                </div>
                            );
                        })}
                    </div>
                    {filteredMembers.length === 0 && (
                        <div style={{ padding: '5rem 0', textAlign: 'center', backgroundColor: '#f8fafc' }}>
                            <div style={{ backgroundColor: 'white', width: '6rem', height: '6rem', borderRadius: '50%', display: 'flex', alignItems: 'center', justifyContent: 'center', margin: '0 auto 1.5rem auto', boxShadow: '0 1px 2px 0 rgba(0,0,0,0.05)', border: '1px solid #e2e8f0' }}>
                                <i className="fas fa-users fa-3x" style={{ color: '#c7d2fe' }}></i>
                            </div>
                            <h3 style={{ fontSize: '1.25rem', fontWeight: '700', color: '#374151' }}>
                                {selectedGroupId ? 'Este grupo está vacío' : 'Crea o selecciona un grupo'}
                            </h3>
                            <p style={{ color: '#6b7280', marginTop: '0.5rem', maxWidth: '24rem', marginInline: 'auto' }}>
                                Utiliza el buscador de arriba para agregar publicadores existentes a este grupo.
                            </p>
                        </div>
                    )}
                </div>
            )}
        </div>
    );
};

export default GrupoCongregacion;

import React, { useState, useEffect, useRef } from 'react';
import { supabase } from '../lib/supabase';

type Publisher = {
    id: number;
    nombre: string;
};

type Group = {
    id: number;
    nombre: string;
};

type GroupMember = {
    id: number;
    grupo_id: number;
    publicador_nombre: string;
};

type MinistryReport = {
    horas: number | '';
    notas?: string;
};

type ReportsMap = Record<string, MinistryReport>;
type VisitsMap = Record<string, string>;

// Helper for avatar colors
const getAvatarClass = (name: string) => {
    const classes = ['avatar-red', 'avatar-orange', 'avatar-amber', 'avatar-green', 'avatar-teal', 'avatar-blue', 'avatar-indigo', 'avatar-purple', 'avatar-pink'];
    let hash = 0;
    for (let i = 0; i < name.length; i++) {
        hash = name.charCodeAt(i) + ((hash << 5) - hash);
    }
    return classes[Math.abs(hash) % classes.length];
};

const GrupoCongregacion: React.FC = () => {
    // Data State
    const [groups, setGroups] = useState<Group[]>([]);
    const [selectedGroupId, setSelectedGroupId] = useState<number | null>(null);
    const [members, setMembers] = useState<GroupMember[]>([]);
    const [masterPublishers, setMasterPublishers] = useState<Publisher[]>([]); // All publishers from DB

    // UI State
    const [loading, setLoading] = useState(true);
    const [currentMonth, setCurrentMonth] = useState<string>('');
    const [reports, setReports] = useState<ReportsMap>({});
    const [visits, setVisits] = useState<VisitsMap>({});
    const [searchTerm, setSearchTerm] = useState('');
    const [addSearchTerm, setAddSearchTerm] = useState(''); // Search input for adding
    const [showSuggestions, setShowSuggestions] = useState(false);
    const [isCreatingGroup, setIsCreatingGroup] = useState(false);
    const [newGroupName, setNewGroupName] = useState('');
    const [statusMessage, setStatusMessage] = useState<{ text: string; type: 'success' | 'error' | 'info' } | null>(null);

    const suggestionsRef = useRef<HTMLDivElement>(null);

    // Initial Load
    useEffect(() => {
        const now = new Date();
        const yyyy = now.getFullYear();
        const mm = String(now.getMonth() + 1).padStart(2, '0');
        setCurrentMonth(`${yyyy}-${mm}`);

        fetchGroups();
        fetchMasterPublishers();

        // Close suggestions on click outside
        const handleClickOutside = (event: MouseEvent) => {
            if (suggestionsRef.current && !suggestionsRef.current.contains(event.target as Node)) {
                setShowSuggestions(false);
            }
        };
        document.addEventListener('mousedown', handleClickOutside);
        return () => document.removeEventListener('mousedown', handleClickOutside);
    }, []);

    // Load Data Functions
    const fetchGroups = async () => {
        const { data, error } = await supabase.from('grupos').select('*').order('nombre');
        if (error) {
            console.error("Error fetching groups:", error);
        } else if (data) {
            setGroups(data);
            if (data.length > 0 && !selectedGroupId) {
                // Try to find "Grupo 5" first, else default to first
                const defaultGroup = data.find(g => g.nombre.includes('5')) || data[0];
                setSelectedGroupId(defaultGroup.id);
            }
        }
    };

    const fetchMasterPublishers = async () => {
        const { data } = await supabase.from('publicadores').select('id, nombre').order('nombre');
        if (data) setMasterPublishers(data);
    };

    const fetchMembers = async () => {
        if (!selectedGroupId) return;
        setLoading(true);
        const { data, error } = await supabase
            .from('miembros_grupo')
            .select('*')
            .eq('grupo_id', selectedGroupId)
            .order('publicador_nombre');

        if (error) console.error("Error fetching members:", error);
        else setMembers(data || []);
        setLoading(false);
    };

    // Load Members when Group Changes
    useEffect(() => {
        fetchMembers();
    }, [selectedGroupId]);

    // Load Reports/Visits when Members or Month Change
    useEffect(() => {
        if (!currentMonth || members.length === 0) return;

        const fetchData = async () => {
            // Get reports only for current members
            const memberNames = members.map(m => m.publicador_nombre);

            const { data: reportsData } = await supabase
                .from('informes_ministerio')
                .select('publicador_nombre, horas')
                .eq('mes', currentMonth)
                .in('publicador_nombre', memberNames);

            const newReports: ReportsMap = {};
            if (reportsData) {
                reportsData.forEach((r: any) => {
                    newReports[r.publicador_nombre] = { horas: r.horas };
                });
            }
            setReports(newReports);

            const { data: visitsData } = await supabase
                .from('visitas_pastoral')
                .select('publicador_nombre, fecha_visita')
                .in('publicador_nombre', memberNames);

            const newVisits: VisitsMap = {};
            if (visitsData) {
                visitsData.forEach((v: any) => {
                    newVisits[v.publicador_nombre] = v.fecha_visita;
                });
            }
            setVisits(newVisits);
        };

        fetchData();
    }, [currentMonth, members]);

    // --- Actions ---

    const handleCreateGroup = async () => {
        if (!newGroupName.trim()) return;
        const normalizedName = newGroupName.trim();

        const { data, error } = await supabase.from('grupos').insert([{ nombre: normalizedName }]).select();

        if (error) {
            // Check for duplicate key error code (Postgres unique violation)
            if (error.code === '23505') {
                const { data: existingGroup } = await supabase
                    .from('grupos')
                    .select('*')
                    .eq('nombre', normalizedName)
                    .single();

                if (existingGroup) {
                    setGroups(prev => {
                        if (prev.some(g => g.id === existingGroup.id)) return prev;
                        return [...prev, existingGroup].sort((a,b) => a.nombre.localeCompare(b.nombre));
                    });
                    setSelectedGroupId(existingGroup.id);
                    setIsCreatingGroup(false);
                    setNewGroupName('');
                    setStatusMessage({ text: `El grupo "${normalizedName}" ya existe. Seleccionado.`, type: 'info' });
                    setTimeout(() => setStatusMessage(null), 3000);
                    return; 
                }
            }

            console.error("Error creating group:", error);
            setStatusMessage({ text: `Error: ${error.message}`, type: 'error' });
            setTimeout(() => setStatusMessage(null), 4000);
        } else if (data) {
            setGroups(prev => [...prev, data[0]].sort((a,b) => a.nombre.localeCompare(b.nombre)));
            setSelectedGroupId(data[0].id);
            setIsCreatingGroup(false);
            setNewGroupName('');
            setStatusMessage({ text: 'Grupo creado con éxito', type: 'success' });
            setTimeout(() => setStatusMessage(null), 3000);
        }
    };

    const handleDeleteGroup = async () => {
        if (!selectedGroupId) return;
        const groupName = groups.find(g => g.id === selectedGroupId)?.nombre;
        if (!window.confirm(`¿Estás seguro de eliminar el "${groupName}" y todos sus integrantes?`)) return;

        const { error } = await supabase.from('grupos').delete().eq('id', selectedGroupId);
        if (error) {
            console.error("Error deleting group:", error);
            setStatusMessage({ text: `Error al eliminar: ${error.message}`, type: 'error' });
        } else {
            const remaining = groups.filter(g => g.id !== selectedGroupId);
            setGroups(remaining);
            setSelectedGroupId(remaining.length > 0 ? remaining[0].id : null);
            setMembers([]);
            setStatusMessage({ text: 'Grupo eliminado', type: 'success' });
            setTimeout(() => setStatusMessage(null), 3000);
        }
    };

    const handleAddMember = async (name: string) => {
        if (!selectedGroupId || !name.trim()) return;

        // Check local duplicate
        if (members.some(m => m.publicador_nombre.toLowerCase() === name.toLowerCase())) {
            setStatusMessage({ text: 'Esta persona ya está en el grupo', type: 'error' });
            setTimeout(() => setStatusMessage(null), 3000);
            return;
        }

        const { error } = await supabase.from('miembros_grupo').insert([{
            grupo_id: selectedGroupId,
            publicador_nombre: name.trim()
        }]);

        if (error) {
            console.error(error);
            setStatusMessage({ text: `Error al agregar: ${error.message}`, type: 'error' });
        } else {
            setStatusMessage({ text: 'Agregado correctamente', type: 'success' });
            setAddSearchTerm('');
            fetchMembers();
        }
        setTimeout(() => setStatusMessage(null), 3000);
    };

    const handleDeleteMember = async (id: number, name: string) => {
        if (!window.confirm(`¿Quitar a ${name} de este grupo?`)) return;
        const { error } = await supabase.from('miembros_grupo').delete().eq('id', id);
        if (!error) fetchMembers();
        else console.error("Error deleting member:", error);
    };

    const handleReportChange = (name: string, value: string) => {
        setReports(prev => ({
            ...prev,
            [name]: { ...prev[name], horas: value === '' ? '' : Number(value) }
        }));
    };

    const handleVisitChange = (name: string, date: string) => {
        setVisits(prev => ({
            ...prev,
            [name]: date
        }));
    };

    const handleSaveRow = async (publisherName: string) => {
        setStatusMessage(null);
        try {
            // --- Save Report Logic ---
            const reportEntry = reports[publisherName];

            if (reportEntry) {
                // If checkbox is active (exists in state), upsert report
                const valToSave = reportEntry.horas === '' ? 0 : reportEntry.horas;

                const { error: reportError } = await supabase
                    .from('informes_ministerio')
                    .upsert({ 
                        publicador_nombre: publisherName, 
                        mes: currentMonth, 
                        horas: valToSave 
                    }, { onConflict: 'publicador_nombre, mes' });
                if (reportError) throw reportError;
            } else {
                // If unchecked (removed from state), delete report from DB
                const { error: deleteError } = await supabase
                    .from('informes_ministerio')
                    .delete()
                    .eq('publicador_nombre', publisherName)
                    .eq('mes', currentMonth);

                // We ignore if it didn't exist, but supabase delete won't error on 0 rows
                if (deleteError) throw deleteError;
            }

            // --- Save Visit Logic ---
            const visitDate = visits[publisherName];
            if (visitDate) {
                const { error: visitError } = await supabase
                    .from('visitas_pastoral')
                    .upsert({ 
                        publicador_nombre: publisherName, 
                        fecha_visita: visitDate 
                    }, { onConflict: 'publicador_nombre' });
                if (visitError) throw visitError;
            }

            setStatusMessage({ text: 'Guardado', type: 'success' });
            setTimeout(() => setStatusMessage(null), 2000);
        } catch (err: any) {
            console.error(err);
            setStatusMessage({ text: 'Error al guardar', type: 'error' });
        }
    };

    // Filter Logic for Main Table
    const filteredMembers = members.filter(m => 
        m.publicador_nombre.toLowerCase().includes(searchTerm.toLowerCase())
    );

    // Filter Logic for Add Suggestions
    const filteredSuggestions = masterPublishers
        .filter(p => p.nombre.toLowerCase().includes(addSearchTerm.toLowerCase()))
        .filter(p => !members.some(m => m.publicador_nombre === p.nombre)) // Exclude already in group
        .slice(0, 6); // Limit results

    const currentGroupName = groups.find(g => g.id === selectedGroupId)?.nombre || 'Sin Grupo';

    return (
        <div className="container mx-auto px-4 py-8 group-container">

            {/* --- TOP BAR: Group Selector & Date --- */}
            <div style={{ display: 'flex', flexDirection: 'column', gap: '1.5rem', marginBottom: '2rem' }}>
                <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', flexWrap: 'wrap', gap: '1rem' }}>
                    <div style={{flex: 1}}>
                        {!isCreatingGroup ? (
                            <div style={{display: 'flex', alignItems: 'center', gap: '10px'}}>
                                <select 
                                    value={selectedGroupId || ''} 
                                    onChange={(e) => setSelectedGroupId(Number(e.target.value))}
                                    className="gc-header-title"
                                    style={{ background: 'transparent', border: 'none', cursor: 'pointer', paddingRight: '20px', outline: 'none' }}
                                >
                                    {groups.length === 0 && <option value="">Crear un grupo...</option>}
                                    {groups.map(g => <option key={g.id} value={g.id}>{g.nombre}</option>)}
                                </select>
                                <button onClick={() => setIsCreatingGroup(true)} style={{background: '#e0e7ff', color: '#4338ca', border: 'none', borderRadius: '50%', width: '32px', height: '32px', cursor: 'pointer', display: 'flex', alignItems: 'center', justifyContent: 'center'}} title="Crear nuevo grupo">
                                    <i className="fas fa-plus"></i>
                                </button>
                                {groups.length > 0 && (
                                    <button onClick={handleDeleteGroup} style={{background: '#fee2e2', color: '#dc2626', border: 'none', borderRadius: '50%', width: '32px', height: '32px', cursor: 'pointer', display: 'flex', alignItems: 'center', justifyContent: 'center', marginLeft: '5px'}} title="Eliminar este grupo">
                                        <i className="fas fa-trash-alt" style={{fontSize: '0.8rem'}}></i>
                                    </button>
                                )}
                            </div>
                        ) : (
                            <div style={{display: 'flex', gap: '10px', alignItems: 'center'}}>
                                <input 
                                    autoFocus
                                    type="text" 
                                    placeholder="Nombre del Grupo (ej. Grupo 1)" 
                                    value={newGroupName}
                                    onChange={(e) => setNewGroupName(e.target.value)}
                                    className="gc-input-add"
                                    style={{width: '250px'}}
                                />
                                <button onClick={handleCreateGroup} className="button" style={{backgroundColor: '#10b981', color: 'white'}}>Guardar</button>
                                <button onClick={() => setIsCreatingGroup(false)} className="button" style={{backgroundColor: '#6b7280', color: 'white'}}>Cancelar</button>
                            </div>
                        )}
                        <p style={{ color: '#6b7280', fontWeight: '500', display: 'flex', alignItems: 'center', gap: '0.5rem', marginTop: '0.5rem' }}>
                            <i className="fas fa-users" style={{ color: '#60a5fa' }}></i>
                            {members.length} Integrantes
                        </p>
                    </div>

                    <div style={{ display: 'flex', gap: '0.75rem', alignItems: 'center', backgroundColor: 'white', padding: '0.5rem', borderRadius: '0.75rem', border: '1px solid #e5e7eb', boxShadow: '0 1px 2px 0 rgba(0,0,0,0.05)' }}>
                        <div style={{ backgroundColor: '#f3f4f6', padding: '0.5rem 0.75rem', borderRadius: '0.5rem', color: '#6b7280' }}>
                            <i className="fas fa-calendar-alt"></i>
                        </div>
                        <input 
                            type="month" 
                            value={currentMonth} 
                            onChange={(e) => setCurrentMonth(e.target.value)}
                            style={{ border: 'none', background: 'transparent', fontWeight: '600', color: '#374151', outline: 'none', cursor: 'pointer' }}
                        />
                    </div>
                </div>
            </div>

            {/* --- ADD MEMBER SECTION (With Autocomplete & Manual Option) --- */}
            {selectedGroupId && (
                <div className="gc-card-add" style={{overflow: 'visible'}}>
                    <div className="gc-label-add">
                        <i className="fas fa-user-plus"></i>
                        Agregar Integrante al {currentGroupName}
                    </div>
                    <div style={{ display: 'flex', flexDirection: 'row', gap: '1rem', flexWrap: 'wrap', position: 'relative' }} ref={suggestionsRef}>
                        <div style={{ position: 'relative', flexGrow: 1 }}>
                            <i className="fas fa-search" style={{ position: 'absolute', left: '1rem', top: '50%', transform: 'translateY(-50%)', color: '#9ca3af', zIndex: 10 }}></i>
                            <input 
                                type="text" 
                                value={addSearchTerm}
                                onChange={(e) => {
                                    setAddSearchTerm(e.target.value);
                                    setShowSuggestions(true);
                                }}
                                onFocus={() => setShowSuggestions(true)}
                                onKeyDown={(e) => {
                                    if (e.key === 'Enter') {
                                        handleAddMember(addSearchTerm);
                                        setShowSuggestions(false);
                                    }
                                }}
                                placeholder="Buscar o escribir nombre nuevo..."
                                className="gc-input-add"
                                autoComplete="off"
                            />
                            {/* Autocomplete Dropdown */}
                            {showSuggestions && addSearchTerm && (
                                <div style={{
                                    position: 'absolute', top: '100%', left: 0, right: 0, 
                                    backgroundColor: 'white', border: '1px solid #e5e7eb', 
                                    borderRadius: '0.75rem', marginTop: '5px', zIndex: 50,
                                    boxShadow: '0 10px 15px -3px rgba(0, 0, 0, 0.1)',
                                    maxHeight: '300px', overflowY: 'auto'
                                }}>
                                    {/* Existing Publishers from DB */}
                                    {filteredSuggestions.map(p => (
                                        <div 
                                            key={p.id}
                                            onClick={() => {
                                                handleAddMember(p.nombre);
                                                setAddSearchTerm(''); 
                                                setShowSuggestions(false);
                                            }}
                                            style={{ padding: '10px 15px', cursor: 'pointer', borderBottom: '1px solid #f3f4f6', display: 'flex', alignItems: 'center', gap: '10px' }}
                                            onMouseEnter={(e) => e.currentTarget.style.backgroundColor = '#f9fafb'}
                                            onMouseLeave={(e) => e.currentTarget.style.backgroundColor = 'white'}
                                        >
                                            <div className={`modern-avatar ${getAvatarClass(p.nombre)}`} style={{width: '24px', height: '24px', fontSize: '0.7rem'}}>
                                                {p.nombre.charAt(0)}
                                            </div>
                                            <span style={{color: '#374151', fontWeight: '500'}}>{p.nombre}</span>
                                            <i className="fas fa-plus" style={{marginLeft: 'auto', color: '#10b981', fontSize: '0.8rem'}}></i>
                                        </div>
                                    ))}

                                    {/* Manual "Add as new" Option (Always visible if text is present) */}
                                    <div 
                                        onClick={() => {
                                            handleAddMember(addSearchTerm);
                                            setAddSearchTerm(''); 
                                            setShowSuggestions(false);
                                        }}
                                        style={{ padding: '10px 15px', cursor: 'pointer', backgroundColor: '#fdf4ff', borderTop: '1px solid #f3f4f6', display: 'flex', alignItems: 'center', gap: '10px' }}
                                        onMouseEnter={(e) => e.currentTarget.style.backgroundColor = '#fce7f3'}
                                        onMouseLeave={(e) => e.currentTarget.style.backgroundColor = '#fdf4ff'}
                                    >
                                        <div style={{width: '24px', height: '24px', display:'flex', alignItems:'center', justifyContent:'center', color: '#d946ef'}}>
                                            <i className="fas fa-pen"></i>
                                        </div>
                                        <div style={{display:'flex', flexDirection:'column'}}>
                                            <span style={{color: '#374151', fontWeight: '600'}}>Agregar "{addSearchTerm}"</span>
                                            <span style={{fontSize: '0.75rem', color: '#d946ef'}}>Nombre manual (no se añade a lista general)</span>
                                        </div>
                                    </div>
                                </div>
                            )}
                        </div>
                        <button 
                            onClick={() => handleAddMember(addSearchTerm)}
                            disabled={!addSearchTerm.trim()}
                            className="gc-btn-add"
                        >
                            <span>Agregar</span>
                            <i className="fas fa-arrow-right"></i>
                        </button>
                    </div>
                </div>
            )}

            {/* Status Toast */}
            {statusMessage && (
                <div style={{ 
                    position: 'fixed', bottom: '1.5rem', right: '1.5rem', zIndex: 100, padding: '1rem 1.5rem', borderRadius: '0.75rem', 
                    boxShadow: '0 10px 15px -3px rgba(0, 0, 0, 0.1)', fontWeight: '600', display: 'flex', alignItems: 'center', gap: '0.75rem',
                    backgroundColor: statusMessage.type === 'success' ? '#059669' : (statusMessage.type === 'info' ? '#3b82f6' : '#dc2626'), color: 'white'
                }}>
                    <i className={`fas ${statusMessage.type === 'success' ? 'fa-check-circle' : (statusMessage.type === 'info' ? 'fa-info-circle' : 'fa-exclamation-circle')}`}></i>
                    {statusMessage.text}
                </div>
            )}

            {/* List Table */}
            {loading ? (
                <div style={{ textAlign: 'center', padding: '5rem 0', color: '#9ca3af' }}>
                    <i className="fas fa-spinner fa-spin fa-3x" style={{ marginBottom: '1rem', color: '#93c5fd' }}></i>
                    <p style={{ fontWeight: '500' }}>Cargando datos...</p>
                </div>
            ) : (
                <div className="modern-card">
                    {/* Desktop Table Header */}
                    <div className="gc-table-header" style={{ display: 'none', gridTemplateColumns: 'repeat(12, minmax(0, 1fr))', borderBottom: '1px solid #e2e8f0', backgroundColor: '#f8fafc' }}>
                        <div style={{ gridColumn: 'span 4', paddingLeft: '1rem' }}>Publicador</div>
                        <div style={{ gridColumn: 'span 3', textAlign: 'center' }}>Horas ({currentMonth.split('-')[1]})</div>
                        <div style={{ gridColumn: 'span 3', textAlign: 'center' }}>Última Visita</div>
                        <div style={{ gridColumn: 'span 2', textAlign: 'center' }}>Acciones</div>
                    </div>
                    <style>{`@media (min-width: 768px) { .gc-table-header { display: grid !important; } }`}</style>

                    <div style={{ display: 'flex', flexDirection: 'column' }}>
                        {filteredMembers.map((m, index) => {
                            const pName = m.publicador_nombre;
                            const hasReport = reports[pName] !== undefined; // If key exists, it is checked
                            const visitDate = visits[pName] || '';

                            // Visual cue logic
                            let visitBadgeClass = 'status-badge neutral';
                            let visitLabel = 'Sin registrar';
                            if (visitDate) {
                                const daysSince = (new Date().getTime() - new Date(visitDate).getTime()) / (1000 * 3600 * 24);
                                if (daysSince < 90) { visitBadgeClass = 'status-badge success'; visitLabel = 'Reciente'; } 
                                else if (daysSince < 180) { visitBadgeClass = 'status-badge warning'; visitLabel = 'Atención'; } 
                                else { visitBadgeClass = 'status-badge danger'; visitLabel = 'Urgente'; }
                            }

                            return (
                                <div key={m.id} style={{ 
                                    display: 'grid', gridTemplateColumns: 'repeat(1, minmax(0, 1fr))', gap: '1rem', padding: '1.25rem', 
                                    borderBottom: '1px solid #f1f5f9', alignItems: 'center', transition: 'background-color 0.2s'
                                }}
                                onMouseEnter={(e) => e.currentTarget.style.backgroundColor = '#f8fafc'}
                                onMouseLeave={(e) => e.currentTarget.style.backgroundColor = 'transparent'}
                                className="md:grid-cols-12"
                                >
                                    <style>{`@media (min-width: 768px) { div[key="${m.id}"] { grid-template-columns: repeat(12, minmax(0, 1fr)) !important; } }`}</style>

                                    {/* Name */}
                                    <div style={{ gridColumn: 'span 1', display: 'flex', alignItems: 'center', gap: '1rem' }} className="md:col-span-4">
                                        <div style={{ color: '#9ca3af', fontWeight: '600', minWidth: '1.5rem', textAlign: 'center' }}>
                                            {index + 1}
                                        </div>
                                        <div style={{ fontWeight: '600', color: '#1f2937', fontSize: '1rem' }}>{pName}</div>
                                    </div>

                                    {/* Hours with Toggle */}
                                    <div style={{ gridColumn: 'span 1', display: 'flex', justifyContent: 'space-between', alignItems: 'center', backgroundColor: '#f9fafb', padding: '0.75rem', borderRadius: '0.5rem' }} className="md:col-span-3 md:bg-transparent md:justify-center md:p-0">
                                        <span className="md:hidden" style={{ color: '#6b7280', fontSize: '0.875rem', fontWeight: '500' }}>Horas:</span>
                                        <div style={{ display: 'flex', alignItems: 'center', gap: '0.75rem', justifyContent: 'flex-end', width: '100%' }} className="md:justify-center">
                                            <input 
                                                type="checkbox"
                                                checked={hasReport}
                                                onChange={(e) => {
                                                    if (e.target.checked) {
                                                        handleReportChange(pName, ''); // Init
                                                    } else {
                                                        setReports(prev => {
                                                            const next = { ...prev };
                                                            delete next[pName];
                                                            return next;
                                                        });
                                                    }
                                                }}
                                                style={{ width: '1.25rem', height: '1.25rem', cursor: 'pointer', accentColor: '#10b981' }}
                                                title="Marcar si participó"
                                            />
                                            <input 
                                                type="number" min="0" step="0.5"
                                                value={reports[pName]?.horas ?? ''}
                                                onChange={(e) => handleReportChange(pName, e.target.value)}
                                                disabled={!hasReport}
                                                className={hasReport ? 'input-has-report' : ''}
                                                style={{ 
                                                    width: '5rem', padding: '0.5rem', textAlign: 'center', fontWeight: '700', borderRadius: '0.5rem', 
                                                    border: hasReport ? '2px solid #34d399' : '1px solid #e5e7eb', 
                                                    outline: 'none', transition: 'all 0.2s', color: '#4b5563',
                                                    opacity: hasReport ? 1 : 0.3,
                                                    backgroundColor: hasReport ? 'white' : '#f3f4f6'
                                                }}
                                                placeholder={hasReport ? '#' : ''}
                                            />
                                        </div>
                                    </div>

                                    {/* Visit */}
                                    <div style={{ gridColumn: 'span 1', display: 'flex', justifyContent: 'space-between', alignItems: 'center', backgroundColor: '#f9fafb', padding: '0.75rem', borderRadius: '0.5rem' }} className="md:col-span-3 md:bg-transparent md:justify-center md:p-0">
                                        <span className="md:hidden" style={{ color: '#6b7280', fontSize: '0.875rem', fontWeight: '500' }}>Visita:</span>
                                        <div style={{ display: 'flex', flexDirection: 'column', alignItems: 'flex-end', gap: '0.25rem', width: '100%' }} className="md:w-auto md:items-center">
                                            <input 
                                                type="date" value={visitDate}
                                                onChange={(e) => handleVisitChange(pName, e.target.value)}
                                                className="modern-input"
                                                style={{ padding: '0.25rem 0.5rem', fontSize: '0.875rem', width: '100%', color: '#4b5563', fontWeight: '500', textAlign: 'right' }}
                                            />
                                            <span className={visitBadgeClass}>
                                                <i className="fas fa-circle" style={{ fontSize: '0.5rem' }}></i> {visitLabel}
                                            </span>
                                        </div>
                                    </div>

                                    {/* Actions */}
                                    <div style={{ gridColumn: 'span 1', display: 'flex', justifyContent: 'flex-end', gap: '0.75rem', marginTop: '0.5rem' }} className="md:col-span-2 md:justify-center md:mt-0">
                                        <button 
                                            onClick={() => handleSaveRow(pName)}
                                            style={{ background: 'linear-gradient(135deg, #4f46e5 0%, #4338ca 100%)', color: 'white', padding: '0.5rem 1rem', borderRadius: '0.5rem', border: 'none', cursor: 'pointer', display: 'flex', alignItems: 'center', gap: '0.5rem', fontSize: '0.875rem', fontWeight: '600', boxShadow: '0 4px 6px -1px rgba(79, 70, 229, 0.2)' }}
                                            title="Guardar cambios"
                                        >
                                            <i className="fas fa-save"></i> <span className="md:hidden">Guardar</span>
                                        </button>
                                        <button 
                                            onClick={() => handleDeleteMember(m.id, pName)}
                                            style={{ padding: '0.5rem', color: '#9ca3af', backgroundColor: 'transparent', border: '1px solid transparent', borderRadius: '0.5rem', cursor: 'pointer', transition: 'color 0.2s' }}
                                            onMouseEnter={(e) => { e.currentTarget.style.color = '#ef4444'; e.currentTarget.style.backgroundColor = '#fef2f2'; }}
                                            onMouseLeave={(e) => { e.currentTarget.style.color = '#9ca3af'; e.currentTarget.style.backgroundColor = 'transparent'; }}
                                            title="Quitar del grupo"
                                        >
                                            <i className="fas fa-trash-alt"></i>
                                        </button>
                                    </div>
                                </div>
                            );
                        })}
                    </div>
                    {filteredMembers.length === 0 && (
                        <div style={{ padding: '5rem 0', textAlign: 'center', backgroundColor: '#f8fafc' }}>
                            <div style={{ backgroundColor: 'white', width: '6rem', height: '6rem', borderRadius: '50%', display: 'flex', alignItems: 'center', justifyContent: 'center', margin: '0 auto 1.5rem auto', boxShadow: '0 1px 2px 0 rgba(0,0,0,0.05)', border: '1px solid #e2e8f0' }}>
                                <i className="fas fa-users fa-3x" style={{ color: '#c7d2fe' }}></i>
                            </div>
                            <h3 style={{ fontSize: '1.25rem', fontWeight: '700', color: '#374151' }}>
                                {selectedGroupId ? 'Este grupo está vacío' : 'Crea o selecciona un grupo'}
                            </h3>
                            <p style={{ color: '#6b7280', marginTop: '0.5rem', maxWidth: '24rem', marginInline: 'auto' }}>
                                Utiliza el buscador de arriba para agregar publicadores existentes a este grupo.
                            </p>
                        </div>
                    )}
                </div>
            )}
        </div>
    );
};

export default GrupoCongregacion;

import React, { useState, useEffect, useRef } from 'react';
import { supabase } from '../lib/supabase';

type Publisher = {
    id: number;
    nombre: string;
};

type Group = {
    id: number;
    nombre: string;
};

type GroupMember = {
    id: number;
    grupo_id: number;
    publicador_nombre: string;
};

type MinistryReport = {
    horas: number | '';
    notas?: string;
};

type ReportsMap = Record<string, MinistryReport>;
type VisitsMap = Record<string, string>;

// Helper for avatar colors
const getAvatarClass = (name: string) => {
    const classes = ['avatar-red', 'avatar-orange', 'avatar-amber', 'avatar-green', 'avatar-teal', 'avatar-blue', 'avatar-indigo', 'avatar-purple', 'avatar-pink'];
    let hash = 0;
    for (let i = 0; i < name.length; i++) {
        hash = name.charCodeAt(i) + ((hash << 5) - hash);
    }
    return classes[Math.abs(hash) % classes.length];
};

const GrupoCongregacion: React.FC = () => {
    // Data State
    const [groups, setGroups] = useState<Group[]>([]);
    const [selectedGroupId, setSelectedGroupId] = useState<number | null>(null);
    const [members, setMembers] = useState<GroupMember[]>([]);
    const [masterPublishers, setMasterPublishers] = useState<Publisher[]>([]); // All publishers from DB

    // UI State
    const [loading, setLoading] = useState(true);
    const [currentMonth, setCurrentMonth] = useState<string>('');
    const [reports, setReports] = useState<ReportsMap>({});
    const [visits, setVisits] = useState<VisitsMap>({});
    const [searchTerm, setSearchTerm] = useState('');
    const [addSearchTerm, setAddSearchTerm] = useState(''); // Search input for adding
    const [showSuggestions, setShowSuggestions] = useState(false);
    const [isCreatingGroup, setIsCreatingGroup] = useState(false);
    const [newGroupName, setNewGroupName] = useState('');
    const [statusMessage, setStatusMessage] = useState<{ text: string; type: 'success' | 'error' | 'info' } | null>(null);

    const suggestionsRef = useRef<HTMLDivElement>(null);

    // Initial Load
    useEffect(() => {
        const now = new Date();
        const yyyy = now.getFullYear();
        const mm = String(now.getMonth() + 1).padStart(2, '0');
        setCurrentMonth(`${yyyy}-${mm}`);

        fetchGroups();
        fetchMasterPublishers();

        // Close suggestions on click outside
        const handleClickOutside = (event: MouseEvent) => {
            if (suggestionsRef.current && !suggestionsRef.current.contains(event.target as Node)) {
                setShowSuggestions(false);
            }
        };
        document.addEventListener('mousedown', handleClickOutside);
        return () => document.removeEventListener('mousedown', handleClickOutside);
    }, []);

    // Load Data Functions
    const fetchGroups = async () => {
        const { data, error } = await supabase.from('grupos').select('*').order('nombre');
        if (error) {
            console.error("Error fetching groups:", error);
        } else if (data) {
            setGroups(data);
            if (data.length > 0 && !selectedGroupId) {
                // Try to find "Grupo 5" first, else default to first
                const defaultGroup = data.find(g => g.nombre.includes('5')) || data[0];
                setSelectedGroupId(defaultGroup.id);
            }
        }
    };

    const fetchMasterPublishers = async () => {
        const { data } = await supabase.from('publicadores').select('id, nombre').order('nombre');
        if (data) setMasterPublishers(data);
    };

    const fetchMembers = async () => {
        if (!selectedGroupId) return;
        setLoading(true);
        const { data, error } = await supabase
            .from('miembros_grupo')
            .select('*')
            .eq('grupo_id', selectedGroupId)
            .order('publicador_nombre');

        if (error) console.error("Error fetching members:", error);
        else setMembers(data || []);
        setLoading(false);
    };

    // Load Members when Group Changes
    useEffect(() => {
        fetchMembers();
    }, [selectedGroupId]);

    // Load Reports/Visits when Members or Month Change
    useEffect(() => {
        if (!currentMonth || members.length === 0) return;

        const fetchData = async () => {
            // Get reports only for current members
            const memberNames = members.map(m => m.publicador_nombre);

            const { data: reportsData } = await supabase
                .from('informes_ministerio')
                .select('publicador_nombre, horas')
                .eq('mes', currentMonth)
                .in('publicador_nombre', memberNames);

            const newReports: ReportsMap = {};
            if (reportsData) {
                reportsData.forEach((r: any) => {
                    newReports[r.publicador_nombre] = { horas: r.horas };
                });
            }
            setReports(newReports);

            const { data: visitsData } = await supabase
                .from('visitas_pastoral')
                .select('publicador_nombre, fecha_visita')
                .in('publicador_nombre', memberNames);

            const newVisits: VisitsMap = {};
            if (visitsData) {
                visitsData.forEach((v: any) => {
                    newVisits[v.publicador_nombre] = v.fecha_visita;
                });
            }
            setVisits(newVisits);
        };

        fetchData();
    }, [currentMonth, members]);

    // --- Actions ---

    const handleCreateGroup = async () => {
        if (!newGroupName.trim()) return;
        const normalizedName = newGroupName.trim();

        const { data, error } = await supabase.from('grupos').insert([{ nombre: normalizedName }]).select();

        if (error) {
            // Check for duplicate key error code (Postgres unique violation)
            if (error.code === '23505') {
                const { data: existingGroup } = await supabase
                    .from('grupos')
                    .select('*')
                    .eq('nombre', normalizedName)
                    .single();

                if (existingGroup) {
                    setGroups(prev => {
                        if (prev.some(g => g.id === existingGroup.id)) return prev;
                        return [...prev, existingGroup].sort((a,b) => a.nombre.localeCompare(b.nombre));
                    });
                    setSelectedGroupId(existingGroup.id);
                    setIsCreatingGroup(false);
                    setNewGroupName('');
                    setStatusMessage({ text: `El grupo "${normalizedName}" ya existe. Seleccionado.`, type: 'info' });
                    setTimeout(() => setStatusMessage(null), 3000);
                    return; 
                }
            }

            console.error("Error creating group:", error);
            setStatusMessage({ text: `Error: ${error.message}`, type: 'error' });
            setTimeout(() => setStatusMessage(null), 4000);
        } else if (data) {
            setGroups(prev => [...prev, data[0]].sort((a,b) => a.nombre.localeCompare(b.nombre)));
            setSelectedGroupId(data[0].id);
            setIsCreatingGroup(false);
            setNewGroupName('');
            setStatusMessage({ text: 'Grupo creado con éxito', type: 'success' });
            setTimeout(() => setStatusMessage(null), 3000);
        }
    };

    const handleDeleteGroup = async () => {
        if (!selectedGroupId) return;
        const groupName = groups.find(g => g.id === selectedGroupId)?.nombre;
        if (!window.confirm(`¿Estás seguro de eliminar el "${groupName}" y todos sus integrantes?`)) return;

        const { error } = await supabase.from('grupos').delete().eq('id', selectedGroupId);
        if (error) {
            console.error("Error deleting group:", error);
            setStatusMessage({ text: `Error al eliminar: ${error.message}`, type: 'error' });
        } else {
            const remaining = groups.filter(g => g.id !== selectedGroupId);
            setGroups(remaining);
            setSelectedGroupId(remaining.length > 0 ? remaining[0].id : null);
            setMembers([]);
            setStatusMessage({ text: 'Grupo eliminado', type: 'success' });
            setTimeout(() => setStatusMessage(null), 3000);
        }
    };

    const handleAddMember = async (name: string) => {
        if (!selectedGroupId || !name.trim()) return;

        // Check local duplicate
        if (members.some(m => m.publicador_nombre.toLowerCase() === name.toLowerCase())) {
            setStatusMessage({ text: 'Esta persona ya está en el grupo', type: 'error' });
            setTimeout(() => setStatusMessage(null), 3000);
            return;
        }

        const { error } = await supabase.from('miembros_grupo').insert([{
            grupo_id: selectedGroupId,
            publicador_nombre: name.trim()
        }]);

        if (error) {
            console.error(error);
            setStatusMessage({ text: `Error al agregar: ${error.message}`, type: 'error' });
        } else {
            setStatusMessage({ text: 'Agregado correctamente', type: 'success' });
            setAddSearchTerm('');
            fetchMembers();
        }
        setTimeout(() => setStatusMessage(null), 3000);
    };

    const handleDeleteMember = async (id: number, name: string) => {
        if (!window.confirm(`¿Quitar a ${name} de este grupo?`)) return;
        const { error } = await supabase.from('miembros_grupo').delete().eq('id', id);
        if (!error) fetchMembers();
        else console.error("Error deleting member:", error);
    };

    const handleReportChange = (name: string, value: string) => {
        setReports(prev => ({
            ...prev,
            [name]: { ...prev[name], horas: value === '' ? '' : Number(value) }
        }));
    };

    const handleVisitChange = (name: string, date: string) => {
        setVisits(prev => ({
            ...prev,
            [name]: date
        }));
    };

    const handleSaveRow = async (publisherName: string) => {
        setStatusMessage(null);
        try {
            // --- Save Report Logic ---
            const reportEntry = reports[publisherName];

            if (reportEntry) {
                // If checkbox is active (exists in state), upsert report
                // Note: If 'Predicó' was selected, horas will be 0. If 'Horas' selected, it will be > 0.
                const valToSave = reportEntry.horas === '' ? 0 : reportEntry.horas;

                const { error: reportError } = await supabase
                    .from('informes_ministerio')
                    .upsert({ 
                        publicador_nombre: publisherName, 
                        mes: currentMonth, 
                        horas: valToSave 
                    }, { onConflict: 'publicador_nombre, mes' });
                if (reportError) throw reportError;
            } else {
                // If reportEntry is missing (User selected 'Vacío'), delete report from DB
                const { error: deleteError } = await supabase
                    .from('informes_ministerio')
                    .delete()
                    .eq('publicador_nombre', publisherName)
                    .eq('mes', currentMonth);

                // We ignore if it didn't exist, but supabase delete won't error on 0 rows
                if (deleteError) throw deleteError;
            }

            // --- Save Visit Logic ---
            const visitDate = visits[publisherName];
            if (visitDate) {
                const { error: visitError } = await supabase
                    .from('visitas_pastoral')
                    .upsert({ 
                        publicador_nombre: publisherName, 
                        fecha_visita: visitDate 
                    }, { onConflict: 'publicador_nombre' });
                if (visitError) throw visitError;
            }

            setStatusMessage({ text: 'Guardado', type: 'success' });
            setTimeout(() => setStatusMessage(null), 2000);
        } catch (err: any) {
            console.error(err);
            setStatusMessage({ text: 'Error al guardar', type: 'error' });
        }
    };

    // Filter Logic for Main Table
    const filteredMembers = members.filter(m => 
        m.publicador_nombre.toLowerCase().includes(searchTerm.toLowerCase())
    );

    // Filter Logic for Add Suggestions
    const filteredSuggestions = masterPublishers
        .filter(p => p.nombre.toLowerCase().includes(addSearchTerm.toLowerCase()))
        .filter(p => !members.some(m => m.publicador_nombre === p.nombre)) // Exclude already in group
        .slice(0, 6); // Limit results

    const currentGroupName = groups.find(g => g.id === selectedGroupId)?.nombre || 'Sin Grupo';

    return (
        <div className="container mx-auto px-4 py-8 group-container">

            {/* --- TOP BAR: Group Selector & Date --- */}
            <div style={{ display: 'flex', flexDirection: 'column', gap: '1.5rem', marginBottom: '2rem' }}>
                <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', flexWrap: 'wrap', gap: '1rem' }}>
                    <div style={{flex: 1}}>
                        {!isCreatingGroup ? (
                            <div style={{display: 'flex', alignItems: 'center', gap: '10px'}}>
                                <select 
                                    value={selectedGroupId || ''} 
                                    onChange={(e) => setSelectedGroupId(Number(e.target.value))}
                                    className="gc-header-title"
                                    style={{ background: 'transparent', border: 'none', cursor: 'pointer', paddingRight: '20px', outline: 'none' }}
                                >
                                    {groups.length === 0 && <option value="">Crear un grupo...</option>}
                                    {groups.map(g => <option key={g.id} value={g.id}>{g.nombre}</option>)}
                                </select>
                                <button onClick={() => setIsCreatingGroup(true)} style={{background: '#e0e7ff', color: '#4338ca', border: 'none', borderRadius: '50%', width: '32px', height: '32px', cursor: 'pointer', display: 'flex', alignItems: 'center', justifyContent: 'center'}} title="Crear nuevo grupo">
                                    <i className="fas fa-plus"></i>
                                </button>
                                {groups.length > 0 && (
                                    <button onClick={handleDeleteGroup} style={{background: '#fee2e2', color: '#dc2626', border: 'none', borderRadius: '50%', width: '32px', height: '32px', cursor: 'pointer', display: 'flex', alignItems: 'center', justifyContent: 'center', marginLeft: '5px'}} title="Eliminar este grupo">
                                        <i className="fas fa-trash-alt" style={{fontSize: '0.8rem'}}></i>
                                    </button>
                                )}
                            </div>
                        ) : (
                            <div style={{display: 'flex', gap: '10px', alignItems: 'center'}}>
                                <input 
                                    autoFocus
                                    type="text" 
                                    placeholder="Nombre del Grupo (ej. Grupo 1)" 
                                    value={newGroupName}
                                    onChange={(e) => setNewGroupName(e.target.value)}
                                    className="gc-input-add"
                                    style={{width: '250px'}}
                                />
                                <button onClick={handleCreateGroup} className="button" style={{backgroundColor: '#10b981', color: 'white'}}>Guardar</button>
                                <button onClick={() => setIsCreatingGroup(false)} className="button" style={{backgroundColor: '#6b7280', color: 'white'}}>Cancelar</button>
                            </div>
                        )}
                        <p style={{ color: '#6b7280', fontWeight: '500', display: 'flex', alignItems: 'center', gap: '0.5rem', marginTop: '0.5rem' }}>
                            <i className="fas fa-users" style={{ color: '#60a5fa' }}></i>
                            {members.length} Integrantes
                        </p>
                    </div>

                    <div style={{ display: 'flex', gap: '0.75rem', alignItems: 'center', backgroundColor: 'white', padding: '0.5rem', borderRadius: '0.75rem', border: '1px solid #e5e7eb', boxShadow: '0 1px 2px 0 rgba(0,0,0,0.05)' }}>
                        <div style={{ backgroundColor: '#f3f4f6', padding: '0.5rem 0.75rem', borderRadius: '0.5rem', color: '#6b7280' }}>
                            <i className="fas fa-calendar-alt"></i>
                        </div>
                        <input 
                            type="month" 
                            value={currentMonth} 
                            onChange={(e) => setCurrentMonth(e.target.value)}
                            style={{ border: 'none', background: 'transparent', fontWeight: '600', color: '#374151', outline: 'none', cursor: 'pointer' }}
                        />
                    </div>
                </div>
            </div>

            {/* --- ADD MEMBER SECTION (With Autocomplete & Manual Option) --- */}
            {selectedGroupId && (
                <div className="gc-card-add" style={{overflow: 'visible'}}>
                    <div className="gc-label-add">
                        <i className="fas fa-user-plus"></i>
                        Agregar Integrante al {currentGroupName}
                    </div>
                    <div style={{ display: 'flex', flexDirection: 'row', gap: '1rem', flexWrap: 'wrap', position: 'relative' }} ref={suggestionsRef}>
                        <div style={{ position: 'relative', flexGrow: 1 }}>
                            <i className="fas fa-search" style={{ position: 'absolute', left: '1rem', top: '50%', transform: 'translateY(-50%)', color: '#9ca3af', zIndex: 10 }}></i>
                            <input 
                                type="text" 
                                value={addSearchTerm}
                                onChange={(e) => {
                                    setAddSearchTerm(e.target.value);
                                    setShowSuggestions(true);
                                }}
                                onFocus={() => setShowSuggestions(true)}
                                onKeyDown={(e) => {
                                    if (e.key === 'Enter') {
                                        handleAddMember(addSearchTerm);
                                        setShowSuggestions(false);
                                    }
                                }}
                                placeholder="Buscar o escribir nombre nuevo..."
                                className="gc-input-add"
                                autoComplete="off"
                            />
                            {/* Autocomplete Dropdown */}
                            {showSuggestions && addSearchTerm && (
                                <div style={{
                                    position: 'absolute', top: '100%', left: 0, right: 0, 
                                    backgroundColor: 'white', border: '1px solid #e5e7eb', 
                                    borderRadius: '0.75rem', marginTop: '5px', zIndex: 50,
                                    boxShadow: '0 10px 15px -3px rgba(0, 0, 0, 0.1)',
                                    maxHeight: '300px', overflowY: 'auto'
                                }}>
                                    {/* Existing Publishers from DB */}
                                    {filteredSuggestions.map(p => (
                                        <div 
                                            key={p.id}
                                            onClick={() => {
                                                handleAddMember(p.nombre);
                                                setAddSearchTerm(''); 
                                                setShowSuggestions(false);
                                            }}
                                            style={{ padding: '10px 15px', cursor: 'pointer', borderBottom: '1px solid #f3f4f6', display: 'flex', alignItems: 'center', gap: '10px' }}
                                            onMouseEnter={(e) => e.currentTarget.style.backgroundColor = '#f9fafb'}
                                            onMouseLeave={(e) => e.currentTarget.style.backgroundColor = 'white'}
                                        >
                                            <div className={`modern-avatar ${getAvatarClass(p.nombre)}`} style={{width: '24px', height: '24px', fontSize: '0.7rem'}}>
                                                {p.nombre.charAt(0)}
                                            </div>
                                            <span style={{color: '#374151', fontWeight: '500'}}>{p.nombre}</span>
                                            <i className="fas fa-plus" style={{marginLeft: 'auto', color: '#10b981', fontSize: '0.8rem'}}></i>
                                        </div>
                                    ))}

                                    {/* Manual "Add as new" Option (Always visible if text is present) */}
                                    <div 
                                        onClick={() => {
                                            handleAddMember(addSearchTerm);
                                            setAddSearchTerm(''); 
                                            setShowSuggestions(false);
                                        }}
                                        style={{ padding: '10px 15px', cursor: 'pointer', backgroundColor: '#fdf4ff', borderTop: '1px solid #f3f4f6', display: 'flex', alignItems: 'center', gap: '10px' }}
                                        onMouseEnter={(e) => e.currentTarget.style.backgroundColor = '#fce7f3'}
                                        onMouseLeave={(e) => e.currentTarget.style.backgroundColor = '#fdf4ff'}
                                    >
                                        <div style={{width: '24px', height: '24px', display:'flex', alignItems:'center', justifyContent:'center', color: '#d946ef'}}>
                                            <i className="fas fa-pen"></i>
                                        </div>
                                        <div style={{display:'flex', flexDirection:'column'}}>
                                            <span style={{color: '#374151', fontWeight: '600'}}>Agregar "{addSearchTerm}"</span>
                                            <span style={{fontSize: '0.75rem', color: '#d946ef'}}>Nombre manual (no se añade a lista general)</span>
                                        </div>
                                    </div>
                                </div>
                            )}
                        </div>
                        <button 
                            onClick={() => handleAddMember(addSearchTerm)}
                            disabled={!addSearchTerm.trim()}
                            className="gc-btn-add"
                        >
                            <span>Agregar</span>
                            <i className="fas fa-arrow-right"></i>
                        </button>
                    </div>
                </div>
            )}

            {/* Status Toast */}
            {statusMessage && (
                <div style={{ 
                    position: 'fixed', bottom: '1.5rem', right: '1.5rem', zIndex: 100, padding: '1rem 1.5rem', borderRadius: '0.75rem', 
                    boxShadow: '0 10px 15px -3px rgba(0, 0, 0, 0.1)', fontWeight: '600', display: 'flex', alignItems: 'center', gap: '0.75rem',
                    backgroundColor: statusMessage.type === 'success' ? '#059669' : (statusMessage.type === 'info' ? '#3b82f6' : '#dc2626'), color: 'white'
                }}>
                    <i className={`fas ${statusMessage.type === 'success' ? 'fa-check-circle' : (statusMessage.type === 'info' ? 'fa-info-circle' : 'fa-exclamation-circle')}`}></i>
                    {statusMessage.text}
                </div>
            )}

            {/* List Table */}
            {loading ? (
                <div style={{ textAlign: 'center', padding: '5rem 0', color: '#9ca3af' }}>
                    <i className="fas fa-spinner fa-spin fa-3x" style={{ marginBottom: '1rem', color: '#93c5fd' }}></i>
                    <p style={{ fontWeight: '500' }}>Cargando datos...</p>
                </div>
            ) : (
                <div className="modern-card">
                    {/* Desktop Table Header */}
                    <div className="gc-table-header" style={{ display: 'none', gridTemplateColumns: 'repeat(12, minmax(0, 1fr))', borderBottom: '1px solid #e2e8f0', backgroundColor: '#f8fafc' }}>
                        <div style={{ gridColumn: 'span 4', paddingLeft: '1rem' }}>Publicador</div>
                        <div style={{ gridColumn: 'span 3', textAlign: 'center' }}>Horas ({currentMonth.split('-')[1]})</div>
                        <div style={{ gridColumn: 'span 3', textAlign: 'center' }}>Última Visita</div>
                        <div style={{ gridColumn: 'span 2', textAlign: 'center' }}>Acciones</div>
                    </div>
                    <style>{`@media (min-width: 768px) { .gc-table-header { display: grid !important; } }`}</style>

                    <div style={{ display: 'flex', flexDirection: 'column' }}>
                        {filteredMembers.map((m, index) => {
                            const pName = m.publicador_nombre;
                            const reportEntry = reports[pName];

                            // Determine current visual mode based on data
                            let currentMode = 'empty';
                            if (reportEntry) {
                                if (reportEntry.horas === 0) currentMode = 'predico';
                                else if (reportEntry.horas > 0 || reportEntry.horas === '') currentMode = 'horas';
                            }

                            const visitDate = visits[pName] || '';

                            // Visual cue logic
                            let visitBadgeClass = 'status-badge neutral';
                            let visitLabel = 'Sin registrar';
                            if (visitDate) {
                                const daysSince = (new Date().getTime() - new Date(visitDate).getTime()) / (1000 * 3600 * 24);
                                if (daysSince < 90) { visitBadgeClass = 'status-badge success'; visitLabel = 'Reciente'; } 
                                else if (daysSince < 180) { visitBadgeClass = 'status-badge warning'; visitLabel = 'Atención'; } 
                                else { visitBadgeClass = 'status-badge danger'; visitLabel = 'Urgente'; }
                            }

                            return (
                                <div key={m.id} style={{ 
                                    display: 'grid', gridTemplateColumns: 'repeat(1, minmax(0, 1fr))', gap: '1rem', padding: '1.25rem', 
                                    borderBottom: '1px solid #f1f5f9', alignItems: 'center', transition: 'background-color 0.2s'
                                }}
                                onMouseEnter={(e) => e.currentTarget.style.backgroundColor = '#f8fafc'}
                                onMouseLeave={(e) => e.currentTarget.style.backgroundColor = 'transparent'}
                                className="md:grid-cols-12"
                                >
                                    <style>{`@media (min-width: 768px) { div[key="${m.id}"] { grid-template-columns: repeat(12, minmax(0, 1fr)) !important; } }`}</style>

                                    {/* Name */}
                                    <div style={{ gridColumn: 'span 1', display: 'flex', alignItems: 'center', gap: '1rem' }} className="md:col-span-4">
                                        <div style={{ color: '#9ca3af', fontWeight: '600', minWidth: '1.5rem', textAlign: 'center' }}>
                                            {index + 1}
                                        </div>
                                        <div style={{ fontWeight: '600', color: '#1f2937', fontSize: '1rem' }}>{pName}</div>
                                    </div>

                                    {/* Hours with Selector */}
                                    <div style={{ gridColumn: 'span 1', display: 'flex', justifyContent: 'space-between', alignItems: 'center', backgroundColor: '#f9fafb', padding: '0.75rem', borderRadius: '0.5rem' }} className="md:col-span-3 md:bg-transparent md:justify-center md:p-0">
                                        <span className="md:hidden" style={{ color: '#6b7280', fontSize: '0.875rem', fontWeight: '500' }}>Horas:</span>
                                        <div style={{ display: 'flex', alignItems: 'center', gap: '0.5rem', justifyContent: 'flex-end', width: '100%' }} className="md:justify-center">
                                            <select
                                                value={currentMode}
                                                onChange={(e) => {
                                                    const newMode = e.target.value;
                                                    if (newMode === 'empty') {
                                                        setReports(prev => {
                                                            const next = { ...prev };
                                                            delete next[pName];
                                                            return next;
                                                        });
                                                    } else if (newMode === 'predico') {
                                                        handleReportChange(pName, '0');
                                                    } else if (newMode === 'horas') {
                                                        handleReportChange(pName, ''); // Reset to empty string to encourage input
                                                    }
                                                }}
                                                style={{ 
                                                    padding: '0.4rem 0.5rem', borderRadius: '0.5rem', border: '1px solid #d1d5db', 
                                                    backgroundColor: 'white', fontSize: '0.875rem', color: '#374151', cursor: 'pointer', outline: 'none' 
                                                }}
                                            >
                                                <option value="empty">-- (Vacío)</option>
                                                <option value="predico">Predicó</option>
                                                <option value="horas">Horas</option>
                                            </select>

                                            {currentMode === 'horas' && (
                                                <input 
                                                    type="number" min="0" step="0.5"
                                                    value={reportEntry?.horas === 0 ? '' : (reportEntry?.horas ?? '')}
                                                    onChange={(e) => handleReportChange(pName, e.target.value)}
                                                    autoFocus
                                                    className="input-has-report"
                                                    style={{ 
                                                        width: '4rem', padding: '0.4rem', textAlign: 'center', fontWeight: '700', borderRadius: '0.5rem', 
                                                        border: '2px solid #34d399', outline: 'none', transition: 'all 0.2s', color: '#4b5563', backgroundColor: 'white'
                                                    }}
                                                    placeholder="#"
                                                />
                                            )}
                                        </div>
                                    </div>

                                    {/* Visit */}
                                    <div style={{ gridColumn: 'span 1', display: 'flex', justifyContent: 'space-between', alignItems: 'center', backgroundColor: '#f9fafb', padding: '0.75rem', borderRadius: '0.5rem' }} className="md:col-span-3 md:bg-transparent md:justify-center md:p-0">
                                        <span className="md:hidden" style={{ color: '#6b7280', fontSize: '0.875rem', fontWeight: '500' }}>Visita:</span>
                                        <div style={{ display: 'flex', flexDirection: 'column', alignItems: 'flex-end', gap: '0.25rem', width: '100%' }} className="md:w-auto md:items-center">
                                            <input 
                                                type="date" value={visitDate}
                                                onChange={(e) => handleVisitChange(pName, e.target.value)}
                                                className="modern-input"
                                                style={{ padding: '0.25rem 0.5rem', fontSize: '0.875rem', width: '100%', color: '#4b5563', fontWeight: '500', textAlign: 'right' }}
                                            />
                                            <span className={visitBadgeClass}>
                                                <i className="fas fa-circle" style={{ fontSize: '0.5rem' }}></i> {visitLabel}
                                            </span>
                                        </div>
                                    </div>

                                    {/* Actions */}
                                    <div style={{ gridColumn: 'span 1', display: 'flex', justifyContent: 'flex-end', gap: '0.75rem', marginTop: '0.5rem' }} className="md:col-span-2 md:justify-center md:mt-0">
                                        <button 
                                            onClick={() => handleSaveRow(pName)}
                                            style={{ background: 'linear-gradient(135deg, #4f46e5 0%, #4338ca 100%)', color: 'white', padding: '0.5rem 1rem', borderRadius: '0.5rem', border: 'none', cursor: 'pointer', display: 'flex', alignItems: 'center', gap: '0.5rem', fontSize: '0.875rem', fontWeight: '600', boxShadow: '0 4px 6px -1px rgba(79, 70, 229, 0.2)' }}
                                            title="Guardar cambios"
                                        >
                                            <i className="fas fa-save"></i> <span className="md:hidden">Guardar</span>
                                        </button>
                                        <button 
                                            onClick={() => handleDeleteMember(m.id, pName)}
                                            style={{ padding: '0.5rem', color: '#9ca3af', backgroundColor: 'transparent', border: '1px solid transparent', borderRadius: '0.5rem', cursor: 'pointer', transition: 'color 0.2s' }}
                                            onMouseEnter={(e) => { e.currentTarget.style.color = '#ef4444'; e.currentTarget.style.backgroundColor = '#fef2f2'; }}
                                            onMouseLeave={(e) => { e.currentTarget.style.color = '#9ca3af'; e.currentTarget.style.backgroundColor = 'transparent'; }}
                                            title="Quitar del grupo"
                                        >
                                            <i className="fas fa-trash-alt"></i>
                                        </button>
                                    </div>
                                </div>
                            );
                        })}
                    </div>
                    {filteredMembers.length === 0 && (
                        <div style={{ padding: '5rem 0', textAlign: 'center', backgroundColor: '#f8fafc' }}>
                            <div style={{ backgroundColor: 'white', width: '6rem', height: '6rem', borderRadius: '50%', display: 'flex', alignItems: 'center', justifyContent: 'center', margin: '0 auto 1.5rem auto', boxShadow: '0 1px 2px 0 rgba(0,0,0,0.05)', border: '1px solid #e2e8f0' }}>
                                <i className="fas fa-users fa-3x" style={{ color: '#c7d2fe' }}></i>
                            </div>
                            <h3 style={{ fontSize: '1.25rem', fontWeight: '700', color: '#374151' }}>
                                {selectedGroupId ? 'Este grupo está vacío' : 'Crea o selecciona un grupo'}
                            </h3>
                            <p style={{ color: '#6b7280', marginTop: '0.5rem', maxWidth: '24rem', marginInline: 'auto' }}>
                                Utiliza el buscador de arriba para agregar publicadores existentes a este grupo.
                            </p>
                        </div>
                    )}
                </div>
            )}
        </div>
    );
};

export default GrupoCongregacion;

import React, { useState, useEffect, useRef } from 'react';
import { supabase } from '../lib/supabase';

type Publisher = {
    id: number;
    nombre: string;
};

type Group = {
    id: number;
    nombre: string;
};

type GroupMember = {
    id: number;
    grupo_id: number;
    publicador_nombre: string;
};

type MinistryReport = {
    horas: number | '';
    notas?: string;
};

type ReportsMap = Record<string, MinistryReport>;
type VisitsMap = Record<string, string>;

// Helper for avatar colors
const getAvatarClass = (name: string) => {
    const classes = ['avatar-red', 'avatar-orange', 'avatar-amber', 'avatar-green', 'avatar-teal', 'avatar-blue', 'avatar-indigo', 'avatar-purple', 'avatar-pink'];
    let hash = 0;
    for (let i = 0; i < name.length; i++) {
        hash = name.charCodeAt(i) + ((hash << 5) - hash);
    }
    return classes[Math.abs(hash) % classes.length];
};

const GrupoCongregacion: React.FC = () => {
    // Data State
    const [groups, setGroups] = useState<Group[]>([]);
    const [selectedGroupId, setSelectedGroupId] = useState<number | null>(null);
    const [members, setMembers] = useState<GroupMember[]>([]);
    const [masterPublishers, setMasterPublishers] = useState<Publisher[]>([]); // All publishers from DB

    // UI State
    const [loading, setLoading] = useState(true);
    const [currentMonth, setCurrentMonth] = useState<string>('');
    const [reports, setReports] = useState<ReportsMap>({});
    const [visits, setVisits] = useState<VisitsMap>({});
    const [searchTerm, setSearchTerm] = useState('');
    const [addSearchTerm, setAddSearchTerm] = useState(''); // Search input for adding
    const [showSuggestions, setShowSuggestions] = useState(false);
    const [isCreatingGroup, setIsCreatingGroup] = useState(false);
    const [newGroupName, setNewGroupName] = useState('');
    const [statusMessage, setStatusMessage] = useState<{ text: string; type: 'success' | 'error' | 'info' } | null>(null);

    const suggestionsRef = useRef<HTMLDivElement>(null);

    // Initial Load
    useEffect(() => {
        const now = new Date();
        const yyyy = now.getFullYear();
        const mm = String(now.getMonth() + 1).padStart(2, '0');
        setCurrentMonth(`${yyyy}-${mm}`);

        fetchGroups();
        fetchMasterPublishers();

        // Close suggestions on click outside
        const handleClickOutside = (event: MouseEvent) => {
            if (suggestionsRef.current && !suggestionsRef.current.contains(event.target as Node)) {
                setShowSuggestions(false);
            }
        };
        document.addEventListener('mousedown', handleClickOutside);
        return () => document.removeEventListener('mousedown', handleClickOutside);
    }, []);

    // Load Data Functions
    const fetchGroups = async () => {
        const { data, error } = await supabase.from('grupos').select('*').order('nombre');
        if (error) {
            console.error("Error fetching groups:", error);
        } else if (data) {
            setGroups(data);
            if (data.length > 0 && !selectedGroupId) {
                // Try to find "Grupo 5" first, else default to first
                const defaultGroup = data.find(g => g.nombre.includes('5')) || data[0];
                setSelectedGroupId(defaultGroup.id);
            }
        }
    };

    const fetchMasterPublishers = async () => {
        const { data } = await supabase.from('publicadores').select('id, nombre').order('nombre');
        if (data) setMasterPublishers(data);
    };

    const fetchMembers = async () => {
        if (!selectedGroupId) return;
        setLoading(true);
        const { data, error } = await supabase
            .from('miembros_grupo')
            .select('*')
            .eq('grupo_id', selectedGroupId)
            .order('publicador_nombre');

        if (error) console.error("Error fetching members:", error);
        else setMembers(data || []);
        setLoading(false);
    };

    // Load Members when Group Changes
    useEffect(() => {
        fetchMembers();
    }, [selectedGroupId]);

    // Load Reports/Visits when Members or Month Change
    useEffect(() => {
        if (!currentMonth || members.length === 0) return;

        const fetchData = async () => {
            // Get reports only for current members
            const memberNames = members.map(m => m.publicador_nombre);

            const { data: reportsData } = await supabase
                .from('informes_ministerio')
                .select('publicador_nombre, horas')
                .eq('mes', currentMonth)
                .in('publicador_nombre', memberNames);

            const newReports: ReportsMap = {};
            if (reportsData) {
                reportsData.forEach((r: any) => {
                    newReports[r.publicador_nombre] = { horas: r.horas };
                });
            }
            setReports(newReports);

            const { data: visitsData } = await supabase
                .from('visitas_pastoral')
                .select('publicador_nombre, fecha_visita')
                .in('publicador_nombre', memberNames);

            const newVisits: VisitsMap = {};
            if (visitsData) {
                visitsData.forEach((v: any) => {
                    newVisits[v.publicador_nombre] = v.fecha_visita;
                });
            }
            setVisits(newVisits);
        };

        fetchData();
    }, [currentMonth, members]);

    // --- Actions ---

    const handleCreateGroup = async () => {
        if (!newGroupName.trim()) return;
        const normalizedName = newGroupName.trim();

        const { data, error } = await supabase.from('grupos').insert([{ nombre: normalizedName }]).select();

        if (error) {
            // Check for duplicate key error code (Postgres unique violation)
            if (error.code === '23505') {
                const { data: existingGroup } = await supabase
                    .from('grupos')
                    .select('*')
                    .eq('nombre', normalizedName)
                    .single();

                if (existingGroup) {
                    setGroups(prev => {
                        if (prev.some(g => g.id === existingGroup.id)) return prev;
                        return [...prev, existingGroup].sort((a,b) => a.nombre.localeCompare(b.nombre));
                    });
                    setSelectedGroupId(existingGroup.id);
                    setIsCreatingGroup(false);
                    setNewGroupName('');
                    setStatusMessage({ text: `El grupo "${normalizedName}" ya existe. Seleccionado.`, type: 'info' });
                    setTimeout(() => setStatusMessage(null), 3000);
                    return; 
                }
            }

            console.error("Error creating group:", error);
            setStatusMessage({ text: `Error: ${error.message}`, type: 'error' });
            setTimeout(() => setStatusMessage(null), 4000);
        } else if (data) {
            setGroups(prev => [...prev, data[0]].sort((a,b) => a.nombre.localeCompare(b.nombre)));
            setSelectedGroupId(data[0].id);
            setIsCreatingGroup(false);
            setNewGroupName('');
            setStatusMessage({ text: 'Grupo creado con éxito', type: 'success' });
            setTimeout(() => setStatusMessage(null), 3000);
        }
    };

    const handleDeleteGroup = async () => {
        if (!selectedGroupId) return;
        const groupName = groups.find(g => g.id === selectedGroupId)?.nombre;
        if (!window.confirm(`¿Estás seguro de eliminar el "${groupName}" y todos sus integrantes?`)) return;

        const { error } = await supabase.from('grupos').delete().eq('id', selectedGroupId);
        if (error) {
            console.error("Error deleting group:", error);
            setStatusMessage({ text: `Error al eliminar: ${error.message}`, type: 'error' });
        } else {
            const remaining = groups.filter(g => g.id !== selectedGroupId);
            setGroups(remaining);
            setSelectedGroupId(remaining.length > 0 ? remaining[0].id : null);
            setMembers([]);
            setStatusMessage({ text: 'Grupo eliminado', type: 'success' });
            setTimeout(() => setStatusMessage(null), 3000);
        }
    };

    const handleAddMember = async (name: string) => {
        if (!selectedGroupId || !name.trim()) return;

        // Check local duplicate
        if (members.some(m => m.publicador_nombre.toLowerCase() === name.toLowerCase())) {
            setStatusMessage({ text: 'Esta persona ya está en el grupo', type: 'error' });
            setTimeout(() => setStatusMessage(null), 3000);
            return;
        }

        const { error } = await supabase.from('miembros_grupo').insert([{
            grupo_id: selectedGroupId,
            publicador_nombre: name.trim()
        }]);

        if (error) {
            console.error(error);
            setStatusMessage({ text: `Error al agregar: ${error.message}`, type: 'error' });
        } else {
            setStatusMessage({ text: 'Agregado correctamente', type: 'success' });
            setAddSearchTerm('');
            fetchMembers();
        }
        setTimeout(() => setStatusMessage(null), 3000);
    };

    const handleDeleteMember = async (id: number, name: string) => {
        if (!window.confirm(`¿Quitar a ${name} de este grupo?`)) return;
        const { error } = await supabase.from('miembros_grupo').delete().eq('id', id);
        if (!error) fetchMembers();
        else console.error("Error deleting member:", error);
    };

    const handleReportChange = (name: string, value: string) => {
        setReports(prev => ({
            ...prev,
            [name]: { ...prev[name], horas: value === '' ? '' : Number(value) }
        }));
    };

    const handleVisitChange = (name: string, date: string) => {
        setVisits(prev => ({
            ...prev,
            [name]: date
        }));
    };

    const handleSaveRow = async (publisherName: string) => {
        setStatusMessage(null);
        try {
            // --- Save Report Logic ---
            const reportEntry = reports[publisherName];

            if (reportEntry) {
                // If checkbox is active (exists in state), upsert report
                // Note: If 'Predicó' was selected, horas will be 0. If 'Horas' selected, it will be > 0.
                const valToSave = reportEntry.horas === '' ? 0 : reportEntry.horas;

                const { error: reportError } = await supabase
                    .from('informes_ministerio')
                    .upsert({ 
                        publicador_nombre: publisherName, 
                        mes: currentMonth, 
                        horas: valToSave 
                    }, { onConflict: 'publicador_nombre, mes' });
                if (reportError) throw reportError;
            } else {
                // If reportEntry is missing (User selected 'Vacío'), delete report from DB
                const { error: deleteError } = await supabase
                    .from('informes_ministerio')
                    .delete()
                    .eq('publicador_nombre', publisherName)
                    .eq('mes', currentMonth);

                // We ignore if it didn't exist, but supabase delete won't error on 0 rows
                if (deleteError) throw deleteError;
            }

            // --- Save Visit Logic ---
            const visitDate = visits[publisherName];
            if (visitDate) {
                const { error: visitError } = await supabase
                    .from('visitas_pastoral')
                    .upsert({ 
                        publicador_nombre: publisherName, 
                        fecha_visita: visitDate 
                    }, { onConflict: 'publicador_nombre' });
                if (visitError) throw visitError;
            }

            setStatusMessage({ text: 'Guardado', type: 'success' });
            setTimeout(() => setStatusMessage(null), 2000);
        } catch (err: any) {
            console.error(err);
            setStatusMessage({ text: 'Error al guardar', type: 'error' });
        }
    };

    // Filter Logic for Main Table
    const filteredMembers = members.filter(m => 
        m.publicador_nombre.toLowerCase().includes(searchTerm.toLowerCase())
    );

    // Filter Logic for Add Suggestions
    const filteredSuggestions = masterPublishers
        .filter(p => p.nombre.toLowerCase().includes(addSearchTerm.toLowerCase()))
        .filter(p => !members.some(m => m.publicador_nombre === p.nombre)) // Exclude already in group
        .slice(0, 6); // Limit results

    const currentGroupName = groups.find(g => g.id === selectedGroupId)?.nombre || 'Sin Grupo';

    return (
        <div className="container mx-auto px-4 py-8 group-container">

            {/* --- TOP BAR: Group Selector & Date --- */}
            <div style={{ display: 'flex', flexDirection: 'column', gap: '1.5rem', marginBottom: '2rem' }}>
                <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', flexWrap: 'wrap', gap: '1rem' }}>
                    <div style={{flex: 1}}>
                        {!isCreatingGroup ? (
                            <div style={{display: 'flex', alignItems: 'center', gap: '10px'}}>
                                <select 
                                    value={selectedGroupId || ''} 
                                    onChange={(e) => setSelectedGroupId(Number(e.target.value))}
                                    className="gc-header-title"
                                    style={{ background: 'transparent', border: 'none', cursor: 'pointer', paddingRight: '20px', outline: 'none' }}
                                >
                                    {groups.length === 0 && <option value="">Crear un grupo...</option>}
                                    {groups.map(g => <option key={g.id} value={g.id}>{g.nombre}</option>)}
                                </select>
                                <button onClick={() => setIsCreatingGroup(true)} style={{background: '#e0e7ff', color: '#4338ca', border: 'none', borderRadius: '50%', width: '32px', height: '32px', cursor: 'pointer', display: 'flex', alignItems: 'center', justifyContent: 'center'}} title="Crear nuevo grupo">
                                    <i className="fas fa-plus"></i>
                                </button>
                                {groups.length > 0 && (
                                    <button onClick={handleDeleteGroup} style={{background: '#fee2e2', color: '#dc2626', border: 'none', borderRadius: '50%', width: '32px', height: '32px', cursor: 'pointer', display: 'flex', alignItems: 'center', justifyContent: 'center', marginLeft: '5px'}} title="Eliminar este grupo">
                                        <i className="fas fa-trash-alt" style={{fontSize: '0.8rem'}}></i>
                                    </button>
                                )}
                            </div>
                        ) : (
                            <div style={{display: 'flex', gap: '10px', alignItems: 'center'}}>
                                <input 
                                    autoFocus
                                    type="text" 
                                    placeholder="Nombre del Grupo (ej. Grupo 1)" 
                                    value={newGroupName}
                                    onChange={(e) => setNewGroupName(e.target.value)}
                                    className="gc-input-add"
                                    style={{width: '250px'}}
                                />
                                <button onClick={handleCreateGroup} className="button" style={{backgroundColor: '#10b981', color: 'white'}}>Guardar</button>
                                <button onClick={() => setIsCreatingGroup(false)} className="button" style={{backgroundColor: '#6b7280', color: 'white'}}>Cancelar</button>
                            </div>
                        )}
                        <p style={{ color: '#6b7280', fontWeight: '500', display: 'flex', alignItems: 'center', gap: '0.5rem', marginTop: '0.5rem' }}>
                            <i className="fas fa-users" style={{ color: '#60a5fa' }}></i>
                            {members.length} Integrantes
                        </p>
                    </div>

                    <div style={{ display: 'flex', gap: '0.75rem', alignItems: 'center', backgroundColor: 'white', padding: '0.5rem', borderRadius: '0.75rem', border: '1px solid #e5e7eb', boxShadow: '0 1px 2px 0 rgba(0,0,0,0.05)' }}>
                        <div style={{ backgroundColor: '#f3f4f6', padding: '0.5rem 0.75rem', borderRadius: '0.5rem', color: '#6b7280' }}>
                            <i className="fas fa-calendar-alt"></i>
                        </div>
                        <input 
                            type="month" 
                            value={currentMonth} 
                            onChange={(e) => setCurrentMonth(e.target.value)}
                            style={{ border: 'none', background: 'transparent', fontWeight: '600', color: '#374151', outline: 'none', cursor: 'pointer' }}
                        />
                    </div>
                </div>
            </div>

            {/* --- ADD MEMBER SECTION (With Autocomplete & Manual Option) --- */}
            {selectedGroupId && (
                <div className="gc-card-add" style={{overflow: 'visible'}}>
                    <div className="gc-label-add">
                        <i className="fas fa-user-plus"></i>
                        Agregar Integrante al {currentGroupName}
                    </div>
                    <div style={{ display: 'flex', flexDirection: 'row', gap: '1rem', flexWrap: 'wrap', position: 'relative' }} ref={suggestionsRef}>
                        <div style={{ position: 'relative', flexGrow: 1 }}>
                            <i className="fas fa-search" style={{ position: 'absolute', left: '1rem', top: '50%', transform: 'translateY(-50%)', color: '#9ca3af', zIndex: 10 }}></i>
                            <input 
                                type="text" 
                                value={addSearchTerm}
                                onChange={(e) => {
                                    setAddSearchTerm(e.target.value);
                                    setShowSuggestions(true);
                                }}
                                onFocus={() => setShowSuggestions(true)}
                                onKeyDown={(e) => {
                                    if (e.key === 'Enter') {
                                        handleAddMember(addSearchTerm);
                                        setShowSuggestions(false);
                                    }
                                }}
                                placeholder="Buscar o escribir nombre nuevo..."
                                className="gc-input-add"
                                autoComplete="off"
                            />
                            {/* Autocomplete Dropdown */}
                            {showSuggestions && addSearchTerm && (
                                <div style={{
                                    position: 'absolute', top: '100%', left: 0, right: 0, 
                                    backgroundColor: 'white', border: '1px solid #e5e7eb', 
                                    borderRadius: '0.75rem', marginTop: '5px', zIndex: 50,
                                    boxShadow: '0 10px 15px -3px rgba(0, 0, 0, 0.1)',
                                    maxHeight: '300px', overflowY: 'auto'
                                }}>
                                    {/* Existing Publishers from DB */}
                                    {filteredSuggestions.map(p => (
                                        <div 
                                            key={p.id}
                                            onClick={() => {
                                                handleAddMember(p.nombre);
                                                setAddSearchTerm(''); 
                                                setShowSuggestions(false);
                                            }}
                                            style={{ padding: '10px 15px', cursor: 'pointer', borderBottom: '1px solid #f3f4f6', display: 'flex', alignItems: 'center', gap: '10px' }}
                                            onMouseEnter={(e) => e.currentTarget.style.backgroundColor = '#f9fafb'}
                                            onMouseLeave={(e) => e.currentTarget.style.backgroundColor = 'white'}
                                        >
                                            <div className={`modern-avatar ${getAvatarClass(p.nombre)}`} style={{width: '24px', height: '24px', fontSize: '0.7rem'}}>
                                                {p.nombre.charAt(0)}
                                            </div>
                                            <span style={{color: '#374151', fontWeight: '500'}}>{p.nombre}</span>
                                            <i className="fas fa-plus" style={{marginLeft: 'auto', color: '#10b981', fontSize: '0.8rem'}}></i>
                                        </div>
                                    ))}

                                    {/* Manual "Add as new" Option (Always visible if text is present) */}
                                    <div 
                                        onClick={() => {
                                            handleAddMember(addSearchTerm);
                                            setAddSearchTerm(''); 
                                            setShowSuggestions(false);
                                        }}
                                        style={{ padding: '10px 15px', cursor: 'pointer', backgroundColor: '#fdf4ff', borderTop: '1px solid #f3f4f6', display: 'flex', alignItems: 'center', gap: '10px' }}
                                        onMouseEnter={(e) => e.currentTarget.style.backgroundColor = '#fce7f3'}
                                        onMouseLeave={(e) => e.currentTarget.style.backgroundColor = '#fdf4ff'}
                                    >
                                        <div style={{width: '24px', height: '24px', display:'flex', alignItems:'center', justifyContent:'center', color: '#d946ef'}}>
                                            <i className="fas fa-pen"></i>
                                        </div>
                                        <div style={{display:'flex', flexDirection:'column'}}>
                                            <span style={{color: '#374151', fontWeight: '600'}}>Agregar "{addSearchTerm}"</span>
                                            <span style={{fontSize: '0.75rem', color: '#d946ef'}}>Nombre manual (no se añade a lista general)</span>
                                        </div>
                                    </div>
                                </div>
                            )}
                        </div>
                        <button 
                            onClick={() => handleAddMember(addSearchTerm)}
                            disabled={!addSearchTerm.trim()}
                            className="gc-btn-add"
                        >
                            <span>Agregar</span>
                            <i className="fas fa-arrow-right"></i>
                        </button>
                    </div>
                </div>
            )}

            {/* Status Toast */}
            {statusMessage && (
                <div style={{ 
                    position: 'fixed', bottom: '1.5rem', right: '1.5rem', zIndex: 100, padding: '1rem 1.5rem', borderRadius: '0.75rem', 
                    boxShadow: '0 10px 15px -3px rgba(0, 0, 0, 0.1)', fontWeight: '600', display: 'flex', alignItems: 'center', gap: '0.75rem',
                    backgroundColor: statusMessage.type === 'success' ? '#059669' : (statusMessage.type === 'info' ? '#3b82f6' : '#dc2626'), color: 'white'
                }}>
                    <i className={`fas ${statusMessage.type === 'success' ? 'fa-check-circle' : (statusMessage.type === 'info' ? 'fa-info-circle' : 'fa-exclamation-circle')}`}></i>
                    {statusMessage.text}
                </div>
            )}

            {/* List Table */}
            {loading ? (
                <div style={{ textAlign: 'center', padding: '5rem 0', color: '#9ca3af' }}>
                    <i className="fas fa-spinner fa-spin fa-3x" style={{ marginBottom: '1rem', color: '#93c5fd' }}></i>
                    <p style={{ fontWeight: '500' }}>Cargando datos...</p>
                </div>
            ) : (
                <div className="modern-card">
                    {/* Desktop Table Header */}
                    <div className="gc-table-header" style={{ display: 'none', gridTemplateColumns: 'repeat(12, minmax(0, 1fr))', borderBottom: '1px solid #e2e8f0', backgroundColor: '#f8fafc' }}>
                        <div style={{ gridColumn: 'span 4', paddingLeft: '1rem' }}>Publicador</div>
                        <div style={{ gridColumn: 'span 3', textAlign: 'center' }}>Horas ({currentMonth.split('-')[1]})</div>
                        <div style={{ gridColumn: 'span 3', textAlign: 'center' }}>Última Visita</div>
                        <div style={{ gridColumn: 'span 2', textAlign: 'center' }}>Acciones</div>
                    </div>
                    <style>{`@media (min-width: 768px) { .gc-table-header { display: grid !important; } }`}</style>

                    <div style={{ display: 'flex', flexDirection: 'column' }}>
                        {filteredMembers.map((m, index) => {
                            const pName = m.publicador_nombre;
                            const reportEntry = reports[pName];

                            // Determine current visual mode based on data
                            let currentMode = 'empty';
                            if (reportEntry) {
                                if (reportEntry.horas === 0) {
                                    currentMode = 'predico';
                                } else if (reportEntry.horas === '' || (typeof reportEntry.horas === 'number' && reportEntry.horas > 0)) {
                                    currentMode = 'horas';
                                }
                            }

                            const visitDate = visits[pName] || '';

                            // Visual cue logic
                            let visitBadgeClass = 'status-badge neutral';
                            let visitLabel = 'Sin registrar';
                            if (visitDate) {
                                const daysSince = (new Date().getTime() - new Date(visitDate).getTime()) / (1000 * 3600 * 24);
                                if (daysSince < 90) { visitBadgeClass = 'status-badge success'; visitLabel = 'Reciente'; } 
                                else if (daysSince < 180) { visitBadgeClass = 'status-badge warning'; visitLabel = 'Atención'; } 
                                else { visitBadgeClass = 'status-badge danger'; visitLabel = 'Urgente'; }
                            }

                            return (
                                <div key={m.id} style={{ 
                                    display: 'grid', gridTemplateColumns: 'repeat(1, minmax(0, 1fr))', gap: '1rem', padding: '1.25rem', 
                                    borderBottom: '1px solid #f1f5f9', alignItems: 'center', transition: 'background-color 0.2s'
                                }}
                                onMouseEnter={(e) => e.currentTarget.style.backgroundColor = '#f8fafc'}
                                onMouseLeave={(e) => e.currentTarget.style.backgroundColor = 'transparent'}
                                className="md:grid-cols-12"
                                >
                                    <style>{`@media (min-width: 768px) { div[key="${m.id}"] { grid-template-columns: repeat(12, minmax(0, 1fr)) !important; } }`}</style>

                                    {/* Name */}
                                    <div style={{ gridColumn: 'span 1', display: 'flex', alignItems: 'center', gap: '1rem' }} className="md:col-span-4">
                                        <div style={{ color: '#9ca3af', fontWeight: '600', minWidth: '1.5rem', textAlign: 'center' }}>
                                            {index + 1}
                                        </div>
                                        <div style={{ fontWeight: '600', color: '#1f2937', fontSize: '1rem' }}>{pName}</div>
                                    </div>

                                    {/* Hours with Selector */}
                                    <div style={{ gridColumn: 'span 1', display: 'flex', justifyContent: 'space-between', alignItems: 'center', backgroundColor: '#f9fafb', padding: '0.75rem', borderRadius: '0.5rem' }} className="md:col-span-3 md:bg-transparent md:justify-center md:p-0">
                                        <span className="md:hidden" style={{ color: '#6b7280', fontSize: '0.875rem', fontWeight: '500' }}>Horas:</span>
                                        <div style={{ display: 'flex', alignItems: 'center', gap: '0.5rem', justifyContent: 'flex-end', width: '100%' }} className="md:justify-center">
                                            <select
                                                value={currentMode}
                                                onChange={(e) => {
                                                    const newMode = e.target.value;
                                                    if (newMode === 'empty') {
                                                        setReports(prev => {
                                                            const next = { ...prev };
                                                            delete next[pName];
                                                            return next;
                                                        });
                                                    } else if (newMode === 'predico') {
                                                        handleReportChange(pName, '0');
                                                    } else if (newMode === 'horas') {
                                                        handleReportChange(pName, ''); // Reset to empty string to encourage input
                                                    }
                                                }}
                                                style={{ 
                                                    padding: '0.4rem 0.5rem', borderRadius: '0.5rem', border: '1px solid #d1d5db', 
                                                    backgroundColor: 'white', fontSize: '0.875rem', color: '#374151', cursor: 'pointer', outline: 'none' 
                                                }}
                                            >
                                                <option value="empty">-- (Vacío)</option>
                                                <option value="predico">Predicó</option>
                                                <option value="horas">Horas</option>
                                            </select>

                                            {currentMode === 'horas' && (
                                                <input 
                                                    type="number" min="0" step="0.5"
                                                    value={reportEntry?.horas === 0 ? '' : (reportEntry?.horas ?? '')}
                                                    onChange={(e) => handleReportChange(pName, e.target.value)}
                                                    autoFocus
                                                    className="input-has-report"
                                                    style={{ 
                                                        width: '4rem', padding: '0.4rem', textAlign: 'center', fontWeight: '700', borderRadius: '0.5rem', 
                                                        border: '2px solid #34d399', outline: 'none', transition: 'all 0.2s', color: '#4b5563', backgroundColor: 'white'
                                                    }}
                                                    placeholder="#"
                                                />
                                            )}
                                        </div>
                                    </div>

                                    {/* Visit */}
                                    <div style={{ gridColumn: 'span 1', display: 'flex', justifyContent: 'space-between', alignItems: 'center', backgroundColor: '#f9fafb', padding: '0.75rem', borderRadius: '0.5rem' }} className="md:col-span-3 md:bg-transparent md:justify-center md:p-0">
                                        <span className="md:hidden" style={{ color: '#6b7280', fontSize: '0.875rem', fontWeight: '500' }}>Visita:</span>
                                        <div style={{ display: 'flex', flexDirection: 'column', alignItems: 'flex-end', gap: '0.25rem', width: '100%' }} className="md:w-auto md:items-center">
                                            <input 
                                                type="date" value={visitDate}
                                                onChange={(e) => handleVisitChange(pName, e.target.value)}
                                                className="modern-input"
                                                style={{ padding: '0.25rem 0.5rem', fontSize: '0.875rem', width: '100%', color: '#4b5563', fontWeight: '500', textAlign: 'right' }}
                                            />
                                            <span className={visitBadgeClass}>
                                                <i className="fas fa-circle" style={{ fontSize: '0.5rem' }}></i> {visitLabel}
                                            </span>
                                        </div>
                                    </div>

                                    {/* Actions */}
                                    <div style={{ gridColumn: 'span 1', display: 'flex', justifyContent: 'flex-end', gap: '0.75rem', marginTop: '0.5rem' }} className="md:col-span-2 md:justify-center md:mt-0">
                                        <button 
                                            onClick={() => handleSaveRow(pName)}
                                            style={{ background: 'linear-gradient(135deg, #4f46e5 0%, #4338ca 100%)', color: 'white', padding: '0.5rem 1rem', borderRadius: '0.5rem', border: 'none', cursor: 'pointer', display: 'flex', alignItems: 'center', gap: '0.5rem', fontSize: '0.875rem', fontWeight: '600', boxShadow: '0 4px 6px -1px rgba(79, 70, 229, 0.2)' }}
                                            title="Guardar cambios"
                                        >
                                            <i className="fas fa-save"></i> <span className="md:hidden">Guardar</span>
                                        </button>
                                        <button 
                                            onClick={() => handleDeleteMember(m.id, pName)}
                                            style={{ padding: '0.5rem', color: '#9ca3af', backgroundColor: 'transparent', border: '1px solid transparent', borderRadius: '0.5rem', cursor: 'pointer', transition: 'color 0.2s' }}
                                            onMouseEnter={(e) => { e.currentTarget.style.color = '#ef4444'; e.currentTarget.style.backgroundColor = '#fef2f2'; }}
                                            onMouseLeave={(e) => { e.currentTarget.style.color = '#9ca3af'; e.currentTarget.style.backgroundColor = 'transparent'; }}
                                            title="Quitar del grupo"
                                        >
                                            <i className="fas fa-trash-alt"></i>
                                        </button>
                                    </div>
                                </div>
                            );
                        })}
                    </div>
                    {filteredMembers.length === 0 && (
                        <div style={{ padding: '5rem 0', textAlign: 'center', backgroundColor: '#f8fafc' }}>
                            <div style={{ backgroundColor: 'white', width: '6rem', height: '6rem', borderRadius: '50%', display: 'flex', alignItems: 'center', justifyContent: 'center', margin: '0 auto 1.5rem auto', boxShadow: '0 1px 2px 0 rgba(0,0,0,0.05)', border: '1px solid #e2e8f0' }}>
                                <i className="fas fa-users fa-3x" style={{ color: '#c7d2fe' }}></i>
                            </div>
                            <h3 style={{ fontSize: '1.25rem', fontWeight: '700', color: '#374151' }}>
                                {selectedGroupId ? 'Este grupo está vacío' : 'Crea o selecciona un grupo'}
                            </h3>
                            <p style={{ color: '#6b7280', marginTop: '0.5rem', maxWidth: '24rem', marginInline: 'auto' }}>
                                Utiliza el buscador de arriba para agregar publicadores existentes a este grupo.
                            </p>
                        </div>
                    )}
                </div>
            )}
        </div>
    );
};

export default GrupoCongregacion;

import React, { useState, useEffect, useRef } from 'react';
import { supabase } from '../lib/supabase';

type Publisher = {
    id: number;
    nombre: string;
};

type Group = {
    id: number;
    nombre: string;
};

type GroupMember = {
    id: number;
    grupo_id: number;
    publicador_nombre: string;
};

type MinistryReport = {
    horas: number | '';
    notas?: string;
};

type ReportsMap = Record<string, MinistryReport>;
type VisitsMap = Record<string, string>;

// Helper for avatar colors
const getAvatarClass = (name: string) => {
    const classes = ['avatar-red', 'avatar-orange', 'avatar-amber', 'avatar-green', 'avatar-teal', 'avatar-blue', 'avatar-indigo', 'avatar-purple', 'avatar-pink'];
    let hash = 0;
    for (let i = 0; i < name.length; i++) {
        hash = name.charCodeAt(i) + ((hash << 5) - hash);
    }
    return classes[Math.abs(hash) % classes.length];
};

const GrupoCongregacion: React.FC = () => {
    // Data State
    const [groups, setGroups] = useState<Group[]>([]);
    const [selectedGroupId, setSelectedGroupId] = useState<number | null>(null);
    const [members, setMembers] = useState<GroupMember[]>([]);
    const [masterPublishers, setMasterPublishers] = useState<Publisher[]>([]); // All publishers from DB

    // UI State
    const [loading, setLoading] = useState(true);
    const [currentMonth, setCurrentMonth] = useState<string>('');
    const [reports, setReports] = useState<ReportsMap>({});
    const [visits, setVisits] = useState<VisitsMap>({});
    const [searchTerm, setSearchTerm] = useState('');
    const [addSearchTerm, setAddSearchTerm] = useState(''); // Search input for adding
    const [showSuggestions, setShowSuggestions] = useState(false);
    const [isCreatingGroup, setIsCreatingGroup] = useState(false);
    const [newGroupName, setNewGroupName] = useState('');
    const [statusMessage, setStatusMessage] = useState<{ text: string; type: 'success' | 'error' | 'info' } | null>(null);

    const suggestionsRef = useRef<HTMLDivElement>(null);

    // Initial Load
    useEffect(() => {
        const now = new Date();
        const yyyy = now.getFullYear();
        const mm = String(now.getMonth() + 1).padStart(2, '0');
        setCurrentMonth(`${yyyy}-${mm}`);

        fetchGroups();
        fetchMasterPublishers();

        // Close suggestions on click outside
        const handleClickOutside = (event: MouseEvent) => {
            if (suggestionsRef.current && !suggestionsRef.current.contains(event.target as Node)) {
                setShowSuggestions(false);
            }
        };
        document.addEventListener('mousedown', handleClickOutside);
        return () => document.removeEventListener('mousedown', handleClickOutside);
    }, []);

    // Load Data Functions
    const fetchGroups = async () => {
        const { data, error } = await supabase.from('grupos').select('*').order('nombre');
        if (error) {
            console.error("Error fetching groups:", error);
        } else if (data) {
            setGroups(data);
            if (data.length > 0 && !selectedGroupId) {
                // Try to find "Grupo 5" first, else default to first
                const defaultGroup = data.find(g => g.nombre.includes('5')) || data[0];
                setSelectedGroupId(defaultGroup.id);
            }
        }
    };

    const fetchMasterPublishers = async () => {
        const { data } = await supabase.from('publicadores').select('id, nombre').order('nombre');
        if (data) setMasterPublishers(data);
    };

    const fetchMembers = async () => {
        if (!selectedGroupId) return;
        setLoading(true);
        const { data, error } = await supabase
            .from('miembros_grupo')
            .select('*')
            .eq('grupo_id', selectedGroupId)
            .order('publicador_nombre');

        if (error) console.error("Error fetching members:", error);
        else setMembers(data || []);
        setLoading(false);
    };

    // Load Members when Group Changes
    useEffect(() => {
        fetchMembers();
    }, [selectedGroupId]);

    // Load Reports/Visits when Members or Month Change
    useEffect(() => {
        if (!currentMonth || members.length === 0) return;

        const fetchData = async () => {
            // Get reports only for current members
            const memberNames = members.map(m => m.publicador_nombre);

            const { data: reportsData } = await supabase
                .from('informes_ministerio')
                .select('publicador_nombre, horas')
                .eq('mes', currentMonth)
                .in('publicador_nombre', memberNames);

            const newReports: ReportsMap = {};
            if (reportsData) {
                reportsData.forEach((r: any) => {
                    newReports[r.publicador_nombre] = { horas: r.horas };
                });
            }
            setReports(newReports);

            const { data: visitsData } = await supabase
                .from('visitas_pastoral')
                .select('publicador_nombre, fecha_visita')
                .in('publicador_nombre', memberNames);

            const newVisits: VisitsMap = {};
            if (visitsData) {
                visitsData.forEach((v: any) => {
                    newVisits[v.publicador_nombre] = v.fecha_visita;
                });
            }
            setVisits(newVisits);
        };

        fetchData();
    }, [currentMonth, members]);

    // --- Actions ---

    const handleCreateGroup = async () => {
        if (!newGroupName.trim()) return;
        const normalizedName = newGroupName.trim();

        const { data, error } = await supabase.from('grupos').insert([{ nombre: normalizedName }]).select();

        if (error) {
            // Check for duplicate key error code (Postgres unique violation)
            if (error.code === '23505') {
                const { data: existingGroup } = await supabase
                    .from('grupos')
                    .select('*')
                    .eq('nombre', normalizedName)
                    .single();

                if (existingGroup) {
                    setGroups(prev => {
                        if (prev.some(g => g.id === existingGroup.id)) return prev;
                        return [...prev, existingGroup].sort((a,b) => a.nombre.localeCompare(b.nombre));
                    });
                    setSelectedGroupId(existingGroup.id);
                    setIsCreatingGroup(false);
                    setNewGroupName('');
                    setStatusMessage({ text: `El grupo "${normalizedName}" ya existe. Seleccionado.`, type: 'info' });
                    setTimeout(() => setStatusMessage(null), 3000);
                    return; 
                }
            }

            console.error("Error creating group:", error);
            setStatusMessage({ text: `Error: ${error.message}`, type: 'error' });
            setTimeout(() => setStatusMessage(null), 4000);
        } else if (data) {
            setGroups(prev => [...prev, data[0]].sort((a,b) => a.nombre.localeCompare(b.nombre)));
            setSelectedGroupId(data[0].id);
            setIsCreatingGroup(false);
            setNewGroupName('');
            setStatusMessage({ text: 'Grupo creado con éxito', type: 'success' });
            setTimeout(() => setStatusMessage(null), 3000);
        }
    };

    const handleDeleteGroup = async () => {
        if (!selectedGroupId) return;
        const groupName = groups.find(g => g.id === selectedGroupId)?.nombre;
        if (!window.confirm(`¿Estás seguro de eliminar el "${groupName}" y todos sus integrantes?`)) return;

        const { error } = await supabase.from('grupos').delete().eq('id', selectedGroupId);
        if (error) {
            console.error("Error deleting group:", error);
            setStatusMessage({ text: `Error al eliminar: ${error.message}`, type: 'error' });
        } else {
            const remaining = groups.filter(g => g.id !== selectedGroupId);
            setGroups(remaining);
            setSelectedGroupId(remaining.length > 0 ? remaining[0].id : null);
            setMembers([]);
            setStatusMessage({ text: 'Grupo eliminado', type: 'success' });
            setTimeout(() => setStatusMessage(null), 3000);
        }
    };

    const handleAddMember = async (name: string) => {
        if (!selectedGroupId || !name.trim()) return;

        // Check local duplicate
        if (members.some(m => m.publicador_nombre.toLowerCase() === name.toLowerCase())) {
            setStatusMessage({ text: 'Esta persona ya está en el grupo', type: 'error' });
            setTimeout(() => setStatusMessage(null), 3000);
            return;
        }

        const { error } = await supabase.from('miembros_grupo').insert([{
            grupo_id: selectedGroupId,
            publicador_nombre: name.trim()
        }]);

        if (error) {
            console.error(error);
            setStatusMessage({ text: `Error al agregar: ${error.message}`, type: 'error' });
        } else {
            setStatusMessage({ text: 'Agregado correctamente', type: 'success' });
            setAddSearchTerm('');
            fetchMembers();
        }
        setTimeout(() => setStatusMessage(null), 3000);
    };

    const handleDeleteMember = async (id: number, name: string) => {
        if (!window.confirm(`¿Quitar a ${name} de este grupo?`)) return;
        const { error } = await supabase.from('miembros_grupo').delete().eq('id', id);
        if (!error) fetchMembers();
        else console.error("Error deleting member:", error);
    };

    const handleReportChange = (name: string, value: string) => {
        setReports(prev => ({
            ...prev,
            [name]: { ...prev[name], horas: value === '' ? '' : Number(value) }
        }));
    };

    const handleVisitChange = (name: string, date: string) => {
        setVisits(prev => ({
            ...prev,
            [name]: date
        }));
    };

    const handleSaveRow = async (publisherName: string) => {
        setStatusMessage(null);
        try {
            // --- Save Report Logic ---
            const reportEntry = reports[publisherName];

            if (reportEntry) {
                // If checkbox is active (exists in state), upsert report
                // Note: If 'Predicó' was selected, horas will be 0. If 'Horas' selected, it will be > 0.
                const valToSave = reportEntry.horas === '' ? 0 : reportEntry.horas;

                const { error: reportError } = await supabase
                    .from('informes_ministerio')
                    .upsert({ 
                        publicador_nombre: publisherName, 
                        mes: currentMonth, 
                        horas: valToSave 
                    }, { onConflict: 'publicador_nombre, mes' });
                if (reportError) throw reportError;
            } else {
                // If reportEntry is missing (User selected 'Vacío'), delete report from DB
                const { error: deleteError } = await supabase
                    .from('informes_ministerio')
                    .delete()
                    .eq('publicador_nombre', publisherName)
                    .eq('mes', currentMonth);

                // We ignore if it didn't exist, but supabase delete won't error on 0 rows
                if (deleteError) throw deleteError;
            }

            // --- Save Visit Logic ---
            const visitDate = visits[publisherName];
            if (visitDate) {
                const { error: visitError } = await supabase
                    .from('visitas_pastoral')
                    .upsert({ 
                        publicador_nombre: publisherName, 
                        fecha_visita: visitDate 
                    }, { onConflict: 'publicador_nombre' });
                if (visitError) throw visitError;
            }

            setStatusMessage({ text: 'Guardado', type: 'success' });
            setTimeout(() => setStatusMessage(null), 2000);
        } catch (err: any) {
            console.error(err);
            setStatusMessage({ text: 'Error al guardar', type: 'error' });
        }
    };

    // Filter Logic for Main Table
    const filteredMembers = members.filter(m => 
        m.publicador_nombre.toLowerCase().includes(searchTerm.toLowerCase())
    );

    // Filter Logic for Add Suggestions
    const filteredSuggestions = masterPublishers
        .filter(p => p.nombre.toLowerCase().includes(addSearchTerm.toLowerCase()))
        .filter(p => !members.some(m => m.publicador_nombre === p.nombre)) // Exclude already in group
        .slice(0, 6); // Limit results

    const currentGroupName = groups.find(g => g.id === selectedGroupId)?.nombre || 'Sin Grupo';

    return (
        <div className="container mx-auto px-4 py-8 group-container">

            {/* --- TOP BAR: Group Selector & Date --- */}
            <div style={{ display: 'flex', flexDirection: 'column', gap: '1.5rem', marginBottom: '2rem' }}>
                <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', flexWrap: 'wrap', gap: '1rem' }}>
                    <div style={{flex: 1}}>
                        {!isCreatingGroup ? (
                            <div style={{display: 'flex', alignItems: 'center', gap: '10px'}}>
                                <select 
                                    value={selectedGroupId || ''} 
                                    onChange={(e) => setSelectedGroupId(Number(e.target.value))}
                                    className="gc-header-title"
                                    style={{ background: 'transparent', border: 'none', cursor: 'pointer', paddingRight: '20px', outline: 'none' }}
                                >
                                    {groups.length === 0 && <option value="">Crear un grupo...</option>}
                                    {groups.map(g => <option key={g.id} value={g.id}>{g.nombre}</option>)}
                                </select>
                                <button onClick={() => setIsCreatingGroup(true)} style={{background: '#e0e7ff', color: '#4338ca', border: 'none', borderRadius: '50%', width: '32px', height: '32px', cursor: 'pointer', display: 'flex', alignItems: 'center', justifyContent: 'center'}} title="Crear nuevo grupo">
                                    <i className="fas fa-plus"></i>
                                </button>
                                {groups.length > 0 && (
                                    <button onClick={handleDeleteGroup} style={{background: '#fee2e2', color: '#dc2626', border: 'none', borderRadius: '50%', width: '32px', height: '32px', cursor: 'pointer', display: 'flex', alignItems: 'center', justifyContent: 'center', marginLeft: '5px'}} title="Eliminar este grupo">
                                        <i className="fas fa-trash-alt" style={{fontSize: '0.8rem'}}></i>
                                    </button>
                                )}
                            </div>
                        ) : (
                            <div style={{display: 'flex', gap: '10px', alignItems: 'center'}}>
                                <input 
                                    autoFocus
                                    type="text" 
                                    placeholder="Nombre del Grupo (ej. Grupo 1)" 
                                    value={newGroupName}
                                    onChange={(e) => setNewGroupName(e.target.value)}
                                    className="gc-input-add"
                                    style={{width: '250px'}}
                                />
                                <button onClick={handleCreateGroup} className="button" style={{backgroundColor: '#10b981', color: 'white'}}>Guardar</button>
                                <button onClick={() => setIsCreatingGroup(false)} className="button" style={{backgroundColor: '#6b7280', color: 'white'}}>Cancelar</button>
                            </div>
                        )}
                        <p style={{ color: '#6b7280', fontWeight: '500', display: 'flex', alignItems: 'center', gap: '0.5rem', marginTop: '0.5rem' }}>
                            <i className="fas fa-users" style={{ color: '#60a5fa' }}></i>
                            {members.length} Integrantes
                        </p>
                    </div>

                    <div style={{ display: 'flex', gap: '0.75rem', alignItems: 'center', backgroundColor: 'white', padding: '0.5rem', borderRadius: '0.75rem', border: '1px solid #e5e7eb', boxShadow: '0 1px 2px 0 rgba(0,0,0,0.05)' }}>
                        <div style={{ backgroundColor: '#f3f4f6', padding: '0.5rem 0.75rem', borderRadius: '0.5rem', color: '#6b7280' }}>
                            <i className="fas fa-calendar-alt"></i>
                        </div>
                        <input 
                            type="month" 
                            value={currentMonth} 
                            onChange={(e) => setCurrentMonth(e.target.value)}
                            style={{ border: 'none', background: 'transparent', fontWeight: '600', color: '#374151', outline: 'none', cursor: 'pointer' }}
                        />
                    </div>
                </div>
            </div>

            {/* --- ADD MEMBER SECTION (With Autocomplete & Manual Option) --- */}
            {selectedGroupId && (
                <div className="gc-card-add" style={{overflow: 'visible'}}>
                    <div className="gc-label-add">
                        <i className="fas fa-user-plus"></i>
                        Agregar Integrante al {currentGroupName}
                    </div>
                    <div style={{ display: 'flex', flexDirection: 'row', gap: '1rem', flexWrap: 'wrap', position: 'relative' }} ref={suggestionsRef}>
                        <div style={{ position: 'relative', flexGrow: 1 }}>
                            <i className="fas fa-search" style={{ position: 'absolute', left: '1rem', top: '50%', transform: 'translateY(-50%)', color: '#9ca3af', zIndex: 10 }}></i>
                            <input 
                                type="text" 
                                value={addSearchTerm}
                                onChange={(e) => {
                                    setAddSearchTerm(e.target.value);
                                    setShowSuggestions(true);
                                }}
                                onFocus={() => setShowSuggestions(true)}
                                onKeyDown={(e) => {
                                    if (e.key === 'Enter') {
                                        handleAddMember(addSearchTerm);
                                        setShowSuggestions(false);
                                    }
                                }}
                                placeholder="Buscar o escribir nombre nuevo..."
                                className="gc-input-add"
                                autoComplete="off"
                            />
                            {/* Autocomplete Dropdown */}
                            {showSuggestions && addSearchTerm && (
                                <div style={{
                                    position: 'absolute', top: '100%', left: 0, right: 0, 
                                    backgroundColor: 'white', border: '1px solid #e5e7eb', 
                                    borderRadius: '0.75rem', marginTop: '5px', zIndex: 50,
                                    boxShadow: '0 10px 15px -3px rgba(0, 0, 0, 0.1)',
                                    maxHeight: '300px', overflowY: 'auto'
                                }}>
                                    {/* Existing Publishers from DB */}
                                    {filteredSuggestions.map(p => (
                                        <div 
                                            key={p.id}
                                            onClick={() => {
                                                handleAddMember(p.nombre);
                                                setAddSearchTerm(''); 
                                                setShowSuggestions(false);
                                            }}
                                            style={{ padding: '10px 15px', cursor: 'pointer', borderBottom: '1px solid #f3f4f6', display: 'flex', alignItems: 'center', gap: '10px' }}
                                            onMouseEnter={(e) => e.currentTarget.style.backgroundColor = '#f9fafb'}
                                            onMouseLeave={(e) => e.currentTarget.style.backgroundColor = 'white'}
                                        >
                                            <div className={`modern-avatar ${getAvatarClass(p.nombre)}`} style={{width: '24px', height: '24px', fontSize: '0.7rem'}}>
                                                {p.nombre.charAt(0)}
                                            </div>
                                            <span style={{color: '#374151', fontWeight: '500'}}>{p.nombre}</span>
                                            <i className="fas fa-plus" style={{marginLeft: 'auto', color: '#10b981', fontSize: '0.8rem'}}></i>
                                        </div>
                                    ))}

                                    {/* Manual "Add as new" Option (Always visible if text is present) */}
                                    <div 
                                        onClick={() => {
                                            handleAddMember(addSearchTerm);
                                            setAddSearchTerm(''); 
                                            setShowSuggestions(false);
                                        }}
                                        style={{ padding: '10px 15px', cursor: 'pointer', backgroundColor: '#fdf4ff', borderTop: '1px solid #f3f4f6', display: 'flex', alignItems: 'center', gap: '10px' }}
                                        onMouseEnter={(e) => e.currentTarget.style.backgroundColor = '#fce7f3'}
                                        onMouseLeave={(e) => e.currentTarget.style.backgroundColor = '#fdf4ff'}
                                    >
                                        <div style={{width: '24px', height: '24px', display:'flex', alignItems:'center', justifyContent:'center', color: '#d946ef'}}>
                                            <i className="fas fa-pen"></i>
                                        </div>
                                        <div style={{display:'flex', flexDirection:'column'}}>
                                            <span style={{color: '#374151', fontWeight: '600'}}>Agregar "{addSearchTerm}"</span>
                                            <span style={{fontSize: '0.75rem', color: '#d946ef'}}>Nombre manual (no se añade a lista general)</span>
                                        </div>
                                    </div>
                                </div>
                            )}
                        </div>
                        <button 
                            onClick={() => handleAddMember(addSearchTerm)}
                            disabled={!addSearchTerm.trim()}
                            className="gc-btn-add"
                        >
                            <span>Agregar</span>
                            <i className="fas fa-arrow-right"></i>
                        </button>
                    </div>
                </div>
            )}

            {/* Status Toast */}
            {statusMessage && (
                <div style={{ 
                    position: 'fixed', bottom: '1.5rem', right: '1.5rem', zIndex: 100, padding: '1rem 1.5rem', borderRadius: '0.75rem', 
                    boxShadow: '0 10px 15px -3px rgba(0, 0, 0, 0.1)', fontWeight: '600', display: 'flex', alignItems: 'center', gap: '0.75rem',
                    backgroundColor: statusMessage.type === 'success' ? '#059669' : (statusMessage.type === 'info' ? '#3b82f6' : '#dc2626'), color: 'white'
                }}>
                    <i className={`fas ${statusMessage.type === 'success' ? 'fa-check-circle' : (statusMessage.type === 'info' ? 'fa-info-circle' : 'fa-exclamation-circle')}`}></i>
                    {statusMessage.text}
                </div>
            )}

            {/* List Table */}
            {loading ? (
                <div style={{ textAlign: 'center', padding: '5rem 0', color: '#9ca3af' }}>
                    <i className="fas fa-spinner fa-spin fa-3x" style={{ marginBottom: '1rem', color: '#93c5fd' }}></i>
                    <p style={{ fontWeight: '500' }}>Cargando datos...</p>
                </div>
            ) : (
                <div className="modern-card">
                    {/* Desktop Table Header */}
                    <div className="gc-table-header hidden md:grid md:grid-cols-12 md:gap-4 md:border-b md:border-slate-200 md:bg-slate-50 md:p-4">
                        <div className="col-span-4 pl-4">Publicador</div>
                        <div className="col-span-3 text-center">Horas ({currentMonth.split('-')[1]})</div>
                        <div className="col-span-3 text-center">Última Visita</div>
                        <div className="col-span-2 text-center">Acciones</div>
                    </div>

                    <div style={{ display: 'flex', flexDirection: 'column' }}>
                        {filteredMembers.map((m, index) => {
                            const pName = m.publicador_nombre;
                            const reportEntry = reports[pName];

                            // Determine current visual mode based on data
                            let currentMode = 'empty';
                            if (reportEntry) {
                                if (reportEntry.horas === 0) {
                                    currentMode = 'predico';
                                } else if (reportEntry.horas === '' || (typeof reportEntry.horas === 'number' && reportEntry.horas > 0)) {
                                    currentMode = 'horas';
                                }
                            }

                            const visitDate = visits[pName] || '';

                            // Visual cue logic
                            let visitBadgeClass = 'status-badge neutral';
                            let visitLabel = 'Sin registrar';
                            if (visitDate) {
                                const daysSince = (new Date().getTime() - new Date(visitDate).getTime()) / (1000 * 3600 * 24);
                                if (daysSince < 90) { visitBadgeClass = 'status-badge success'; visitLabel = 'Reciente'; } 
                                else if (daysSince < 180) { visitBadgeClass = 'status-badge warning'; visitLabel = 'Atención'; } 
                                else { visitBadgeClass = 'status-badge danger'; visitLabel = 'Urgente'; }
                            }

                            return (
                                <div key={m.id} className="grid grid-cols-2 gap-3 p-3 border-b border-slate-100 items-center transition-colors hover:bg-slate-50 md:grid-cols-12 md:gap-4 md:p-5">

                                    {/* Name: Spans 2 cols on mobile (full width), 4 on desktop */}
                                    <div className="col-span-2 flex items-center gap-3 md:col-span-4">
                                        <div className="text-gray-400 font-semibold min-w-[1.5rem] text-center text-sm">{index + 1}</div>
                                        <div className="font-semibold text-gray-800 text-base">{pName}</div>
                                    </div>

                                    {/* Hours: Spans 1 col on mobile (half), 3 on desktop */}
                                    <div className="col-span-1 flex flex-col items-center bg-gray-50 p-2 rounded-lg md:col-span-3 md:flex-row md:justify-center md:bg-transparent md:p-0">
                                        <span className="md:hidden text-xs text-gray-500 font-bold uppercase mb-1">Horas</span>
                                        <div className="flex items-center gap-2 justify-center w-full">
                                            <select
                                                value={currentMode}
                                                onChange={(e) => {
                                                    const newMode = e.target.value;
                                                    if (newMode === 'empty') {
                                                        setReports(prev => {
                                                            const next = { ...prev };
                                                            delete next[pName];
                                                            return next;
                                                        });
                                                    } else if (newMode === 'predico') {
                                                        handleReportChange(pName, '0');
                                                    } else if (newMode === 'horas') {
                                                        handleReportChange(pName, ''); // Reset to empty string to encourage input
                                                    }
                                                }}
                                                style={{ 
                                                    padding: '0.3rem 0.4rem', borderRadius: '0.4rem', border: '1px solid #d1d5db', 
                                                    backgroundColor: 'white', fontSize: '0.8rem', color: '#374151', cursor: 'pointer', outline: 'none' 
                                                }}
                                            >
                                                <option value="empty">-- (Vacío)</option>
                                                <option value="predico">Predicó</option>
                                                <option value="horas">Horas</option>
                                            </select>

                                            {currentMode === 'horas' && (
                                                <input 
                                                    type="number" min="0" step="0.5"
                                                    value={reportEntry?.horas === 0 ? '' : (reportEntry?.horas ?? '')}
                                                    onChange={(e) => handleReportChange(pName, e.target.value)}
                                                    autoFocus
                                                    className="input-has-report"
                                                    style={{ 
                                                        width: '3.5rem', padding: '0.3rem', textAlign: 'center', fontWeight: '700', borderRadius: '0.4rem', 
                                                        border: '2px solid #34d399', outline: 'none', transition: 'all 0.2s', color: '#4b5563', backgroundColor: 'white', fontSize: '0.9rem'
                                                    }}
                                                    placeholder="#"
                                                />
                                            )}
                                        </div>
                                    </div>

                                    {/* Visit: Spans 1 col on mobile (half), 3 on desktop */}
                                    <div className="col-span-1 flex flex-col items-center bg-gray-50 p-2 rounded-lg md:col-span-3 md:flex-row md:justify-center md:bg-transparent md:p-0">
                                        <span className="md:hidden text-xs text-gray-500 font-bold uppercase mb-1">Visita</span>
                                        <div className="flex flex-col items-end gap-1 w-full md:w-auto md:items-center">
                                            <input 
                                                type="date" value={visitDate}
                                                onChange={(e) => handleVisitChange(pName, e.target.value)}
                                                className="modern-input"
                                                style={{ padding: '0.2rem 0.4rem', fontSize: '0.8rem', width: '100%', color: '#4b5563', fontWeight: '500', textAlign: 'center', borderRadius: '0.4rem', border: '1px solid #d1d5db' }}
                                            />
                                            <span className={visitBadgeClass} style={{fontSize: '0.7rem', padding: '2px 6px'}}>
                                                <i className="fas fa-circle" style={{ fontSize: '0.4rem', marginRight: '3px' }}></i> {visitLabel}
                                            </span>
                                        </div>
                                    </div>

                                    {/* Actions: Spans 2 cols on mobile (full width), 2 on desktop */}
                                    <div className="col-span-2 flex justify-end gap-3 pt-1 border-t border-slate-100 md:col-span-2 md:justify-center md:border-0 md:pt-0">
                                        <button 
                                            onClick={() => handleSaveRow(pName)}
                                            style={{ background: 'linear-gradient(135deg, #4f46e5 0%, #4338ca 100%)', color: 'white', padding: '0.4rem 0.8rem', borderRadius: '0.4rem', border: 'none', cursor: 'pointer', display: 'flex', alignItems: 'center', gap: '0.4rem', fontSize: '0.8rem', fontWeight: '600', boxShadow: '0 2px 4px rgba(79, 70, 229, 0.2)' }}
                                            title="Guardar cambios"
                                        >
                                            <i className="fas fa-save"></i> <span>Guardar</span>
                                        </button>
                                        <button 
                                            onClick={() => handleDeleteMember(m.id, pName)}
                                            style={{ padding: '0.4rem', color: '#9ca3af', backgroundColor: 'transparent', border: '1px solid transparent', borderRadius: '0.4rem', cursor: 'pointer', transition: 'color 0.2s' }}
                                            onMouseEnter={(e) => { e.currentTarget.style.color = '#ef4444'; e.currentTarget.style.backgroundColor = '#fef2f2'; }}
                                            onMouseLeave={(e) => { e.currentTarget.style.color = '#9ca3af'; e.currentTarget.style.backgroundColor = 'transparent'; }}
                                            title="Quitar del grupo"
                                        >
                                            <i className="fas fa-trash-alt"></i>
                                        </button>
                                    </div>
                                </div>
                            );
                        })}
                    </div>
                    {filteredMembers.length === 0 && (
                        <div style={{ padding: '5rem 0', textAlign: 'center', backgroundColor: '#f8fafc' }}>
                            <div style={{ backgroundColor: 'white', width: '6rem', height: '6rem', borderRadius: '50%', display: 'flex', alignItems: 'center', justifyContent: 'center', margin: '0 auto 1.5rem auto', boxShadow: '0 1px 2px 0 rgba(0,0,0,0.05)', border: '1px solid #e2e8f0' }}>
                                <i className="fas fa-users fa-3x" style={{ color: '#c7d2fe' }}></i>
                            </div>
                            <h3 style={{ fontSize: '1.25rem', fontWeight: '700', color: '#374151' }}>
                                {selectedGroupId ? 'Este grupo está vacío' : 'Crea o selecciona un grupo'}
                            </h3>
                            <p style={{ color: '#6b7280', marginTop: '0.5rem', maxWidth: '24rem', marginInline: 'auto' }}>
                                Utiliza el buscador de arriba para agregar publicadores existentes a este grupo.
                            </p>
                        </div>
                    )}
                </div>
            )}
        </div>
    );
};

export default GrupoCongregacion;

import React, { useState, useEffect, useRef } from 'react';
import { supabase } from '../lib/supabase';

type Publisher = {
    id: number;
    nombre: string;
};

type Group = {
    id: number;
    nombre: string;
};

type GroupMember = {
    id: number;
    grupo_id: number;
    publicador_nombre: string;
};

type MinistryReport = {
    horas: number | '';
    notas?: string;
};

type ReportsMap = Record<string, MinistryReport>;
type VisitsMap = Record<string, string>;

// Helper for avatar colors
const getAvatarClass = (name: string) => {
    const classes = ['avatar-red', 'avatar-orange', 'avatar-amber', 'avatar-green', 'avatar-teal', 'avatar-blue', 'avatar-indigo', 'avatar-purple', 'avatar-pink'];
    let hash = 0;
    for (let i = 0; i < name.length; i++) {
        hash = name.charCodeAt(i) + ((hash << 5) - hash);
    }
    return classes[Math.abs(hash) % classes.length];
};

const GrupoCongregacion: React.FC = () => {
    // Data State
    const [groups, setGroups] = useState<Group[]>([]);
    const [selectedGroupId, setSelectedGroupId] = useState<number | null>(null);
    const [members, setMembers] = useState<GroupMember[]>([]);
    const [masterPublishers, setMasterPublishers] = useState<Publisher[]>([]); // All publishers from DB

    // UI State
    const [loading, setLoading] = useState(true);
    const [currentMonth, setCurrentMonth] = useState<string>('');
    const [reports, setReports] = useState<ReportsMap>({});
    const [visits, setVisits] = useState<VisitsMap>({});
    const [searchTerm, setSearchTerm] = useState('');
    const [addSearchTerm, setAddSearchTerm] = useState(''); // Search input for adding
    const [showSuggestions, setShowSuggestions] = useState(false);
    const [isCreatingGroup, setIsCreatingGroup] = useState(false);
    const [newGroupName, setNewGroupName] = useState('');
    const [statusMessage, setStatusMessage] = useState<{ text: string; type: 'success' | 'error' | 'info' } | null>(null);

    const suggestionsRef = useRef<HTMLDivElement>(null);

    // Initial Load
    useEffect(() => {
        const now = new Date();
        const yyyy = now.getFullYear();
        const mm = String(now.getMonth() + 1).padStart(2, '0');
        setCurrentMonth(`${yyyy}-${mm}`);

        fetchGroups();
        fetchMasterPublishers();

        // Close suggestions on click outside
        const handleClickOutside = (event: MouseEvent) => {
            if (suggestionsRef.current && !suggestionsRef.current.contains(event.target as Node)) {
                setShowSuggestions(false);
            }
        };
        document.addEventListener('mousedown', handleClickOutside);
        return () => document.removeEventListener('mousedown', handleClickOutside);
    }, []);

    // Load Data Functions
    const fetchGroups = async () => {
        const { data, error } = await supabase.from('grupos').select('*').order('nombre');
        if (error) {
            console.error("Error fetching groups:", error);
        } else if (data) {
            setGroups(data);
            if (data.length > 0 && !selectedGroupId) {
                // Try to find "Grupo 5" first, else default to first
                const defaultGroup = data.find(g => g.nombre.includes('5')) || data[0];
                setSelectedGroupId(defaultGroup.id);
            }
        }
    };

    const fetchMasterPublishers = async () => {
        const { data } = await supabase.from('publicadores').select('id, nombre').order('nombre');
        if (data) setMasterPublishers(data);
    };

    const fetchMembers = async () => {
        if (!selectedGroupId) return;
        setLoading(true);
        const { data, error } = await supabase
            .from('miembros_grupo')
            .select('*')
            .eq('grupo_id', selectedGroupId)
            .order('publicador_nombre');

        if (error) console.error("Error fetching members:", error);
        else setMembers(data || []);
        setLoading(false);
    };

    // Load Members when Group Changes
    useEffect(() => {
        fetchMembers();
    }, [selectedGroupId]);

    // Load Reports/Visits when Members or Month Change
    useEffect(() => {
        if (!currentMonth || members.length === 0) return;

        const fetchData = async () => {
            // Get reports only for current members
            const memberNames = members.map(m => m.publicador_nombre);

            const { data: reportsData } = await supabase
                .from('informes_ministerio')
                .select('publicador_nombre, horas')
                .eq('mes', currentMonth)
                .in('publicador_nombre', memberNames);

            const newReports: ReportsMap = {};
            if (reportsData) {
                reportsData.forEach((r: any) => {
                    newReports[r.publicador_nombre] = { horas: r.horas };
                });
            }
            setReports(newReports);

            const { data: visitsData } = await supabase
                .from('visitas_pastoral')
                .select('publicador_nombre, fecha_visita')
                .in('publicador_nombre', memberNames);

            const newVisits: VisitsMap = {};
            if (visitsData) {
                visitsData.forEach((v: any) => {
                    newVisits[v.publicador_nombre] = v.fecha_visita;
                });
            }
            setVisits(newVisits);
        };

        fetchData();
    }, [currentMonth, members]);

    // --- Actions ---

    const handleCreateGroup = async () => {
        if (!newGroupName.trim()) return;
        const normalizedName = newGroupName.trim();

        const { data, error } = await supabase.from('grupos').insert([{ nombre: normalizedName }]).select();

        if (error) {
            // Check for duplicate key error code (Postgres unique violation)
            if (error.code === '23505') {
                const { data: existingGroup } = await supabase
                    .from('grupos')
                    .select('*')
                    .eq('nombre', normalizedName)
                    .single();

                if (existingGroup) {
                    setGroups(prev => {
                        if (prev.some(g => g.id === existingGroup.id)) return prev;
                        return [...prev, existingGroup].sort((a,b) => a.nombre.localeCompare(b.nombre));
                    });
                    setSelectedGroupId(existingGroup.id);
                    setIsCreatingGroup(false);
                    setNewGroupName('');
                    setStatusMessage({ text: `El grupo "${normalizedName}" ya existe. Seleccionado.`, type: 'info' });
                    setTimeout(() => setStatusMessage(null), 3000);
                    return; 
                }
            }

            console.error("Error creating group:", error);
            setStatusMessage({ text: `Error: ${error.message}`, type: 'error' });
            setTimeout(() => setStatusMessage(null), 4000);
        } else if (data) {
            setGroups(prev => [...prev, data[0]].sort((a,b) => a.nombre.localeCompare(b.nombre)));
            setSelectedGroupId(data[0].id);
            setIsCreatingGroup(false);
            setNewGroupName('');
            setStatusMessage({ text: 'Grupo creado con éxito', type: 'success' });
            setTimeout(() => setStatusMessage(null), 3000);
        }
    };

    const handleDeleteGroup = async () => {
        if (!selectedGroupId) return;
        const groupName = groups.find(g => g.id === selectedGroupId)?.nombre;
        if (!window.confirm(`¿Estás seguro de eliminar el "${groupName}" y todos sus integrantes?`)) return;

        const { error } = await supabase.from('grupos').delete().eq('id', selectedGroupId);
        if (error) {
            console.error("Error deleting group:", error);
            setStatusMessage({ text: `Error al eliminar: ${error.message}`, type: 'error' });
        } else {
            const remaining = groups.filter(g => g.id !== selectedGroupId);
            setGroups(remaining);
            setSelectedGroupId(remaining.length > 0 ? remaining[0].id : null);
            setMembers([]);
            setStatusMessage({ text: 'Grupo eliminado', type: 'success' });
            setTimeout(() => setStatusMessage(null), 3000);
        }
    };

    const handleAddMember = async (name: string) => {
        if (!selectedGroupId || !name.trim()) return;

        // Check local duplicate
        if (members.some(m => m.publicador_nombre.toLowerCase() === name.toLowerCase())) {
            setStatusMessage({ text: 'Esta persona ya está en el grupo', type: 'error' });
            setTimeout(() => setStatusMessage(null), 3000);
            return;
        }

        const { error } = await supabase.from('miembros_grupo').insert([{
            grupo_id: selectedGroupId,
            publicador_nombre: name.trim()
        }]);

        if (error) {
            console.error(error);
            setStatusMessage({ text: `Error al agregar: ${error.message}`, type: 'error' });
        } else {
            setStatusMessage({ text: 'Agregado correctamente', type: 'success' });
            setAddSearchTerm('');
            fetchMembers();
        }
        setTimeout(() => setStatusMessage(null), 3000);
    };

    const handleDeleteMember = async (id: number, name: string) => {
        if (!window.confirm(`¿Quitar a ${name} de este grupo?`)) return;
        const { error } = await supabase.from('miembros_grupo').delete().eq('id', id);
        if (!error) fetchMembers();
        else console.error("Error deleting member:", error);
    };

    const handleReportChange = (name: string, value: string) => {
        setReports(prev => ({
            ...prev,
            [name]: { ...prev[name], horas: value === '' ? '' : Number(value) }
        }));
    };

    const handleVisitChange = (name: string, date: string) => {
        setVisits(prev => ({
            ...prev,
            [name]: date
        }));
    };

    const handleSaveRow = async (publisherName: string) => {
        setStatusMessage(null);
        try {
            // --- Save Report Logic ---
            const reportEntry = reports[publisherName];

            if (reportEntry) {
                // If checkbox is active (exists in state), upsert report
                // Note: If 'Predicó' was selected, horas will be 0. If 'Horas' selected, it will be > 0.
                const valToSave = reportEntry.horas === '' ? 0 : reportEntry.horas;

                const { error: reportError } = await supabase
                    .from('informes_ministerio')
                    .upsert({ 
                        publicador_nombre: publisherName, 
                        mes: currentMonth, 
                        horas: valToSave 
                    }, { onConflict: 'publicador_nombre, mes' });
                if (reportError) throw reportError;
            } else {
                // If reportEntry is missing (User selected 'Vacío'), delete report from DB
                const { error: deleteError } = await supabase
                    .from('informes_ministerio')
                    .delete()
                    .eq('publicador_nombre', publisherName)
                    .eq('mes', currentMonth);

                // We ignore if it didn't exist, but supabase delete won't error on 0 rows
                if (deleteError) throw deleteError;
            }

            // --- Save Visit Logic ---
            const visitDate = visits[publisherName];
            if (visitDate) {
                const { error: visitError } = await supabase
                    .from('visitas_pastoral')
                    .upsert({ 
                        publicador_nombre: publisherName, 
                        fecha_visita: visitDate 
                    }, { onConflict: 'publicador_nombre' });
                if (visitError) throw visitError;
            }

            setStatusMessage({ text: 'Guardado', type: 'success' });
            setTimeout(() => setStatusMessage(null), 2000);
        } catch (err: any) {
            console.error(err);
            setStatusMessage({ text: 'Error al guardar', type: 'error' });
        }
    };

    // Filter Logic for Main Table
    const filteredMembers = members.filter(m => 
        m.publicador_nombre.toLowerCase().includes(searchTerm.toLowerCase())
    );

    // Filter Logic for Add Suggestions
    const filteredSuggestions = masterPublishers
        .filter(p => p.nombre.toLowerCase().includes(addSearchTerm.toLowerCase()))
        .filter(p => !members.some(m => m.publicador_nombre === p.nombre)) // Exclude already in group
        .slice(0, 6); // Limit results

    const currentGroupName = groups.find(g => g.id === selectedGroupId)?.nombre || 'Sin Grupo';

    return (
        <div className="container mx-auto px-4 py-8 group-container">

            {/* --- TOP BAR: Group Selector & Date --- */}
            <div style={{ display: 'flex', flexDirection: 'column', gap: '1.5rem', marginBottom: '2rem' }}>
                <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', flexWrap: 'wrap', gap: '1rem' }}>
                    <div style={{flex: 1}}>
                        {!isCreatingGroup ? (
                            <div style={{display: 'flex', alignItems: 'center', gap: '10px'}}>
                                <select 
                                    value={selectedGroupId || ''} 
                                    onChange={(e) => setSelectedGroupId(Number(e.target.value))}
                                    className="gc-header-title"
                                    style={{ background: 'transparent', border: 'none', cursor: 'pointer', paddingRight: '20px', outline: 'none' }}
                                >
                                    {groups.length === 0 && <option value="">Crear un grupo...</option>}
                                    {groups.map(g => <option key={g.id} value={g.id}>{g.nombre}</option>)}
                                </select>
                                <button onClick={() => setIsCreatingGroup(true)} style={{background: '#e0e7ff', color: '#4338ca', border: 'none', borderRadius: '50%', width: '32px', height: '32px', cursor: 'pointer', display: 'flex', alignItems: 'center', justifyContent: 'center'}} title="Crear nuevo grupo">
                                    <i className="fas fa-plus"></i>
                                </button>
                                {groups.length > 0 && (
                                    <button onClick={handleDeleteGroup} style={{background: '#fee2e2', color: '#dc2626', border: 'none', borderRadius: '50%', width: '32px', height: '32px', cursor: 'pointer', display: 'flex', alignItems: 'center', justifyContent: 'center', marginLeft: '5px'}} title="Eliminar este grupo">
                                        <i className="fas fa-trash-alt" style={{fontSize: '0.8rem'}}></i>
                                    </button>
                                )}
                            </div>
                        ) : (
                            <div style={{display: 'flex', gap: '10px', alignItems: 'center'}}>
                                <input 
                                    autoFocus
                                    type="text" 
                                    placeholder="Nombre del Grupo (ej. Grupo 1)" 
                                    value={newGroupName}
                                    onChange={(e) => setNewGroupName(e.target.value)}
                                    className="gc-input-add"
                                    style={{width: '250px'}}
                                />
                                <button onClick={handleCreateGroup} className="button" style={{backgroundColor: '#10b981', color: 'white'}}>Guardar</button>
                                <button onClick={() => setIsCreatingGroup(false)} className="button" style={{backgroundColor: '#6b7280', color: 'white'}}>Cancelar</button>
                            </div>
                        )}
                        <p style={{ color: '#6b7280', fontWeight: '500', display: 'flex', alignItems: 'center', gap: '0.5rem', marginTop: '0.5rem' }}>
                            <i className="fas fa-users" style={{ color: '#60a5fa' }}></i>
                            {members.length} Integrantes
                        </p>
                    </div>

                    <div style={{ display: 'flex', gap: '0.75rem', alignItems: 'center', backgroundColor: 'white', padding: '0.5rem', borderRadius: '0.75rem', border: '1px solid #e5e7eb', boxShadow: '0 1px 2px 0 rgba(0,0,0,0.05)' }}>
                        <div style={{ backgroundColor: '#f3f4f6', padding: '0.5rem 0.75rem', borderRadius: '0.5rem', color: '#6b7280' }}>
                            <i className="fas fa-calendar-alt"></i>
                        </div>
                        <input 
                            type="month" 
                            value={currentMonth} 
                            onChange={(e) => setCurrentMonth(e.target.value)}
                            style={{ border: 'none', background: 'transparent', fontWeight: '600', color: '#374151', outline: 'none', cursor: 'pointer' }}
                        />
                    </div>
                </div>
            </div>

            {/* --- ADD MEMBER SECTION (With Autocomplete & Manual Option) --- */}
            {selectedGroupId && (
                <div className="gc-card-add" style={{overflow: 'visible'}}>
                    <div className="gc-label-add">
                        <i className="fas fa-user-plus"></i>
                        Agregar Integrante al {currentGroupName}
                    </div>
                    <div style={{ display: 'flex', flexDirection: 'row', gap: '1rem', flexWrap: 'wrap', position: 'relative' }} ref={suggestionsRef}>
                        <div style={{ position: 'relative', flexGrow: 1 }}>
                            <i className="fas fa-search" style={{ position: 'absolute', left: '1rem', top: '50%', transform: 'translateY(-50%)', color: '#9ca3af', zIndex: 10 }}></i>
                            <input 
                                type="text" 
                                value={addSearchTerm}
                                onChange={(e) => {
                                    setAddSearchTerm(e.target.value);
                                    setShowSuggestions(true);
                                }}
                                onFocus={() => setShowSuggestions(true)}
                                onKeyDown={(e) => {
                                    if (e.key === 'Enter') {
                                        handleAddMember(addSearchTerm);
                                        setShowSuggestions(false);
                                    }
                                }}
                                placeholder="Buscar o escribir nombre nuevo..."
                                className="gc-input-add"
                                autoComplete="off"
                            />
                            {/* Autocomplete Dropdown */}
                            {showSuggestions && addSearchTerm && (
                                <div style={{
                                    position: 'absolute', top: '100%', left: 0, right: 0, 
                                    backgroundColor: 'white', border: '1px solid #e5e7eb', 
                                    borderRadius: '0.75rem', marginTop: '5px', zIndex: 50,
                                    boxShadow: '0 10px 15px -3px rgba(0, 0, 0, 0.1)',
                                    maxHeight: '300px', overflowY: 'auto'
                                }}>
                                    {/* Existing Publishers from DB */}
                                    {filteredSuggestions.map(p => (
                                        <div 
                                            key={p.id}
                                            onClick={() => {
                                                handleAddMember(p.nombre);
                                                setAddSearchTerm(''); 
                                                setShowSuggestions(false);
                                            }}
                                            style={{ padding: '10px 15px', cursor: 'pointer', borderBottom: '1px solid #f3f4f6', display: 'flex', alignItems: 'center', gap: '10px' }}
                                            onMouseEnter={(e) => e.currentTarget.style.backgroundColor = '#f9fafb'}
                                            onMouseLeave={(e) => e.currentTarget.style.backgroundColor = 'white'}
                                        >
                                            <div className={`modern-avatar ${getAvatarClass(p.nombre)}`} style={{width: '24px', height: '24px', fontSize: '0.7rem'}}>
                                                {p.nombre.charAt(0)}
                                            </div>
                                            <span style={{color: '#374151', fontWeight: '500'}}>{p.nombre}</span>
                                            <i className="fas fa-plus" style={{marginLeft: 'auto', color: '#10b981', fontSize: '0.8rem'}}></i>
                                        </div>
                                    ))}

                                    {/* Manual "Add as new" Option (Always visible if text is present) */}
                                    <div 
                                        onClick={() => {
                                            handleAddMember(addSearchTerm);
                                            setAddSearchTerm(''); 
                                            setShowSuggestions(false);
                                        }}
                                        style={{ padding: '10px 15px', cursor: 'pointer', backgroundColor: '#fdf4ff', borderTop: '1px solid #f3f4f6', display: 'flex', alignItems: 'center', gap: '10px' }}
                                        onMouseEnter={(e) => e.currentTarget.style.backgroundColor = '#fce7f3'}
                                        onMouseLeave={(e) => e.currentTarget.style.backgroundColor = '#fdf4ff'}
                                    >
                                        <div style={{width: '24px', height: '24px', display:'flex', alignItems:'center', justifyContent:'center', color: '#d946ef'}}>
                                            <i className="fas fa-pen"></i>
                                        </div>
                                        <div style={{display:'flex', flexDirection:'column'}}>
                                            <span style={{color: '#374151', fontWeight: '600'}}>Agregar "{addSearchTerm}"</span>
                                            <span style={{fontSize: '0.75rem', color: '#d946ef'}}>Nombre manual (no se añade a lista general)</span>
                                        </div>
                                    </div>
                                </div>
                            )}
                        </div>
                        <button 
                            onClick={() => handleAddMember(addSearchTerm)}
                            disabled={!addSearchTerm.trim()}
                            className="gc-btn-add"
                        >
                            <span>Agregar</span>
                            <i className="fas fa-arrow-right"></i>
                        </button>
                    </div>
                </div>
            )}

            {/* Status Toast */}
            {statusMessage && (
                <div style={{ 
                    position: 'fixed', bottom: '1.5rem', right: '1.5rem', zIndex: 100, padding: '1rem 1.5rem', borderRadius: '0.75rem', 
                    boxShadow: '0 10px 15px -3px rgba(0, 0, 0, 0.1)', fontWeight: '600', display: 'flex', alignItems: 'center', gap: '0.75rem',
                    backgroundColor: statusMessage.type === 'success' ? '#059669' : (statusMessage.type === 'info' ? '#3b82f6' : '#dc2626'), color: 'white'
                }}>
                    <i className={`fas ${statusMessage.type === 'success' ? 'fa-check-circle' : (statusMessage.type === 'info' ? 'fa-info-circle' : 'fa-exclamation-circle')}`}></i>
                    {statusMessage.text}
                </div>
            )}

            {/* List Table */}
            {loading ? (
                <div style={{ textAlign: 'center', padding: '5rem 0', color: '#9ca3af' }}>
                    <i className="fas fa-spinner fa-spin fa-3x" style={{ marginBottom: '1rem', color: '#93c5fd' }}></i>
                    <p style={{ fontWeight: '500' }}>Cargando datos...</p>
                </div>
            ) : (
                <div className="modern-card">
                    {/* Desktop Table Header */}
                    <div className="gc-table-header hidden md:grid md:grid-cols-12 md:gap-4 md:border-b md:border-slate-200 md:bg-slate-50 md:p-4">
                        <div className="col-span-4 pl-4">Publicador</div>
                        <div className="col-span-3 text-center">Horas ({currentMonth.split('-')[1]})</div>
                        <div className="col-span-3 text-center">Última Visita</div>
                        <div className="col-span-2 text-center">Acciones</div>
                    </div>

                    <div style={{ display: 'flex', flexDirection: 'column' }}>
                        {filteredMembers.map((m, index) => {
                            const pName = m.publicador_nombre;
                            const reportEntry = reports[pName];

                            // Determine current visual mode based on data
                            let currentMode = 'empty';
                            if (reportEntry) {
                                if (reportEntry.horas === 0) {
                                    currentMode = 'predico';
                                } else if (reportEntry.horas === '' || (typeof reportEntry.horas === 'number' && reportEntry.horas > 0)) {
                                    currentMode = 'horas';
                                }
                            }

                            const visitDate = visits[pName] || '';

                            // Visual cue logic
                            let visitBadgeClass = 'status-badge neutral';
                            let visitLabel = 'Sin registrar';
                            if (visitDate) {
                                const daysSince = (new Date().getTime() - new Date(visitDate).getTime()) / (1000 * 3600 * 24);
                                if (daysSince < 90) { visitBadgeClass = 'status-badge success'; visitLabel = 'Reciente'; } 
                                else if (daysSince < 180) { visitBadgeClass = 'status-badge warning'; visitLabel = 'Atención'; } 
                                else { visitBadgeClass = 'status-badge danger'; visitLabel = 'Urgente'; }
                            }

                            return (
                                <div key={m.id} className="grid grid-cols-2 gap-3 p-3 border-b border-slate-100 items-center transition-colors hover:bg-slate-50 md:grid-cols-12 md:gap-4 md:p-5">

                                    {/* Name: Spans 2 cols on mobile (full width), 4 on desktop */}
                                    <div className="col-span-2 flex items-center gap-3 md:col-span-4">
                                        <div className="text-gray-400 font-semibold min-w-[1.5rem] text-center text-sm">{index + 1}</div>
                                        <div className="font-semibold text-gray-800 text-base">{pName}</div>
                                    </div>

                                    {/* Hours: Spans 1 col on mobile (half), 3 on desktop */}
                                    <div className="col-span-1 flex flex-col items-center bg-gray-50 p-2 rounded-lg md:col-span-3 md:flex-row md:justify-center md:bg-transparent md:p-0">
                                        <span className="md:hidden text-xs text-gray-500 font-bold uppercase mb-1">Horas</span>
                                        <div className="flex items-center gap-2 justify-center w-full">
                                            <select
                                                value={currentMode}
                                                onChange={(e) => {
                                                    const newMode = e.target.value;
                                                    if (newMode === 'empty') {
                                                        setReports(prev => {
                                                            const next = { ...prev };
                                                            delete next[pName];
                                                            return next;
                                                        });
                                                    } else if (newMode === 'predico') {
                                                        handleReportChange(pName, '0');
                                                    } else if (newMode === 'horas') {
                                                        handleReportChange(pName, ''); // Reset to empty string to encourage input
                                                    }
                                                }}
                                                style={{ 
                                                    padding: '0.3rem 0.4rem', borderRadius: '0.4rem', border: '1px solid #d1d5db', 
                                                    backgroundColor: 'white', fontSize: '0.8rem', color: '#374151', cursor: 'pointer', outline: 'none' 
                                                }}
                                            >
                                                <option value="empty">-- (Vacío)</option>
                                                <option value="predico">Predicó</option>
                                                <option value="horas">Horas</option>
                                            </select>

                                            {currentMode === 'horas' && (
                                                <input 
                                                    type="number" min="0" step="0.5"
                                                    value={reportEntry?.horas === 0 ? '' : (reportEntry?.horas ?? '')}
                                                    onChange={(e) => handleReportChange(pName, e.target.value)}
                                                    autoFocus
                                                    className="input-has-report"
                                                    style={{ 
                                                        width: '3.5rem', padding: '0.3rem', textAlign: 'center', fontWeight: '700', borderRadius: '0.4rem', 
                                                        border: '2px solid #34d399', outline: 'none', transition: 'all 0.2s', color: '#4b5563', backgroundColor: 'white', fontSize: '0.9rem'
                                                    }}
                                                    placeholder="#"
                                                />
                                            )}
                                        </div>
                                    </div>

                                    {/* Visit: Spans 1 col on mobile (half), 3 on desktop */}
                                    <div className="col-span-1 flex flex-col items-center bg-gray-50 p-2 rounded-lg md:col-span-3 md:flex-row md:justify-center md:bg-transparent md:p-0">
                                        <span className="md:hidden text-xs text-gray-500 font-bold uppercase mb-1">Visita</span>
                                        <div className="flex flex-col items-center gap-1 md:w-auto">
                                            <input 
                                                type="date" value={visitDate}
                                                onChange={(e) => handleVisitChange(pName, e.target.value)}
                                                className="modern-input"
                                                style={{ 
                                                    padding: '0.2rem 0.4rem', 
                                                    fontSize: '0.85rem', 
                                                    color: '#4b5563', 
                                                    fontWeight: '500', 
                                                    textAlign: 'center', 
                                                    borderRadius: '0.4rem', 
                                                    border: '1px solid #d1d5db',
                                                    maxWidth: '140px'
                                                }}
                                            />
                                            <span className={visitBadgeClass} style={{fontSize: '0.7rem', padding: '2px 6px'}}>
                                                <i className="fas fa-circle" style={{ fontSize: '0.4rem', marginRight: '3px' }}></i> {visitLabel}
                                            </span>
                                        </div>
                                    </div>

                                    {/* Actions: Spans 2 cols on mobile (full width), 2 on desktop */}
                                    <div className="col-span-2 flex justify-end gap-3 pt-1 border-t border-slate-100 md:col-span-2 md:justify-center md:border-0 md:pt-0">
                                        <button 
                                            onClick={() => handleSaveRow(pName)}
                                            style={{ background: 'linear-gradient(135deg, #4f46e5 0%, #4338ca 100%)', color: 'white', padding: '0.4rem 0.8rem', borderRadius: '0.4rem', border: 'none', cursor: 'pointer', display: 'flex', alignItems: 'center', gap: '0.4rem', fontSize: '0.8rem', fontWeight: '600', boxShadow: '0 2px 4px rgba(79, 70, 229, 0.2)' }}
                                            title="Guardar cambios"
                                        >
                                            <i className="fas fa-save"></i> <span>Guardar</span>
                                        </button>
                                        <button 
                                            onClick={() => handleDeleteMember(m.id, pName)}
                                            style={{ padding: '0.4rem', color: '#9ca3af', backgroundColor: 'transparent', border: '1px solid transparent', borderRadius: '0.4rem', cursor: 'pointer', transition: 'color 0.2s' }}
                                            onMouseEnter={(e) => { e.currentTarget.style.color = '#ef4444'; e.currentTarget.style.backgroundColor = '#fef2f2'; }}
                                            onMouseLeave={(e) => { e.currentTarget.style.color = '#9ca3af'; e.currentTarget.style.backgroundColor = 'transparent'; }}
                                            title="Quitar del grupo"
                                        >
                                            <i className="fas fa-trash-alt"></i>
                                        </button>
                                    </div>
                                </div>
                            );
                        })}
                    </div>
                    {filteredMembers.length === 0 && (
                        <div style={{ padding: '5rem 0', textAlign: 'center', backgroundColor: '#f8fafc' }}>
                            <div style={{ backgroundColor: 'white', width: '6rem', height: '6rem', borderRadius: '50%', display: 'flex', alignItems: 'center', justifyContent: 'center', margin: '0 auto 1.5rem auto', boxShadow: '0 1px 2px 0 rgba(0,0,0,0.05)', border: '1px solid #e2e8f0' }}>
                                <i className="fas fa-users fa-3x" style={{ color: '#c7d2fe' }}></i>
                            </div>
                            <h3 style={{ fontSize: '1.25rem', fontWeight: '700', color: '#374151' }}>
                                {selectedGroupId ? 'Este grupo está vacío' : 'Crea o selecciona un grupo'}
                            </h3>
                            <p style={{ color: '#6b7280', marginTop: '0.5rem', maxWidth: '24rem', marginInline: 'auto' }}>
                                Utiliza el buscador de arriba para agregar publicadores existentes a este grupo.
                            </p>
                        </div>
                    )}
                </div>
            )}
        </div>
    );
};

export default GrupoCongregacion;

import React, { useState, useEffect, useRef } from 'react';
import { supabase } from '../lib/supabase';

type Publisher = {
    id: number;
    nombre: string;
};

type Group = {
    id: number;
    nombre: string;
};

type GroupMember = {
    id: number;
    grupo_id: number;
    publicador_nombre: string;
};

type MinistryReport = {
    horas: number | '';
    estudios: number | '';
    notas?: string;
};

type VisitData = {
    date: string;
    notes: string;
};

type ReportsMap = Record<string, MinistryReport>;
type VisitsMap = Record<string, VisitData>;

// Helper for avatar colors
const getAvatarClass = (name: string) => {
    const classes = ['avatar-red', 'avatar-orange', 'avatar-amber', 'avatar-green', 'avatar-teal', 'avatar-blue', 'avatar-indigo', 'avatar-purple', 'avatar-pink'];
    let hash = 0;
    for (let i = 0; i < name.length; i++) {
        hash = name.charCodeAt(i) + ((hash << 5) - hash);
    }
    return classes[Math.abs(hash) % classes.length];
};

const GrupoCongregacion: React.FC = () => {
    // Data State
    const [groups, setGroups] = useState<Group[]>([]);
    const [selectedGroupId, setSelectedGroupId] = useState<number | null>(null);
    const [members, setMembers] = useState<GroupMember[]>([]);
    const [masterPublishers, setMasterPublishers] = useState<Publisher[]>([]); // All publishers from DB

    // UI State
    const [loading, setLoading] = useState(true);
    const [currentMonth, setCurrentMonth] = useState<string>('');
    const [reports, setReports] = useState<ReportsMap>({});
    const [visits, setVisits] = useState<VisitsMap>({});
    const [searchTerm, setSearchTerm] = useState('');
    const [addSearchTerm, setAddSearchTerm] = useState(''); // Search input for adding
    const [showSuggestions, setShowSuggestions] = useState(false);
    const [isCreatingGroup, setIsCreatingGroup] = useState(false);
    const [newGroupName, setNewGroupName] = useState('');
    const [statusMessage, setStatusMessage] = useState<{ text: string; type: 'success' | 'error' | 'info' } | null>(null);

    const suggestionsRef = useRef<HTMLDivElement>(null);

    // Initial Load
    useEffect(() => {
        const now = new Date();
        const yyyy = now.getFullYear();
        const mm = String(now.getMonth() + 1).padStart(2, '0');
        setCurrentMonth(`${yyyy}-${mm}`);

        fetchGroups();
        fetchMasterPublishers();

        // Close suggestions on click outside
        const handleClickOutside = (event: MouseEvent) => {
            if (suggestionsRef.current && !suggestionsRef.current.contains(event.target as Node)) {
                setShowSuggestions(false);
            }
        };
        document.addEventListener('mousedown', handleClickOutside);
        return () => document.removeEventListener('mousedown', handleClickOutside);
    }, []);

    // Load Data Functions
    const fetchGroups = async () => {
        const { data, error } = await supabase.from('grupos').select('*').order('nombre');
        if (error) {
            console.error("Error fetching groups:", error);
        } else if (data) {
            setGroups(data);
            if (data.length > 0 && !selectedGroupId) {
                // Try to find "Grupo 5" first, else default to first
                const defaultGroup = data.find(g => g.nombre.includes('5')) || data[0];
                setSelectedGroupId(defaultGroup.id);
            }
        }
    };

    const fetchMasterPublishers = async () => {
        const { data } = await supabase.from('publicadores').select('id, nombre').order('nombre');
        if (data) setMasterPublishers(data);
    };

    const fetchMembers = async () => {
        if (!selectedGroupId) return;
        setLoading(true);
        const { data, error } = await supabase
            .from('miembros_grupo')
            .select('*')
            .eq('grupo_id', selectedGroupId)
            .order('publicador_nombre');

        if (error) console.error("Error fetching members:", error);
        else setMembers(data || []);
        setLoading(false);
    };

    // Load Members when Group Changes
    useEffect(() => {
        fetchMembers();
    }, [selectedGroupId]);

    // Load Reports/Visits when Members or Month Change
    useEffect(() => {
        if (!currentMonth || members.length === 0) return;

        const fetchData = async () => {
            // Get reports only for current members
            const memberNames = members.map(m => m.publicador_nombre);

            const { data: reportsData } = await supabase
                .from('informes_ministerio')
                .select('publicador_nombre, horas, estudios, notas')
                .eq('mes', currentMonth)
                .in('publicador_nombre', memberNames);

            const newReports: ReportsMap = {};
            if (reportsData) {
                reportsData.forEach((r: any) => {
                    newReports[r.publicador_nombre] = { 
                        horas: r.horas,
                        estudios: r.estudios || '',
                        notas: r.notas || ''
                    };
                });
            }
            setReports(newReports);

            const { data: visitsData } = await supabase
                .from('visitas_pastoral')
                .select('publicador_nombre, fecha_visita, notas')
                .in('publicador_nombre', memberNames);

            const newVisits: VisitsMap = {};
            if (visitsData) {
                visitsData.forEach((v: any) => {
                    newVisits[v.publicador_nombre] = {
                        date: v.fecha_visita,
                        notes: v.notas || ''
                    };
                });
            }
            setVisits(newVisits);
        };

        fetchData();
    }, [currentMonth, members]);

    // --- Actions ---

    const handleCreateGroup = async () => {
        if (!newGroupName.trim()) return;
        const normalizedName = newGroupName.trim();

        const { data, error } = await supabase.from('grupos').insert([{ nombre: normalizedName }]).select();

        if (error) {
            // Check for duplicate key error code (Postgres unique violation)
            if (error.code === '23505') {
                const { data: existingGroup } = await supabase
                    .from('grupos')
                    .select('*')
                    .eq('nombre', normalizedName)
                    .single();

                if (existingGroup) {
                    setGroups(prev => {
                        if (prev.some(g => g.id === existingGroup.id)) return prev;
                        return [...prev, existingGroup].sort((a,b) => a.nombre.localeCompare(b.nombre));
                    });
                    setSelectedGroupId(existingGroup.id);
                    setIsCreatingGroup(false);
                    setNewGroupName('');
                    setStatusMessage({ text: `El grupo "${normalizedName}" ya existe. Seleccionado.`, type: 'info' });
                    setTimeout(() => setStatusMessage(null), 3000);
                    return; 
                }
            }

            console.error("Error creating group:", error);
            setStatusMessage({ text: `Error: ${error.message}`, type: 'error' });
            setTimeout(() => setStatusMessage(null), 4000);
        } else if (data) {
            setGroups(prev => [...prev, data[0]].sort((a,b) => a.nombre.localeCompare(b.nombre)));
            setSelectedGroupId(data[0].id);
            setIsCreatingGroup(false);
            setNewGroupName('');
            setStatusMessage({ text: 'Grupo creado con éxito', type: 'success' });
            setTimeout(() => setStatusMessage(null), 3000);
        }
    };

    const handleDeleteGroup = async () => {
        if (!selectedGroupId) return;
        const groupName = groups.find(g => g.id === selectedGroupId)?.nombre;
        if (!window.confirm(`¿Estás seguro de eliminar el "${groupName}" y todos sus integrantes?`)) return;

        const { error } = await supabase.from('grupos').delete().eq('id', selectedGroupId);
        if (error) {
            console.error("Error deleting group:", error);
            setStatusMessage({ text: `Error al eliminar: ${error.message}`, type: 'error' });
        } else {
            const remaining = groups.filter(g => g.id !== selectedGroupId);
            setGroups(remaining);
            setSelectedGroupId(remaining.length > 0 ? remaining[0].id : null);
            setMembers([]);
            setStatusMessage({ text: 'Grupo eliminado', type: 'success' });
            setTimeout(() => setStatusMessage(null), 3000);
        }
    };

    const handleAddMember = async (name: string) => {
        if (!selectedGroupId || !name.trim()) return;

        // Check local duplicate
        if (members.some(m => m.publicador_nombre.toLowerCase() === name.toLowerCase())) {
            setStatusMessage({ text: 'Esta persona ya está en el grupo', type: 'error' });
            setTimeout(() => setStatusMessage(null), 3000);
            return;
        }

        const { error } = await supabase.from('miembros_grupo').insert([{
            grupo_id: selectedGroupId,
            publicador_nombre: name.trim()
        }]);

        if (error) {
            console.error(error);
            setStatusMessage({ text: `Error al agregar: ${error.message}`, type: 'error' });
        } else {
            setStatusMessage({ text: 'Agregado correctamente', type: 'success' });
            setAddSearchTerm('');
            fetchMembers();
        }
        setTimeout(() => setStatusMessage(null), 3000);
    };

    const handleDeleteMember = async (id: number, name: string) => {
        if (!window.confirm(`¿Quitar a ${name} de este grupo?`)) return;
        const { error } = await supabase.from('miembros_grupo').delete().eq('id', id);
        if (!error) fetchMembers();
        else console.error("Error deleting member:", error);
    };

    const handleReportChange = (name: string, field: keyof MinistryReport, value: string) => {
        setReports(prev => {
            const currentEntry = prev[name] || { horas: '', estudios: '', notas: '' };
            const newValue = (field === 'horas' || field === 'estudios') 
                ? (value === '' ? '' : Number(value)) 
                : value;

            return {
                ...prev,
                [name]: { ...currentEntry, [field]: newValue }
            };
        });
    };

    const handleVisitChange = (name: string, field: keyof VisitData, value: string) => {
        setVisits(prev => {
            const currentEntry = prev[name] || { date: '', notes: '' };
            return {
                ...prev,
                [name]: { ...currentEntry, [field]: value }
            };
        });
    };

    const handleSaveRow = async (publisherName: string) => {
        setStatusMessage(null);
        try {
            // --- Save Report Logic ---
            const reportEntry = reports[publisherName];

            if (reportEntry) {
                // If checkbox is active (exists in state), upsert report
                // Note: If 'Predicó' was selected, horas will be 0. If 'Horas' selected, it will be > 0.
                const valToSave = reportEntry.horas === '' ? 0 : reportEntry.horas;

                const { error: reportError } = await supabase
                    .from('informes_ministerio')
                    .upsert({ 
                        publicador_nombre: publisherName, 
                        mes: currentMonth, 
                        horas: valToSave,
                        estudios: reportEntry.estudios === '' ? 0 : reportEntry.estudios,
                        notas: reportEntry.notas || ''
                    }, { onConflict: 'publicador_nombre, mes' });
                if (reportError) throw reportError;
            } else {
                // If reportEntry is missing (User selected 'Vacío'), delete report from DB
                const { error: deleteError } = await supabase
                    .from('informes_ministerio')
                    .delete()
                    .eq('publicador_nombre', publisherName)
                    .eq('mes', currentMonth);

                // We ignore if it didn't exist, but supabase delete won't error on 0 rows
                if (deleteError) throw deleteError;
            }

            // --- Save Visit Logic ---
            const visitData = visits[publisherName];
            if (visitData && (visitData.date || visitData.notes)) {
                const { error: visitError } = await supabase
                    .from('visitas_pastoral')
                    .upsert({ 
                        publicador_nombre: publisherName, 
                        fecha_visita: visitData.date,
                        notas: visitData.notes
                    }, { onConflict: 'publicador_nombre' });
                if (visitError) throw visitError;
            }

            setStatusMessage({ text: 'Guardado', type: 'success' });
            setTimeout(() => setStatusMessage(null), 2000);
        } catch (err: any) {
            console.error(err);
            setStatusMessage({ text: 'Error al guardar', type: 'error' });
        }
    };

    // Filter Logic for Main Table
    const filteredMembers = members.filter(m => 
        m.publicador_nombre.toLowerCase().includes(searchTerm.toLowerCase())
    );

    // Filter Logic for Add Suggestions
    const filteredSuggestions = masterPublishers
        .filter(p => p.nombre.toLowerCase().includes(addSearchTerm.toLowerCase()))
        .filter(p => !members.some(m => m.publicador_nombre === p.nombre)) // Exclude already in group
        .slice(0, 6); // Limit results

    const currentGroupName = groups.find(g => g.id === selectedGroupId)?.nombre || 'Sin Grupo';

    return (
        <div className="container mx-auto px-4 py-8 group-container">

            {/* --- TOP BAR: Group Selector & Date --- */}
            <div style={{ display: 'flex', flexDirection: 'column', gap: '1.5rem', marginBottom: '2rem' }}>
                <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', flexWrap: 'wrap', gap: '1rem' }}>
                    <div style={{flex: 1}}>
                        {!isCreatingGroup ? (
                            <div style={{display: 'flex', alignItems: 'center', gap: '10px'}}>
                                <select 
                                    value={selectedGroupId || ''} 
                                    onChange={(e) => setSelectedGroupId(Number(e.target.value))}
                                    className="gc-header-title"
                                    style={{ background: 'transparent', border: 'none', cursor: 'pointer', paddingRight: '20px', outline: 'none' }}
                                >
                                    {groups.length === 0 && <option value="">Crear un grupo...</option>}
                                    {groups.map(g => <option key={g.id} value={g.id}>{g.nombre}</option>)}
                                </select>
                                <button onClick={() => setIsCreatingGroup(true)} style={{background: '#e0e7ff', color: '#4338ca', border: 'none', borderRadius: '50%', width: '32px', height: '32px', cursor: 'pointer', display: 'flex', alignItems: 'center', justifyContent: 'center'}} title="Crear nuevo grupo">
                                    <i className="fas fa-plus"></i>
                                </button>
                                {groups.length > 0 && (
                                    <button onClick={handleDeleteGroup} style={{background: '#fee2e2', color: '#dc2626', border: 'none', borderRadius: '50%', width: '32px', height: '32px', cursor: 'pointer', display: 'flex', alignItems: 'center', justifyContent: 'center', marginLeft: '5px'}} title="Eliminar este grupo">
                                        <i className="fas fa-trash-alt" style={{fontSize: '0.8rem'}}></i>
                                    </button>
                                )}
                            </div>
                        ) : (
                            <div style={{display: 'flex', gap: '10px', alignItems: 'center'}}>
                                <input 
                                    autoFocus
                                    type="text" 
                                    placeholder="Nombre del Grupo (ej. Grupo 1)" 
                                    value={newGroupName}
                                    onChange={(e) => setNewGroupName(e.target.value)}
                                    className="gc-input-add"
                                    style={{width: '250px'}}
                                />
                                <button onClick={handleCreateGroup} className="button" style={{backgroundColor: '#10b981', color: 'white'}}>Guardar</button>
                                <button onClick={() => setIsCreatingGroup(false)} className="button" style={{backgroundColor: '#6b7280', color: 'white'}}>Cancelar</button>
                            </div>
                        )}
                        <p style={{ color: '#6b7280', fontWeight: '500', display: 'flex', alignItems: 'center', gap: '0.5rem', marginTop: '0.5rem' }}>
                            <i className="fas fa-users" style={{ color: '#60a5fa' }}></i>
                            {members.length} Integrantes
                        </p>
                    </div>

                    <div style={{ display: 'flex', gap: '0.75rem', alignItems: 'center', backgroundColor: 'white', padding: '0.5rem', borderRadius: '0.75rem', border: '1px solid #e5e7eb', boxShadow: '0 1px 2px 0 rgba(0,0,0,0.05)' }}>
                        <div style={{ backgroundColor: '#f3f4f6', padding: '0.5rem 0.75rem', borderRadius: '0.5rem', color: '#6b7280' }}>
                            <i className="fas fa-calendar-alt"></i>
                        </div>
                        <input 
                            type="month" 
                            value={currentMonth} 
                            onChange={(e) => setCurrentMonth(e.target.value)}
                            style={{ border: 'none', background: 'transparent', fontWeight: '600', color: '#374151', outline: 'none', cursor: 'pointer' }}
                        />
                    </div>
                </div>
            </div>

            {/* --- ADD MEMBER SECTION (With Autocomplete & Manual Option) --- */}
            {selectedGroupId && (
                <div className="gc-card-add" style={{overflow: 'visible'}}>
                    <div className="gc-label-add">
                        <i className="fas fa-user-plus"></i>
                        Agregar Integrante al {currentGroupName}
                    </div>
                    <div style={{ display: 'flex', flexDirection: 'row', gap: '1rem', flexWrap: 'wrap', position: 'relative' }} ref={suggestionsRef}>
                        <div style={{ position: 'relative', flexGrow: 1 }}>
                            <i className="fas fa-search" style={{ position: 'absolute', left: '1rem', top: '50%', transform: 'translateY(-50%)', color: '#9ca3af', zIndex: 10 }}></i>
                            <input 
                                type="text" 
                                value={addSearchTerm}
                                onChange={(e) => {
                                    setAddSearchTerm(e.target.value);
                                    setShowSuggestions(true);
                                }}
                                onFocus={() => setShowSuggestions(true)}
                                onKeyDown={(e) => {
                                    if (e.key === 'Enter') {
                                        handleAddMember(addSearchTerm);
                                        setShowSuggestions(false);
                                    }
                                }}
                                placeholder="Buscar o escribir nombre nuevo..."
                                className="gc-input-add"
                                autoComplete="off"
                            />
                            {/* Autocomplete Dropdown */}
                            {showSuggestions && addSearchTerm && (
                                <div style={{
                                    position: 'absolute', top: '100%', left: 0, right: 0, 
                                    backgroundColor: 'white', border: '1px solid #e5e7eb', 
                                    borderRadius: '0.75rem', marginTop: '5px', zIndex: 50,
                                    boxShadow: '0 10px 15px -3px rgba(0, 0, 0, 0.1)',
                                    maxHeight: '300px', overflowY: 'auto'
                                }}>
                                    {/* Existing Publishers from DB */}
                                    {filteredSuggestions.map(p => (
                                        <div 
                                            key={p.id}
                                            onClick={() => {
                                                handleAddMember(p.nombre);
                                                setAddSearchTerm(''); 
                                                setShowSuggestions(false);
                                            }}
                                            style={{ padding: '10px 15px', cursor: 'pointer', borderBottom: '1px solid #f3f4f6', display: 'flex', alignItems: 'center', gap: '10px' }}
                                            onMouseEnter={(e) => e.currentTarget.style.backgroundColor = '#f9fafb'}
                                            onMouseLeave={(e) => e.currentTarget.style.backgroundColor = 'white'}
                                        >
                                            <div className={`modern-avatar ${getAvatarClass(p.nombre)}`} style={{width: '24px', height: '24px', fontSize: '0.7rem'}}>
                                                {p.nombre.charAt(0)}
                                            </div>
                                            <span style={{color: '#374151', fontWeight: '500'}}>{p.nombre}</span>
                                            <i className="fas fa-plus" style={{marginLeft: 'auto', color: '#10b981', fontSize: '0.8rem'}}></i>
                                        </div>
                                    ))}

                                    {/* Manual "Add as new" Option (Always visible if text is present) */}
                                    <div 
                                        onClick={() => {
                                            handleAddMember(addSearchTerm);
                                            setAddSearchTerm(''); 
                                            setShowSuggestions(false);
                                        }}
                                        style={{ padding: '10px 15px', cursor: 'pointer', backgroundColor: '#fdf4ff', borderTop: '1px solid #f3f4f6', display: 'flex', alignItems: 'center', gap: '10px' }}
                                        onMouseEnter={(e) => e.currentTarget.style.backgroundColor = '#fce7f3'}
                                        onMouseLeave={(e) => e.currentTarget.style.backgroundColor = '#fdf4ff'}
                                    >
                                        <div style={{width: '24px', height: '24px', display:'flex', alignItems:'center', justifyContent:'center', color: '#d946ef'}}>
                                            <i className="fas fa-pen"></i>
                                        </div>
                                        <div style={{display:'flex', flexDirection:'column'}}>
                                            <span style={{color: '#374151', fontWeight: '600'}}>Agregar "{addSearchTerm}"</span>
                                            <span style={{fontSize: '0.75rem', color: '#d946ef'}}>Nombre manual (no se añade a lista general)</span>
                                        </div>
                                    </div>
                                </div>
                            )}
                        </div>
                        <button 
                            onClick={() => handleAddMember(addSearchTerm)}
                            disabled={!addSearchTerm.trim()}
                            className="gc-btn-add"
                        >
                            <span>Agregar</span>
                            <i className="fas fa-arrow-right"></i>
                        </button>
                    </div>
                </div>
            )}

            {/* Status Toast */}
            {statusMessage && (
                <div style={{ 
                    position: 'fixed', bottom: '1.5rem', right: '1.5rem', zIndex: 100, padding: '1rem 1.5rem', borderRadius: '0.75rem', 
                    boxShadow: '0 10px 15px -3px rgba(0, 0, 0, 0.1)', fontWeight: '600', display: 'flex', alignItems: 'center', gap: '0.75rem',
                    backgroundColor: statusMessage.type === 'success' ? '#059669' : (statusMessage.type === 'info' ? '#3b82f6' : '#dc2626'), color: 'white'
                }}>
                    <i className={`fas ${statusMessage.type === 'success' ? 'fa-check-circle' : (statusMessage.type === 'info' ? 'fa-info-circle' : 'fa-exclamation-circle')}`}></i>
                    {statusMessage.text}
                </div>
            )}

            {/* List Table */}
            {loading ? (
                <div style={{ textAlign: 'center', padding: '5rem 0', color: '#9ca3af' }}>
                    <i className="fas fa-spinner fa-spin fa-3x" style={{ marginBottom: '1rem', color: '#93c5fd' }}></i>
                    <p style={{ fontWeight: '500' }}>Cargando datos...</p>
                </div>
            ) : (
                <div className="modern-card">
                    {/* Desktop Table Header */}
                    <div className="gc-table-header hidden md:grid md:grid-cols-12 md:gap-4 md:border-b md:border-slate-200 md:bg-slate-50 md:p-4">
                        <div className="col-span-3 pl-2">Publicador</div>
                        <div className="col-span-2 text-center">Horas</div>
                        <div className="col-span-1 text-center">Est.</div>
                        <div className="col-span-2 text-center">Observaciones</div>
                        <div className="col-span-2 text-center">Pastoreo</div>
                        <div className="col-span-2 text-center">Acciones</div>
                    </div>

                    <div style={{ display: 'flex', flexDirection: 'column' }}>
                        {filteredMembers.map((m, index) => {
                            const pName = m.publicador_nombre;
                            const reportEntry = reports[pName];

                            // Determine current visual mode based on data
                            let currentMode = 'empty';
                            if (reportEntry) {
                                if (reportEntry.horas === 0) {
                                    currentMode = 'predico';
                                } else if (reportEntry.horas === '' || (typeof reportEntry.horas === 'number' && reportEntry.horas > 0)) {
                                    currentMode = 'horas';
                                }
                            }

                            const visitData = visits[pName] || { date: '', notes: '' };
                            const visitDate = visitData.date;

                            // Visual cue logic
                            let visitBadgeClass = 'status-badge neutral';
                            let visitLabel = 'Sin registrar';
                            if (visitDate) {
                                const daysSince = (new Date().getTime() - new Date(visitDate).getTime()) / (1000 * 3600 * 24);
                                if (daysSince < 90) { visitBadgeClass = 'status-badge success'; visitLabel = 'Reciente'; } 
                                else if (daysSince < 180) { visitBadgeClass = 'status-badge warning'; visitLabel = 'Atención'; } 
                                else { visitBadgeClass = 'status-badge danger'; visitLabel = 'Urgente'; }
                            }

                            return (
                                <div key={m.id} className="grid grid-cols-2 gap-3 p-3 border-b border-slate-100 items-center transition-colors hover:bg-slate-50 md:grid-cols-12 md:gap-4 md:p-4 md:items-start">

                                    {/* Name: Spans 2 cols on mobile (full width), 3 on desktop */}
                                    <div className="col-span-2 flex items-center gap-3 md:col-span-3 md:mt-2">
                                        <div className="text-gray-400 font-semibold min-w-[1.5rem] text-center text-sm">{index + 1}</div>
                                        <div className="font-semibold text-gray-800 text-base">{pName}</div>
                                    </div>

                                    {/* Hours & Studies: Spans 2 col on mobile, 3 on desktop (2 for hours, 1 for studies) */}
                                    <div className="col-span-2 flex gap-2 md:col-span-3 md:contents">
                                        {/* Hours */}
                                        <div className="flex flex-col items-center bg-gray-50 p-2 rounded-lg w-1/2 md:w-auto md:bg-transparent md:p-0 md:col-span-2">
                                            <span className="md:hidden text-xs text-gray-500 font-bold uppercase mb-1">Horas</span>
                                            <div className="flex items-center gap-2 justify-center w-full">
