                                const newMode = e.target.value;
                                if (newMode === 'empty') {
                                    onRemoveReport(pName);
                                    setIsCustomHour(false);
                                } else if (newMode === 'predico') {
                                    onReportChange(pName, 'horas', '0');
                                    setIsCustomHour(false);
                                } else if (newMode === 'horas') {
                                    // Al cambiar a horas, limpiamos para forzar selección en menú
                                    onReportChange(pName, 'horas', ''); 
                                    setIsCustomHour(false);
                                }
                            }}
                            style={{ 
                                padding: '0.3rem 0.4rem', borderRadius: '0.4rem', border: '1px solid #d1d5db', 
                                backgroundColor: 'white', fontSize: '0.8rem', color: '#374151', cursor: 'pointer', outline: 'none' 
                            }}
                        >
                            <option value="empty">--</option>
                            <option value="predico">Predicó</option>
                            <option value="horas">Horas</option>
                        </select>

                        {currentMode === 'horas' && (
                            <>
                                {!isCustomHour ? (
                                    <select
                                        value={reportEntry?.horas || ''}
                                        onChange={(e) => {
                                            const val = e.target.value;
                                            if (val === 'custom') {
                                                setIsCustomHour(true);
                                                // Opcional: limpiar valor al cambiar a manual para escribir desde cero
                                                // onReportChange(pName, 'horas', ''); 
                                            } else {
                                                onReportChange(pName, 'horas', val);
                                            }
                                        }}
                                        className="input-has-report"
                                        style={{ 
                                            padding: '0.3rem', borderRadius: '0.4rem', border: '2px solid #34d399', 
                                            outline: 'none', color: '#065f46', backgroundColor: '#ecfdf5', fontSize: '0.9rem', fontWeight: '700',
                                            cursor: 'pointer', width: '4rem'
