            .print-actions button { font-size: 0.95em; padding: 10px 24px; border: 1px solid #cbd5e1; border-radius: 8px; cursor: pointer; background:#fff; font-weight: 600; color: #334155; transition: all 0.2s; display: flex; align-items: center; gap: 8px; }
