const Programa: React.FC = () => {
    const { programs, lists, history, loading, error, refetch } = useProgramData();
    const [selectedWeek, setSelectedWeek] = useState('');
    const [programData, setProgramData] = useState<any | null>(null);
    const [saveStatus, setSaveStatus] = useState<{ message: string, type: 'error' | 'success' | 'loading' } | null>(null);
    const [printStartWeek, setPrintStartWeek] = useState('');
    const [printEndWeek, setPrintEndWeek] = useState('');

    useEffect(() => {
        if (programs.length > 0 && !selectedWeek) {
            const today = new Date();
            const closest = programs.reduce((prev: any, curr: any) => 
                (Math.abs(new Date(curr.week_id).getTime() - today.getTime()) < Math.abs(new Date(prev.week_id).getTime() - today.getTime()) ? curr : prev)
            );
            const initialWeek = closest?.week_id || programs[0]?.week_id || '';
            setSelectedWeek(initialWeek);
            setPrintStartWeek(initialWeek);
            setPrintEndWeek(initialWeek);
        }
    }, [programs, selectedWeek]);

    useEffect(() => {
        if (selectedWeek && programs.length > 0) {
            const data = programs.find(p => p.week_id === selectedWeek)?.data;
            if (data) {
                setProgramData(JSON.parse(JSON.stringify(data)));
            }
        }
    }, [selectedWeek, programs]);

    const handleDataChange = (weekId: string, path: string, value: any) => {
        if (!programData || weekId !== selectedWeek) return;
        setProgramData((prev: any) => {
            const newData = JSON.parse(JSON.stringify(prev));
            const keys = path.split('.');
            let current = newData;
            for (let i = 0; i < keys.length - 1; i++) {
                const key = keys[i];
                if (!current[key]) current[key] = !isNaN(parseInt(keys[i+1], 10)) ? [] : {};
                current = current[key];
            }
            current[keys[keys.length - 1]] = value;
            return newData;
        });
    };

    const handleSave = async () => {
        if (!programData || !selectedWeek) return;
        setSaveStatus({ message: 'Guardando...', type: 'loading' });

        const { error: updateError } = await supabase.from('programas').update({ data: programData }).eq('week_id', selectedWeek);

        if (updateError) { 
            setSaveStatus({ message: `Error: ${updateError.message}`, type: 'error' }); 
        } else {
            setSaveStatus({ message: '¡Guardado con éxito!', type: 'success' });
            refetch();
        }
        setTimeout(() => setSaveStatus(null), 3000);
    };

    const handleOpenPrintPreview = () => {
        if (!printStartWeek || !printEndWeek) {
            alert('Por favor seleccione un rango de fechas válido');
            return;
        }

        const weeks = programs
            .map(p => p.week_id)
            .sort()
            .filter(w => w >= printStartWeek && w <= printEndWeek);

        if (weeks.length === 0) {
            alert('No hay programas en el rango seleccionado');
            return;
        }

        const programsToPrint = weeks.map(week => ({
            data: week === selectedWeek ? programData : programs.find(p => p.week_id === week)?.data,
            week_id: week
        }));

        const html = buildPrintableHTML(programsToPrint);
        const printWindow = window.open('', '_blank');
        if (printWindow) {
            printWindow.document.open();
            printWindow.document.write(html);
            printWindow.document.close();
        } else {
            alert("Por favor, permita las ventanas emergentes para esta página.");
        }
    };

    const getValue = (path: string) => path.split('.').reduce((o, key) => o?.[key], programData);

    // Rule-based duplication detection logic
    const duplicatedParticipants = useMemo(() => {
        if (!programData) return [];

        const counts: Record<string, number> = {};
        const participants: string[] = [];

        const addNames = (val: any) => {
            if (!val || typeof val !== 'string') return;
            // Split by slash and trim to handle pairs in SMM
            val.split('/').forEach(name => {
                const trimmed = name.trim();
                if (trimmed) participants.push(trimmed);
            });
        };

        // 1. Presidente Sala Principal
        addNames(programData.presidentes?.principal);

        // 2. Tesoros de la Biblia
        if (programData.tesoros) {
            addNames(programData.tesoros.p1?.main);
            addNames(programData.tesoros.p2?.main);
            addNames(programData.tesoros.p3?.main);
            addNames(programData.tesoros.p3?.aux2);
            addNames(programData.tesoros.p3?.aux3);
        }

        // 3. Seamos Mejores Maestros (All rooms)
        if (programData.maestros) {
            programData.maestros.forEach((m: any) => {
                addNames(m.main);
                addNames(m.aux2);
                addNames(m.aux3);
            });
        }

        // 4. Vida Cristiana
        if (programData.vidaCristiana) {
            programData.vidaCristiana.forEach((v: any) => {
                if (v.discursante) addNames(v.discursante);
                if (v.conductor) addNames(v.conductor);
                if (v.lector) addNames(v.lector);
            });
        }

        participants.forEach(p => counts[p] = (counts[p] || 0) + 1);
        return Object.entries(counts)
            .filter(([_, count]) => count > 1)
            .map(([name, _]) => name);
    }, [programData]);

    if (loading) return <div className="p-10 text-center">Cargando programa...</div>;
    if (error) return <div className="p-10 text-center text-red-600">Error al cargar: {error}</div>;

    return (
        <div className="container mx-auto px-4 py-8 programa-page">
            <div className="programa-controls-box">
                <label htmlFor="week-selector">Seleccione Semana:</label>
                <select id="week-selector" value={selectedWeek} onChange={e => setSelectedWeek(e.target.value)}>
                    {programs.map(p => <option key={p.week_id} value={p.week_id}>{p.data?.titulo || p.week_id}</option>)}
                </select>
            </div>

            {/* Duplication Warning Alert */}
            {duplicatedParticipants.length > 0 && (
                <div className="bg-amber-100 border-l-4 border-amber-500 text-amber-800 p-4 mb-6 rounded shadow-sm flex items-start gap-3 animate-pulse-subtle">
                    <i className="fas fa-exclamation-triangle mt-1 text-amber-600"></i>
                    <div>
                        <p className="font-bold">Advertencia de Duplicación</p>
                        <p className="text-sm">
                            Los siguientes participantes tienen más de una asignación esta semana: 
                            <span className="font-semibold ml-1">{duplicatedParticipants.join(', ')}</span>.
                        </p>
                    </div>
                </div>
            )}

            {saveStatus && <div className={`text-center font-semibold p-4 mb-4 rounded-lg bg-${saveStatus.type === 'error' ? 'red-100 text-red-800' : saveStatus.type === 'success' ? 'green-100 text-green-800' : 'blue-100 text-blue-800'}`}>{saveStatus.message}</div>}

            <DesktopProgramView programData={programData} getValue={getValue} handleDataChange={handleDataChange} lists={lists} history={history} selectedWeek={selectedWeek} />
            <MobileProgramView programData={programData} getValue={getValue} handleDataChange={handleDataChange} lists={lists} history={history} selectedWeek={selectedWeek} />

             <div className="program-controls-footer">
                <div className="print-controls-group">
                    <div className="print-control-item">
                        <label htmlFor="print-start-week">Imprimir desde:</label>
                        <select 
                            id="print-start-week" 
                            value={printStartWeek} 
                            onChange={e => {
                                const newStart = e.target.value;
                                setPrintStartWeek(newStart);
                                if (printEndWeek < newStart) {
                                    setPrintEndWeek(newStart);
                                }
                            }}
                        >
                            {programs.map(p => <option key={p.week_id} value={p.week_id}>{p.data?.titulo || p.week_id}</option>)}
                        </select>
                    </div>
                    <div className="print-control-item">
                        <label htmlFor="print-end-week">hasta:</label>
                        <select 
                            id="print-end-week" 
                            value={printEndWeek} 
                            onChange={e => setPrintEndWeek(e.target.value)}
                        >
                            {programs.filter(p => p.week_id >= printStartWeek).map(p => <option key={p.week_id} value={p.week_id}>{p.data?.titulo || p.week_id}</option>)}
                        </select>
                    </div>
                    <div className="print-control-item">
                        <label htmlFor="watermark-text">Marca de agua:</label>
                        <input 
                            type="text" 
                            id="watermark-text" 
                            value={programData?.watermark ?? 'PRELIMINAR'} 
                            onChange={e => handleDataChange(selectedWeek, 'watermark', e.target.value)} 
                        />
                    </div>
                    <div className="print-control-item">
                        <label htmlFor="toggle-blur">
                            <input 
                                type="checkbox" 
                                id="toggle-blur" 
                                checked={programData?.isBlurred ?? false} 
                                onChange={e => handleDataChange(selectedWeek, 'isBlurred', e.target.checked)} 
                            />
                            Difuminar
                        </label>
                    </div>
                </div>
                 <div className="footer-actions">
                    <button onClick={handleOpenPrintPreview} className="button-print">
                        <i className="fas fa-eye"></i> Vista Previa
                    </button>
                    <button onClick={handleSave} className="button-save">
                        <i className="fas fa-save"></i> Guardar Cambios
                    </button>
                </div>
            </div>
        </div>
    );
};

