            .print-actions button.primary { background: #2563eb; color: #fff; border-color: #1d4ed8; }
            .print-actions button.pdf-btn { background: #10b981; color: #fff; border-color: #059669; }
            .print-actions button.whatsapp-btn { background: #25D366; color: #fff; border-color: #128C7E; }
            .print-actions button.whatsapp-btn:hover { background: #128C7E; border-color: #075E54; }

            #print-container { width: 210mm; margin: 0 auto; background-color: transparent; padding: 0; }

            .print-page {
                width: 210mm;
                max-height: 297mm;
                padding: 6mm 10mm;
                box-sizing: border-box;
                display: flex;
                flex-direction: column;
                position: relative;
                background: #ffffff;
                box-shadow: 0 4px 20px rgba(0,0,0,0.1);
                margin-bottom: 0;
                page-break-after: always;
            }

            .print-page:last-of-type {
                page-break-after: auto;
            }

            .printable-program { 
                /* Increased height slightly to accommodate content, but kept constraints for layout */
                height: 140mm; 
                max-height: 140mm;
                overflow: hidden;
                display: flex;
                flex-direction: column;
                position: relative;
                box-sizing: border-box;
                background: #fff;
            }

            .page-divider {
                height: 0;
                border-top: 1px dashed #cbd5e1;
                margin: 3mm 0;
                width: 100%;
                flex-shrink: 0;
            }

            /* Compact Styles for Table */
            .print-table { width: 100%; border-collapse: collapse; table-layout: fixed; font-size: 9pt; border: 1px solid #ccc; }
            .print-header-date { font-size: 12pt; font-weight: 700; padding: 2px; border: 1px solid #ccc; text-align: center; text-transform: uppercase; background: #fff; color: #000; }

            .room-headers th { padding: 2px 2px; border: 1px solid #ccc; text-align: center; font-weight: 600; font-size: 9pt; background: #f8fafc; }

            .print-table td { padding: 1px 3px; vertical-align: middle; line-height: 1.1; border: 1px solid #ccc; }
            .print-table td.participante { text-align: center; font-weight: 400; color: #000; }
            .part-label { text-align: left; }

            .col-parte { width: 38%; }
            .col-sala { width: 20.6%; }

            .section td { font-weight: 800; text-transform: uppercase; color: #fff; padding: 2px 8px; text-align: center !important; font-size: 9.5pt; border: 1px solid #000 !important; }
            .section.tesoros td { background-color: #475569 !important; } 
            .section.maestros td { background-color: #c19a26 !important; } 
            .section.vida-cristiana td { background-color: #8b2c39 !important; } 

            .printable-program.blurred { position: relative; }
            .printable-program.blurred::before { 
                content: attr(data-watermark); 
                position: absolute; 
                top: 50%; 
                left: 50%; 
                transform: translate(-50%, -50%) rotate(-35deg); 
                font-size: 4.5em; 
                color: rgba(0,0,0,0.08); 
                font-weight: 900; 
                pointer-events: none; 
                z-index: 1000; 
                white-space: nowrap;
            }
            .printable-program.blurred .print-table { filter: blur(4px); opacity: 0.7; }
        </style>
    `;

    return `
        <!DOCTYPE html><html lang="es"><head><meta charset="utf-8"><title>Programa VMT - Vista Previa</title>
        <script src="https://cdnjs.cloudflare.com/ajax/libs/html2pdf.js/0.10.1/html2pdf.bundle.min.js"></script>
        <script src="https://html2canvas.hertzen.com/dist/html2canvas.min.js"></script>
        <link rel="stylesheet" href="https://cdnjs.cloudflare.com/ajax/libs/font-awesome/6.4.0/css/all.min.css">
        ${styles}</head><body>
            <div class="print-actions no-print">
                <button class="primary" onclick="window.print()"><i class="fas fa-print"></i> Imprimir</button>
                <button class="pdf-btn" onclick="generatePDF()"><i class="fas fa-file-pdf"></i> Descargar PDF</button>
                <button class="whatsapp-btn" onclick="shareImage()"><i class="fab fa-whatsapp"></i> Compartir</button>
                <button onclick="window.close()"><i class="fas fa-times"></i> Cerrar</button>
            </div>
            <div id="print-container">${pagesHTML}</div>
            <script>
                function generatePDF() {
                    const element = document.getElementById('print-container');
                    const opt = {
                        margin: 0,
                        filename: 'programa_vmt.pdf',
                        image: { type: 'jpeg', quality: 1 },
                        html2canvas: { scale: 2, useCORS: true, logging: false },
                        jsPDF: { unit: 'mm', format: 'a4', orientation: 'portrait' },
                        pagebreak: { mode: ['css', 'legacy'] }
                    };
                    html2pdf().from(element).set(opt).save();
                }

                function shareImage() {
                    const element = document.getElementById('print-container');
                    const btn = document.querySelector('.whatsapp-btn');
                    const originalText = btn.innerHTML;

                    btn.innerHTML = '<i class="fas fa-spinner fa-spin"></i> Generando...';
                    btn.disabled = true;

                    html2canvas(element, { 
                        scale: 2, 
                        useCORS: true,
                        backgroundColor: '#ffffff'
                    }).then(canvas => {
                        canvas.toBlob(async (blob) => {
                            if (!blob) {
                                alert("Error al generar la imagen.");
                                btn.innerHTML = originalText;
                                btn.disabled = false;
                                return;
                            }

                            const file = new File([blob], "programa_vmt.png", { type: "image/png" });

                            // Check if Web Share API is supported and can share files
                            if (navigator.canShare && navigator.canShare({ files: [file] })) {
                                try {
                                    await navigator.share({
                                        files: [file],
                                        title: 'Programa VMT',
                                        text: 'Estimados hermanitos un recordatorio para nuestra reunión de entre semana.'
                                    });
                                } catch (err) {
                                    if (err.name !== 'AbortError') {
                                        console.error('Error al compartir:', err);
                                    }
                                }
                            } else {
                                // Fallback for desktop or browsers without file sharing support
                                const link = document.createElement('a');
                                link.download = 'programa_vmt.png';
                                link.href = canvas.toDataURL('image/png');
                                link.click();
                                alert("Tu navegador no soporta compartir imágenes directamente. La imagen se ha descargado; puedes enviarla manualmente.");
                            }

                            btn.innerHTML = originalText;
                            btn.disabled = false;
                        }, 'image/png');
                    }).catch(err => {
                        console.error(err);
                        alert("Ocurrió un error al procesar la imagen.");
                        btn.innerHTML = originalText;
                        btn.disabled = false;
                    });
                }
            </script>
        </body></html>
    `;
};


