                    }
                    return null;
                })}
            </div>
        </div>
    );

    return (
        <div className="programa-mobile-view">
             <nav className="mobile-tabs-nav">
                <button onClick={() => setActiveMobileTab('general')} className={activeMobileTab === 'general' ? 'active' : ''}>General</button>
                <button onClick={() => setActiveMobileTab('tesoros')} className={activeMobileTab === 'tesoros' ? 'active' : ''}>Tesoros</button>
