            </div>
        </>
    );
};

const GrupoCongregacion: React.FC = () => {
    // Data State
    const [groups, setGroups] = useState<Group[]>([]);
    const [selectedGroupId, setSelectedGroupId] = useState<number | null>(null);
    const [members, setMembers] = useState<GroupMember[]>([]);
    const [masterPublishers, setMasterPublishers] = useState<Publisher[]>([]); // All publishers from DB

    // UI State
    const [loading, setLoading] = useState(true);
    const [currentMonth, setCurrentMonth] = useState<string>('');
    const [reports, setReports] = useState<ReportsMap>({});
    const [visits, setVisits] = useState<VisitsMap>({});
    const [searchTerm, setSearchTerm] = useState('');
    const [addSearchTerm, setAddSearchTerm] = useState(''); // Search input for adding
    const [showSuggestions, setShowSuggestions] = useState(false);
    const [isCreatingGroup, setIsCreatingGroup] = useState(false);
    const [newGroupName, setNewGroupName] = useState('');
    const [statusMessage, setStatusMessage] = useState<{ text: string; type: 'success' | 'error' | 'info' } | null>(null);

    const suggestionsRef = useRef<HTMLDivElement>(null);

    // Initial Load
    useEffect(() => {
        const now = new Date();
        const yyyy = now.getFullYear();
        const mm = String(now.getMonth() + 1).padStart(2, '0');
        setCurrentMonth(`${yyyy}-${mm}`);

        fetchGroups();
        fetchMasterPublishers();

        // Close suggestions on click outside
        const handleClickOutside = (event: MouseEvent) => {
            if (suggestionsRef.current && !suggestionsRef.current.contains(event.target as Node)) {
                setShowSuggestions(false);
            }
        };
        document.addEventListener('mousedown', handleClickOutside);
        return () => document.removeEventListener('mousedown', handleClickOutside);
    }, []);

    // Load Data Functions
    const fetchGroups = async () => {
        const { data, error } = await supabase.from('grupos').select('*').order('nombre');
        if (error) {
            console.error("Error fetching groups:", error);
        } else if (data) {
            setGroups(data);
            if (data.length > 0 && !selectedGroupId) {
                // Try to find "Grupo 5" first, else default to first
                const defaultGroup = data.find(g => g.nombre.includes('5')) || data[0];
                setSelectedGroupId(defaultGroup.id);
            }
        }
    };

    const fetchMasterPublishers = async () => {
        const { data } = await supabase.from('publicadores').select('id, nombre').order('nombre');
        if (data) setMasterPublishers(data);
    };

    const fetchMembers = async () => {
        if (!selectedGroupId) return;
        setLoading(true);
        const { data, error } = await supabase
            .from('miembros_grupo')
            .select('*')
            .eq('grupo_id', selectedGroupId)
            .order('publicador_nombre');

        if (error) console.error("Error fetching members:", error);
        else setMembers(data || []);
        setLoading(false);
    };

    // Load Members when Group Changes
    useEffect(() => {
        fetchMembers();
    }, [selectedGroupId]);

    // Load Reports/Visits when Members or Month Change
    useEffect(() => {
        if (!currentMonth || members.length === 0) return;

        const fetchData = async () => {
            // Get reports only for current members
            const memberNames = members.map(m => m.publicador_nombre);

            const { data: reportsData } = await supabase
                .from('informes_ministerio')
                .select('publicador_nombre, horas, estudios, notas')
                .eq('mes', currentMonth)
                .in('publicador_nombre', memberNames);

            const newReports: ReportsMap = {};
            if (reportsData) {
                reportsData.forEach((r: any) => {
                    newReports[r.publicador_nombre] = { 
                        horas: r.horas,
                        estudios: r.estudios || '',
                        notas: r.notas || ''
                    };
                });
            }
            setReports(newReports);

            const { data: visitsData } = await supabase
                .from('visitas_pastoral')
                .select('publicador_nombre, fecha_visita, notas')
                .in('publicador_nombre', memberNames);

            const newVisits: VisitsMap = {};
            if (visitsData) {
                visitsData.forEach((v: any) => {
                    newVisits[v.publicador_nombre] = {
                        date: v.fecha_visita,
                        notes: v.notas || ''
                    };
                });
            }
            setVisits(newVisits);
        };

        fetchData();
    }, [currentMonth, members]);

    // --- Actions ---

    const handleCreateGroup = async () => {
        if (!newGroupName.trim()) return;
        const normalizedName = newGroupName.trim();

        const { data, error } = await supabase.from('grupos').insert([{ nombre: normalizedName }]).select();

        if (error) {
            // Check for duplicate key error code (Postgres unique violation)
            if (error.code === '23505') {
                const { data: existingGroup } = await supabase
                    .from('grupos')
                    .select('*')
                    .eq('nombre', normalizedName)
                    .single();

                if (existingGroup) {
                    setGroups(prev => {
                        if (prev.some(g => g.id === existingGroup.id)) return prev;
                        return [...prev, existingGroup].sort((a,b) => a.nombre.localeCompare(b.nombre));
                    });
                    setSelectedGroupId(existingGroup.id);
                    setIsCreatingGroup(false);
                    setNewGroupName('');
                    setStatusMessage({ text: `El grupo "${normalizedName}" ya existe. Seleccionado.`, type: 'info' });
                    setTimeout(() => setStatusMessage(null), 3000);
                    return; 
                }
            }

            console.error("Error creating group:", error);
            setStatusMessage({ text: `Error: ${error.message}`, type: 'error' });
            setTimeout(() => setStatusMessage(null), 4000);
        } else if (data) {
            setGroups(prev => [...prev, data[0]].sort((a,b) => a.nombre.localeCompare(b.nombre)));
            setSelectedGroupId(data[0].id);
            setIsCreatingGroup(false);
            setNewGroupName('');
            setStatusMessage({ text: 'Grupo creado con éxito', type: 'success' });
            setTimeout(() => setStatusMessage(null), 3000);
        }
    };

    const handleDeleteGroup = async () => {
        if (!selectedGroupId) return;
        const groupName = groups.find(g => g.id === selectedGroupId)?.nombre;
        if (!window.confirm(`¿Estás seguro de eliminar el "${groupName}" y todos sus integrantes?`)) return;

        const { error } = await supabase.from('grupos').delete().eq('id', selectedGroupId);
        if (error) {
            console.error("Error deleting group:", error);
            setStatusMessage({ text: `Error al eliminar: ${error.message}`, type: 'error' });
        } else {
            const remaining = groups.filter(g => g.id !== selectedGroupId);
            setGroups(remaining);
            setSelectedGroupId(remaining.length > 0 ? remaining[0].id : null);
            setMembers([]);
            setStatusMessage({ text: 'Grupo eliminado', type: 'success' });
            setTimeout(() => setStatusMessage(null), 3000);
        }
    };

    const handleAddMember = async (name: string) => {
        if (!selectedGroupId || !name.trim()) return;

        // Check local duplicate
        if (members.some(m => m.publicador_nombre.toLowerCase() === name.toLowerCase())) {
            setStatusMessage({ text: 'Esta persona ya está en el grupo', type: 'error' });
            setTimeout(() => setStatusMessage(null), 3000);
            return;
        }

        const { error } = await supabase.from('miembros_grupo').insert([{
            grupo_id: selectedGroupId,
            publicador_nombre: name.trim()
        }]);

        if (error) {
            console.error(error);
            setStatusMessage({ text: `Error al agregar: ${error.message}`, type: 'error' });
        } else {
            setStatusMessage({ text: 'Agregado correctamente', type: 'success' });
            setAddSearchTerm('');
            fetchMembers();
        }
        setTimeout(() => setStatusMessage(null), 3000);
    };

    const handleDeleteMember = async (id: number, name: string) => {
        if (!window.confirm(`¿Quitar a ${name} de este grupo?`)) return;
        const { error } = await supabase.from('miembros_grupo').delete().eq('id', id);
        if (!error) fetchMembers();
        else console.error("Error deleting member:", error);
    };

    const handleReportChange = (name: string, field: keyof MinistryReport, value: string) => {
        setReports(prev => {
            const currentEntry = prev[name] || { horas: '', estudios: '', notas: '' };
            const newValue = (field === 'horas' || field === 'estudios') 
                ? (value === '' ? '' : Number(value)) 
                : value;

            return {
                ...prev,
                [name]: { ...currentEntry, [field]: newValue }
            };
        });
    };

    const handleRemoveReport = (name: string) => {
        setReports(prev => {
            const next = { ...prev };
            delete next[name];
            return next;
        });
    };

    const handleVisitChange = (name: string, field: keyof VisitData, value: string) => {
        setVisits(prev => {
            const currentEntry = prev[name] || { date: '', notes: '' };
            return {
                ...prev,
                [name]: { ...currentEntry, [field]: value }
            };
        });
    };

    const handleSaveRow = async (publisherName: string) => {
        setStatusMessage(null);
        try {
            // --- Save Report Logic ---
            const reportEntry = reports[publisherName];

            if (reportEntry) {
                // If checkbox is active (exists in state), upsert report
                // Note: If 'Predicó' was selected, horas will be 0. If 'Horas' selected, it will be > 0.
                const valToSave = reportEntry.horas === '' ? 0 : reportEntry.horas;

                const { error: reportError } = await supabase
                    .from('informes_ministerio')
                    .upsert({ 
                        publicador_nombre: publisherName, 
                        mes: currentMonth, 
                        horas: valToSave,
                        estudios: reportEntry.estudios === '' ? 0 : reportEntry.estudios,
                        notas: reportEntry.notas || ''
                    }, { onConflict: 'publicador_nombre, mes' });
                if (reportError) throw reportError;
            } else {
                // If reportEntry is missing (User selected 'Vacío'), delete report from DB
                const { error: deleteError } = await supabase
                    .from('informes_ministerio')
                    .delete()
                    .eq('publicador_nombre', publisherName)
                    .eq('mes', currentMonth);

                // We ignore if it didn't exist, but supabase delete won't error on 0 rows
                if (deleteError) throw deleteError;
            }

            // --- Save Visit Logic ---
            const visitData = visits[publisherName];
            if (visitData && (visitData.date || visitData.notes)) {
                const { error: visitError } = await supabase
                    .from('visitas_pastoral')
                    .upsert({ 
                        publicador_nombre: publisherName, 
                        fecha_visita: visitData.date,
                        notas: visitData.notes
                    }, { onConflict: 'publicador_nombre' });
                if (visitError) throw visitError;
            }

            setStatusMessage({ text: 'Guardado', type: 'success' });
            setTimeout(() => setStatusMessage(null), 2000);
        } catch (err: any) {
            console.error(err);
            setStatusMessage({ text: 'Error al guardar', type: 'error' });
        }
    };

    // Filter Logic for Main Table
    const filteredMembers = members.filter(m => 
        m.publicador_nombre.toLowerCase().includes(searchTerm.toLowerCase())
    );

    // Filter Logic for Add Suggestions
    const filteredSuggestions = masterPublishers
        .filter(p => p.nombre.toLowerCase().includes(addSearchTerm.toLowerCase()))
        .filter(p => !members.some(m => m.publicador_nombre === p.nombre)) // Exclude already in group
