                            </div>
                            <h3 style={{ fontSize: '1.25rem', fontWeight: '700', color: '#374151' }}>
                                {selectedGroupId ? 'Este grupo está vacío' : 'Crea o selecciona un grupo'}
                            </h3>
                            <p style={{ color: '#6b7280', marginTop: '0.5rem', maxWidth: '24rem', marginInline: 'auto' }}>
                                Utiliza el buscador de arriba para agregar publicadores existentes a este grupo.
                            </p>
                        </div>
                    )}
                </div>
            )}
        </div>
    );
};

export default GrupoCongregacion;

import React, { useState, useEffect, useRef } from 'react';
import { supabase } from '../lib/supabase';

type Publisher = {
    id: number;
    nombre: string;
};

type Group = {
    id: number;
    nombre: string;
};

type GroupMember = {
    id: number;
    grupo_id: number;
    publicador_nombre: string;
};

type MinistryReport = {
    horas: number | '';
    estudios: number | '';
    notas?: string;
};

type VisitData = {
    date: string;
    notes: string;
};

type ReportsMap = Record<string, MinistryReport>;
type VisitsMap = Record<string, VisitData>;

// Helper for avatar colors
const getAvatarClass = (name: string) => {
    const classes = ['avatar-red', 'avatar-orange', 'avatar-amber', 'avatar-green', 'avatar-teal', 'avatar-blue', 'avatar-indigo', 'avatar-purple', 'avatar-pink'];
    let hash = 0;
    for (let i = 0; i < name.length; i++) {
        hash = name.charCodeAt(i) + ((hash << 5) - hash);
    }
    return classes[Math.abs(hash) % classes.length];
};

// --- Subcomponente para la fila de cada miembro ---
const MemberRow: React.FC<{
    m: GroupMember;
    index: number;
    reportEntry: MinistryReport | undefined;
    visitData: VisitData;
    onReportChange: (name: string, field: keyof MinistryReport, value: string) => void;
    onVisitChange: (name: string, field: keyof VisitData, value: string) => void;
    onSave: (name: string) => void;
    onDelete: (id: number, name: string) => void;
    onRemoveReport: (name: string) => void;
}> = ({ m, index, reportEntry, visitData, onReportChange, onVisitChange, onSave, onDelete, onRemoveReport }) => {
    const pName = m.publicador_nombre;
    const visitDate = visitData.date;

    // Estado para el Modal Móvil
    const [isMobileModalOpen, setIsMobileModalOpen] = useState(false);

    // Estado local para alternar entre Menú (1-9) y Input Manual
    const [isCustomHour, setIsCustomHour] = useState(false);

    // Determinar modo actual (Vacío / Predicó / Horas)
    let currentMode = 'empty';
    if (reportEntry) {
        if (reportEntry.horas === 0) {
            currentMode = 'predico';
        } else if (reportEntry.horas === '' || (typeof reportEntry.horas === 'number' && reportEntry.horas > 0)) {
            currentMode = 'horas';
        }
    }

    // Efecto para detectar si el valor existente requiere modo manual
    useEffect(() => {
        if (reportEntry?.horas && typeof reportEntry.horas === 'number' && reportEntry.horas > 0) {
            const h = reportEntry.horas;
            if (h > 9 || !Number.isInteger(h)) {
                setIsCustomHour(true);
            } else {
                setIsCustomHour(false);
            }
        }
    }, [reportEntry?.horas]);

    // Lógica visual para las visitas
    let visitBadgeClass = 'bg-gray-100 text-gray-500 border-gray-200';
    let visitLabel = 'N/A';
    if (visitDate) {
        const daysSince = (new Date().getTime() - new Date(visitDate).getTime()) / (1000 * 3600 * 24);
        if (daysSince < 90) { visitBadgeClass = 'bg-green-100 text-green-700 border-green-200'; visitLabel = 'Al día'; } 
        else if (daysSince < 180) { visitBadgeClass = 'bg-amber-100 text-amber-700 border-amber-200'; visitLabel = 'Atención'; } 
        else { visitBadgeClass = 'bg-red-100 text-red-700 border-red-200'; visitLabel = 'Urgente'; }
    }

    // Resumen para la vista compacta móvil
    const getReportSummary = () => {
        if (currentMode === 'empty') return <span className="text-gray-400 italic text-xs">Sin informe</span>;
        if (currentMode === 'predico') return <span className="text-blue-600 font-bold text-xs bg-blue-50 px-2 py-0.5 rounded-full border border-blue-100">Predicó</span>;
        return <span className="text-green-700 font-bold text-xs bg-green-50 px-2 py-0.5 rounded-full border border-green-100">{reportEntry?.horas}h {reportEntry?.estudios ? `+ ${reportEntry.estudios} est.` : ''}</span>;
    };

    // --- RENDERIZADO DEL SELECTOR DE HORAS ---
    const renderHourSelector = (isMobile = false) => (
        <div className={`flex items-center gap-2 ${isMobile ? 'w-full' : 'justify-center'}`}>
            <select
                value={currentMode}
                onChange={(e) => {
                    const newMode = e.target.value;
                    if (newMode === 'empty') {
                        onRemoveReport(pName);
                        setIsCustomHour(false);
                    } else if (newMode === 'predico') {
                        onReportChange(pName, 'horas', '0');
                        setIsCustomHour(false);
                    } else if (newMode === 'horas') {
                        onReportChange(pName, 'horas', ''); 
                        setIsCustomHour(false);
                    }
                }}
                className={`bg-white border border-gray-300 text-gray-700 text-sm rounded-lg focus:ring-blue-500 focus:border-blue-500 block p-2 ${isMobile ? 'flex-grow h-10' : ''}`}
                style={!isMobile ? {minWidth: '80px'} : {}}
            >
                <option value="empty">-- Sin Informe --</option>
                <option value="predico">Predicó (0h)</option>
                <option value="horas">Horas</option>
            </select>

            {currentMode === 'horas' && (
                <>
                    {!isCustomHour ? (
                        <select
                            value={reportEntry?.horas || ''}
                            onChange={(e) => {
                                const val = e.target.value;
                                if (val === 'custom') setIsCustomHour(true);
                                else onReportChange(pName, 'horas', val);
                            }}
                            className={`bg-green-50 border border-green-300 text-green-900 text-sm rounded-lg focus:ring-green-500 focus:border-green-500 block p-2 font-bold text-center ${isMobile ? 'h-10 w-20' : 'w-16'}`}
                        >
                            <option value="" disabled>#</option>
                            {[1, 2, 3, 4, 5, 6, 7, 8, 9].map(num => (
                                <option key={num} value={num}>{num}</option>
                            ))}
                            <option value="custom">...</option>
                        </select>
                    ) : (
                        <div className="flex items-center gap-1">
                            <input 
                                type="number" min="0" step="0.5"
                                value={reportEntry?.horas === 0 ? '' : (reportEntry?.horas ?? '')}
                                onChange={(e) => onReportChange(pName, 'horas', e.target.value)}
                                autoFocus
                                className={`bg-white border border-green-300 text-gray-900 text-sm rounded-lg focus:ring-green-500 focus:border-green-500 block p-2 font-bold text-center ${isMobile ? 'h-10 w-20' : 'w-16'}`}
                                placeholder="#"
                            />
                            <button 
                                onClick={() => setIsCustomHour(false)}
                                title="Volver al menú"
                                className="text-gray-400 hover:text-blue-600 px-1 py-2"
                            >
                                <i className="fas fa-undo text-xs"></i>
                            </button>
                        </div>
                    )}
                </>
            )}
        </div>
    );

    return (
        <>
            {/* --- VISTA MÓVIL: LISTA COMPACTA + MODAL --- */}
            <div className="md:hidden">
                <div 
                    onClick={() => setIsMobileModalOpen(true)}
                    className="flex items-center justify-between p-3 bg-white border-b border-gray-100 active:bg-gray-50 transition-colors cursor-pointer"
                >
                    <div className="flex items-center gap-3 overflow-hidden flex-1">
                        <div className={`flex-shrink-0 w-8 h-8 flex items-center justify-center rounded-full text-xs font-bold shadow-sm ${getAvatarClass(pName)}`}>
                            {pName.charAt(0)}
                        </div>
                        <div className="flex flex-col overflow-hidden">
                            <span className="font-semibold text-gray-800 truncate text-sm">{pName}</span>
                            <div className="flex items-center gap-2 mt-0.5">
                                {getReportSummary()}
                                {visitDate && (
                                    <span className={`text-[10px] px-1.5 py-px rounded border ${visitBadgeClass}`}>
                                        Visita: {visitLabel}
                                    </span>
                                )}
                            </div>
                        </div>
                    </div>
                    <div className="text-gray-400 pl-2">
                        <i className="fas fa-chevron-right text-xs"></i>
                    </div>
                </div>

                {/* MODAL EMERGENTE */}
                {isMobileModalOpen && (
                    <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/50 backdrop-blur-[2px] p-4 animate-fadeIn">
                        <div className="bg-white w-full max-w-sm rounded-2xl shadow-2xl overflow-hidden flex flex-col max-h-[90vh] animate-slideUp">

                            {/* Modal Header */}
                            <div className="bg-gray-50 px-4 py-3 border-b border-gray-200 flex justify-between items-center">
                                <h3 className="font-bold text-gray-700 truncate pr-2">{pName}</h3>
                                <button 
                                    onClick={() => setIsMobileModalOpen(false)}
                                    className="text-gray-400 hover:text-gray-600 p-1"
                                >
                                    <i className="fas fa-times text-lg"></i>
                                </button>
                            </div>

                            {/* Modal Body */}
                            <div className="p-5 overflow-y-auto">

                                {/* Sección Ministerio */}
                                <div className="mb-6">
                                    <h4 className="text-xs font-bold text-gray-400 uppercase tracking-wider mb-3 flex items-center gap-2">
                                        <i className="fas fa-briefcase"></i> Informe del Mes
                                    </h4>

                                    <div className="space-y-4">
                                        <div className="flex gap-3">
                                            {renderHourSelector(true)}
                                        </div>

                                        <div className="grid grid-cols-2 gap-3">
                                            <div className="relative">
                                                <label className="text-[10px] text-gray-500 absolute -top-1.5 left-2 bg-white px-1">Estudios</label>
                                                <input 
                                                    type="number" min="0" 
                                                    value={reportEntry?.estudios || ''} 
                                                    onChange={(e) => onReportChange(pName, 'estudios', e.target.value)}
                                                    className="block w-full px-3 py-2.5 text-sm border border-gray-300 rounded-lg focus:ring-blue-500 focus:border-blue-500"
                                                    placeholder="0"
                                                />
                                            </div>
                                        </div>

                                        <div className="relative">
                                            <label className="text-[10px] text-gray-500 absolute -top-1.5 left-2 bg-white px-1">Observaciones</label>
                                            <textarea
                                                value={reportEntry?.notas || ''}
                                                onChange={(e) => onReportChange(pName, 'notas', e.target.value)}
                                                rows={2}
                                                className="block w-full px-3 py-2.5 text-sm border border-gray-300 rounded-lg focus:ring-blue-500 focus:border-blue-500 resize-none"
                                                placeholder="Ej. Precursor auxiliar..."
                                            ></textarea>
                                        </div>
                                    </div>
                                </div>

                                <div className="border-t border-dashed border-gray-200 my-4"></div>

                                {/* Sección Pastoreo */}
                                <div>
                                    <div className="flex justify-between items-center mb-3">
                                        <h4 className="text-xs font-bold text-gray-400 uppercase tracking-wider flex items-center gap-2">
                                            <i className="fas fa-hand-holding-heart"></i> Visita Pastoral
                                        </h4>
                                        <span className={`px-2 py-0.5 rounded text-[10px] font-medium border ${visitBadgeClass}`}>
                                            {visitLabel}
                                        </span>
                                    </div>

                                    <div className="space-y-3">
                                        <div className="relative">
                                            <label className="text-[10px] text-gray-500 absolute -top-1.5 left-2 bg-white px-1">Última Visita</label>
                                            <input 
                                                type="date" 
                                                value={visitDate}
                                                onChange={(e) => onVisitChange(pName, 'date', e.target.value)}
                                                className="block w-full px-3 py-2.5 text-sm border border-gray-300 rounded-lg focus:ring-blue-500 focus:border-blue-500"
                                            />
                                        </div>
                                        <div className="relative">
                                            <label className="text-[10px] text-gray-500 absolute -top-1.5 left-2 bg-white px-1">Nota Pastoral</label>
                                            <textarea
                                                value={visitData.notes || ''}
                                                onChange={(e) => onVisitChange(pName, 'notes', e.target.value)}
                                                rows={2}
                                                className="block w-full px-3 py-2.5 text-sm border border-gray-300 rounded-lg focus:ring-blue-500 focus:border-blue-500 resize-none"
                                                placeholder="Detalles de la visita..."
                                            ></textarea>
                                        </div>
                                    </div>
                                </div>
                            </div>

                            {/* Modal Footer */}
                            <div className="bg-gray-50 p-4 border-t border-gray-200 flex gap-3">
                                <button 
                                    onClick={() => onDelete(m.id, pName)}
                                    className="flex-1 bg-white text-red-600 border border-red-200 hover:bg-red-50 font-medium py-2.5 rounded-lg text-sm transition-colors"
                                >
                                    <i className="fas fa-trash-alt mr-2"></i> Eliminar
                                </button>
                                <button 
                                    onClick={() => {
                                        onSave(pName);
                                        setIsMobileModalOpen(false);
                                    }}
                                    className="flex-[2] bg-blue-600 text-white hover:bg-blue-700 font-bold py-2.5 rounded-lg text-sm shadow-md active:scale-[0.98] transition-all"
                                >
                                    <i className="fas fa-save mr-2"></i> Guardar
                                </button>
                            </div>
                        </div>
                    </div>
                )}
            </div>

            {/* --- VISTA DE ESCRITORIO (TABLA CLÁSICA - SIN CAMBIOS) --- */}
            <div className="hidden md:grid md:grid-cols-12 md:gap-4 md:p-4 md:items-start border-b border-slate-100 hover:bg-slate-50 transition-colors">
                {/* Nombre */}
                <div className="col-span-3 flex items-center gap-3 md:mt-2">
                    <div className="text-gray-400 font-semibold min-w-[1.5rem] text-center text-sm">{index + 1}</div>
                    <div className="font-semibold text-gray-800 text-base">{pName}</div>
                </div>

                {/* Inputs Horas/Estudios */}
                <div className="col-span-2 flex justify-center">
                    {renderHourSelector()}
                </div>
                <div className="col-span-1 flex justify-center">
                    <input 
                        type="number" min="0"
                        value={reportEntry?.estudios || ''}
                        onChange={(e) => onReportChange(pName, 'estudios', e.target.value)}
                        className="bg-white border border-gray-300 text-gray-900 text-sm rounded-lg focus:ring-blue-500 focus:border-blue-500 block w-14 p-1.5 text-center"
                        placeholder="0"
                    />
                </div>

                {/* Observaciones */}
                <div className="col-span-2">
                    <input
                        type="text"
                        value={reportEntry?.notas || ''}
                        onChange={(e) => onReportChange(pName, 'notas', e.target.value)}
                        placeholder="..."
                        className="bg-white border border-gray-300 text-gray-700 text-sm rounded-lg focus:ring-blue-500 focus:border-blue-500 block w-full p-1.5"
                    />
                </div>

                {/* Pastoreo */}
                <div className="col-span-2 flex flex-col gap-1">
                    <div className="flex gap-1">
                        <input 
                            type="date" value={visitDate}
                            onChange={(e) => onVisitChange(pName, 'date', e.target.value)}
                            className="bg-white border border-gray-300 text-gray-700 text-xs rounded-lg p-1 w-full"
                        />
                        <div className={`w-3 h-3 rounded-full mt-1.5 ${
                            visitLabel === 'Urgente' ? 'bg-red-500' : visitLabel === 'Atención' ? 'bg-amber-500' : visitLabel === 'Al día' ? 'bg-green-500' : 'bg-gray-300'
                        }`} title={visitLabel}></div>
                    </div>
                    <input
                        type="text"
                        value={visitData.notes || ''}
                        onChange={(e) => onVisitChange(pName, 'notes', e.target.value)}
                        placeholder="Notas..."
                        className="bg-white border border-gray-300 text-gray-700 text-xs rounded-lg p-1 w-full"
                    />
                </div>

                {/* Acciones */}
                <div className="col-span-2 flex justify-center gap-2 pt-1">
                    <button 
                        onClick={() => onSave(pName)}
                        className="text-white bg-indigo-600 hover:bg-indigo-700 font-medium rounded-lg text-xs px-3 py-1.5 shadow-sm"
                    >
                        Guardar
                    </button>
                    <button 
                        onClick={() => onDelete(m.id, pName)}
                        className="text-gray-400 hover:text-red-600 p-1.5"
                    >
                        <i className="fas fa-trash-alt"></i>
                    </button>
                </div>
            </div>
        </>
    );
};

const GrupoCongregacion: React.FC = () => {
    // Data State
    const [groups, setGroups] = useState<Group[]>([]);
    const [selectedGroupId, setSelectedGroupId] = useState<number | null>(null);
    const [members, setMembers] = useState<GroupMember[]>([]);
    const [masterPublishers, setMasterPublishers] = useState<Publisher[]>([]); // All publishers from DB

    // UI State
    const [loading, setLoading] = useState(true);
    const [currentMonth, setCurrentMonth] = useState<string>('');
    const [reports, setReports] = useState<ReportsMap>({});
    const [visits, setVisits] = useState<VisitsMap>({});
    const [searchTerm, setSearchTerm] = useState('');
    const [addSearchTerm, setAddSearchTerm] = useState(''); // Search input for adding
    const [showSuggestions, setShowSuggestions] = useState(false);
    const [isCreatingGroup, setIsCreatingGroup] = useState(false);
    const [newGroupName, setNewGroupName] = useState('');
    const [statusMessage, setStatusMessage] = useState<{ text: string; type: 'success' | 'error' | 'info' } | null>(null);

    const suggestionsRef = useRef<HTMLDivElement>(null);

    // Initial Load
    useEffect(() => {
        const now = new Date();
        const yyyy = now.getFullYear();
        const mm = String(now.getMonth() + 1).padStart(2, '0');
        setCurrentMonth(`${yyyy}-${mm}`);

        fetchGroups();
        fetchMasterPublishers();

        // Close suggestions on click outside
        const handleClickOutside = (event: MouseEvent) => {
            if (suggestionsRef.current && !suggestionsRef.current.contains(event.target as Node)) {
                setShowSuggestions(false);
            }
        };
        document.addEventListener('mousedown', handleClickOutside);
        return () => document.removeEventListener('mousedown', handleClickOutside);
    }, []);

    // Load Data Functions
    const fetchGroups = async () => {
        const { data, error } = await supabase.from('grupos').select('*').order('nombre');
        if (error) {
            console.error("Error fetching groups:", error);
        } else if (data) {
            setGroups(data);
            if (data.length > 0 && !selectedGroupId) {
                // Try to find "Grupo 5" first, else default to first
                const defaultGroup = data.find(g => g.nombre.includes('5')) || data[0];
                setSelectedGroupId(defaultGroup.id);
            }
        }
    };

    const fetchMasterPublishers = async () => {
        const { data } = await supabase.from('publicadores').select('id, nombre').order('nombre');
        if (data) setMasterPublishers(data);
    };

    const fetchMembers = async () => {
        if (!selectedGroupId) return;
        setLoading(true);
        const { data, error } = await supabase
            .from('miembros_grupo')
            .select('*')
            .eq('grupo_id', selectedGroupId)
            .order('publicador_nombre');

        if (error) console.error("Error fetching members:", error);
        else setMembers(data || []);
        setLoading(false);
    };

    // Load Members when Group Changes
    useEffect(() => {
        fetchMembers();
    }, [selectedGroupId]);

    // Load Reports/Visits when Members or Month Change
    useEffect(() => {
        if (!currentMonth || members.length === 0) return;

        const fetchData = async () => {
            // Get reports only for current members
            const memberNames = members.map(m => m.publicador_nombre);

            const { data: reportsData } = await supabase
                .from('informes_ministerio')
                .select('publicador_nombre, horas, estudios, notas')
                .eq('mes', currentMonth)
                .in('publicador_nombre', memberNames);

            const newReports: ReportsMap = {};
            if (reportsData) {
                reportsData.forEach((r: any) => {
                    newReports[r.publicador_nombre] = { 
                        horas: r.horas,
                        estudios: r.estudios || '',
                        notas: r.notas || ''
                    };
                });
            }
            setReports(newReports);

            const { data: visitsData } = await supabase
                .from('visitas_pastoral')
                .select('publicador_nombre, fecha_visita, notas')
                .in('publicador_nombre', memberNames);

            const newVisits: VisitsMap = {};
            if (visitsData) {
                visitsData.forEach((v: any) => {
                    newVisits[v.publicador_nombre] = {
                        date: v.fecha_visita,
                        notes: v.notas || ''
                    };
                });
            }
            setVisits(newVisits);
        };

        fetchData();
    }, [currentMonth, members]);

    // --- Actions ---

    const handleCreateGroup = async () => {
        if (!newGroupName.trim()) return;
        const normalizedName = newGroupName.trim();

        const { data, error } = await supabase.from('grupos').insert([{ nombre: normalizedName }]).select();

        if (error) {
            // Check for duplicate key error code (Postgres unique violation)
            if (error.code === '23505') {
                const { data: existingGroup } = await supabase
                    .from('grupos')
                    .select('*')
                    .eq('nombre', normalizedName)
                    .single();

                if (existingGroup) {
                    setGroups(prev => {
                        if (prev.some(g => g.id === existingGroup.id)) return prev;
                        return [...prev, existingGroup].sort((a,b) => a.nombre.localeCompare(b.nombre));
                    });
                    setSelectedGroupId(existingGroup.id);
                    setIsCreatingGroup(false);
                    setNewGroupName('');
                    setStatusMessage({ text: `El grupo "${normalizedName}" ya existe. Seleccionado.`, type: 'info' });
                    setTimeout(() => setStatusMessage(null), 3000);
                    return; 
                }
            }

            console.error("Error creating group:", error);
            setStatusMessage({ text: `Error: ${error.message}`, type: 'error' });
            setTimeout(() => setStatusMessage(null), 4000);
        } else if (data) {
            setGroups(prev => [...prev, data[0]].sort((a,b) => a.nombre.localeCompare(b.nombre)));
            setSelectedGroupId(data[0].id);
            setIsCreatingGroup(false);
            setNewGroupName('');
            setStatusMessage({ text: 'Grupo creado con éxito', type: 'success' });
            setTimeout(() => setStatusMessage(null), 3000);
        }
    };

    const handleDeleteGroup = async () => {
        if (!selectedGroupId) return;
        const groupName = groups.find(g => g.id === selectedGroupId)?.nombre;
        if (!window.confirm(`¿Estás seguro de eliminar el "${groupName}" y todos sus integrantes?`)) return;

        const { error } = await supabase.from('grupos').delete().eq('id', selectedGroupId);
        if (error) {
            console.error("Error deleting group:", error);
            setStatusMessage({ text: `Error al eliminar: ${error.message}`, type: 'error' });
        } else {
            const remaining = groups.filter(g => g.id !== selectedGroupId);
            setGroups(remaining);
            setSelectedGroupId(remaining.length > 0 ? remaining[0].id : null);
            setMembers([]);
            setStatusMessage({ text: 'Grupo eliminado', type: 'success' });
            setTimeout(() => setStatusMessage(null), 3000);
        }
    };

    const handleAddMember = async (name: string) => {
        if (!selectedGroupId || !name.trim()) return;

        // Check local duplicate
        if (members.some(m => m.publicador_nombre.toLowerCase() === name.toLowerCase())) {
            setStatusMessage({ text: 'Esta persona ya está en el grupo', type: 'error' });
            setTimeout(() => setStatusMessage(null), 3000);
            return;
        }

        const { error } = await supabase.from('miembros_grupo').insert([{
            grupo_id: selectedGroupId,
            publicador_nombre: name.trim()
        }]);

        if (error) {
            console.error(error);
            setStatusMessage({ text: `Error al agregar: ${error.message}`, type: 'error' });
        } else {
            setStatusMessage({ text: 'Agregado correctamente', type: 'success' });
            setAddSearchTerm('');
            fetchMembers();
        }
        setTimeout(() => setStatusMessage(null), 3000);
    };

    const handleDeleteMember = async (id: number, name: string) => {
        if (!window.confirm(`¿Quitar a ${name} de este grupo?`)) return;
        const { error } = await supabase.from('miembros_grupo').delete().eq('id', id);
        if (!error) fetchMembers();
        else console.error("Error deleting member:", error);
    };

    const handleReportChange = (name: string, field: keyof MinistryReport, value: string) => {
        setReports(prev => {
            const currentEntry = prev[name] || { horas: '', estudios: '', notas: '' };
            const newValue = (field === 'horas' || field === 'estudios') 
                ? (value === '' ? '' : Number(value)) 
                : value;

            return {
                ...prev,
                [name]: { ...currentEntry, [field]: newValue }
            };
        });
    };

    const handleRemoveReport = (name: string) => {
        setReports(prev => {
            const next = { ...prev };
            delete next[name];
            return next;
        });
    };

    const handleVisitChange = (name: string, field: keyof VisitData, value: string) => {
        setVisits(prev => {
            const currentEntry = prev[name] || { date: '', notes: '' };
            return {
                ...prev,
                [name]: { ...currentEntry, [field]: value }
            };
        });
    };

    const handleSaveRow = async (publisherName: string) => {
        setStatusMessage(null);
        try {
            // --- Save Report Logic ---
            const reportEntry = reports[publisherName];

            if (reportEntry) {
                // If checkbox is active (exists in state), upsert report
                // Note: If 'Predicó' was selected, horas will be 0. If 'Horas' selected, it will be > 0.
                const valToSave = reportEntry.horas === '' ? 0 : reportEntry.horas;

                const { error: reportError } = await supabase
                    .from('informes_ministerio')
                    .upsert({ 
                        publicador_nombre: publisherName, 
                        mes: currentMonth, 
                        horas: valToSave,
                        estudios: reportEntry.estudios === '' ? 0 : reportEntry.estudios,
                        notas: reportEntry.notas || ''
                    }, { onConflict: 'publicador_nombre, mes' });
                if (reportError) throw reportError;
            } else {
                // If reportEntry is missing (User selected 'Vacío'), delete report from DB
                const { error: deleteError } = await supabase
                    .from('informes_ministerio')
                    .delete()
                    .eq('publicador_nombre', publisherName)
                    .eq('mes', currentMonth);

                // We ignore if it didn't exist, but supabase delete won't error on 0 rows
                if (deleteError) throw deleteError;
            }

            // --- Save Visit Logic ---
            const visitData = visits[publisherName];
            if (visitData && (visitData.date || visitData.notes)) {
                const { error: visitError } = await supabase
                    .from('visitas_pastoral')
                    .upsert({ 
                        publicador_nombre: publisherName, 
                        fecha_visita: visitData.date,
                        notas: visitData.notes
                    }, { onConflict: 'publicador_nombre' });
                if (visitError) throw visitError;
            }

            setStatusMessage({ text: 'Guardado', type: 'success' });
            setTimeout(() => setStatusMessage(null), 2000);
        } catch (err: any) {
            console.error(err);
            setStatusMessage({ text: 'Error al guardar', type: 'error' });
        }
    };

    // Filter Logic for Main Table
    const filteredMembers = members.filter(m => 
        m.publicador_nombre.toLowerCase().includes(searchTerm.toLowerCase())
    );

    // Filter Logic for Add Suggestions
    const filteredSuggestions = masterPublishers
        .filter(p => p.nombre.toLowerCase().includes(addSearchTerm.toLowerCase()))
        .filter(p => !members.some(m => m.publicador_nombre === p.nombre)) // Exclude already in group
        .slice(0, 6); // Limit results

    const currentGroupName = groups.find(g => g.id === selectedGroupId)?.nombre || 'Sin Grupo';

    return (
        <div className="container mx-auto px-4 py-8 group-container">

            {/* --- TOP BAR: Group Selector & Date --- */}
            <div style={{ display: 'flex', flexDirection: 'column', gap: '1.5rem', marginBottom: '2rem' }}>
                <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', flexWrap: 'wrap', gap: '1rem' }}>
                    <div style={{flex: 1}}>
                        {!isCreatingGroup ? (
                            <div style={{display: 'flex', alignItems: 'center', gap: '10px'}}>
                                <select 
                                    value={selectedGroupId || ''} 
                                    onChange={(e) => setSelectedGroupId(Number(e.target.value))}
                                    className="gc-header-title"
                                    style={{ background: 'transparent', border: 'none', cursor: 'pointer', paddingRight: '20px', outline: 'none' }}
                                >
                                    {groups.length === 0 && <option value="">Crear un grupo...</option>}
                                    {groups.map(g => <option key={g.id} value={g.id}>{g.nombre}</option>)}
                                </select>
                                <button onClick={() => setIsCreatingGroup(true)} style={{background: '#e0e7ff', color: '#4338ca', border: 'none', borderRadius: '50%', width: '32px', height: '32px', cursor: 'pointer', display: 'flex', alignItems: 'center', justifyContent: 'center'}} title="Crear nuevo grupo">
                                    <i className="fas fa-plus"></i>
                                </button>
                                {groups.length > 0 && (
                                    <button onClick={handleDeleteGroup} style={{background: '#fee2e2', color: '#dc2626', border: 'none', borderRadius: '50%', width: '32px', height: '32px', cursor: 'pointer', display: 'flex', alignItems: 'center', justifyContent: 'center', marginLeft: '5px'}} title="Eliminar este grupo">
                                        <i className="fas fa-trash-alt" style={{fontSize: '0.8rem'}}></i>
                                    </button>
                                )}
                            </div>
                        ) : (
                            <div style={{display: 'flex', gap: '10px', alignItems: 'center'}}>
                                <input 
                                    autoFocus
                                    type="text" 
                                    placeholder="Nombre del Grupo (ej. Grupo 1)" 
                                    value={newGroupName}
                                    onChange={(e) => setNewGroupName(e.target.value)}
                                    className="gc-input-add"
                                    style={{width: '250px'}}
                                />
                                <button onClick={handleCreateGroup} className="button" style={{backgroundColor: '#10b981', color: 'white'}}>Guardar</button>
                                <button onClick={() => setIsCreatingGroup(false)} className="button" style={{backgroundColor: '#6b7280', color: 'white'}}>Cancelar</button>
                            </div>
                        )}
                        <p style={{ color: '#6b7280', fontWeight: '500', display: 'flex', alignItems: 'center', gap: '0.5rem', marginTop: '0.5rem' }}>
                            <i className="fas fa-users" style={{ color: '#60a5fa' }}></i>
                            {members.length} Integrantes
                        </p>
                    </div>

                    <div style={{ display: 'flex', gap: '0.75rem', alignItems: 'center', backgroundColor: 'white', padding: '0.5rem', borderRadius: '0.75rem', border: '1px solid #e5e7eb', boxShadow: '0 1px 2px 0 rgba(0,0,0,0.05)' }}>
                        <div style={{ backgroundColor: '#f3f4f6', padding: '0.5rem 0.75rem', borderRadius: '0.5rem', color: '#6b7280' }}>
                            <i className="fas fa-calendar-alt"></i>
                        </div>
                        <input 
                            type="month" 
                            value={currentMonth} 
                            onChange={(e) => setCurrentMonth(e.target.value)}
                            style={{ border: 'none', background: 'transparent', fontWeight: '600', color: '#374151', outline: 'none', cursor: 'pointer' }}
                        />
                    </div>
                </div>
            </div>

            {/* --- ADD MEMBER SECTION (With Autocomplete & Manual Option) --- */}
            {selectedGroupId && (
                <div className="gc-card-add" style={{overflow: 'visible'}}>
                    <div className="gc-label-add">
                        <i className="fas fa-user-plus"></i>
                        Agregar Integrante al {currentGroupName}
                    </div>
                    <div style={{ display: 'flex', flexDirection: 'row', gap: '1rem', flexWrap: 'wrap', position: 'relative' }} ref={suggestionsRef}>
                        <div style={{ position: 'relative', flexGrow: 1 }}>
                            <i className="fas fa-search" style={{ position: 'absolute', left: '1rem', top: '50%', transform: 'translateY(-50%)', color: '#9ca3af', zIndex: 10 }}></i>
                            <input 
                                type="text" 
                                value={addSearchTerm}
                                onChange={(e) => {
                                    setAddSearchTerm(e.target.value);
                                    setShowSuggestions(true);
                                }}
                                onFocus={() => setShowSuggestions(true)}
                                onKeyDown={(e) => {
                                    if (e.key === 'Enter') {
                                        handleAddMember(addSearchTerm);
                                        setShowSuggestions(false);
                                    }
                                }}
                                placeholder="Buscar o escribir nombre nuevo..."
                                className="gc-input-add"
                                autoComplete="off"
                            />
                            {/* Autocomplete Dropdown */}
                            {showSuggestions && addSearchTerm && (
                                <div style={{
                                    position: 'absolute', top: '100%', left: 0, right: 0, 
                                    backgroundColor: 'white', border: '1px solid #e5e7eb', 
                                    borderRadius: '0.75rem', marginTop: '5px', zIndex: 50,
                                    boxShadow: '0 10px 15px -3px rgba(0, 0, 0, 0.1)',
                                    maxHeight: '300px', overflowY: 'auto'
                                }}>
                                    {/* Existing Publishers from DB */}
                                    {filteredSuggestions.map(p => (
                                        <div 
                                            key={p.id}
                                            onClick={() => {
                                                handleAddMember(p.nombre);
                                                setAddSearchTerm(''); 
                                                setShowSuggestions(false);
                                            }}
                                            style={{ padding: '10px 15px', cursor: 'pointer', borderBottom: '1px solid #f3f4f6', display: 'flex', alignItems: 'center', gap: '10px' }}
                                            onMouseEnter={(e) => e.currentTarget.style.backgroundColor = '#f9fafb'}
                                            onMouseLeave={(e) => e.currentTarget.style.backgroundColor = 'white'}
                                        >
                                            <div className={`modern-avatar ${getAvatarClass(p.nombre)}`} style={{width: '24px', height: '24px', fontSize: '0.7rem'}}>
                                                {p.nombre.charAt(0)}
                                            </div>
                                            <span style={{color: '#374151', fontWeight: '500'}}>{p.nombre}</span>
                                            <i className="fas fa-plus" style={{marginLeft: 'auto', color: '#10b981', fontSize: '0.8rem'}}></i>
                                        </div>
                                    ))}

                                    {/* Manual "Add as new" Option (Always visible if text is present) */}
                                    <div 
                                        onClick={() => {
                                            handleAddMember(addSearchTerm);
                                            setAddSearchTerm(''); 
                                            setShowSuggestions(false);
                                        }}
                                        style={{ padding: '10px 15px', cursor: 'pointer', backgroundColor: '#fdf4ff', borderTop: '1px solid #f3f4f6', display: 'flex', alignItems: 'center', gap: '10px' }}
                                        onMouseEnter={(e) => e.currentTarget.style.backgroundColor = '#fce7f3'}
                                        onMouseLeave={(e) => e.currentTarget.style.backgroundColor = '#fdf4ff'}
                                    >
                                        <div style={{width: '24px', height: '24px', display:'flex', alignItems:'center', justifyContent:'center', color: '#d946ef'}}>
                                            <i className="fas fa-pen"></i>
                                        </div>
                                        <div style={{display:'flex', flexDirection:'column'}}>
                                            <span style={{color: '#374151', fontWeight: '600'}}>Agregar "{addSearchTerm}"</span>
                                            <span style={{fontSize: '0.75rem', color: '#d946ef'}}>Nombre manual (no se añade a lista general)</span>
                                        </div>
                                    </div>
                                </div>
                            )}
                        </div>
                        <button 
                            onClick={() => handleAddMember(addSearchTerm)}
                            disabled={!addSearchTerm.trim()}
                            className="gc-btn-add"
                        >
                            <span>Agregar</span>
                            <i className="fas fa-arrow-right"></i>
                        </button>
                    </div>
                </div>
            )}

            {/* Status Toast */}
            {statusMessage && (
                <div style={{ 
                    position: 'fixed', bottom: '1.5rem', right: '1.5rem', zIndex: 100, padding: '1rem 1.5rem', borderRadius: '0.75rem', 
                    boxShadow: '0 10px 15px -3px rgba(0, 0, 0, 0.1)', fontWeight: '600', display: 'flex', alignItems: 'center', gap: '0.75rem',
                    backgroundColor: statusMessage.type === 'success' ? '#059669' : (statusMessage.type === 'info' ? '#3b82f6' : '#dc2626'), color: 'white'
                }}>
