                onClick={e => e.stopPropagation()}
            >
                {/* Header */}
                <div className="bg-white px-5 py-4 border-b border-gray-100 flex justify-between items-center sticky top-0 z-10">
                    <div className="flex items-center gap-3 overflow-hidden">
                        <div className={`flex-shrink-0 w-10 h-10 flex items-center justify-center rounded-full text-sm font-bold text-white shadow-sm ${getAvatarClass(pName)}`}>
                            {pName.charAt(0)}
                        </div>
                        <h3 className="font-bold text-gray-800 text-lg truncate">{pName}</h3>
                    </div>
                    <button onClick={onClose} className="w-8 h-8 flex items-center justify-center rounded-full bg-gray-100 text-gray-500 hover:bg-gray-200">
                        <i className="fas fa-times"></i>
                    </button>
                </div>

                {/* Body */}
                <div className="p-6 overflow-y-auto">

                    {/* Sección Ministerio */}
