                            <h4 className="text-xs font-bold text-gray-400 uppercase tracking-wider flex items-center gap-2">
                                <i className="fas fa-briefcase text-blue-500"></i> Informe
                            </h4>
                            {/* Toggle Switch */}
                            <label className="relative inline-flex items-center cursor-pointer">
                                <input type="checkbox" className="sr-only peer" checked={hasReport} onChange={handleToggleReport} />
                                <div className="w-11 h-6 bg-gray-200 peer-focus:outline-none rounded-full peer peer-checked:after:translate-x-full peer-checked:after:border-white after:content-[''] after:absolute after:top-[2px] after:left-[2px] after:bg-white after:border-gray-300 after:border after:rounded-full after:h-5 after:w-5 after:transition-all peer-checked:bg-blue-600"></div>
                                <span className="ml-2 text-sm font-medium text-gray-600">{hasReport ? 'Sí' : 'No'}</span>
                            </label>
                        </div>

                        {hasReport ? (
                            <div className="space-y-4 bg-blue-50/50 p-4 rounded-xl border border-blue-100">
