const GrupoCongregacion: React.FC = () => {
    // Data State
    const [groups, setGroups] = useState<Group[]>([]);
    const [selectedGroupId, setSelectedGroupId] = useState<number | null>(null);
    const [members, setMembers] = useState<GroupMember[]>([]);
    const [masterPublishers, setMasterPublishers] = useState<Publisher[]>([]); 

    // UI State
    const [loading, setLoading] = useState(true);
    const [currentMonth, setCurrentMonth] = useState<string>('');
    const [reports, setReports] = useState<ReportsMap>({});
    const [visits, setVisits] = useState<VisitsMap>({});
    const [searchTerm, setSearchTerm] = useState('');
    const [addSearchTerm, setAddSearchTerm] = useState(''); 
    const [showSuggestions, setShowSuggestions] = useState(false);
    const [isCreatingGroup, setIsCreatingGroup] = useState(false);
    const [newGroupName, setNewGroupName] = useState('');
    const [statusMessage, setStatusMessage] = useState<{ text: string; type: 'success' | 'error' | 'info' } | null>(null);

    // Global Modal State for Mobile
    const [editingMember, setEditingMember] = useState<GroupMember | null>(null);

    const suggestionsRef = useRef<HTMLDivElement>(null);

    // Initial Load
    useEffect(() => {
        const now = new Date();
        const yyyy = now.getFullYear();
        const mm = String(now.getMonth() + 1).padStart(2, '0');
        setCurrentMonth(`${yyyy}-${mm}`);

        fetchGroups();
        fetchMasterPublishers();

        const handleClickOutside = (event: MouseEvent) => {
            if (suggestionsRef.current && !suggestionsRef.current.contains(event.target as Node)) {
                setShowSuggestions(false);
            }
        };
        document.addEventListener('mousedown', handleClickOutside);
        return () => document.removeEventListener('mousedown', handleClickOutside);
    }, []);

    // Load Data Functions
    const fetchGroups = async () => {
        const { data, error } = await supabase.from('grupos').select('*').order('nombre');
        if (error) {
            console.error("Error fetching groups:", error);
        } else if (data) {
            setGroups(data);
            if (data.length > 0 && !selectedGroupId) {
                const defaultGroup = data.find(g => g.nombre.includes('5')) || data[0];
                setSelectedGroupId(defaultGroup.id);
            }
        }
    };

    const fetchMasterPublishers = async () => {
        const { data } = await supabase.from('publicadores').select('id, nombre').order('nombre');
        if (data) setMasterPublishers(data);
    };

    const fetchMembers = async () => {
        if (!selectedGroupId) return;
        setLoading(true);
        const { data, error } = await supabase
            .from('miembros_grupo')
            .select('*')
            .eq('grupo_id', selectedGroupId)
            .order('publicador_nombre');

        if (error) console.error("Error fetching members:", error);
        else setMembers(data || []);
        setLoading(false);
    };

    useEffect(() => {
        fetchMembers();
    }, [selectedGroupId]);

    useEffect(() => {
        if (!currentMonth || members.length === 0) return;

        const fetchData = async () => {
            const memberNames = members.map(m => m.publicador_nombre);

            const { data: reportsData } = await supabase
                .from('informes_ministerio')
                .select('publicador_nombre, horas, estudios, notas')
                .eq('mes', currentMonth)
                .in('publicador_nombre', memberNames);

            const newReports: ReportsMap = {};
            if (reportsData) {
                reportsData.forEach((r: any) => {
                    newReports[r.publicador_nombre] = { 
                        horas: r.horas,
                        estudios: r.estudios || '',
                        notas: r.notas || ''
                    };
                });
            }
            setReports(newReports);

            const { data: visitsData } = await supabase
                .from('visitas_pastoral')
                .select('publicador_nombre, fecha_visita, notas')
                .in('publicador_nombre', memberNames);

            const newVisits: VisitsMap = {};
            if (visitsData) {
                visitsData.forEach((v: any) => {
                    newVisits[v.publicador_nombre] = {
                        date: v.fecha_visita,
                        notes: v.notas || ''
                    };
                });
            }
            setVisits(newVisits);
        };

        fetchData();
    }, [currentMonth, members]);

    const handleCreateGroup = async () => {
        if (!newGroupName.trim()) return;
        const normalizedName = newGroupName.trim();

        const { data, error } = await supabase.from('grupos').insert([{ nombre: normalizedName }]).select();

        if (error) {
            if (error.code === '23505') {
                const { data: existingGroup } = await supabase.from('grupos').select('*').eq('nombre', normalizedName).single();
                if (existingGroup) {
                    setGroups(prev => prev.some(g => g.id === existingGroup.id) ? prev : [...prev, existingGroup].sort((a,b) => a.nombre.localeCompare(b.nombre)));
                    setSelectedGroupId(existingGroup.id);
                    setIsCreatingGroup(false);
                    setNewGroupName('');
                    setStatusMessage({ text: `El grupo "${normalizedName}" ya existe. Seleccionado.`, type: 'info' });
                    setTimeout(() => setStatusMessage(null), 3000);
                    return; 
                }
            }
            console.error("Error creating group:", error);
            setStatusMessage({ text: `Error: ${error.message}`, type: 'error' });
            setTimeout(() => setStatusMessage(null), 4000);
        } else if (data) {
            setGroups(prev => [...prev, data[0]].sort((a,b) => a.nombre.localeCompare(b.nombre)));
            setSelectedGroupId(data[0].id);
            setIsCreatingGroup(false);
            setNewGroupName('');
            setStatusMessage({ text: 'Grupo creado con éxito', type: 'success' });
            setTimeout(() => setStatusMessage(null), 3000);
        }
    };

    const handleDeleteGroup = async () => {
        if (!selectedGroupId) return;
        const groupName = groups.find(g => g.id === selectedGroupId)?.nombre;
        if (!window.confirm(`¿Estás seguro de eliminar el "${groupName}" y todos sus integrantes?`)) return;

        const { error } = await supabase.from('grupos').delete().eq('id', selectedGroupId);
        if (error) {
            setStatusMessage({ text: `Error al eliminar: ${error.message}`, type: 'error' });
        } else {
            const remaining = groups.filter(g => g.id !== selectedGroupId);
            setGroups(remaining);
            setSelectedGroupId(remaining.length > 0 ? remaining[0].id : null);
            setMembers([]);
            setStatusMessage({ text: 'Grupo eliminado', type: 'success' });
            setTimeout(() => setStatusMessage(null), 3000);
        }
    };

    const handleAddMember = async (name: string) => {
        if (!selectedGroupId || !name.trim()) return;
        if (members.some(m => m.publicador_nombre.toLowerCase() === name.toLowerCase())) {
            setStatusMessage({ text: 'Esta persona ya está en el grupo', type: 'error' });
            setTimeout(() => setStatusMessage(null), 3000);
            return;
        }
        const { error } = await supabase.from('miembros_grupo').insert([{ grupo_id: selectedGroupId, publicador_nombre: name.trim() }]);
        if (error) {
            setStatusMessage({ text: `Error al agregar: ${error.message}`, type: 'error' });
        } else {
            setStatusMessage({ text: 'Agregado correctamente', type: 'success' });
            setAddSearchTerm('');
            fetchMembers();
        }
        setTimeout(() => setStatusMessage(null), 3000);
    };

    const handleDeleteMember = async (id: number, name: string) => {
        // Confirmation is handled in the modal for mobile, or simple check here
        const { error } = await supabase.from('miembros_grupo').delete().eq('id', id);
        if (!error) {
            fetchMembers();
            if(editingMember?.id === id) setEditingMember(null);
        } else console.error("Error deleting member:", error);
    };

    const handleReportChange = (name: string, field: keyof MinistryReport, value: string | number) => {
        setReports(prev => {
            const currentEntry = prev[name] || { horas: '', estudios: '', notas: '' };
            const newValue = (field === 'horas' || field === 'estudios') 
                ? (value === '' ? '' : Number(value)) 
                : value;

            return {
                ...prev,
                [name]: { ...currentEntry, [field]: newValue }
            };
        });
    };

    const handleRemoveReport = (name: string) => {
        setReports(prev => {
            const next = { ...prev };
            delete next[name];
            return next;
        });
    };

    const handleVisitChange = (name: string, field: keyof VisitData, value: string) => {
        setVisits(prev => {
            const currentEntry = prev[name] || { date: '', notes: '' };
            return {
                ...prev,
                [name]: { ...currentEntry, [field]: value }
            };
        });
    };

    const handleSaveRow = async (publisherName: string) => {
        setStatusMessage(null);
        try {
            const reportEntry = reports[publisherName];
            if (reportEntry) {
                const valToSave = reportEntry.horas === '' ? 0 : reportEntry.horas;
                const { error: reportError } = await supabase.from('informes_ministerio').upsert({ 
                    publicador_nombre: publisherName, 
                    mes: currentMonth, 
                    horas: valToSave,
                    estudios: reportEntry.estudios === '' ? 0 : reportEntry.estudios,
                    notas: reportEntry.notas || ''
                }, { onConflict: 'publicador_nombre, mes' });
                if (reportError) throw reportError;
            } else {
                const { error: deleteError } = await supabase.from('informes_ministerio').delete().eq('publicador_nombre', publisherName).eq('mes', currentMonth);
                if (deleteError) throw deleteError; // Ignore if didn't exist
            }

            const visitData = visits[publisherName];
            if (visitData && (visitData.date || visitData.notes)) {
                const { error: visitError } = await supabase.from('visitas_pastoral').upsert({ 
                    publicador_nombre: publisherName, 
                    fecha_visita: visitData.date,
                    notas: visitData.notes
                }, { onConflict: 'publicador_nombre' });
                if (visitError) throw visitError;
            }

            setStatusMessage({ text: 'Guardado', type: 'success' });
            setTimeout(() => setStatusMessage(null), 2000);
        } catch (err: any) {
            console.error(err);
            setStatusMessage({ text: 'Error al guardar', type: 'error' });
        }
    };

    const filteredMembers = members.filter(m => m.publicador_nombre.toLowerCase().includes(searchTerm.toLowerCase()));
    const filteredSuggestions = masterPublishers.filter(p => p.nombre.toLowerCase().includes(addSearchTerm.toLowerCase()) && !members.some(m => m.publicador_nombre === p.nombre)).slice(0, 6);
    const currentGroupName = groups.find(g => g.id === selectedGroupId)?.nombre || 'Sin Grupo';

    return (
        <div className="container mx-auto px-4 py-8 group-container relative">

            {/* --- Global Edit Modal (Mobile) --- */}
            {editingMember && (
                <EditMemberModal 
                    member={editingMember}
                    reportEntry={reports[editingMember.publicador_nombre]}
                    visitData={visits[editingMember.publicador_nombre] || { date: '', notes: '' }}
                    onClose={() => setEditingMember(null)}
                    onReportChange={handleReportChange}
                    onVisitChange={handleVisitChange}
                    onSave={handleSaveRow}
                    onDelete={handleDeleteMember}
                    onRemoveReport={handleRemoveReport}
                />
            )}

            {/* --- TOP BAR --- */}
            <div style={{ display: 'flex', flexDirection: 'column', gap: '1.5rem', marginBottom: '2rem' }}>
                <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', flexWrap: 'wrap', gap: '1rem' }}>
                    <div style={{flex: 1}}>
                        {!isCreatingGroup ? (
                            <div style={{display: 'flex', alignItems: 'center', gap: '10px'}}>
                                <select 
                                    value={selectedGroupId || ''} 
                                    onChange={(e) => setSelectedGroupId(Number(e.target.value))}
                                    className="gc-header-title"
                                    style={{ background: 'transparent', border: 'none', cursor: 'pointer', paddingRight: '20px', outline: 'none' }}
                                >
                                    {groups.length === 0 && <option value="">Crear un grupo...</option>}
                                    {groups.map(g => <option key={g.id} value={g.id}>{g.nombre}</option>)}
                                </select>
                                <button onClick={() => setIsCreatingGroup(true)} style={{background: '#e0e7ff', color: '#4338ca', border: 'none', borderRadius: '50%', width: '32px', height: '32px', cursor: 'pointer', display: 'flex', alignItems: 'center', justifyContent: 'center'}} title="Crear nuevo grupo">
                                    <i className="fas fa-plus"></i>
                                </button>
                                {groups.length > 0 && (
                                    <button onClick={handleDeleteGroup} style={{background: '#fee2e2', color: '#dc2626', border: 'none', borderRadius: '50%', width: '32px', height: '32px', cursor: 'pointer', display: 'flex', alignItems: 'center', justifyContent: 'center', marginLeft: '5px'}} title="Eliminar este grupo">
                                        <i className="fas fa-trash-alt" style={{fontSize: '0.8rem'}}></i>
                                    </button>
                                )}
                            </div>
                        ) : (
                            <div style={{display: 'flex', gap: '10px', alignItems: 'center'}}>
                                <input 
                                    autoFocus type="text" placeholder="Nombre del Grupo" 
                                    value={newGroupName} onChange={(e) => setNewGroupName(e.target.value)}
                                    className="gc-input-add" style={{width: '250px'}}
                                />
                                <button onClick={handleCreateGroup} className="button" style={{backgroundColor: '#10b981', color: 'white'}}>Guardar</button>
                                <button onClick={() => setIsCreatingGroup(false)} className="button" style={{backgroundColor: '#6b7280', color: 'white'}}>Cancelar</button>
                            </div>
                        )}
                        <p style={{ color: '#6b7280', fontWeight: '500', display: 'flex', alignItems: 'center', gap: '0.5rem', marginTop: '0.5rem' }}>
                            <i className="fas fa-users" style={{ color: '#60a5fa' }}></i>
                            {members.length} Integrantes
                        </p>
                    </div>

                    <div style={{ display: 'flex', gap: '0.75rem', alignItems: 'center', backgroundColor: 'white', padding: '0.5rem', borderRadius: '0.75rem', border: '1px solid #e5e7eb', boxShadow: '0 1px 2px 0 rgba(0,0,0,0.05)' }}>
                        <div style={{ backgroundColor: '#f3f4f6', padding: '0.5rem 0.75rem', borderRadius: '0.5rem', color: '#6b7280' }}><i className="fas fa-calendar-alt"></i></div>
                        <input type="month" value={currentMonth} onChange={(e) => setCurrentMonth(e.target.value)} style={{ border: 'none', background: 'transparent', fontWeight: '600', color: '#374151', outline: 'none', cursor: 'pointer' }} />
                    </div>
                </div>
            </div>

            {/* --- ADD MEMBER --- */}
            {selectedGroupId && (
                <div className="gc-card-add" style={{overflow: 'visible'}}>
                    <div className="gc-label-add"><i className="fas fa-user-plus"></i>Agregar Integrante</div>
                    <div style={{ display: 'flex', flexDirection: 'row', gap: '1rem', flexWrap: 'wrap', position: 'relative' }} ref={suggestionsRef}>
                        <div style={{ position: 'relative', flexGrow: 1 }}>
                            <i className="fas fa-search" style={{ position: 'absolute', left: '1rem', top: '50%', transform: 'translateY(-50%)', color: '#9ca3af', zIndex: 10 }}></i>
                            <input 
                                type="text" value={addSearchTerm}
                                onChange={(e) => { setAddSearchTerm(e.target.value); setShowSuggestions(true); }}
                                onFocus={() => setShowSuggestions(true)}
                                onKeyDown={(e) => { if (e.key === 'Enter') { handleAddMember(addSearchTerm); setShowSuggestions(false); } }}
                                placeholder="Buscar o escribir nombre nuevo..."
                                className="gc-input-add" autoComplete="off"
                            />
                            {showSuggestions && addSearchTerm && (
                                <div style={{ position: 'absolute', top: '100%', left: 0, right: 0, backgroundColor: 'white', border: '1px solid #e5e7eb', borderRadius: '0.75rem', marginTop: '5px', zIndex: 50, boxShadow: '0 10px 15px -3px rgba(0, 0, 0, 0.1)', maxHeight: '300px', overflowY: 'auto' }}>
                                    {filteredSuggestions.map(p => (
                                        <div key={p.id} onClick={() => { handleAddMember(p.nombre); setAddSearchTerm(''); setShowSuggestions(false); }} style={{ padding: '10px 15px', cursor: 'pointer', borderBottom: '1px solid #f3f4f6', display: 'flex', alignItems: 'center', gap: '10px' }}>
                                            <div className={`flex-shrink-0 w-6 h-6 flex items-center justify-center rounded-full text-xs text-white font-bold ${getAvatarClass(p.nombre)}`}>{p.nombre.charAt(0)}</div>
                                            <span style={{color: '#374151', fontWeight: '500'}}>{p.nombre}</span>
                                            <i className="fas fa-plus" style={{marginLeft: 'auto', color: '#10b981', fontSize: '0.8rem'}}></i>
                                        </div>
                                    ))}
                                    <div onClick={() => { handleAddMember(addSearchTerm); setAddSearchTerm(''); setShowSuggestions(false); }} style={{ padding: '10px 15px', cursor: 'pointer', backgroundColor: '#fdf4ff', borderTop: '1px solid #f3f4f6', display: 'flex', alignItems: 'center', gap: '10px' }}>
                                        <div style={{width: '24px', height: '24px', display:'flex', alignItems:'center', justifyContent:'center', color: '#d946ef'}}><i className="fas fa-pen"></i></div>
                                        <div style={{display:'flex', flexDirection:'column'}}><span style={{color: '#374151', fontWeight: '600'}}>Agregar "{addSearchTerm}"</span><span style={{fontSize: '0.75rem', color: '#d946ef'}}>Nombre manual</span></div>
                                    </div>
                                </div>
                            )}
                        </div>
                        <button onClick={() => handleAddMember(addSearchTerm)} disabled={!addSearchTerm.trim()} className="gc-btn-add"><span>Agregar</span><i className="fas fa-arrow-right"></i></button>
                    </div>
                </div>
            )}

            {/* Status Toast */}
            {statusMessage && (
                <div style={{ position: 'fixed', bottom: '1.5rem', right: '1.5rem', zIndex: 100, padding: '1rem 1.5rem', borderRadius: '0.75rem', boxShadow: '0 10px 15px -3px rgba(0, 0, 0, 0.1)', fontWeight: '600', display: 'flex', alignItems: 'center', gap: '0.75rem', backgroundColor: statusMessage.type === 'success' ? '#059669' : (statusMessage.type === 'info' ? '#3b82f6' : '#dc2626'), color: 'white' }}>
                    <i className={`fas ${statusMessage.type === 'success' ? 'fa-check-circle' : (statusMessage.type === 'info' ? 'fa-info-circle' : 'fa-exclamation-circle')}`}></i>
                    {statusMessage.text}
                </div>
            )}

            {/* Members List */}
            {loading ? (
                <div style={{ textAlign: 'center', padding: '5rem 0', color: '#9ca3af' }}><i className="fas fa-spinner fa-spin fa-3x" style={{ marginBottom: '1rem', color: '#93c5fd' }}></i><p style={{ fontWeight: '500' }}>Cargando datos...</p></div>
            ) : (
                <div className="modern-card bg-transparent shadow-none md:bg-white md:shadow-md md:rounded-lg">
                    <div className="gc-table-header hidden md:grid md:grid-cols-12 md:gap-4 md:border-b md:border-slate-200 md:bg-slate-50 md:p-4">
                        <div className="col-span-3 pl-2">Publicador</div><div className="col-span-2 text-center">Horas</div><div className="col-span-1 text-center">Est.</div><div className="col-span-2 text-center">Observaciones</div><div className="col-span-2 text-center">Pastoreo</div><div className="col-span-2 text-center">Acciones</div>
                    </div>
                    <div style={{ display: 'flex', flexDirection: 'column' }}>
                        {filteredMembers.map((m, index) => (
                            <MemberRow 
                                key={m.id}
                                m={m}
                                index={index}
                                reportEntry={reports[m.publicador_nombre]}
                                visitData={visits[m.publicador_nombre] || { date: '', notes: '' }}
                                onReportChange={handleReportChange}
                                onVisitChange={handleVisitChange}
                                onSave={handleSaveRow}
                                onDelete={handleDeleteMember}
                                onRemoveReport={handleRemoveReport}
                                onOpenModal={setEditingMember}
                            />
                        ))}
                    </div>
                    {filteredMembers.length === 0 && (
                        <div style={{ padding: '5rem 0', textAlign: 'center', backgroundColor: '#f8fafc', borderRadius: '0.75rem' }}>
                            <div style={{ backgroundColor: 'white', width: '6rem', height: '6rem', borderRadius: '50%', display: 'flex', alignItems: 'center', justifyContent: 'center', margin: '0 auto 1.5rem auto', boxShadow: '0 1px 2px 0 rgba(0,0,0,0.05)', border: '1px solid #e2e8f0' }}><i className="fas fa-users fa-3x" style={{ color: '#c7d2fe' }}></i></div>
                            <h3 style={{ fontSize: '1.25rem', fontWeight: '700', color: '#374151' }}>{selectedGroupId ? 'Este grupo está vacío' : 'Crea o selecciona un grupo'}</h3>
                            <p style={{ color: '#6b7280', marginTop: '0.5rem', maxWidth: '24rem', marginInline: 'auto' }}>Utiliza el buscador de arriba para agregar publicadores.</p>
                        </div>
                    )}
                </div>
            )}
        </div>
    );
};

export default GrupoCongregacion;

import React, { useState, useEffect, useRef } from 'react';
import { supabase } from '../lib/supabase';

type Publisher = {
    id: number;
    nombre: string;
};

type Group = {
    id: number;
    nombre: string;
};

type GroupMember = {
    id: number;
    grupo_id: number;
    publicador_nombre: string;
};

type MinistryReport = {
    horas: number | '';
    estudios: number | '';
    notas?: string;
};

type VisitData = {
    date: string;
    notes: string;
};

type ReportsMap = Record<string, MinistryReport>;
type VisitsMap = Record<string, VisitData>;

// Helper for avatar colors
const getAvatarClass = (name: string) => {
    const classes = ['bg-red-500', 'bg-orange-500', 'bg-amber-500', 'bg-green-500', 'bg-teal-500', 'bg-blue-500', 'bg-indigo-500', 'bg-purple-500', 'bg-pink-500'];
    let hash = 0;
    for (let i = 0; i < name.length; i++) {
        hash = name.charCodeAt(i) + ((hash << 5) - hash);
    }
    return classes[Math.abs(hash) % classes.length];
};

// --- MODAL COMPONENT (Ventana Emergente Única) ---
const EditMemberModal: React.FC<{
    member: GroupMember;
    reportEntry: MinistryReport | undefined;
    visitData: VisitData;
    onClose: () => void;
    onReportChange: (name: string, field: keyof MinistryReport, value: string | number) => void;
    onVisitChange: (name: string, field: keyof VisitData, value: string) => void;
    onSave: (name: string) => void;
    onDelete: (id: number, name: string) => void;
    onRemoveReport: (name: string) => void;
}> = ({ member, reportEntry, visitData, onClose, onReportChange, onVisitChange, onSave, onDelete, onRemoveReport }) => {
    const pName = member.publicador_nombre;
    const visitDate = visitData.date;

    // Estado local para "Informó Actividad"
    const hasReport = reportEntry !== undefined;

    const handleToggleReport = (e: React.ChangeEvent<HTMLInputElement>) => {
        if (e.target.checked) {
            onReportChange(pName, 'horas', 0); // Inicia con 0 horas (Predicó)
        } else {
            onRemoveReport(pName); // Elimina el informe
        }
    };

    // Lógica visual para semáforo de visita
    let visitBadgeClass = 'bg-gray-100 text-gray-500 border-gray-200';
    let visitLabel = 'N/A';
    if (visitDate) {
        const daysSince = (new Date().getTime() - new Date(visitDate).getTime()) / (1000 * 3600 * 24);
        if (daysSince < 90) { visitBadgeClass = 'bg-green-100 text-green-700 border-green-200'; visitLabel = 'Al día'; } 
        else if (daysSince < 180) { visitBadgeClass = 'bg-amber-100 text-amber-700 border-amber-200'; visitLabel = 'Atención'; } 
        else { visitBadgeClass = 'bg-red-100 text-red-700 border-red-200'; visitLabel = 'Urgente'; }
    }

    return (
        <div className="fixed inset-0 z-[9999] flex items-end sm:items-center justify-center bg-black/60 backdrop-blur-sm animate-fadeIn" onClick={onClose}>
            <div 
                className="bg-white w-full max-w-sm rounded-t-3xl sm:rounded-2xl shadow-2xl overflow-hidden flex flex-col max-h-[90vh] animate-slideUp" 
                onClick={e => e.stopPropagation()}
            >
                {/* Header */}
                <div className="bg-white px-5 py-4 border-b border-gray-100 flex justify-between items-center sticky top-0 z-10">
                    <div className="flex items-center gap-3 overflow-hidden">
                        <div className={`flex-shrink-0 w-10 h-10 flex items-center justify-center rounded-full text-lg font-bold text-white shadow-sm ${getAvatarClass(pName)}`}>
                            {pName.charAt(0)}
                        </div>
                        <h3 className="font-bold text-gray-800 text-lg truncate">{pName}</h3>
                    </div>
                    <button onClick={onClose} className="w-10 h-10 flex items-center justify-center rounded-full bg-gray-100 text-gray-500 hover:bg-gray-200 text-xl">
                        <i className="fas fa-times"></i>
                    </button>
                </div>

                {/* Body */}
                <div className="p-6 overflow-y-auto">

                    {/* Sección Ministerio */}
                    <div className="mb-8">
                        <div className="flex justify-between items-center mb-4">
                            <h4 className="text-xs font-bold text-gray-400 uppercase tracking-wider flex items-center gap-2">
                                <i className="fas fa-briefcase text-blue-500"></i> Informe
                            </h4>
                            {/* Toggle Switch */}
                            <label className="relative inline-flex items-center cursor-pointer">
                                <input type="checkbox" className="sr-only peer" checked={hasReport} onChange={handleToggleReport} />
                                <div className="w-11 h-6 bg-gray-200 peer-focus:outline-none rounded-full peer peer-checked:after:translate-x-full peer-checked:after:border-white after:content-[''] after:absolute after:top-[2px] after:left-[2px] after:bg-white after:border-gray-300 after:border after:rounded-full after:h-5 after:w-5 after:transition-all peer-checked:bg-blue-600"></div>
                                <span className="ml-2 text-sm font-medium text-gray-600">{hasReport ? 'Sí' : 'No'}</span>
                            </label>
                        </div>

                        {hasReport ? (
                            <div className="space-y-4 bg-blue-50/50 p-4 rounded-xl border border-blue-100">
                                <div className="grid grid-cols-2 gap-4">
                                    <div className="relative">
                                        <label className="block text-[10px] uppercase font-bold text-blue-400 mb-1 ml-1">Horas</label>
                                        <div className="relative">
                                            <input 
                                                type="number" min="0" step="0.5"
                                                value={reportEntry?.horas === 0 ? '0' : (reportEntry?.horas || '')} 
                                                onChange={(e) => onReportChange(pName, 'horas', e.target.value)}
                                                className="block w-full px-3 py-3 text-lg font-bold text-gray-800 bg-white border border-blue-200 rounded-xl focus:ring-2 focus:ring-blue-500 focus:border-blue-500 text-center shadow-sm"
                                                placeholder="0"
                                            />
                                        </div>
                                    </div>
                                    <div className="relative">
                                        <label className="block text-[10px] uppercase font-bold text-blue-400 mb-1 ml-1">Estudios</label>
                                        <div className="relative">
                                            <input 
                                                type="number" min="0" 
                                                value={reportEntry?.estudios || ''} 
                                                onChange={(e) => onReportChange(pName, 'estudios', e.target.value)}
                                                className="block w-full px-3 py-3 text-lg font-bold text-gray-800 bg-white border border-blue-200 rounded-xl focus:ring-2 focus:ring-blue-500 focus:border-blue-500 text-center shadow-sm"
                                                placeholder="0"
                                            />
                                        </div>
                                    </div>
                                </div>

                                <div className="relative">
                                    <input
                                        type="text"
                                        value={reportEntry?.notas || ''}
                                        onChange={(e) => onReportChange(pName, 'notas', e.target.value)}
                                        className="block w-full px-3 py-3 text-sm text-gray-700 bg-white border border-blue-200 rounded-xl focus:ring-2 focus:ring-blue-500 focus:border-blue-500 shadow-sm"
                                        placeholder="Observaciones..."
                                    />
                                </div>
                            </div>
                        ) : (
                            <div className="p-4 rounded-xl border-2 border-dashed border-gray-200 text-center">
                                <span className="text-gray-400 text-sm font-medium">Sin informe este mes</span>
                            </div>
                        )}
                    </div>

                    <div className="border-t border-gray-100 my-6"></div>

                    {/* Sección Pastoreo */}
                    <div>
                        <div className="flex justify-between items-center mb-4">
                            <h4 className="text-xs font-bold text-gray-400 uppercase tracking-wider flex items-center gap-2">
                                <i className="fas fa-heart text-pink-500"></i> Visita de Pastoreo
                            </h4>
                            <span className={`px-2 py-1 rounded text-[10px] font-bold border ${visitBadgeClass}`}>
                                {visitLabel}
                            </span>
                        </div>

                        <div className="space-y-4 bg-pink-50/50 p-4 rounded-xl border border-pink-100">
                            <div className="relative">
                                <label className="block text-[10px] uppercase font-bold text-pink-400 mb-1 ml-1">Fecha</label>
                                <input 
                                    type="date" 
                                    value={visitDate}
                                    onChange={(e) => onVisitChange(pName, 'date', e.target.value)}
                                    className="block w-full px-3 py-3 text-sm font-medium text-gray-700 bg-white border border-pink-200 rounded-xl focus:ring-2 focus:ring-pink-500 focus:border-pink-500 shadow-sm"
                                />
                            </div>
                            <div className="relative">
                                <input
                                    type="text"
                                    value={visitData.notes || ''}
                                    onChange={(e) => onVisitChange(pName, 'notes', e.target.value)}
                                    className="block w-full px-3 py-3 text-sm text-gray-700 bg-white border border-pink-200 rounded-xl focus:ring-2 focus:ring-pink-500 focus:border-pink-500 shadow-sm"
                                    placeholder="Nota de la visita..."
                                />
                            </div>
                        </div>
                    </div>
                </div>

                {/* Footer Buttons (Solo Signos) */}
                <div className="bg-white p-4 border-t border-gray-100 flex gap-4">
                    <button 
                        onClick={() => {
                            if(window.confirm('¿Eliminar a este integrante?')) {
                                onDelete(member.id, pName);
                                onClose();
                            }
                        }}
                        className="w-16 h-14 flex items-center justify-center rounded-xl bg-red-100 text-red-600 hover:bg-red-200 transition-colors"
                        title="Eliminar"
                    >
                        <i className="fas fa-trash-alt text-2xl"></i>
                    </button>

                    <button 
                        onClick={() => {
                            onSave(pName);
                            onClose();
                        }}
                        className="flex-1 h-14 flex items-center justify-center rounded-xl bg-gray-900 text-white hover:bg-gray-800 shadow-lg active:scale-[0.98] transition-all"
                        title="Guardar"
                    >
                        <i className="fas fa-save text-2xl"></i>
                    </button>
                </div>
            </div>
        </div>
    );
};

// --- MemberRow: SOLO MUESTRA EL NOMBRE Y FLECHA EN MÓVIL ---
const MemberRow: React.FC<{
    m: GroupMember;
    index: number;
    reportEntry: MinistryReport | undefined;
    visitData: VisitData;
    onReportChange: (name: string, field: keyof MinistryReport, value: string) => void;
    onVisitChange: (name: string, field: keyof VisitData, value: string) => void;
    onSave: (name: string) => void;
    onDelete: (id: number, name: string) => void;
    onRemoveReport: (name: string) => void;
    onOpenModal: (member: GroupMember) => void;
}> = ({ m, index, reportEntry, visitData, onReportChange, onVisitChange, onSave, onDelete, onRemoveReport, onOpenModal }) => {
    const pName = m.publicador_nombre;
    const visitDate = visitData.date;

    // Estado para indicadores visuales mínimos (puntos de color)
    const hasReport = reportEntry !== undefined;

    // Color de visita
    let visitStatusColor = 'bg-gray-300';
    if (visitDate) {
        const daysSince = (new Date().getTime() - new Date(visitDate).getTime()) / (1000 * 3600 * 24);
        if (daysSince < 90) visitStatusColor = 'bg-green-500';
        else if (daysSince < 180) visitStatusColor = 'bg-amber-500';
        else visitStatusColor = 'bg-red-500';
    }

    return (
        <>
            {/* --- VISTA MÓVIL MINIMALISTA (SOLO NOMBRE) --- */}
            <div className="md:hidden">
                <div 
                    onClick={() => onOpenModal(m)}
                    className="flex items-center justify-between p-4 bg-white border-b border-gray-100 active:bg-gray-50 transition-colors cursor-pointer group h-20"
                >
                    <div className="flex items-center gap-4 overflow-hidden flex-1">
                        <div className={`flex-shrink-0 w-12 h-12 flex items-center justify-center rounded-full text-lg font-bold text-white shadow-sm ${getAvatarClass(pName)}`}>
                            {pName.charAt(0)}
                        </div>
                        <div className="flex flex-col justify-center gap-1">
                            <span className="font-bold text-gray-800 truncate text-lg">{pName}</span>
                            {/* Pequeños indicadores visuales (dots) */}
                            <div className="flex gap-2">
                                {hasReport && <div className="w-2 h-2 rounded-full bg-blue-500" title="Informe entregado"></div>}
                                {visitDate && <div className={`w-2 h-2 rounded-full ${visitStatusColor}`} title="Estado visita"></div>}
                            </div>
                        </div>
                    </div>
                    <div className="text-gray-300 pl-4">
                        <i className="fas fa-chevron-right text-lg"></i>
                    </div>
                </div>
            </div>

            {/* --- VISTA DE ESCRITORIO (Mantiene tabla completa) --- */}
            <div className="hidden md:grid md:grid-cols-12 md:gap-4 md:p-4 md:items-start border-b border-slate-100 hover:bg-slate-50 transition-colors">
                <div className="col-span-3 flex items-center gap-3 md:mt-2">
                    <div className="text-gray-400 font-semibold min-w-[1.5rem] text-center text-sm">{index + 1}</div>
                    <div className="font-semibold text-gray-800 text-base">{pName}</div>
                </div>
                <div className="col-span-2 flex justify-center">
                    <input 
                        type="number" min="0" step="0.5"
                        value={reportEntry?.horas === 0 ? 0 : (reportEntry?.horas ?? '')}
                        onChange={(e) => onReportChange(pName, 'horas', e.target.value)}
                        className="bg-white border border-gray-300 text-gray-900 text-sm rounded-lg block w-20 p-1.5 text-center"
                        placeholder="Horas"
                    />
                </div>
                <div className="col-span-1 flex justify-center">
                    <input 
                        type="number" min="0"
                        value={reportEntry?.estudios || ''}
                        onChange={(e) => onReportChange(pName, 'estudios', e.target.value)}
                        className="bg-white border border-gray-300 text-gray-900 text-sm rounded-lg block w-14 p-1.5 text-center"
                        placeholder="0"
                    />
                </div>
                <div className="col-span-2">
                    <input
                        type="text"
                        value={reportEntry?.notas || ''}
                        onChange={(e) => onReportChange(pName, 'notas', e.target.value)}
                        placeholder="..."
                        className="bg-white border border-gray-300 text-gray-700 text-sm rounded-lg block w-full p-1.5"
                    />
                </div>
                <div className="col-span-2 flex flex-col gap-1">
                    <div className="flex gap-1">
                        <input 
                            type="date" value={visitDate}
                            onChange={(e) => onVisitChange(pName, 'date', e.target.value)}
                            className="bg-white border border-gray-300 text-gray-700 text-xs rounded-lg p-1 w-full"
                        />
                    </div>
                    <input
                        type="text"
                        value={visitData.notes || ''}
                        onChange={(e) => onVisitChange(pName, 'notes', e.target.value)}
                        placeholder="Visita de Pastoreo..."
                        className="bg-white border border-gray-300 text-gray-700 text-xs rounded-lg p-1 w-full"
                    />
                </div>
                <div className="col-span-2 flex justify-center gap-2 pt-1">
                    <button onClick={() => onSave(pName)} className="text-white bg-indigo-600 hover:bg-indigo-700 font-medium rounded-lg text-xs px-3 py-1.5 shadow-sm">Guardar</button>
                    <button onClick={() => onDelete(m.id, pName)} className="text-gray-400 hover:text-red-600 p-1.5"><i className="fas fa-trash-alt"></i></button>
                </div>
            </div>
        </>
    );
};

const GrupoCongregacion: React.FC = () => {
    // Data State
    const [groups, setGroups] = useState<Group[]>([]);
    const [selectedGroupId, setSelectedGroupId] = useState<number | null>(null);
    const [members, setMembers] = useState<GroupMember[]>([]);
    const [masterPublishers, setMasterPublishers] = useState<Publisher[]>([]); 

    // UI State
    const [loading, setLoading] = useState(true);
    const [currentMonth, setCurrentMonth] = useState<string>('');
    const [reports, setReports] = useState<ReportsMap>({});
    const [visits, setVisits] = useState<VisitsMap>({});
    const [searchTerm, setSearchTerm] = useState('');
    const [addSearchTerm, setAddSearchTerm] = useState(''); 
    const [showSuggestions, setShowSuggestions] = useState(false);
    const [isCreatingGroup, setIsCreatingGroup] = useState(false);
    const [newGroupName, setNewGroupName] = useState('');
    const [statusMessage, setStatusMessage] = useState<{ text: string; type: 'success' | 'error' | 'info' } | null>(null);

    // Global Modal State for Mobile
    const [editingMember, setEditingMember] = useState<GroupMember | null>(null);

    const suggestionsRef = useRef<HTMLDivElement>(null);

    // Initial Load
    useEffect(() => {
        const now = new Date();
        const yyyy = now.getFullYear();
        const mm = String(now.getMonth() + 1).padStart(2, '0');
        setCurrentMonth(`${yyyy}-${mm}`);

        fetchGroups();
        fetchMasterPublishers();

        const handleClickOutside = (event: MouseEvent) => {
            if (suggestionsRef.current && !suggestionsRef.current.contains(event.target as Node)) {
                setShowSuggestions(false);
            }
        };
        document.addEventListener('mousedown', handleClickOutside);
        return () => document.removeEventListener('mousedown', handleClickOutside);
    }, []);

    // Load Data Functions
    const fetchGroups = async () => {
        const { data, error } = await supabase.from('grupos').select('*').order('nombre');
        if (error) {
            console.error("Error fetching groups:", error);
        } else if (data) {
            setGroups(data);
            if (data.length > 0 && !selectedGroupId) {
                const defaultGroup = data.find(g => g.nombre.includes('5')) || data[0];
                setSelectedGroupId(defaultGroup.id);
            }
        }
    };

    const fetchMasterPublishers = async () => {
        const { data } = await supabase.from('publicadores').select('id, nombre').order('nombre');
        if (data) setMasterPublishers(data);
    };

    const fetchMembers = async () => {
        if (!selectedGroupId) return;
        setLoading(true);
        const { data, error } = await supabase
            .from('miembros_grupo')
            .select('*')
            .eq('grupo_id', selectedGroupId)
            .order('publicador_nombre');

        if (error) console.error("Error fetching members:", error);
        else setMembers(data || []);
        setLoading(false);
    };

    useEffect(() => {
        fetchMembers();
    }, [selectedGroupId]);

    useEffect(() => {
        if (!currentMonth || members.length === 0) return;

        const fetchData = async () => {
            const memberNames = members.map(m => m.publicador_nombre);

            const { data: reportsData } = await supabase
                .from('informes_ministerio')
                .select('publicador_nombre, horas, estudios, notas')
                .eq('mes', currentMonth)
                .in('publicador_nombre', memberNames);

            const newReports: ReportsMap = {};
            if (reportsData) {
                reportsData.forEach((r: any) => {
                    newReports[r.publicador_nombre] = { 
                        horas: r.horas,
                        estudios: r.estudios || '',
                        notas: r.notas || ''
                    };
                });
            }
            setReports(newReports);

            const { data: visitsData } = await supabase
                .from('visitas_pastoral')
                .select('publicador_nombre, fecha_visita, notas')
                .in('publicador_nombre', memberNames);

            const newVisits: VisitsMap = {};
            if (visitsData) {
                visitsData.forEach((v: any) => {
                    newVisits[v.publicador_nombre] = {
                        date: v.fecha_visita,
                        notes: v.notas || ''
                    };
                });
            }
            setVisits(newVisits);
        };

        fetchData();
    }, [currentMonth, members]);

    const handleCreateGroup = async () => {
        if (!newGroupName.trim()) return;
        const normalizedName = newGroupName.trim();

        const { data, error } = await supabase.from('grupos').insert([{ nombre: normalizedName }]).select();

        if (error) {
            if (error.code === '23505') {
                const { data: existingGroup } = await supabase.from('grupos').select('*').eq('nombre', normalizedName).single();
                if (existingGroup) {
                    setGroups(prev => prev.some(g => g.id === existingGroup.id) ? prev : [...prev, existingGroup].sort((a,b) => a.nombre.localeCompare(b.nombre)));
                    setSelectedGroupId(existingGroup.id);
                    setIsCreatingGroup(false);
                    setNewGroupName('');
                    setStatusMessage({ text: `El grupo "${normalizedName}" ya existe. Seleccionado.`, type: 'info' });
                    setTimeout(() => setStatusMessage(null), 3000);
                    return; 
                }
            }
            console.error("Error creating group:", error);
            setStatusMessage({ text: `Error: ${error.message}`, type: 'error' });
            setTimeout(() => setStatusMessage(null), 4000);
        } else if (data) {
            setGroups(prev => [...prev, data[0]].sort((a,b) => a.nombre.localeCompare(b.nombre)));
            setSelectedGroupId(data[0].id);
            setIsCreatingGroup(false);
            setNewGroupName('');
            setStatusMessage({ text: 'Grupo creado con éxito', type: 'success' });
            setTimeout(() => setStatusMessage(null), 3000);
        }
    };

    const handleDeleteGroup = async () => {
        if (!selectedGroupId) return;
        const groupName = groups.find(g => g.id === selectedGroupId)?.nombre;
        if (!window.confirm(`¿Estás seguro de eliminar el "${groupName}" y todos sus integrantes?`)) return;

        const { error } = await supabase.from('grupos').delete().eq('id', selectedGroupId);
        if (error) {
            setStatusMessage({ text: `Error al eliminar: ${error.message}`, type: 'error' });
        } else {
            const remaining = groups.filter(g => g.id !== selectedGroupId);
            setGroups(remaining);
            setSelectedGroupId(remaining.length > 0 ? remaining[0].id : null);
            setMembers([]);
            setStatusMessage({ text: 'Grupo eliminado', type: 'success' });
            setTimeout(() => setStatusMessage(null), 3000);
        }
    };

    const handleAddMember = async (name: string) => {
        if (!selectedGroupId || !name.trim()) return;
        if (members.some(m => m.publicador_nombre.toLowerCase() === name.toLowerCase())) {
            setStatusMessage({ text: 'Esta persona ya está en el grupo', type: 'error' });
            setTimeout(() => setStatusMessage(null), 3000);
            return;
        }
        const { error } = await supabase.from('miembros_grupo').insert([{ grupo_id: selectedGroupId, publicador_nombre: name.trim() }]);
        if (error) {
            setStatusMessage({ text: `Error al agregar: ${error.message}`, type: 'error' });
        } else {
            setStatusMessage({ text: 'Agregado correctamente', type: 'success' });
            setAddSearchTerm('');
            fetchMembers();
        }
        setTimeout(() => setStatusMessage(null), 3000);
    };

    const handleDeleteMember = async (id: number, name: string) => {
        // Confirmation is handled in the modal for mobile, or simple check here
        const { error } = await supabase.from('miembros_grupo').delete().eq('id', id);
        if (!error) {
            fetchMembers();
            if(editingMember?.id === id) setEditingMember(null);
        } else console.error("Error deleting member:", error);
    };

    const handleReportChange = (name: string, field: keyof MinistryReport, value: string | number) => {
        setReports(prev => {
            const currentEntry = prev[name] || { horas: '', estudios: '', notas: '' };
            const newValue = (field === 'horas' || field === 'estudios') 
                ? (value === '' ? '' : Number(value)) 
                : value;

            return {
                ...prev,
                [name]: { ...currentEntry, [field]: newValue }
            };
        });
    };

    const handleRemoveReport = (name: string) => {
        setReports(prev => {
            const next = { ...prev };
            delete next[name];
            return next;
        });
    };

    const handleVisitChange = (name: string, field: keyof VisitData, value: string) => {
        setVisits(prev => {
            const currentEntry = prev[name] || { date: '', notes: '' };
            return {
                ...prev,
                [name]: { ...currentEntry, [field]: value }
            };
        });
    };

    const handleSaveRow = async (publisherName: string) => {
        setStatusMessage(null);
        try {
            const reportEntry = reports[publisherName];
            if (reportEntry) {
                const valToSave = reportEntry.horas === '' ? 0 : reportEntry.horas;
                const { error: reportError } = await supabase.from('informes_ministerio').upsert({ 
                    publicador_nombre: publisherName, 
                    mes: currentMonth, 
                    horas: valToSave,
                    estudios: reportEntry.estudios === '' ? 0 : reportEntry.estudios,
                    notas: reportEntry.notas || ''
                }, { onConflict: 'publicador_nombre, mes' });
                if (reportError) throw reportError;
            } else {
                const { error: deleteError } = await supabase.from('informes_ministerio').delete().eq('publicador_nombre', publisherName).eq('mes', currentMonth);
                if (deleteError) throw deleteError; // Ignore if didn't exist
            }

            const visitData = visits[publisherName];
            if (visitData && (visitData.date || visitData.notes)) {
                const { error: visitError } = await supabase.from('visitas_pastoral').upsert({ 
                    publicador_nombre: publisherName, 
                    fecha_visita: visitData.date,
                    notas: visitData.notes
                }, { onConflict: 'publicador_nombre' });
                if (visitError) throw visitError;
            }

            setStatusMessage({ text: 'Guardado', type: 'success' });
            setTimeout(() => setStatusMessage(null), 2000);
        } catch (err: any) {
            console.error(err);
            setStatusMessage({ text: 'Error al guardar', type: 'error' });
        }
    };

    const filteredMembers = members.filter(m => m.publicador_nombre.toLowerCase().includes(searchTerm.toLowerCase()));
    const filteredSuggestions = masterPublishers.filter(p => p.nombre.toLowerCase().includes(addSearchTerm.toLowerCase()) && !members.some(m => m.publicador_nombre === p.nombre)).slice(0, 6);
    const currentGroupName = groups.find(g => g.id === selectedGroupId)?.nombre || 'Sin Grupo';

    return (
        <div className="container mx-auto px-4 py-8 group-container relative">

            {/* --- Global Edit Modal (Mobile) --- */}
            {editingMember && (
                <EditMemberModal 
                    member={editingMember}
                    reportEntry={reports[editingMember.publicador_nombre]}
                    visitData={visits[editingMember.publicador_nombre] || { date: '', notes: '' }}
                    onClose={() => setEditingMember(null)}
                    onReportChange={handleReportChange}
                    onVisitChange={handleVisitChange}
                    onSave={handleSaveRow}
                    onDelete={handleDeleteMember}
                    onRemoveReport={handleRemoveReport}
                />
            )}

            {/* --- TOP BAR --- */}
            <div style={{ display: 'flex', flexDirection: 'column', gap: '1.5rem', marginBottom: '2rem' }}>
                <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', flexWrap: 'wrap', gap: '1rem' }}>
                    <div style={{flex: 1}}>
                        {!isCreatingGroup ? (
                            <div style={{display: 'flex', alignItems: 'center', gap: '10px'}}>
                                <select 
                                    value={selectedGroupId || ''} 
                                    onChange={(e) => setSelectedGroupId(Number(e.target.value))}
                                    className="gc-header-title"
                                    style={{ background: 'transparent', border: 'none', cursor: 'pointer', paddingRight: '20px', outline: 'none' }}
                                >
                                    {groups.length === 0 && <option value="">Crear un grupo...</option>}
                                    {groups.map(g => <option key={g.id} value={g.id}>{g.nombre}</option>)}
                                </select>
                                <button onClick={() => setIsCreatingGroup(true)} style={{background: '#e0e7ff', color: '#4338ca', border: 'none', borderRadius: '50%', width: '32px', height: '32px', cursor: 'pointer', display: 'flex', alignItems: 'center', justifyContent: 'center'}} title="Crear nuevo grupo">
                                    <i className="fas fa-plus"></i>
                                </button>
                                {groups.length > 0 && (
                                    <button onClick={handleDeleteGroup} style={{background: '#fee2e2', color: '#dc2626', border: 'none', borderRadius: '50%', width: '32px', height: '32px', cursor: 'pointer', display: 'flex', alignItems: 'center', justifyContent: 'center', marginLeft: '5px'}} title="Eliminar este grupo">
                                        <i className="fas fa-trash-alt" style={{fontSize: '0.8rem'}}></i>
                                    </button>
                                )}
                            </div>
                        ) : (
                            <div style={{display: 'flex', gap: '10px', alignItems: 'center'}}>
                                <input 
                                    autoFocus type="text" placeholder="Nombre del Grupo" 
                                    value={newGroupName} onChange={(e) => setNewGroupName(e.target.value)}
                                    className="gc-input-add" style={{width: '250px'}}
                                />
                                <button onClick={handleCreateGroup} className="button" style={{backgroundColor: '#10b981', color: 'white'}}>Guardar</button>
                                <button onClick={() => setIsCreatingGroup(false)} className="button" style={{backgroundColor: '#6b7280', color: 'white'}}>Cancelar</button>
                            </div>
                        )}
                        <p style={{ color: '#6b7280', fontWeight: '500', display: 'flex', alignItems: 'center', gap: '0.5rem', marginTop: '0.5rem' }}>
                            <i className="fas fa-users" style={{ color: '#60a5fa' }}></i>
                            {members.length} Integrantes
                        </p>
                    </div>

                    <div style={{ display: 'flex', gap: '0.75rem', alignItems: 'center', backgroundColor: 'white', padding: '0.5rem', borderRadius: '0.75rem', border: '1px solid #e5e7eb', boxShadow: '0 1px 2px 0 rgba(0,0,0,0.05)' }}>
                        <div style={{ backgroundColor: '#f3f4f6', padding: '0.5rem 0.75rem', borderRadius: '0.5rem', color: '#6b7280' }}><i className="fas fa-calendar-alt"></i></div>
                        <input type="month" value={currentMonth} onChange={(e) => setCurrentMonth(e.target.value)} style={{ border: 'none', background: 'transparent', fontWeight: '600', color: '#374151', outline: 'none', cursor: 'pointer' }} />
                    </div>
                </div>
            </div>

            {/* --- ADD MEMBER --- */}
            {selectedGroupId && (
                <div className="gc-card-add" style={{overflow: 'visible'}}>
                    <div className="gc-label-add"><i className="fas fa-user-plus"></i>Agregar Integrante</div>
                    <div style={{ display: 'flex', flexDirection: 'row', gap: '1rem', flexWrap: 'wrap', position: 'relative' }} ref={suggestionsRef}>
                        <div style={{ position: 'relative', flexGrow: 1 }}>
                            <i className="fas fa-search" style={{ position: 'absolute', left: '1rem', top: '50%', transform: 'translateY(-50%)', color: '#9ca3af', zIndex: 10 }}></i>
                            <input 
                                type="text" value={addSearchTerm}
                                onChange={(e) => { setAddSearchTerm(e.target.value); setShowSuggestions(true); }}
                                onFocus={() => setShowSuggestions(true)}
                                onKeyDown={(e) => { if (e.key === 'Enter') { handleAddMember(addSearchTerm); setShowSuggestions(false); } }}
                                placeholder="Buscar o escribir nombre nuevo..."
                                className="gc-input-add" autoComplete="off"
                            />
                            {showSuggestions && addSearchTerm && (
                                <div style={{ position: 'absolute', top: '100%', left: 0, right: 0, backgroundColor: 'white', border: '1px solid #e5e7eb', borderRadius: '0.75rem', marginTop: '5px', zIndex: 50, boxShadow: '0 10px 15px -3px rgba(0, 0, 0, 0.1)', maxHeight: '300px', overflowY: 'auto' }}>
                                    {filteredSuggestions.map(p => (
                                        <div key={p.id} onClick={() => { handleAddMember(p.nombre); setAddSearchTerm(''); setShowSuggestions(false); }} style={{ padding: '10px 15px', cursor: 'pointer', borderBottom: '1px solid #f3f4f6', display: 'flex', alignItems: 'center', gap: '10px' }}>
                                            <div className={`flex-shrink-0 w-6 h-6 flex items-center justify-center rounded-full text-xs text-white font-bold ${getAvatarClass(p.nombre)}`}>{p.nombre.charAt(0)}</div>
                                            <span style={{color: '#374151', fontWeight: '500'}}>{p.nombre}</span>
                                            <i className="fas fa-plus" style={{marginLeft: 'auto', color: '#10b981', fontSize: '0.8rem'}}></i>
                                        </div>
                                    ))}
                                    <div onClick={() => { handleAddMember(addSearchTerm); setAddSearchTerm(''); setShowSuggestions(false); }} style={{ padding: '10px 15px', cursor: 'pointer', backgroundColor: '#fdf4ff', borderTop: '1px solid #f3f4f6', display: 'flex', alignItems: 'center', gap: '10px' }}>
                                        <div style={{width: '24px', height: '24px', display:'flex', alignItems:'center', justifyContent:'center', color: '#d946ef'}}><i className="fas fa-pen"></i></div>
                                        <div style={{display:'flex', flexDirection:'column'}}><span style={{color: '#374151', fontWeight: '600'}}>Agregar "{addSearchTerm}"</span><span style={{fontSize: '0.75rem', color: '#d946ef'}}>Nombre manual</span></div>
                                    </div>
                                </div>
                            )}
                        </div>
                        <button onClick={() => handleAddMember(addSearchTerm)} disabled={!addSearchTerm.trim()} className="gc-btn-add"><span>Agregar</span><i className="fas fa-arrow-right"></i></button>
                    </div>
                </div>
            )}

            {/* Status Toast */}
            {statusMessage && (
