                                    <div className="relative">
                                        <label className="block text-[10px] uppercase font-bold text-gray-400 mb-1 ml-1">Estudios</label>
                                        <div className="relative">
                                            <input 
                                                type="number" min="0" 
                                                value={reportEntry?.estudios || ''} 
                                                onChange={(e) => onReportChange(pName, 'estudios', e.target.value)}
                                                className="block w-full px-4 py-3 text-2xl font-bold text-gray-800 bg-gray-50 border border-gray-200 rounded-xl focus:ring-2 focus:ring-blue-500 focus:border-blue-500 text-center shadow-sm"
                                                placeholder="0"
                                            />
                                        </div>
