                                    <label className="block text-[10px] uppercase font-bold text-gray-400 mb-1 ml-1">Notas</label>
                                    <input
                                        type="text"
                                        value={reportEntry?.notas || ''}
                                        onChange={(e) => onReportChange(pName, 'notas', e.target.value)}
                                        className="block w-full px-4 py-3 text-base text-gray-700 bg-gray-50 border border-gray-200 rounded-xl focus:ring-2 focus:ring-blue-500 focus:border-blue-500 shadow-sm"
