import React, { useState, useEffect, useRef } from 'react';
import { supabase } from '../lib/supabase';

type Publisher = {
    id: number;
    nombre: string;
};

type Group = {
    id: number;
    nombre: string;
};

type GroupMember = {
    id: number;
    grupo_id: number;
    publicador_nombre: string;
};

type MinistryReport = {
    horas: number | '';
    estudios: number | '';
    notas?: string;
};

type VisitData = {
    date: string;
    notes: string;
};

type ReportsMap = Record<string, MinistryReport>;
type VisitsMap = Record<string, VisitData>;

// Helper for avatar colors
const getAvatarClass = (name: string) => {
    const classes = ['bg-red-500', 'bg-orange-500', 'bg-amber-500', 'bg-green-500', 'bg-teal-500', 'bg-blue-500', 'bg-indigo-500', 'bg-purple-500', 'bg-pink-500'];
    let hash = 0;
    for (let i = 0; i < name.length; i++) {
        hash = name.charCodeAt(i) + ((hash << 5) - hash);
    }
    return classes[Math.abs(hash) % classes.length];
};

// --- MODAL COMPONENT (Ventana Emergente Única) ---
const EditMemberModal: React.FC<{
    member: GroupMember;
    reportEntry: MinistryReport | undefined;
    visitData: VisitData;
    onClose: () => void;
    onReportChange: (name: string, field: keyof MinistryReport, value: string | number) => void;
    onVisitChange: (name: string, field: keyof VisitData, value: string) => void;
    onSave: (name: string) => void;
    onDelete: (id: number, name: string) => void;
    onRemoveReport: (name: string) => void;
}> = ({ member, reportEntry, visitData, onClose, onReportChange, onVisitChange, onSave, onDelete, onRemoveReport }) => {
    const pName = member.publicador_nombre;
    const visitDate = visitData.date;

    // Estado local para "Informó Actividad"
    const hasReport = reportEntry !== undefined;

    const handleToggleReport = (e: React.ChangeEvent<HTMLInputElement>) => {
        if (e.target.checked) {
            onReportChange(pName, 'horas', 0); // Inicia con 0 horas (Predicó)
        } else {
            onRemoveReport(pName); // Elimina el informe
        }
    };

    // Lógica visual para semáforo de visita
    let visitBadgeClass = 'bg-gray-100 text-gray-500 border-gray-200';
    let visitLabel = 'N/A';
    if (visitDate) {
        const daysSince = (new Date().getTime() - new Date(visitDate).getTime()) / (1000 * 3600 * 24);
        if (daysSince < 90) { visitBadgeClass = 'bg-green-100 text-green-700 border-green-200'; visitLabel = 'Al día'; } 
        else if (daysSince < 180) { visitBadgeClass = 'bg-amber-100 text-amber-700 border-amber-200'; visitLabel = 'Atención'; } 
        else { visitBadgeClass = 'bg-red-100 text-red-700 border-red-200'; visitLabel = 'Urgente'; }
    }

    return (
        <div className="fixed inset-0 z-[9999] flex items-end sm:items-center justify-center bg-black/60 backdrop-blur-sm animate-fadeIn" onClick={onClose}>
            <div 
                className="bg-white w-full max-w-md rounded-t-3xl sm:rounded-2xl shadow-2xl overflow-hidden flex flex-col max-h-[90vh] animate-slideUp" 
                onClick={e => e.stopPropagation()}
            >
                {/* Header */}
                <div className="bg-white px-6 py-5 border-b border-gray-100 flex justify-between items-center sticky top-0 z-10">
                    <div className="flex items-center gap-4 overflow-hidden">
                        <div className={`flex-shrink-0 w-12 h-12 flex items-center justify-center rounded-full text-xl font-bold text-white shadow-md ${getAvatarClass(pName)}`}>
                            {pName.charAt(0)}
                        </div>
                        <h3 className="font-bold text-gray-900 text-xl truncate">{pName}</h3>
                    </div>
                    <button onClick={onClose} className="w-10 h-10 flex items-center justify-center rounded-full bg-gray-100 text-gray-500 hover:bg-gray-200 text-xl">
                        <i className="fas fa-times"></i>
                    </button>
                </div>

                {/* Body */}
                <div className="p-6 overflow-y-auto bg-slate-50">

                    {/* Sección Ministerio */}
                    <div className="bg-white p-5 rounded-2xl shadow-sm border border-gray-100 mb-6">
                        <div className="flex justify-between items-center mb-4">
                            <h4 className="text-sm font-extrabold text-blue-600 uppercase tracking-wider flex items-center gap-2">
                                <i className="fas fa-briefcase"></i> Informe
                            </h4>
                            {/* Toggle Switch */}
                            <label className="relative inline-flex items-center cursor-pointer">
                                <input type="checkbox" className="sr-only peer" checked={hasReport} onChange={handleToggleReport} />
                                <div className="w-12 h-7 bg-gray-200 peer-focus:outline-none rounded-full peer peer-checked:after:translate-x-full peer-checked:after:border-white after:content-[''] after:absolute after:top-[2px] after:left-[2px] after:bg-white after:border-gray-300 after:border after:rounded-full after:h-6 after:w-6 after:transition-all peer-checked:bg-blue-600 shadow-inner"></div>
                            </label>
                        </div>

                        {hasReport ? (
                            <div className="space-y-4 animate-fadeIn">
                                <div className="grid grid-cols-2 gap-4">
                                    <div className="relative">
                                        <label className="block text-[10px] uppercase font-bold text-gray-400 mb-1 ml-1">Horas</label>
                                        <div className="relative">
                                            <input 
                                                type="number" min="0" step="0.5"
                                                value={reportEntry?.horas === 0 ? '0' : (reportEntry?.horas || '')} 
                                                onChange={(e) => onReportChange(pName, 'horas', e.target.value)}
                                                className="block w-full px-4 py-3 text-2xl font-bold text-gray-800 bg-gray-50 border border-gray-200 rounded-xl focus:ring-2 focus:ring-blue-500 focus:border-blue-500 text-center shadow-sm"
                                                placeholder="0"
                                            />
                                        </div>
                                    </div>
                                    <div className="relative">
                                        <label className="block text-[10px] uppercase font-bold text-gray-400 mb-1 ml-1">Estudios</label>
                                        <div className="relative">
                                            <input 
                                                type="number" min="0" 
                                                value={reportEntry?.estudios || ''} 
                                                onChange={(e) => onReportChange(pName, 'estudios', e.target.value)}
                                                className="block w-full px-4 py-3 text-2xl font-bold text-gray-800 bg-gray-50 border border-gray-200 rounded-xl focus:ring-2 focus:ring-blue-500 focus:border-blue-500 text-center shadow-sm"
                                                placeholder="0"
                                            />
                                        </div>
                                    </div>
                                </div>

                                <div className="relative">
                                    <label className="block text-[10px] uppercase font-bold text-gray-400 mb-1 ml-1">Notas</label>
                                    <input
                                        type="text"
                                        value={reportEntry?.notas || ''}
                                        onChange={(e) => onReportChange(pName, 'notas', e.target.value)}
                                        className="block w-full px-4 py-3 text-base text-gray-700 bg-gray-50 border border-gray-200 rounded-xl focus:ring-2 focus:ring-blue-500 focus:border-blue-500 shadow-sm"
                                        placeholder="Observaciones..."
                                    />
                                </div>
                            </div>
                        ) : (
                            <div className="p-6 rounded-xl border-2 border-dashed border-gray-200 text-center bg-gray-50">
                                <span className="text-gray-400 text-sm font-medium">Inactivo este mes</span>
                            </div>
                        )}
                    </div>

                    {/* Sección Pastoreo */}
                    <div className="bg-white p-5 rounded-2xl shadow-sm border border-gray-100">
                        <div className="flex justify-between items-center mb-4">
                            <h4 className="text-sm font-extrabold text-pink-600 uppercase tracking-wider flex items-center gap-2">
                                <i className="fas fa-heart"></i> Pastoreo
                            </h4>
                            <span className={`px-3 py-1 rounded-full text-[10px] font-bold border uppercase tracking-wide ${visitBadgeClass}`}>
                                {visitLabel}
                            </span>
                        </div>

                        <div className="space-y-4">
                            <div className="relative">
                                <label className="block text-[10px] uppercase font-bold text-gray-400 mb-1 ml-1">Fecha de Visita</label>
                                <input 
                                    type="date" 
                                    value={visitDate}
                                    onChange={(e) => onVisitChange(pName, 'date', e.target.value)}
                                    className="block w-full px-4 py-3 text-base font-medium text-gray-700 bg-gray-50 border border-gray-200 rounded-xl focus:ring-2 focus:ring-pink-500 focus:border-pink-500 shadow-sm"
                                />
                            </div>
                            <div className="relative">
                                <label className="block text-[10px] uppercase font-bold text-gray-400 mb-1 ml-1">Apuntes</label>
                                <input
                                    type="text"
                                    value={visitData.notes || ''}
                                    onChange={(e) => onVisitChange(pName, 'notes', e.target.value)}
                                    className="block w-full px-4 py-3 text-base text-gray-700 bg-gray-50 border border-gray-200 rounded-xl focus:ring-2 focus:ring-pink-500 focus:border-pink-500 shadow-sm"
                                    placeholder="Nota de la visita..."
                                />
                            </div>
                        </div>
                    </div>
                </div>

                {/* Footer Buttons (Solo Signos Grandes) */}
                <div className="bg-white p-4 border-t border-gray-100 flex gap-4 shadow-[0_-4px_6px_-1px_rgba(0,0,0,0.05)]">
                    <button 
                        onClick={() => {
                            if(window.confirm('¿Eliminar a este integrante?')) {
                                onDelete(member.id, pName);
                                onClose();
                            }
                        }}
                        className="w-20 h-16 flex items-center justify-center rounded-2xl bg-red-50 text-red-500 hover:bg-red-100 transition-colors border border-red-100"
                        title="Eliminar"
                    >
                        <i className="fas fa-trash-alt text-2xl"></i>
                    </button>

                    <button 
                        onClick={() => {
                            onSave(pName);
                            onClose();
                        }}
                        className="flex-1 h-16 flex items-center justify-center rounded-2xl bg-blue-600 text-white hover:bg-blue-700 shadow-lg shadow-blue-200 active:scale-[0.98] transition-all"
                        title="Guardar"
                    >
                        <i className="fas fa-save text-3xl"></i>
                    </button>
                </div>
            </div>
        </div>
    );
};

