const GrupoCongregacion: React.FC = () => {
    // Data State
    const [groups, setGroups] = useState<Group[]>([]);
    const [selectedGroupId, setSelectedGroupId] = useState<number | null>(null);
    const [members, setMembers] = useState<GroupMember[]>([]);
    const [masterPublishers, setMasterPublishers] = useState<Publisher[]>([]); 

    // UI State
    const [loading, setLoading] = useState(true);
    const [currentMonth, setCurrentMonth] = useState<string>('');
    const [reports, setReports] = useState<ReportsMap>({});
    const [visits, setVisits] = useState<VisitsMap>({});
    const [searchTerm, setSearchTerm] = useState('');
    const [addSearchTerm, setAddSearchTerm] = useState(''); 
    const [showSuggestions, setShowSuggestions] = useState(false);
    const [isCreatingGroup, setIsCreatingGroup] = useState(false);
    const [newGroupName, setNewGroupName] = useState('');
    const [statusMessage, setStatusMessage] = useState<{ text: string; type: 'success' | 'error' | 'info' } | null>(null);

    // Global Modal State for Mobile
    const [editingMember, setEditingMember] = useState<GroupMember | null>(null);

    const suggestionsRef = useRef<HTMLDivElement>(null);

    // Initial Load
    useEffect(() => {
        const now = new Date();
        const yyyy = now.getFullYear();
        const mm = String(now.getMonth() + 1).padStart(2, '0');
        setCurrentMonth(`${yyyy}-${mm}`);

        fetchGroups();
        fetchMasterPublishers();

        const handleClickOutside = (event: MouseEvent) => {
            if (suggestionsRef.current && !suggestionsRef.current.contains(event.target as Node)) {
                setShowSuggestions(false);
            }
        };
        document.addEventListener('mousedown', handleClickOutside);
        return () => document.removeEventListener('mousedown', handleClickOutside);
    }, []);

    // Load Data Functions
    const fetchGroups = async () => {
        const { data, error } = await supabase.from('grupos').select('*').order('nombre');
        if (error) {
            console.error("Error fetching groups:", error);
        } else if (data) {
            setGroups(data);
            if (data.length > 0 && !selectedGroupId) {
                const defaultGroup = data.find(g => g.nombre.includes('5')) || data[0];
                setSelectedGroupId(defaultGroup.id);
            }
        }
    };

    const fetchMasterPublishers = async () => {
        const { data } = await supabase.from('publicadores').select('id, nombre').order('nombre');
        if (data) setMasterPublishers(data);
    };

    const fetchMembers = async () => {
        if (!selectedGroupId) return;
        setLoading(true);
        const { data, error } = await supabase
            .from('miembros_grupo')
            .select('*')
            .eq('grupo_id', selectedGroupId)
            .order('publicador_nombre');

        if (error) console.error("Error fetching members:", error);
        else setMembers(data || []);
        setLoading(false);
    };

    useEffect(() => {
        fetchMembers();
    }, [selectedGroupId]);

    useEffect(() => {
        if (!currentMonth || members.length === 0) return;

        const fetchData = async () => {
            const memberNames = members.map(m => m.publicador_nombre);

            const { data: reportsData } = await supabase
                .from('informes_ministerio')
                .select('publicador_nombre, horas, estudios, notas')
                .eq('mes', currentMonth)
                .in('publicador_nombre', memberNames);

            const newReports: ReportsMap = {};
            if (reportsData) {
                reportsData.forEach((r: any) => {
                    newReports[r.publicador_nombre] = { 
                        horas: r.horas,
                        estudios: r.estudios || '',
                        notas: r.notas || ''
                    };
                });
            }
            setReports(newReports);

            const { data: visitsData } = await supabase
                .from('visitas_pastoral')
                .select('publicador_nombre, fecha_visita, notas')
                .in('publicador_nombre', memberNames);

            const newVisits: VisitsMap = {};
            if (visitsData) {
                visitsData.forEach((v: any) => {
                    newVisits[v.publicador_nombre] = {
                        date: v.fecha_visita,
                        notes: v.notas || ''
                    };
                });
            }
            setVisits(newVisits);
        };

        fetchData();
    }, [currentMonth, members]);

    const handleCreateGroup = async () => {
        if (!newGroupName.trim()) return;
        const normalizedName = newGroupName.trim();

        const { data, error } = await supabase.from('grupos').insert([{ nombre: normalizedName }]).select();

        if (error) {
            if (error.code === '23505') {
                const { data: existingGroup } = await supabase.from('grupos').select('*').eq('nombre', normalizedName).single();
                if (existingGroup) {
                    setGroups(prev => prev.some(g => g.id === existingGroup.id) ? prev : [...prev, existingGroup].sort((a,b) => a.nombre.localeCompare(b.nombre)));
                    setSelectedGroupId(existingGroup.id);
                    setIsCreatingGroup(false);
                    setNewGroupName('');
                    setStatusMessage({ text: `El grupo "${normalizedName}" ya existe. Seleccionado.`, type: 'info' });
                    setTimeout(() => setStatusMessage(null), 3000);
                    return; 
                }
            }
            console.error("Error creating group:", error);
            setStatusMessage({ text: `Error: ${error.message}`, type: 'error' });
            setTimeout(() => setStatusMessage(null), 4000);
        } else if (data) {
            setGroups(prev => [...prev, data[0]].sort((a,b) => a.nombre.localeCompare(b.nombre)));
            setSelectedGroupId(data[0].id);
            setIsCreatingGroup(false);
            setNewGroupName('');
            setStatusMessage({ text: 'Grupo creado con éxito', type: 'success' });
            setTimeout(() => setStatusMessage(null), 3000);
        }
    };

    const handleDeleteGroup = async () => {
        if (!selectedGroupId) return;
        const groupName = groups.find(g => g.id === selectedGroupId)?.nombre;
        if (!window.confirm(`¿Estás seguro de eliminar el "${groupName}" y todos sus integrantes?`)) return;

        const { error } = await supabase.from('grupos').delete().eq('id', selectedGroupId);
        if (error) {
            setStatusMessage({ text: `Error al eliminar: ${error.message}`, type: 'error' });
        } else {
            const remaining = groups.filter(g => g.id !== selectedGroupId);
            setGroups(remaining);
            setSelectedGroupId(remaining.length > 0 ? remaining[0].id : null);
            setMembers([]);
            setStatusMessage({ text: 'Grupo eliminado', type: 'success' });
            setTimeout(() => setStatusMessage(null), 3000);
        }
    };

    const handleAddMember = async (name: string) => {
        if (!selectedGroupId || !name.trim()) return;
        if (members.some(m => m.publicador_nombre.toLowerCase() === name.toLowerCase())) {
            setStatusMessage({ text: 'Esta persona ya está en el grupo', type: 'error' });
            setTimeout(() => setStatusMessage(null), 3000);
            return;
        }
        const { error } = await supabase.from('miembros_grupo').insert([{ grupo_id: selectedGroupId, publicador_nombre: name.trim() }]);
        if (error) {
            setStatusMessage({ text: `Error al agregar: ${error.message}`, type: 'error' });
        } else {
            setStatusMessage({ text: 'Agregado correctamente', type: 'success' });
            setAddSearchTerm('');
            fetchMembers();
        }
        setTimeout(() => setStatusMessage(null), 3000);
    };

    const handleDeleteMember = async (id: number, name: string) => {
        // Confirmation is handled in the modal for mobile, or simple check here
        const { error } = await supabase.from('miembros_grupo').delete().eq('id', id);
        if (!error) {
            fetchMembers();
            if(editingMember?.id === id) setEditingMember(null);
        } else console.error("Error deleting member:", error);
    };

    const handleReportChange = (name: string, field: keyof MinistryReport, value: string | number) => {
        setReports(prev => {
            const currentEntry = prev[name] || { horas: '', estudios: '', notas: '' };
            const newValue = (field === 'horas' || field === 'estudios') 
                ? (value === '' ? '' : Number(value)) 
                : value;

            return {
                ...prev,
                [name]: { ...currentEntry, [field]: newValue }
            };
        });
    };

    const handleRemoveReport = (name: string) => {
        setReports(prev => {
            const next = { ...prev };
            delete next[name];
            return next;
        });
    };

    const handleVisitChange = (name: string, field: keyof VisitData, value: string) => {
        setVisits(prev => {
            const currentEntry = prev[name] || { date: '', notes: '' };
            return {
                ...prev,
                [name]: { ...currentEntry, [field]: value }
            };
        });
    };

    const handleSaveRow = async (publisherName: string) => {
        setStatusMessage(null);
        try {
            const reportEntry = reports[publisherName];
            if (reportEntry) {
                const valToSave = reportEntry.horas === '' ? 0 : reportEntry.horas;
                const { error: reportError } = await supabase.from('informes_ministerio').upsert({ 
                    publicador_nombre: publisherName, 
                    mes: currentMonth, 
                    horas: valToSave,
                    estudios: reportEntry.estudios === '' ? 0 : reportEntry.estudios,
                    notas: reportEntry.notas || ''
                }, { onConflict: 'publicador_nombre, mes' });
                if (reportError) throw reportError;
            } else {
                const { error: deleteError } = await supabase.from('informes_ministerio').delete().eq('publicador_nombre', publisherName).eq('mes', currentMonth);
                if (deleteError) throw deleteError; // Ignore if didn't exist
            }

            const visitData = visits[publisherName];
            if (visitData && (visitData.date || visitData.notes)) {
                const { error: visitError } = await supabase.from('visitas_pastoral').upsert({ 
                    publicador_nombre: publisherName, 
                    fecha_visita: visitData.date,
                    notas: visitData.notes
                }, { onConflict: 'publicador_nombre' });
                if (visitError) throw visitError;
            }

            setStatusMessage({ text: 'Guardado', type: 'success' });
            setTimeout(() => setStatusMessage(null), 2000);
        } catch (err: any) {
            console.error(err);
            setStatusMessage({ text: 'Error al guardar', type: 'error' });
        }
    };

    const filteredMembers = members.filter(m => m.publicador_nombre.toLowerCase().includes(searchTerm.toLowerCase()));
    const filteredSuggestions = masterPublishers.filter(p => p.nombre.toLowerCase().includes(addSearchTerm.toLowerCase()) && !members.some(m => m.publicador_nombre === p.nombre)).slice(0, 6);
    const currentGroupName = groups.find(g => g.id === selectedGroupId)?.nombre || 'Sin Grupo';

    return (
        <div className="container mx-auto px-4 py-8 group-container relative">
            <style>{`
                @media (max-width: 1023px) {
                    .gc-desktop-view, .gc-table-header { display: none !important; }
                    .gc-mobile-view { display: block !important; }
                }
                @media (min-width: 1024px) {
                    .gc-desktop-view { display: grid !important; }
                    .gc-table-header { display: grid !important; }
                    .gc-mobile-view { display: none !important; }
                }
            `}</style>

            {/* --- Global Edit Modal (Mobile) --- */}
            {editingMember && (
                <EditMemberModal 
                    member={editingMember}
                    reportEntry={reports[editingMember.publicador_nombre]}
                    visitData={visits[editingMember.publicador_nombre] || { date: '', notes: '' }}
                    onClose={() => setEditingMember(null)}
                    onReportChange={handleReportChange}
                    onVisitChange={handleVisitChange}
                    onSave={handleSaveRow}
                    onDelete={handleDeleteMember}
                    onRemoveReport={handleRemoveReport}
                />
            )}

            {/* --- TOP BAR (Rediseñado para Móvil y Desktop) --- */}
            <div className="flex flex-col gap-6 mb-8">
                {/* Controles de Grupo y Mes */}
                <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                    {/* Selector de Grupo */}
                    <div className="bg-white p-3 rounded-xl shadow-sm border border-gray-200 flex items-center gap-3">
                        <div className="w-10 h-10 rounded-lg bg-blue-50 flex items-center justify-center text-blue-600">
                            <i className="fas fa-users text-lg"></i>
                        </div>
                        <div className="flex-1 min-w-0">
                            <label className="block text-xs font-bold text-gray-400 uppercase tracking-wider mb-0.5">Grupo</label>
                            {isCreatingGroup ? (
                                <div className="flex gap-2">
                                    <input 
                                        autoFocus type="text" placeholder="Nombre..." 
                                        value={newGroupName} onChange={(e) => setNewGroupName(e.target.value)}
                                        className="w-full text-sm font-semibold text-gray-800 bg-transparent border-b border-blue-300 focus:outline-none"
                                    />
                                    <button onClick={handleCreateGroup} className="text-green-600"><i className="fas fa-check"></i></button>
                                    <button onClick={() => setIsCreatingGroup(false)} className="text-gray-400"><i className="fas fa-times"></i></button>
                                </div>
                            ) : (
                                <div className="flex items-center justify-between">
                                    <select 
                                        value={selectedGroupId || ''} 
                                        onChange={(e) => setSelectedGroupId(Number(e.target.value))}
                                        className="w-full text-base font-bold text-gray-800 bg-transparent border-none p-0 focus:ring-0 cursor-pointer"
                                    >
                                        {groups.length === 0 && <option value="">Crear un grupo...</option>}
                                        {groups.map(g => <option key={g.id} value={g.id}>{g.nombre}</option>)}
                                    </select>
                                    <div className="flex gap-2 ml-2">
                                        <button onClick={() => setIsCreatingGroup(true)} className="text-blue-500 hover:text-blue-700 p-1"><i className="fas fa-plus"></i></button>
                                        {groups.length > 0 && <button onClick={handleDeleteGroup} className="text-red-400 hover:text-red-600 p-1"><i className="fas fa-trash-alt"></i></button>}
                                    </div>
                                </div>
                            )}
                        </div>
                    </div>

                    {/* Selector de Mes */}
                    <div className="bg-white p-3 rounded-xl shadow-sm border border-gray-200 flex items-center gap-3">
                        <div className="w-10 h-10 rounded-lg bg-indigo-50 flex items-center justify-center text-indigo-600">
                            <i className="fas fa-calendar-alt text-lg"></i>
                        </div>
                        <div className="flex-1">
                            <label className="block text-xs font-bold text-gray-400 uppercase tracking-wider mb-0.5">Mes</label>
                            <input 
                                type="month" 
                                value={currentMonth} 
                                onChange={(e) => setCurrentMonth(e.target.value)}
                                className="w-full text-base font-bold text-gray-800 bg-transparent border-none p-0 focus:ring-0 cursor-pointer"
                            />
                        </div>
                    </div>
                </div>

                {/* --- ADD MEMBER & SEARCH (Estilo Tarjeta Unificada) --- */}
                {selectedGroupId && (
                    <div className="bg-white p-2 rounded-xl shadow-sm border border-gray-200 flex items-center" ref={suggestionsRef}>
                        <div className="pl-3 text-gray-400">
                            <i className="fas fa-search"></i>
                        </div>
                        <div className="flex-1 relative">
                            <input 
                                type="text" 
                                value={addSearchTerm}
                                onChange={(e) => { setAddSearchTerm(e.target.value); setShowSuggestions(true); }}
                                onFocus={() => setShowSuggestions(true)}
                                onKeyDown={(e) => { if (e.key === 'Enter') { handleAddMember(addSearchTerm); setShowSuggestions(false); } }}
                                placeholder="Buscar o agregar nuevo..."
                                className="w-full p-3 text-sm font-medium text-gray-700 bg-transparent border-none focus:ring-0 placeholder-gray-400"
                                autoComplete="off"
                            />
                            {/* Suggestions Dropdown */}
                            {showSuggestions && addSearchTerm && (
                                <div className="absolute top-full left-0 right-0 bg-white border border-gray-100 rounded-xl mt-2 shadow-xl z-50 overflow-hidden">
                                    {filteredSuggestions.map(p => (
                                        <div key={p.id} onClick={() => { handleAddMember(p.nombre); setAddSearchTerm(''); setShowSuggestions(false); }} className="px-4 py-3 hover:bg-gray-50 cursor-pointer border-b border-gray-50 flex items-center gap-3">
                                            <div className={`w-6 h-6 rounded-full flex items-center justify-center text-xs text-white font-bold ${getAvatarClass(p.nombre)}`}>{p.nombre.charAt(0)}</div>
                                            <span className="text-gray-700 font-medium">{p.nombre}</span>
                                            <i className="fas fa-plus ml-auto text-green-500 text-xs"></i>
                                        </div>
                                    ))}
                                    <div onClick={() => { handleAddMember(addSearchTerm); setAddSearchTerm(''); setShowSuggestions(false); }} className="px-4 py-3 bg-purple-50 hover:bg-purple-100 cursor-pointer flex items-center gap-3 text-purple-700">
                                        <i className="fas fa-pen text-xs"></i>
                                        <span className="font-semibold">Crear nuevo: "{addSearchTerm}"</span>
                                    </div>
                                </div>
                            )}
                        </div>
                        <button 
                            onClick={() => handleAddMember(addSearchTerm)} 
                            disabled={!addSearchTerm.trim()}
                            className="bg-gray-900 text-white px-4 py-2 rounded-lg font-bold text-sm hover:bg-gray-800 disabled:bg-gray-300 transition-colors"
                        >
                            Agregar
                        </button>
                    </div>
                )}
            </div>

            {/* Status Toast */}
            {statusMessage && (
                <div style={{ position: 'fixed', bottom: '1.5rem', right: '1.5rem', zIndex: 100, padding: '1rem 1.5rem', borderRadius: '0.75rem', boxShadow: '0 10px 15px -3px rgba(0, 0, 0, 0.1)', fontWeight: '600', display: 'flex', alignItems: 'center', gap: '0.75rem', backgroundColor: statusMessage.type === 'success' ? '#059669' : (statusMessage.type === 'info' ? '#3b82f6' : '#dc2626'), color: 'white' }}>
                    <i className={`fas ${statusMessage.type === 'success' ? 'fa-check-circle' : (statusMessage.type === 'info' ? 'fa-info-circle' : 'fa-exclamation-circle')}`}></i>
                    {statusMessage.text}
                </div>
            )}

            {/* Members List */}
            {loading ? (
                <div style={{ textAlign: 'center', padding: '5rem 0', color: '#9ca3af' }}><i className="fas fa-spinner fa-spin fa-3x" style={{ marginBottom: '1rem', color: '#93c5fd' }}></i><p style={{ fontWeight: '500' }}>Cargando datos...</p></div>
            ) : (
                <div className="modern-card bg-transparent shadow-none md:bg-white md:shadow-md md:rounded-lg">
                    {/* Header para Desktop */}
                    <div className="gc-table-header hidden lg:grid lg:grid-cols-12 lg:gap-4 lg:border-b lg:border-slate-200 lg:bg-slate-50 lg:p-4">
                        <div className="col-span-3 pl-2">Publicador</div><div className="col-span-2 text-center">Horas</div><div className="col-span-1 text-center">Est.</div><div className="col-span-2 text-center">Observaciones</div><div className="col-span-2 text-center">Pastoreo</div><div className="col-span-2 text-center">Acciones</div>
                    </div>

                    {/* Lista */}
                    <div style={{ display: 'flex', flexDirection: 'column' }}>
                        {filteredMembers.map((m, index) => (
                            <MemberRow 
                                key={m.id}
                                m={m}
                                index={index}
                                reportEntry={reports[m.publicador_nombre]}
                                visitData={visits[m.publicador_nombre] || { date: '', notes: '' }}
                                onReportChange={handleReportChange}
                                onVisitChange={handleVisitChange}
                                onSave={handleSaveRow}
                                onDelete={handleDeleteMember}
                                onRemoveReport={handleRemoveReport}
                                onOpenModal={setEditingMember}
                            />
                        ))}
                    </div>

                    {/* Empty State */}
                    {filteredMembers.length === 0 && (
                        <div style={{ padding: '5rem 0', textAlign: 'center', backgroundColor: '#f8fafc', borderRadius: '0.75rem' }}>
                            <div style={{ backgroundColor: 'white', width: '6rem', height: '6rem', borderRadius: '50%', display: 'flex', alignItems: 'center', justifyContent: 'center', margin: '0 auto 1.5rem auto', boxShadow: '0 1px 2px 0 rgba(0,0,0,0.05)', border: '1px solid #e2e8f0' }}><i className="fas fa-users fa-3x" style={{ color: '#c7d2fe' }}></i></div>
                            <h3 style={{ fontSize: '1.25rem', fontWeight: '700', color: '#374151' }}>{selectedGroupId ? 'Este grupo está vacío' : 'Crea o selecciona un grupo'}</h3>
                            <p style={{ color: '#6b7280', marginTop: '0.5rem', maxWidth: '24rem', marginInline: 'auto' }}>Utiliza el buscador de arriba para agregar publicadores.</p>
                        </div>
                    )}
                </div>
            )}
        </div>
    );
};

export default GrupoCongregacion;

import React, { useState, useEffect, useRef } from 'react';
import { supabase } from '../lib/supabase';

type Publisher = {
    id: number;
    nombre: string;
};

type Group = {
    id: number;
    nombre: string;
};

type GroupMember = {
    id: number;
    grupo_id: number;
    publicador_nombre: string;
};

type MinistryReport = {
    horas: number | '';
    estudios: number | '';
    notas?: string;
};

type VisitData = {
    date: string;
    notes: string;
};

type ReportsMap = Record<string, MinistryReport>;
type VisitsMap = Record<string, VisitData>;

// Helper for avatar colors (HEX codes to ensure they appear)
const getAvatarColor = (name: string) => {
    const colors = [
        '#ef4444', // red-500
        '#f97316', // orange-500
        '#f59e0b', // amber-500
        '#22c55e', // green-500
        '#14b8a6', // teal-500
        '#3b82f6', // blue-500
        '#6366f1', // indigo-500
        '#a855f7', // purple-500
        '#ec4899'  // pink-500
    ];
    let hash = 0;
    for (let i = 0; i < name.length; i++) {
        hash = name.charCodeAt(i) + ((hash << 5) - hash);
    }
    return colors[Math.abs(hash) % colors.length];
};

// --- MODAL COMPONENT (Ventana Emergente) ---
const EditMemberModal: React.FC<{
    member: GroupMember;
    reportEntry: MinistryReport | undefined;
    visitData: VisitData;
    onClose: () => void;
    onReportChange: (name: string, field: keyof MinistryReport, value: string | number) => void;
    onVisitChange: (name: string, field: keyof VisitData, value: string) => void;
    onSave: (name: string) => void;
    onDelete: (id: number, name: string) => void;
    onRemoveReport: (name: string) => void;
}> = ({ member, reportEntry, visitData, onClose, onReportChange, onVisitChange, onSave, onDelete, onRemoveReport }) => {
    const pName = member.publicador_nombre;
    const visitDate = visitData.date;

    const hasReport = reportEntry !== undefined;

    const handleToggleReport = (e: React.ChangeEvent<HTMLInputElement>) => {
        if (e.target.checked) {
            onReportChange(pName, 'horas', 0);
        } else {
            onRemoveReport(pName);
        }
    };

    let visitLabel = 'N/A';
    let visitColor = '#9ca3af'; // gray
    let visitBg = '#f3f4f6';

    if (visitDate) {
        const daysSince = (new Date().getTime() - new Date(visitDate).getTime()) / (1000 * 3600 * 24);
        if (daysSince < 90) { visitLabel = 'Al día'; visitColor = '#15803d'; visitBg = '#dcfce7'; } 
        else if (daysSince < 180) { visitLabel = 'Atención'; visitColor = '#b45309'; visitBg = '#fef3c7'; } 
        else { visitLabel = 'Urgente'; visitColor = '#b91c1c'; visitBg = '#fee2e2'; }
    }

    return (
        <div style={{
            position: 'fixed', top: 0, left: 0, right: 0, bottom: 0,
            backgroundColor: 'rgba(0,0,0,0.6)', zIndex: 99999,
            display: 'flex', alignItems: 'flex-end', justifyContent: 'center'
        }} onClick={onClose}>
            <div style={{
                backgroundColor: 'white', width: '100%', maxWidth: '500px',
                borderTopLeftRadius: '20px', borderTopRightRadius: '20px',
                overflow: 'hidden', display: 'flex', flexDirection: 'column',
                maxHeight: '90vh', animation: 'slideUp 0.3s ease-out'
            }} onClick={e => e.stopPropagation()}>

                {/* Header */}
                <div style={{ padding: '15px 20px', borderBottom: '1px solid #eee', display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
                    <div style={{ display: 'flex', alignItems: 'center', gap: '15px' }}>
                        <div style={{
                            width: '40px', height: '40px', borderRadius: '50%',
                            backgroundColor: getAvatarColor(pName), color: 'white',
                            display: 'flex', alignItems: 'center', justifyContent: 'center',
                            fontWeight: 'bold', fontSize: '1.2rem'
                        }}>
                            {pName.charAt(0)}
                        </div>
                        <h3 style={{ margin: 0, fontSize: '1.2rem', color: '#1f2937' }}>{pName}</h3>
                    </div>
                    <button onClick={onClose} style={{ border: 'none', background: 'transparent', fontSize: '1.5rem', color: '#6b7280', cursor: 'pointer' }}>
                        &times;
                    </button>
                </div>

                {/* Body */}
                <div style={{ padding: '20px', overflowY: 'auto', backgroundColor: '#f9fafb' }}>

                    {/* Informe Section */}
                    <div style={{ backgroundColor: 'white', padding: '15px', borderRadius: '12px', marginBottom: '15px', boxShadow: '0 1px 3px rgba(0,0,0,0.05)' }}>
                        <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '10px' }}>
                            <h4 style={{ margin: 0, color: '#2563eb', display: 'flex', alignItems: 'center', gap: '5px' }}>
                                <i className="fas fa-briefcase"></i> Informe
                            </h4>
                            <label style={{ display: 'flex', alignItems: 'center', gap: '10px', cursor: 'pointer' }}>
                                <span style={{ fontSize: '0.9rem', color: '#6b7280' }}>{hasReport ? 'Activo' : 'Inactivo'}</span>
                                <input type="checkbox" checked={hasReport} onChange={handleToggleReport} style={{ transform: 'scale(1.5)' }} />
                            </label>
                        </div>

                        {hasReport && (
                            <div style={{ display: 'flex', flexDirection: 'column', gap: '15px' }}>
                                <div style={{ display: 'flex', gap: '15px' }}>
                                    <div style={{ flex: 1 }}>
                                        <label style={{ display: 'block', fontSize: '0.8rem', color: '#6b7280', marginBottom: '5px' }}>Horas</label>
                                        <input 
                                            type="number" step="0.5" min="0"
                                            value={reportEntry?.horas === 0 ? '0' : (reportEntry?.horas || '')} 
                                            onChange={(e) => onReportChange(pName, 'horas', e.target.value)}
                                            style={{ width: '100%', padding: '10px', fontSize: '1.2rem', borderRadius: '8px', border: '1px solid #d1d5db', textAlign: 'center' }}
                                        />
                                    </div>
                                    <div style={{ flex: 1 }}>
                                        <label style={{ display: 'block', fontSize: '0.8rem', color: '#6b7280', marginBottom: '5px' }}>Estudios</label>
                                        <input 
                                            type="number" min="0" 
                                            value={reportEntry?.estudios || ''} 
                                            onChange={(e) => onReportChange(pName, 'estudios', e.target.value)}
                                            style={{ width: '100%', padding: '10px', fontSize: '1.2rem', borderRadius: '8px', border: '1px solid #d1d5db', textAlign: 'center' }}
                                        />
                                    </div>
                                </div>
                                <div>
                                    <label style={{ display: 'block', fontSize: '0.8rem', color: '#6b7280', marginBottom: '5px' }}>Notas</label>
                                    <input
                                        type="text"
                                        value={reportEntry?.notas || ''}
                                        onChange={(e) => onReportChange(pName, 'notas', e.target.value)}
                                        style={{ width: '100%', padding: '10px', borderRadius: '8px', border: '1px solid #d1d5db', boxSizing: 'border-box' }}
                                        placeholder="Observaciones..."
                                    />
                                </div>
                            </div>
                        )}
                        {!hasReport && (
                            <div style={{ padding: '15px', textAlign: 'center', color: '#9ca3af', border: '1px dashed #e5e7eb', borderRadius: '8px' }}>
                                Sin actividad este mes
                            </div>
                        )}
                    </div>

                    {/* Pastoreo Section */}
                    <div style={{ backgroundColor: 'white', padding: '15px', borderRadius: '12px', boxShadow: '0 1px 3px rgba(0,0,0,0.05)' }}>
                        <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '10px' }}>
                            <h4 style={{ margin: 0, color: '#ec4899', display: 'flex', alignItems: 'center', gap: '5px' }}>
                                <i className="fas fa-heart"></i> Pastoreo
                            </h4>
                            <span style={{ backgroundColor: visitBg, color: visitColor, padding: '2px 8px', borderRadius: '10px', fontSize: '0.8rem', fontWeight: 'bold' }}>
                                {visitLabel}
                            </span>
                        </div>
                        <div style={{ display: 'flex', flexDirection: 'column', gap: '15px' }}>
                            <div>
                                <label style={{ display: 'block', fontSize: '0.8rem', color: '#6b7280', marginBottom: '5px' }}>Fecha Visita</label>
                                <input 
                                    type="date" 
                                    value={visitDate}
                                    onChange={(e) => onVisitChange(pName, 'date', e.target.value)}
                                    style={{ width: '100%', padding: '10px', borderRadius: '8px', border: '1px solid #d1d5db', boxSizing: 'border-box' }}
                                />
                            </div>
                            <div>
                                <label style={{ display: 'block', fontSize: '0.8rem', color: '#6b7280', marginBottom: '5px' }}>Apuntes</label>
                                <input
                                    type="text"
                                    value={visitData.notes || ''}
                                    onChange={(e) => onVisitChange(pName, 'notes', e.target.value)}
                                    style={{ width: '100%', padding: '10px', borderRadius: '8px', border: '1px solid #d1d5db', boxSizing: 'border-box' }}
                                    placeholder="Nota de visita..."
                                />
                            </div>
                        </div>
                    </div>

                </div>

                {/* Footer Actions */}
                <div style={{ padding: '15px 20px', borderTop: '1px solid #eee', display: 'flex', gap: '15px' }}>
                    <button 
                        onClick={() => { if(window.confirm('¿Eliminar?')) { onDelete(member.id, pName); onClose(); } }}
                        style={{ padding: '12px', borderRadius: '8px', border: '1px solid #fecaca', backgroundColor: '#fef2f2', color: '#ef4444', cursor: 'pointer' }}
                    >
                        <i className="fas fa-trash-alt"></i>
                    </button>
                    <button 
                        onClick={() => { onSave(pName); onClose(); }}
                        style={{ flex: 1, padding: '12px', borderRadius: '8px', border: 'none', backgroundColor: '#2563eb', color: 'white', fontWeight: 'bold', cursor: 'pointer', fontSize: '1rem' }}
                    >
                        Guardar Cambios
                    </button>
                </div>
            </div>
        </div>
    );
};

// --- COMPONENTE PRINCIPAL ---
const GrupoCongregacion: React.FC = () => {
    // Data State
    const [groups, setGroups] = useState<Group[]>([]);
    const [selectedGroupId, setSelectedGroupId] = useState<number | null>(null);
    const [members, setMembers] = useState<GroupMember[]>([]);
    const [masterPublishers, setMasterPublishers] = useState<Publisher[]>([]); 

    // UI State
    const [isMobile, setIsMobile] = useState(window.innerWidth < 1024);
    const [loading, setLoading] = useState(true);
    const [currentMonth, setCurrentMonth] = useState<string>('');
    const [reports, setReports] = useState<ReportsMap>({});
    const [visits, setVisits] = useState<VisitsMap>({});
    const [searchTerm, setSearchTerm] = useState('');
    const [addSearchTerm, setAddSearchTerm] = useState(''); 
    const [showSuggestions, setShowSuggestions] = useState(false);
    const [isCreatingGroup, setIsCreatingGroup] = useState(false);
    const [newGroupName, setNewGroupName] = useState('');
    const [statusMessage, setStatusMessage] = useState<{ text: string; type: 'success' | 'error' | 'info' } | null>(null);

    // Global Modal State for Mobile
    const [editingMember, setEditingMember] = useState<GroupMember | null>(null);

    const suggestionsRef = useRef<HTMLDivElement>(null);

    // Initial Load
    useEffect(() => {
        const handleResize = () => setIsMobile(window.innerWidth < 1024);
        window.addEventListener('resize', handleResize);

        const now = new Date();
        const yyyy = now.getFullYear();
        const mm = String(now.getMonth() + 1).padStart(2, '0');
        setCurrentMonth(`${yyyy}-${mm}`);

        fetchGroups();
        fetchMasterPublishers();

        const handleClickOutside = (event: MouseEvent) => {
            if (suggestionsRef.current && !suggestionsRef.current.contains(event.target as Node)) {
                setShowSuggestions(false);
            }
        };
        document.addEventListener('mousedown', handleClickOutside);
        return () => {
            document.removeEventListener('mousedown', handleClickOutside);
            window.removeEventListener('resize', handleResize);
        }
    }, []);

    // Load Data Functions
    const fetchGroups = async () => {
        const { data, error } = await supabase.from('grupos').select('*').order('nombre');
        if (error) {
            console.error("Error fetching groups:", error);
        } else if (data) {
            setGroups(data);
            if (data.length > 0 && !selectedGroupId) {
                const defaultGroup = data.find(g => g.nombre.includes('5')) || data[0];
                setSelectedGroupId(defaultGroup.id);
            }
        }
    };

    const fetchMasterPublishers = async () => {
        const { data } = await supabase.from('publicadores').select('id, nombre').order('nombre');
        if (data) setMasterPublishers(data);
    };

    const fetchMembers = async () => {
        if (!selectedGroupId) return;
        setLoading(true);
        const { data, error } = await supabase
            .from('miembros_grupo')
            .select('*')
            .eq('grupo_id', selectedGroupId)
            .order('publicador_nombre');

        if (error) console.error("Error fetching members:", error);
        else setMembers(data || []);
        setLoading(false);
    };

    useEffect(() => {
        fetchMembers();
    }, [selectedGroupId]);

    useEffect(() => {
        if (!currentMonth || members.length === 0) return;

        const fetchData = async () => {
            const memberNames = members.map(m => m.publicador_nombre);

            const { data: reportsData } = await supabase
                .from('informes_ministerio')
                .select('publicador_nombre, horas, estudios, notas')
                .eq('mes', currentMonth)
                .in('publicador_nombre', memberNames);

            const newReports: ReportsMap = {};
            if (reportsData) {
                reportsData.forEach((r: any) => {
                    newReports[r.publicador_nombre] = { 
                        horas: r.horas,
                        estudios: r.estudios || '',
                        notas: r.notas || ''
                    };
                });
            }
            setReports(newReports);

            const { data: visitsData } = await supabase
                .from('visitas_pastoral')
                .select('publicador_nombre, fecha_visita, notas')
                .in('publicador_nombre', memberNames);

            const newVisits: VisitsMap = {};
            if (visitsData) {
                visitsData.forEach((v: any) => {
                    newVisits[v.publicador_nombre] = {
                        date: v.fecha_visita,
                        notes: v.notas || ''
                    };
                });
            }
            setVisits(newVisits);
        };

        fetchData();
    }, [currentMonth, members]);

    // ... (Handlers remain similar but simplified for brevity in this snippet)
    const handleCreateGroup = async () => { /* ... same logic ... */ };
    const handleDeleteGroup = async () => { /* ... same logic ... */ };
    const handleAddMember = async (name: string) => { 
        if (!selectedGroupId || !name.trim()) return;
        // ... basic insert logic ...
        const { error } = await supabase.from('miembros_grupo').insert([{ grupo_id: selectedGroupId, publicador_nombre: name.trim() }]);
        if(!error) { setAddSearchTerm(''); fetchMembers(); }
    };
    const handleDeleteMember = async (id: number, name: string) => {
        const { error } = await supabase.from('miembros_grupo').delete().eq('id', id);
        if (!error) { fetchMembers(); if(editingMember?.id === id) setEditingMember(null); }
    };
    const handleReportChange = (name: string, field: keyof MinistryReport, value: string | number) => {
        setReports(prev => {
            const currentEntry = prev[name] || { horas: '', estudios: '', notas: '' };
            const newValue = (field === 'horas' || field === 'estudios') ? (value === '' ? '' : Number(value)) : value;
            return { ...prev, [name]: { ...currentEntry, [field]: newValue } };
        });
    };
    const handleRemoveReport = (name: string) => {
        setReports(prev => { const next = { ...prev }; delete next[name]; return next; });
    };
    const handleVisitChange = (name: string, field: keyof VisitData, value: string) => {
        setVisits(prev => {
            const currentEntry = prev[name] || { date: '', notes: '' };
            return { ...prev, [name]: { ...currentEntry, [field]: value } };
        });
    };
    const handleSaveRow = async (publisherName: string) => {
        // ... upsert logic for report and visit ...
        const reportEntry = reports[publisherName];
        if (reportEntry) {
            await supabase.from('informes_ministerio').upsert({ 
                publicador_nombre: publisherName, mes: currentMonth, 
                horas: reportEntry.horas === '' ? 0 : reportEntry.horas, 
                estudios: reportEntry.estudios === '' ? 0 : reportEntry.estudios, 
                notas: reportEntry.notas || '' 
            }, { onConflict: 'publicador_nombre, mes' });
        } else {
            await supabase.from('informes_ministerio').delete().eq('publicador_nombre', publisherName).eq('mes', currentMonth);
        }
        const visitData = visits[publisherName];
        if (visitData && (visitData.date || visitData.notes)) {
            await supabase.from('visitas_pastoral').upsert({ publicador_nombre: publisherName, fecha_visita: visitData.date, notas: visitData.notes }, { onConflict: 'publicador_nombre' });
        }
        setStatusMessage({ text: 'Guardado', type: 'success' });
        setTimeout(() => setStatusMessage(null), 2000);
    };

    const filteredMembers = members.filter(m => m.publicador_nombre.toLowerCase().includes(searchTerm.toLowerCase()));
    const filteredSuggestions = masterPublishers.filter(p => p.nombre.toLowerCase().includes(addSearchTerm.toLowerCase()) && !members.some(m => m.publicador_nombre === p.nombre)).slice(0, 6);

    return (
        <div className="container mx-auto px-4 py-8 group-container relative">

            {/* Modal */}
            {editingMember && (
                <EditMemberModal 
                    member={editingMember}
                    reportEntry={reports[editingMember.publicador_nombre]}
                    visitData={visits[editingMember.publicador_nombre] || { date: '', notes: '' }}
                    onClose={() => setEditingMember(null)}
                    onReportChange={handleReportChange}
                    onVisitChange={handleVisitChange}
                    onSave={handleSaveRow}
                    onDelete={handleDeleteMember}
                    onRemoveReport={handleRemoveReport}
                />
            )}

            {/* Top Bar Controls */}
            <div className="flex flex-col gap-6 mb-8">
                <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                    <div className="bg-white p-3 rounded-xl shadow-sm border border-gray-200 flex items-center gap-3">
                        <div className="w-10 h-10 rounded-lg bg-blue-50 flex items-center justify-center text-blue-600"><i className="fas fa-users text-lg"></i></div>
                        <div className="flex-1 min-w-0">
                            <label className="block text-xs font-bold text-gray-400 uppercase tracking-wider mb-0.5">Grupo</label>
                            <select value={selectedGroupId || ''} onChange={(e) => setSelectedGroupId(Number(e.target.value))} className="w-full text-base font-bold text-gray-800 bg-transparent border-none p-0 focus:ring-0 cursor-pointer">
                                {groups.length === 0 && <option value="">Crear...</option>}
                                {groups.map(g => <option key={g.id} value={g.id}>{g.nombre}</option>)}
                            </select>
                        </div>
                    </div>
                    <div className="bg-white p-3 rounded-xl shadow-sm border border-gray-200 flex items-center gap-3">
                        <div className="w-10 h-10 rounded-lg bg-indigo-50 flex items-center justify-center text-indigo-600"><i className="fas fa-calendar-alt text-lg"></i></div>
                        <div className="flex-1">
                            <label className="block text-xs font-bold text-gray-400 uppercase tracking-wider mb-0.5">Mes</label>
                            <input type="month" value={currentMonth} onChange={(e) => setCurrentMonth(e.target.value)} className="w-full text-base font-bold text-gray-800 bg-transparent border-none p-0 focus:ring-0 cursor-pointer" />
                        </div>
                    </div>
                </div>

                {/* Add Member */}
                {selectedGroupId && (
                    <div className="bg-white p-2 rounded-xl shadow-sm border border-gray-200 flex items-center" ref={suggestionsRef}>
                        <div className="pl-3 text-gray-400"><i className="fas fa-search"></i></div>
                        <div className="flex-1 relative">
                            <input type="text" value={addSearchTerm} onChange={(e) => { setAddSearchTerm(e.target.value); setShowSuggestions(true); }} placeholder="Buscar o agregar nuevo..." className="w-full p-3 text-sm font-medium text-gray-700 bg-transparent border-none focus:ring-0 placeholder-gray-400" />
                            {showSuggestions && addSearchTerm && (
                                <div className="absolute top-full left-0 right-0 bg-white border border-gray-100 rounded-xl mt-2 shadow-xl z-50 overflow-hidden">
                                    {filteredSuggestions.map(p => (
                                        <div key={p.id} onClick={() => { handleAddMember(p.nombre); setAddSearchTerm(''); setShowSuggestions(false); }} className="px-4 py-3 hover:bg-gray-50 cursor-pointer border-b border-gray-50 flex items-center gap-3">
                                            <div style={{ backgroundColor: getAvatarColor(p.nombre) }} className="w-6 h-6 rounded-full flex items-center justify-center text-xs text-white font-bold">{p.nombre.charAt(0)}</div>
                                            <span className="text-gray-700 font-medium">{p.nombre}</span>
                                        </div>
                                    ))}
                                    <div onClick={() => { handleAddMember(addSearchTerm); setAddSearchTerm(''); setShowSuggestions(false); }} className="px-4 py-3 bg-purple-50 hover:bg-purple-100 cursor-pointer flex items-center gap-3 text-purple-700">
                                        <i className="fas fa-pen text-xs"></i><span className="font-semibold">Crear nuevo: "{addSearchTerm}"</span>
                                    </div>
                                </div>
                            )}
                        </div>
                        <button onClick={() => handleAddMember(addSearchTerm)} disabled={!addSearchTerm.trim()} className="bg-gray-900 text-white px-4 py-2 rounded-lg font-bold text-sm hover:bg-gray-800 disabled:bg-gray-300 transition-colors">Agregar</button>
                    </div>
                )}
            </div>

            {/* --- CONTENIDO PRINCIPAL --- */}
            {loading ? (
                <div style={{ textAlign: 'center', padding: '5rem 0', color: '#9ca3af' }}>Cargando...</div>
            ) : (
                <div className="bg-white rounded-lg shadow-md overflow-hidden">

                    {/* VISTA MÓVIL (Tarjeta) */}
                    {isMobile ? (
                        <div style={{ display: 'flex', flexDirection: 'column' }}>
                            {filteredMembers.map((m) => {
                                const pName = m.publicador_nombre;
                                const report = reports[pName];
                                const hasReport = report !== undefined;
                                const statusColor = hasReport ? '#10b981' : '#9ca3af'; // Verde o Gris

                                return (
                                    <div 
                                        key={m.id}
                                        onClick={() => setEditingMember(m)}
                                        style={{
                                            display: 'flex', alignItems: 'center', padding: '16px',
                                            borderBottom: '1px solid #f3f4f6', cursor: 'pointer',
                                            backgroundColor: 'white', position: 'relative'
                                        }}
                                    >
                                        {/* Barra lateral de color */}
                                        <div style={{
                                            position: 'absolute', left: 0, top: 0, bottom: 0, width: '5px',
                                            backgroundColor: statusColor
                                        }}></div>

                                        {/* Avatar */}
                                        <div style={{
                                            width: '42px', height: '42px', borderRadius: '50%',
                                            backgroundColor: getAvatarColor(pName), color: 'white',
                                            display: 'flex', alignItems: 'center', justifyContent: 'center',
                                            fontWeight: 'bold', fontSize: '1.1rem', marginRight: '15px', marginLeft: '10px'
                                        }}>
                                            {pName.charAt(0)}
