                                        {/* Info */}
                                        <div style={{ flex: 1 }}>
                                            <div style={{ fontWeight: 'bold', color: '#1f2937', fontSize: '1rem' }}>{pName}</div>
                                            <div style={{ fontSize: '0.85rem', color: hasReport ? '#059669' : '#6b7280', fontWeight: hasReport ? '600' : '400' }}>
                                                {hasReport ? `Informó: ${report.horas}h` : 'Pendiente'}
                                            </div>
                                        </div>

                                        {/* Arrow */}
                                        <div style={{ color: '#d1d5db' }}><i className="fas fa-chevron-right"></i></div>
                                    </div>
