                                        <div style={{
                                            width: '42px', height: '42px', borderRadius: '50%',
                                            backgroundColor: getAvatarColor(pName), color: 'white',
                                            display: 'flex', alignItems: 'center', justifyContent: 'center',
                                            fontWeight: 'bold', fontSize: '1.1rem', marginRight: '15px', marginLeft: '12px',
