                    ) : (
                        /* VISTA ESCRITORIO (Tabla) */
                        <div className="hidden lg:grid lg:grid-cols-12 lg:gap-4 lg:p-4 lg:items-start border-b border-slate-100 hover:bg-slate-50 transition-colors">
                            {/* ... Header and Rows ... */}
                            <div className="col-span-12 p-4 text-center text-gray-500">
                                Vista de escritorio activa (Tabla completa con inputs en línea)
                            </div>
                            {filteredMembers.map((m, index) => (
                                <div key={m.id} className="col-span-12 grid grid-cols-12 gap-4 items-center border-b p-2">
                                    <div className="col-span-3 font-bold">{m.publicador_nombre}</div>
                                    <div className="col-span-2"><input type="number" placeholder="Horas" className="border rounded p-1 w-full" 
                                        value={reports[m.publicador_nombre]?.horas || ''} 
                                        onChange={(e) => handleReportChange(m.publicador_nombre, 'horas', e.target.value)} />
                                    </div>
                                    <div className="col-span-2"><input type="text" placeholder="Notas" className="border rounded p-1 w-full"
                                        value={reports[m.publicador_nombre]?.notas || ''} 
                                        onChange={(e) => handleReportChange(m.publicador_nombre, 'notas', e.target.value)} />
                                    </div>
                                    <div className="col-span-3 flex gap-2">
                                        <button className="bg-blue-600 text-white px-3 py-1 rounded" onClick={() => handleSaveRow(m.publicador_nombre)}>Guardar</button>
                                        <button className="text-red-500" onClick={() => handleDeleteMember(m.id, m.publicador_nombre)}><i className="fas fa-trash"></i></button>
                                    </div>
                                </div>
                            ))}
                        </div>
                    )}

                    {filteredMembers.length === 0 && (
                        <div style={{ padding: '4rem 2rem', textAlign: 'center', color: '#9ca3af' }}>
                            <div className="w-20 h-20 bg-gray-100 rounded-full flex items-center justify-center mx-auto mb-4">
                                <i className="fas fa-user-plus text-3xl text-gray-300"></i>
                            </div>
                            <h3 className="text-lg font-bold text-gray-600">Grupo vacío</h3>
                            <p className="text-sm mt-1">Utiliza el buscador de arriba para agregar publicadores.</p>
                        </div>
                    )}
                </div>
            )}

            {/* Status Toast */}
            {statusMessage && (
                <div style={{ position: 'fixed', bottom: '20px', right: '20px', backgroundColor: '#10b981', color: 'white', padding: '12px 20px', borderRadius: '12px', boxShadow: '0 10px 25px -5px rgba(0,0,0,0.2)', fontWeight: 'bold', zIndex: 1000, display: 'flex', alignItems: 'center', gap: '10px' }}>
                    <i className="fas fa-check-circle"></i>
                    {statusMessage.text}
                </div>
            )}
        </div>
    );
};

