                text += `✅ ${m.publicador_nombre}: ${hours}${studies}\n`;
            } else {
                text += `⏳ ${m.publicador_nombre}\n`;
            }
        });

        navigator.clipboard.writeText(text).then(() => {
            setStatusMessage({ text: 'Informe copiado al portapapeles', type: 'success' });
            setTimeout(() => setStatusMessage(null), 3000);
        });
