                                        position: 'absolute', cursor: 'pointer', top: 0, left: 0, right: 0, bottom: 0,
                                        backgroundColor: hasReport ? '#2563eb' : '#e5e7eb', transition: '.4s', borderRadius: '34px'
                                    }}></span>
