                            <th style={{ border: '1px solid #999', padding: '6px', textAlign: 'center', width: '15%' }}>Cursos</th>
                            <th style={{ border: '1px solid #999', padding: '6px', textAlign: 'left', width: '30%' }}>Observaciones</th>
                        </tr>
                    </thead>
                    <tbody>
                        {filteredMembers.map((m) => {
                            const r = reports[m.publicador_nombre];
                            return (
                                <tr key={m.id}>
                                    <td style={{ border: '1px solid #999', padding: '6px' }}>{m.publicador_nombre}</td>
                                    <td style={{ border: '1px solid #999', padding: '6px', textAlign: 'center' }}>
                                        {r ? (r.horas === 0 ? 'Predicó' : r.horas) : '-'}
                                    </td>
                                    <td style={{ border: '1px solid #999', padding: '6px', textAlign: 'center' }}>
                                        {r && r.estudios ? r.estudios : '-'}
                                    </td>
                                    <td style={{ border: '1px solid #999', padding: '6px', fontSize: '9pt', color: '#444' }}>
                                        {r?.notas || ''}
                                    </td>
                                </tr>
                            );
                        })}
                    </tbody>
                </table>
                <div style={{ marginTop: '10mm', fontSize: '9pt', color: '#666', borderTop: '1px solid #ccc', paddingTop: '2mm' }}>
                    Generado el {new Date().toLocaleDateString('es-ES')}
                </div>
            </div>

            {/* Status Toast */}
            {statusMessage && (
                <div style={{ 
                    position: 'fixed', bottom: '20px', right: '20px', 
                    backgroundColor: statusMessage.type === 'error' ? '#ef4444' : statusMessage.type === 'info' ? '#3b82f6' : '#10b981', 
                    color: 'white', padding: '12px 20px', borderRadius: '12px', 
                    boxShadow: '0 10px 25px -5px rgba(0,0,0,0.2)', fontWeight: 'bold', zIndex: 1000, 
                    display: 'flex', alignItems: 'center', gap: '10px' 
                }}>
                    <i className={`fas ${statusMessage.type === 'error' ? 'fa-exclamation-circle' : statusMessage.type === 'info' ? 'fa-spinner fa-spin' : 'fa-check-circle'}`}></i>
                    {statusMessage.text}
                </div>
            )}
        </div>
    );
};

