            </div>

            {/* Status Toast */}
            {statusMessage && (
                <div style={{ 
                    position: 'fixed', bottom: '20px', right: '20px', 
                    backgroundColor: statusMessage.type === 'error' ? '#ef4444' : statusMessage.type === 'info' ? '#3b82f6' : '#10b981', 
