                <div style={{ backgroundColor: '#1e293b', padding: '8px', borderRadius: '14px', display: 'flex', boxShadow: '0 4px 6px rgba(0,0,0,0.1)' }}>
                    <input type="text" value={addSearchTerm} onChange={e => setAddSearchTerm(e.target.value)} placeholder="Añadir nuevo publicador al grupo..." style={{ flex: 1, background: 'transparent', border: 'none', color: 'white', outline: 'none', padding: '10px 15px', fontSize: '0.95rem' }} />
                    <button onClick={() => handleAddMember(addSearchTerm)} style={{ color: 'white', background: '#3b82f6', border: 'none', borderRadius: '10px', padding: '0 20px', fontWeight: 'bold' }}>Añadir</button>
                </div>
            </div>

            {loading ? <div style={{ textAlign: 'center', padding: '3rem', color: '#64748b' }}><i className="fas fa-spinner fa-spin fa-2x"></i><br/>Cargando...</div> : (
                <div className="bg-white rounded-2xl shadow-sm border border-slate-200 overflow-hidden">
                    {members.map(m => (
                        <div key={m.identificacion} onClick={() => setEditingMember(m)} style={{ display: 'flex', alignItems: 'center', padding: '18px 20px', borderBottom: '1px solid #f1f5f9', cursor: 'pointer', transition: 'background 0.2s' }}>
                            <div style={{ width: '44px', height: '44px', borderRadius: '50%', backgroundColor: getAvatarColor(m.publicador_nombre), color: 'white', display: 'flex', alignItems: 'center', justifyContent: 'center', fontWeight: 'bold', marginRight: '18px', fontSize: '1.1rem' }}>{m.publicador_nombre.charAt(0)}</div>
                            <div style={{ flex: 1 }}>
                                <div style={{ fontWeight: '700', color: '#334155', fontSize: '1rem' }}>{m.publicador_nombre}</div>
                                <div style={{ fontSize: '0.85rem', color: reports[m.publicador_nombre] ? '#059669' : '#94a3b8', fontWeight: reports[m.publicador_nombre] ? '700' : '400' }}>
                                    {reports[m.publicador_nombre] ? `✔ Informe: ${reports[m.publicador_nombre].horas}h` : '⌛ Pendiente'}
                                </div>
                            </div>
                            <i className="fas fa-chevron-right" style={{ color: '#cbd5e1' }}></i>
