                    onClose={() => setEditingMember(null)} 
                    onReportChange={handleReportChange} 
                    onVisitChange={(name, f, v) => setVisits(prev => ({ ...prev, [name]: { ...(prev[name] || { date: '', notes: '' }), [f]: v } }))} 
                    onSave={handleSaveRow} 
                    onDelete={handleDeleteMember} 
                    onRemoveReport={name => setReports(prev => { const n = {...prev}; delete n[name]; return n; })} 
                />
            )}

            {/* --- Hidden Professional PDF Template --- */}
            <div ref={printRef} style={{ display: 'none' }}>
                <div style={{ width: '210mm', minHeight: '297mm', padding: '18mm', fontFamily: 'Arial, sans-serif', color: '#000', boxSizing: 'border-box', backgroundColor: '#fff' }}>
                    {/* Header Doc */}
                    <div style={{ borderBottom: '2px solid #1e3a8a', paddingBottom: '10px', marginBottom: '20px', display: 'flex', justifyContent: 'space-between', alignItems: 'flex-end' }}>
                        <div>
                            <h1 style={{ margin: 0, fontSize: '18pt', color: '#1e3a8a', fontWeight: 'bold' }}>INFORME DE ACTIVIDAD DEL GRUPO</h1>
                            <p style={{ margin: 0, fontSize: '11pt', color: '#475569' }}>{groups.find(g => g.id === selectedGroupId)?.nombre} • Congregación Central</p>
                        </div>
                        <div style={{ textAlign: 'right' }}>
                            <p style={{ margin: 0, fontSize: '12pt', fontWeight: 'bold', textTransform: 'capitalize' }}>{formatMonth(currentMonth)}</p>
                        </div>
                    </div>

                    {/* Resumen Box */}
                    <div style={{ display: 'flex', gap: '15px', marginBottom: '25px' }}>
                        <div style={{ flex: 1, border: '1px solid #e2e8f0', borderRadius: '8px', padding: '12px', textAlign: 'center' }}>
                            <span style={{ display: 'block', fontSize: '8pt', color: '#64748b', textTransform: 'uppercase', fontWeight: 'bold' }}>Total Publicadores</span>
                            <span style={{ fontSize: '16pt', fontWeight: 'bold' }}>{members.length}</span>
                        </div>
                        <div style={{ flex: 1, border: '1px solid #e2e8f0', borderRadius: '8px', padding: '12px', textAlign: 'center' }}>
                            <span style={{ display: 'block', fontSize: '8pt', color: '#64748b', textTransform: 'uppercase', fontWeight: 'bold' }}>Informes Recibidos</span>
                            <span style={{ fontSize: '16pt', fontWeight: 'bold' }}>{totalInformes}</span>
                        </div>
                        <div style={{ flex: 1, border: '1px solid #e2e8f0', borderRadius: '8px', padding: '12px', textAlign: 'center' }}>
                            <span style={{ display: 'block', fontSize: '8pt', color: '#64748b', textTransform: 'uppercase', fontWeight: 'bold' }}>Total Horas</span>
                            <span style={{ fontSize: '16pt', fontWeight: 'bold' }}>{totalHoras}</span>
                        </div>
                    </div>

                    {/* Detailed Table */}
                    <table style={{ width: '100%', borderCollapse: 'collapse', fontSize: '10pt' }}>
                        <thead>
                            <tr style={{ backgroundColor: '#f8fafc' }}>
                                <th style={{ border: '0.5pt solid #cbd5e1', padding: '10px', textAlign: 'left', width: '45%' }}>NOMBRE DEL PUBLICADOR</th>
                                <th style={{ border: '0.5pt solid #cbd5e1', padding: '10px', textAlign: 'center', width: '15%' }}>HORAS</th>
                                <th style={{ border: '0.5pt solid #cbd5e1', padding: '10px', textAlign: 'center', width: '40%' }}>OBSERVACIONES</th>
                            </tr>
                        </thead>
                        <tbody>
                            {members.map(m => {
                                const r = reports[m.publicador_nombre];
                                return (
                                    <tr key={m.identificacion}>
                                        <td style={{ border: '0.5pt solid #cbd5e1', padding: '8px 10px', fontWeight: 'bold' }}>{m.publicador_nombre}</td>
                                        <td style={{ border: '0.5pt solid #cbd5e1', padding: '8px 10px', textAlign: 'center' }}>{r ? (r.horas === 0 ? 'Participó' : r.horas) : '—'}</td>
                                        <td style={{ border: '0.5pt solid #cbd5e1', padding: '8px 10px', fontSize: '9pt', color: '#334155' }}>{r?.notas || ''}</td>
                                    </tr>
                                );
                            })}
                        </tbody>
                    </table>

                    {/* Footer Doc */}
                    <div style={{ marginTop: 'auto', paddingTop: '30px', display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
                        <div style={{ fontSize: '8pt', color: '#94a3b8' }}>
                            Documento generado digitalmente el {new Date().toLocaleDateString('es-ES', { day: '2-digit', month: 'long', year: 'numeric' })}
                        </div>
                        <div style={{ borderTop: '1px solid #000', width: '180px', textAlign: 'center', paddingTop: '5px' }}>
                            <span style={{ fontSize: '9pt', fontWeight: 'bold' }}>Firma del Superintendente</span>
                        </div>
                    </div>
                </div>
            </div>

            {statusMessage && (
                <div style={{ position: 'fixed', bottom: '20px', right: '20px', backgroundColor: statusMessage.type === 'error' ? '#ef4444' : statusMessage.type === 'info' ? '#3b82f6' : '#10b981', color: 'white', padding: '12px 25px', borderRadius: '12px', fontWeight: 'bold', zIndex: 1000, boxShadow: '0 10px 15px -3px rgba(0,0,0,0.1)' }}>
                    {statusMessage.type === 'info' && <i className="fas fa-spinner fa-spin" style={{marginRight: '8px'}}></i>}
                    {statusMessage.text}
                </div>
            )}
        </div>
    );
};

export default GrupoCongregacion;

import React, { useState, useEffect, useRef } from 'react';
import { supabase } from '../lib/supabase';

// Librerías externas
declare const html2canvas: any;
declare const html2pdf: any;

type Publisher = {
    identificacion: number;
    nombre: string;
};

type Group = {
    id: number;
    nombre: string;
};

type GroupMember = {
    identificacion: number;
    grupo_id: number;
    publicador_nombre: string;
};

type MinistryReport = {
    horas: number | '';
    estudios: number | '';
    notas?: string;
};

type VisitData = {
    date: string;
    notes: string;
};

type ReportsMap = Record<string, MinistryReport>;
type VisitsMap = Record<string, VisitData>;

const getAvatarColor = (name: string) => {
    const colors = ['#ef4444', '#f97316', '#f59e0b', '#22c55e', '#14b8a6', '#3b82f6', '#6366f1', '#a855f7', '#ec4899'];
    let hash = 0;
    for (let i = 0; i < name.length; i++) hash = name.charCodeAt(i) + ((hash << 5) - hash);
    return colors[Math.abs(hash) % colors.length];
};

const formatMonth = (dateStr: string) => {
    if (!dateStr) return '';
    const [year, month] = dateStr.split('-');
    const date = new Date(parseInt(year), parseInt(month) - 1);
    return date.toLocaleDateString('es-ES', { month: 'long', year: 'numeric' });
};

// --- MODAL COMPONENT ---
const EditMemberModal: React.FC<{
    member: GroupMember;
    reportEntry: MinistryReport | undefined;
    visitData: VisitData;
    onClose: () => void;
    onReportChange: (name: string, field: keyof MinistryReport, value: string | number) => void;
    onVisitChange: (name: string, field: keyof VisitData, value: string) => void;
    onSave: (name: string) => void;
    onDelete: (id: number, name: string) => void;
    onRemoveReport: (name: string) => void;
}> = ({ member, reportEntry, visitData, onClose, onReportChange, onVisitChange, onSave, onDelete, onRemoveReport }) => {
    const pName = member.publicador_nombre;
    const hasReport = reportEntry !== undefined;

    let visitLabel = 'N/A';
    let visitColor = '#9ca3af';
    let visitBg = '#f3f4f6';
    if (visitData.date) {
        const daysSince = (new Date().getTime() - new Date(visitData.date).getTime()) / (1000 * 3600 * 24);
        if (daysSince < 90) { visitLabel = 'Al día'; visitColor = '#15803d'; visitBg = '#dcfce7'; } 
        else if (daysSince < 180) { visitLabel = 'Atención'; visitColor = '#b45309'; visitBg = '#fef3c7'; } 
        else { visitLabel = 'Urgente'; visitColor = '#b91c1c'; visitBg = '#fee2e2'; }
    }

    return (
        <div style={{ position: 'fixed', top: 0, left: 0, right: 0, bottom: 0, backgroundColor: 'rgba(0,0,0,0.6)', zIndex: 99999, display: 'flex', alignItems: 'flex-end', justifyContent: 'center' }} onClick={onClose}>
            <div style={{ backgroundColor: 'white', width: '100%', maxWidth: '500px', borderTopLeftRadius: '20px', borderTopRightRadius: '20px', overflow: 'hidden', display: 'flex', flexDirection: 'column', maxHeight: '90vh' }} onClick={e => e.stopPropagation()}>
                <div style={{ padding: '15px 20px', borderBottom: '1px solid #eee', display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
                    <div style={{ display: 'flex', alignItems: 'center', gap: '15px' }}>
                        <div style={{ width: '40px', height: '40px', borderRadius: '50%', backgroundColor: getAvatarColor(pName), color: 'white', display: 'flex', alignItems: 'center', justifyContent: 'center', fontWeight: 'bold' }}>{pName.charAt(0)}</div>
                        <h3 style={{ margin: 0, color: '#1f2937' }}>{pName}</h3>
                    </div>
                    <button onClick={onClose} style={{ border: 'none', background: 'transparent', fontSize: '1.5rem', cursor: 'pointer' }}>&times;</button>
                </div>
                <div style={{ padding: '20px', overflowY: 'auto', backgroundColor: '#f9fafb' }}>
                    <div style={{ backgroundColor: 'white', padding: '20px', borderRadius: '16px', marginBottom: '15px', boxShadow: '0 2px 8px rgba(0,0,0,0.04)' }}>
                        <div style={{ display: 'flex', justifyContent: 'space-between', marginBottom: '15px' }}>
                            <h4 style={{ margin: 0, color: '#2563eb' }}><i className="fas fa-file-alt"></i> Informe Mensual</h4>
                            <input type="checkbox" checked={hasReport} onChange={(e) => e.target.checked ? onReportChange(pName, 'horas', 0) : onRemoveReport(pName)} />
                        </div>
                        {hasReport && (
                            <div style={{ display: 'flex', flexDirection: 'column', gap: '15px' }}>
                                <div style={{ display: 'flex', gap: '15px' }}>
                                    <div style={{ flex: 1 }}>
                                        <label style={{ display: 'block', fontSize: '0.75rem', fontWeight:'700', color: '#64748b' }}>Horas</label>
                                        <input type="number" step="0.5" value={reportEntry?.horas || ''} onChange={(e) => onReportChange(pName, 'horas', e.target.value)} style={{ width: '100%', padding: '10px', borderRadius: '8px', border: '1px solid #e2e8f0' }} placeholder="0" />
                                    </div>
                                    <div style={{ flex: 1 }}>
                                        <label style={{ display: 'block', fontSize: '0.75rem', fontWeight:'700', color: '#64748b' }}>Cursos Bíblicos</label>
                                        <input type="number" value={reportEntry?.estudios || ''} onChange={(e) => onReportChange(pName, 'estudios', e.target.value)} style={{ width: '100%', padding: '10px', borderRadius: '8px', border: '1px solid #e2e8f0' }} placeholder="0" />
                                    </div>
                                </div>
                                <input type="text" value={reportEntry?.notas || ''} onChange={(e) => onReportChange(pName, 'notas', e.target.value)} style={{ width: '100%', padding: '10px', borderRadius: '8px', border: '1px solid #e2e8f0' }} placeholder="Observaciones..." />
                            </div>
                        )}
                    </div>
                    <div style={{ backgroundColor: 'white', padding: '20px', borderRadius: '16px', boxShadow: '0 2px 8px rgba(0,0,0,0.04)' }}>
                        <div style={{ display: 'flex', justifyContent: 'space-between', marginBottom: '15px' }}>
                            <h4 style={{ margin: 0, color: '#ec4899' }}><i className="fas fa-heart"></i> Pastoreo</h4>
                            <span style={{ backgroundColor: visitBg, color: visitColor, padding: '4px 10px', borderRadius: '20px', fontSize: '0.75rem' }}>{visitLabel}</span>
                        </div>
                        <input type="date" value={visitData.date} onChange={(e) => onVisitChange(pName, 'date', e.target.value)} style={{ width: '100%', padding: '10px', borderRadius: '8px', border: '1px solid #e2e8f0', marginBottom: '10px' }} />
                        <input type="text" value={visitData.notes} onChange={(e) => onVisitChange(pName, 'notes', e.target.value)} style={{ width: '100%', padding: '10px', borderRadius: '8px', border: '1px solid #e2e8f0' }} placeholder="Notas de visita..." />
                    </div>
                </div>
                <div style={{ padding: '15px 20px', borderTop: '1px solid #eee', display: 'flex', gap: '15px' }}>
                    <button onClick={() => { if(confirm('¿Eliminar publicador del grupo?')) onDelete(member.identificacion, pName); onClose(); }} style={{ padding: '12px', borderRadius: '10px', border: '1px solid #fee2e2', backgroundColor: '#fef2f2', color: '#ef4444' }}><i className="fas fa-trash-alt"></i></button>
                    <button onClick={() => { onSave(pName); onClose(); }} style={{ flex: 1, padding: '14px', borderRadius: '10px', border: 'none', backgroundColor: '#2563eb', color: 'white', fontWeight: 'bold' }}>Guardar</button>
                </div>
            </div>
        </div>
    );
};

const GrupoCongregacion: React.FC = () => {
    const [groups, setGroups] = useState<Group[]>([]);
    const [selectedGroupId, setSelectedGroupId] = useState<number | null>(null);
    const [members, setMembers] = useState<GroupMember[]>([]);
    const [masterPublishers, setMasterPublishers] = useState<Publisher[]>([]); 
    const [loading, setLoading] = useState(true);
    const [currentMonth, setCurrentMonth] = useState<string>('');
    const [reports, setReports] = useState<ReportsMap>({});
    const [visits, setVisits] = useState<VisitsMap>({});
    const [searchTerm, setSearchTerm] = useState(''); // Estado para búsqueda
    const [addSearchTerm, setAddSearchTerm] = useState(''); 
    const [statusMessage, setStatusMessage] = useState<{ text: string; type: 'success' | 'error' | 'info' } | null>(null);
    const [editingMember, setEditingMember] = useState<GroupMember | null>(null);
    const printRef = useRef<HTMLDivElement>(null);

    useEffect(() => {
        const now = new Date();
        setCurrentMonth(`${now.getFullYear()}-${String(now.getMonth() + 1).padStart(2, '0')}`);
        fetchGroups();
        fetchMasterPublishers();
    }, []);

    const fetchGroups = async () => {
        const { data } = await supabase.from('grupos').select('*').order('nombre');
        if (data) {
            setGroups(data);
            if (data.length > 0) setSelectedGroupId(data[0].id);
        }
    };

    const fetchMasterPublishers = async () => {
        const { data } = await supabase.from('publicadores').select('identificacion, nombre').order('nombre');
        if (data) setMasterPublishers(data);
    };

    const fetchMembers = async () => {
        if (!selectedGroupId) return;
        setLoading(true);
        const { data } = await supabase.from('integrantes_grupo').select('*').eq('grupo_id', selectedGroupId).order('publicador_nombre');
        setMembers(data || []);
        setLoading(false);
    };

    useEffect(() => { fetchMembers(); }, [selectedGroupId]);

    useEffect(() => {
        if (!currentMonth || members.length === 0) return;
        const fetchData = async () => {
            const memberNames = members.map(m => m.publicador_nombre);
            const { data: reportsData } = await supabase.from('informes_ministerio').select('publicador_nombre, horas, notas').eq('mes', currentMonth).in('publicador_nombre', memberNames);
            const newReports: ReportsMap = {};
            if (reportsData) reportsData.forEach((r: any) => { newReports[r.publicador_nombre] = { horas: r.horas, estudios: '', notas: r.notas || '' }; });
            setReports(newReports);

            const { data: visitsData } = await supabase.from('visitas_pastoral').select('publicador_nombre, fecha_visita, notas').in('publicador_nombre', memberNames);
            const newVisits: VisitsMap = {};
            if (visitsData) visitsData.forEach((v: any) => { newVisits[v.publicador_nombre] = { date: v.fecha_visita || '', notes: v.notas || '' }; });
            setVisits(newVisits);
        };
        fetchData();
    }, [currentMonth, members]);

    const handleAddMember = async (name: string) => { 
        if (!selectedGroupId || !name.trim()) return;
        const { error } = await supabase.from('integrantes_grupo').insert([{ grupo_id: selectedGroupId, publicador_nombre: name.trim() }]);
        if(!error) { setAddSearchTerm(''); fetchMembers(); }
    };

    const handleDeleteMember = async (id: number) => {
        await supabase.from('integrantes_grupo').delete().eq('identificacion', id);
        fetchMembers();
    };

    const handleReportChange = (name: string, field: keyof MinistryReport, value: string | number) => {
        setReports(prev => {
            const current = prev[name] || { horas: '', estudios: '', notas: '' };
            return { ...prev, [name]: { ...current, [field]: (field === 'horas' || field === 'estudios') ? (value === '' ? '' : Number(value)) : value } };
        });
    };

    const handleSaveRow = async (publisherName: string) => {
        setStatusMessage({ text: 'Guardando...', type: 'info' });
        try {
            const reportEntry = reports[publisherName];
            const { data: existing } = await supabase.from('informes_ministerio').select('identificacion').eq('publicador_nombre', publisherName).eq('mes', currentMonth).maybeSingle();
            const payload = { publicador_nombre: publisherName, mes: currentMonth, horas: reportEntry?.horas || 0, notas: reportEntry?.notas || '' };
            if (reportEntry) {
                if (existing) await supabase.from('informes_ministerio').update(payload).eq('identificacion', existing.identificacion);
                else await supabase.from('informes_ministerio').insert([payload]);
            } else if (existing) {
                await supabase.from('informes_ministerio').delete().eq('identificacion', existing.identificacion);
            }
            const v = visits[publisherName];
            if (v && (v.date || v.notes)) {
                const { data: existV } = await supabase.from('visitas_pastoral').select('identificacion').eq('publicador_nombre', publisherName).maybeSingle();
                const vPayload = { publicador_nombre: publisherName, fecha_visita: v.date || null, notas: v.notes || '' };
                if (existV) await supabase.from('visitas_pastoral').update(vPayload).eq('identificacion', existV.identificacion);
                else await supabase.from('visitas_pastoral').insert([vPayload]);
            }
            setStatusMessage({ text: 'Cambios guardados', type: 'success' });
            setTimeout(() => setStatusMessage(null), 2000);
        } catch (e) {
            setStatusMessage({ text: 'Error al guardar', type: 'error' });
        }
    };

    const handleSharePDF = () => {
        if (!printRef.current) return;
        setStatusMessage({ text: 'Generando archivo...', type: 'info' });

        const element = printRef.current.cloneNode(true) as HTMLElement;
        element.style.display = 'block'; 
        element.style.position = 'absolute'; 
        element.style.top = '0'; 
        element.style.left = '0'; 
        element.style.width = '210mm'; 
        element.style.zIndex = '-9999'; 
        element.style.backgroundColor = 'white';
        document.body.appendChild(element);

        const groupName = groups.find(g => g.id === selectedGroupId)?.nombre || 'Grupo';
        const opt = { 
            margin: 0, 
            filename: `Informe_${groupName}_${currentMonth}.pdf`, 
            image: { type: 'jpeg', quality: 0.98 }, 
            html2canvas: { scale: 3, useCORS: true, letterRendering: true }, 
            jsPDF: { unit: 'mm', format: 'a4', orientation: 'portrait' } 
        };

        html2pdf().from(element).set(opt).save().then(() => {
            document.body.removeChild(element);
            setStatusMessage({ text: 'PDF Descargado', type: 'success' });
            setTimeout(() => setStatusMessage(null), 2000);
        }).catch(() => {
            setStatusMessage({ text: 'Error en generación', type: 'error' });
        });
    };

    // Filtro para mostrar en lista y en PDF
    const filteredMembers = members.filter(m => 
        m.publicador_nombre.toLowerCase().includes(searchTerm.toLowerCase())
    );

    const totalInformes = Object.keys(reports).length;
    const totalHoras = Object.values(reports).reduce((acc: number, r: MinistryReport) => acc + (Number(r.horas) || 0), 0);

    return (
        <div className="container mx-auto px-4 py-8 bg-slate-50 min-h-screen">
            <h1 style={{ fontSize: '1.8rem', fontWeight: '800', textAlign: 'center', marginBottom: '1.5rem', color: '#1e40af', textTransform: 'uppercase', letterSpacing: '1px' }}>Gestión de Grupo</h1>

            <div style={{ display: 'flex', flexDirection: 'column', gap: '20px', marginBottom: '25px' }}>
                <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
