    useEffect(() => {
        const handleResize = () => setIsMobile(window.innerWidth < 1024);
        window.addEventListener('resize', handleResize);

        const now = new Date();
        const yyyy = now.getFullYear();
        const mm = String(now.getMonth() + 1).padStart(2, '0');
        setCurrentMonth(`${yyyy}-${mm}`);

        fetchGroups();
        fetchMasterPublishers();

        const handleClickOutside = (event: MouseEvent) => {
            if (suggestionsRef.current && !suggestionsRef.current.contains(event.target as Node)) {
                setShowSuggestions(false);
            }
        };
        document.addEventListener('mousedown', handleClickOutside);
        return () => {
            document.removeEventListener('mousedown', handleClickOutside);
            window.removeEventListener('resize', handleResize);
        }
    }, []);

    // Load Data Functions
    const fetchGroups = async () => {
        const { data, error } = await supabase.from('grupos').select('*').order('nombre');
        if (data) {
            setGroups(data);
            if (data.length > 0 && !selectedGroupId) {
                const defaultGroup = data.find(g => g.nombre.includes('5')) || data[0];
                setSelectedGroupId(defaultGroup.id);
            }
        }
    };

    const fetchMasterPublishers = async () => {
        const { data } = await supabase.from('publicadores').select('id, nombre').order('nombre');
        if (data) setMasterPublishers(data);
    };

    const fetchMembers = async () => {
        if (!selectedGroupId) return;
        setLoading(true);
        const { data } = await supabase.from('miembros_grupo').select('*').eq('grupo_id', selectedGroupId).order('publicador_nombre');
        setMembers(data || []);
        setLoading(false);
    };

    useEffect(() => { fetchMembers(); }, [selectedGroupId]);

    useEffect(() => {
        if (!currentMonth || members.length === 0) return;
        const fetchData = async () => {
            const memberNames = members.map(m => m.publicador_nombre);
            if (memberNames.length === 0) { setReports({}); setVisits({}); return; }

            const { data: reportsData } = await supabase.from('informes_ministerio').select('publicador_nombre, horas, notas').eq('mes', currentMonth).in('publicador_nombre', memberNames);
            const newReports: ReportsMap = {};
            if (reportsData) reportsData.forEach((r: any) => { newReports[r.publicador_nombre] = { horas: r.horas, estudios: '', notas: r.notas || '' }; });
            setReports(newReports);

            const { data: visitsData } = await supabase.from('visitas_pastoral').select('publicador_nombre, fecha_visita, notas').in('publicador_nombre', memberNames);
            const newVisits: VisitsMap = {};
            if (visitsData) visitsData.forEach((v: any) => { newVisits[v.publicador_nombre] = { date: v.fecha_visita, notes: v.notas || '' }; });
            setVisits(newVisits);
        };
        fetchData();
    }, [currentMonth, members]);

    const handleCreateGroup = async () => {
        if (!newGroupName.trim()) return;
        const { data, error } = await supabase.from('grupos').insert([{ nombre: newGroupName.trim() }]).select();
        if (!error && data) {
            setGroups(prev => [...prev, data[0]].sort((a,b) => a.nombre.localeCompare(b.nombre)));
            setSelectedGroupId(data[0].id);
            setIsCreatingGroup(false);
            setNewGroupName('');
        }
    };

    const handleAddMember = async (name: string) => { 
        if (!selectedGroupId || !name.trim()) return;
        const { error } = await supabase.from('miembros_grupo').insert([{ grupo_id: selectedGroupId, publicador_nombre: name.trim() }]);
        if(!error) { setAddSearchTerm(''); fetchMembers(); }
    };

    const handleDeleteMember = async (id: number, name: string) => {
        const { error } = await supabase.from('miembros_grupo').delete().eq('id', id);
        if (!error) { fetchMembers(); if(editingMember?.id === id) setEditingMember(null); }
    };

    const handleReportChange = (name: string, field: keyof MinistryReport, value: string | number) => {
        setReports(prev => {
            const currentEntry = prev[name] || { horas: '', estudios: '', notas: '' };
            const newValue = (field === 'horas' || field === 'estudios') ? (value === '' ? '' : Number(value)) : value;
            return { ...prev, [name]: { ...currentEntry, [field]: newValue } };
        });
    };

    const handleRemoveReport = (name: string) => {
        setReports(prev => { const next = { ...prev }; delete next[name]; return next; });
    };

    const handleVisitChange = (name: string, field: keyof VisitData, value: string) => {
        setVisits(prev => {
            const currentEntry = prev[name] || { date: '', notes: '' };
            return { ...prev, [name]: { ...currentEntry, [field]: value } };
        });
    };

    const handleSaveRow = async (publisherName: string) => {
        setStatusMessage({ text: 'Guardando...', type: 'info' });
        try {
            const reportEntry = reports[publisherName];
            const { data: existingReport } = await supabase.from('informes_ministerio').select('id').eq('publicador_nombre', publisherName).eq('mes', currentMonth).maybeSingle();
            const reportData = { publicador_nombre: publisherName, mes: currentMonth, horas: reportEntry?.horas === '' ? 0 : reportEntry?.horas, notas: reportEntry?.notas || '' };

            if (reportEntry) {
                if (existingReport) await supabase.from('informes_ministerio').update(reportData).eq('id', existingReport.id);
                else await supabase.from('informes_ministerio').insert([reportData]);
            } else if (existingReport) {
                await supabase.from('informes_ministerio').delete().eq('id', existingReport.id);
            }

            const visitData = visits[publisherName];
            if (visitData && (visitData.date || visitData.notes)) {
                const { data: existingVisit } = await supabase.from('visitas_pastoral').select('id').eq('publicador_nombre', publisherName).maybeSingle();
                const visitPayload = { publicador_nombre: publisherName, fecha_visita: visitData.date, notas: visitData.notes };
                if (existingVisit) await supabase.from('visitas_pastoral').update(visitPayload).eq('id', existingVisit.id);
                else await supabase.from('visitas_pastoral').insert([visitPayload]);
            }
            setStatusMessage({ text: 'Guardado', type: 'success' });
            setTimeout(() => setStatusMessage(null), 2000);
        } catch (error) {
            setStatusMessage({ text: 'Error', type: 'error' });
        }
    };

    const filteredMembers = members.filter(m => m.publicador_nombre.toLowerCase().includes(searchTerm.toLowerCase()));
    const filteredSuggestions = masterPublishers.filter(p => p.nombre.toLowerCase().includes(addSearchTerm.toLowerCase()) && !members.some(m => m.publicador_nombre === p.nombre)).slice(0, 6);

    const totalReports = members.length;
    const submittedReports = members.filter(m => reports[m.publicador_nombre] !== undefined).length;
    const pendingReports = totalReports - submittedReports;
    const totalHours = Object.values(reports).reduce((sum: number, r: MinistryReport) => sum + (Number(r.horas) || 0), 0);
    const totalStudies = Object.values(reports).reduce((sum: number, r: MinistryReport) => sum + (Number(r.estudios) || 0), 0);

    const handleSharePDF = () => {
        if (!printRef.current) return;
        setIsSharing(true);
        // Usar la plantilla oculta
        const element = printRef.current.cloneNode(true) as HTMLElement;
        element.style.display = 'block';
        element.style.position = 'absolute';
        element.style.left = '-9999px';
        element.style.top = '0';
        document.body.appendChild(element);

        const groupName = groups.find(g => g.id === selectedGroupId)?.nombre || 'Grupo';
        const opt = {
            margin: 0,
            filename: `Informe_${groupName}_${currentMonth}.pdf`,
            image: { type: 'jpeg', quality: 0.98 },
            html2canvas: { scale: 2, useCORS: true, letterRendering: true },
            jsPDF: { unit: 'mm', format: 'a4', orientation: 'portrait' }
        };

        html2pdf().from(element).set(opt).save().then(() => {
                document.body.removeChild(element);
                setIsSharing(false);
            }).catch(() => {
                if (document.body.contains(element)) document.body.removeChild(element);
                setIsSharing(false);
            });
    };

    const handleCopyText = () => {
        const groupName = groups.find(g => g.id === selectedGroupId)?.nombre || 'Grupo';
        let text = `*Informe ${groupName} - ${currentMonth}*\n`;
        text += `📊 Total: ${totalReports} | ✅ Entregados: ${submittedReports} | ⏳ Pendientes: ${pendingReports}\n\n`;
        filteredMembers.forEach(m => {
            const r = reports[m.publicador_nombre];
            if (r) text += `✅ ${m.publicador_nombre}: ${r.horas ? `${r.horas}h` : 'Predicó'}${r.estudios ? ` (${r.estudios} est.)` : ''}\n`;
            else text += `⏳ ${m.publicador_nombre}\n`;
        });
        navigator.clipboard.writeText(text).then(() => {
            setStatusMessage({ text: 'Copiado al portapapeles', type: 'success' });
            setTimeout(() => setStatusMessage(null), 3000);
        });
    };

    // Calculate members for 2 columns for PDF
    // Usamos 'members' (completo) para el PDF, a menos que se quiera imprimir lo filtrado. 
    // Usualmente el PDF es del reporte completo.
    const pdfMembers = members; 
    const midPoint = Math.ceil(pdfMembers.length / 2);
    const col1 = pdfMembers.slice(0, midPoint);
    const col2 = pdfMembers.slice(midPoint);

    return (
        <div className="container mx-auto px-4 py-8 group-container relative bg-[var(--bg-color)] min-h-screen">
            <h1 style={{ fontSize: '1.8rem', fontWeight: '800', textAlign: 'center', marginBottom: '1.5rem', color: 'var(--primary-color)', textTransform: 'uppercase', letterSpacing: '0.5px' }}>Gestión del Grupo</h1>

            {editingMember && (
                <EditMemberModal 
                    member={editingMember}
                    reportEntry={reports[editingMember.publicador_nombre]}
                    visitData={visits[editingMember.publicador_nombre] || { date: '', notes: '' }}
                    onClose={() => setEditingMember(null)}
                    onReportChange={handleReportChange}
                    onVisitChange={handleVisitChange}
                    onSave={handleSaveRow}
                    onDelete={handleDeleteMember}
                    onRemoveReport={handleRemoveReport}
                />
            )}

            <div style={{ display: 'flex', flexDirection: 'column', gap: '20px', marginBottom: '25px' }}>
                {/* Stats */}
                <div style={{ display: 'flex', gap: '10px', overflowX: 'auto', paddingBottom: '5px' }}>
                    {[{l:'Total',v:totalReports,c:'#3b82f6'}, {l:'Listos',v:submittedReports,c:'#10b981'}, {l:'Faltan',v:pendingReports,c:'#f97316'}].map((s,i)=>(
                        <div key={i} style={{ flex: 1, minWidth: '90px', backgroundColor: s.c, borderRadius: '12px', padding: '15px', color: 'white', textAlign: 'center', boxShadow: '0 4px 6px rgba(0,0,0,0.1)' }}>
                            <div style={{ fontSize: '0.8rem', textTransform: 'uppercase', opacity: 0.8, fontWeight: 'bold' }}>{s.l}</div>
                            <div style={{ fontSize: '1.8rem', fontWeight: '900', lineHeight: 1 }}>{s.v}</div>
                        </div>
                    ))}
                </div>

                <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                    <div style={{ backgroundColor: 'var(--card-bg-color)', padding: '12px', borderRadius: '12px', borderLeft: '5px solid #3b82f6', boxShadow: 'var(--shadow)', display: 'flex', alignItems: 'center', gap: '12px' }}>
                        <div style={{ flex: 1 }}>
                            <label style={{ display: 'block', fontSize: '0.75rem', fontWeight: '700', color: 'var(--text-color-light)', textTransform: 'uppercase' }}>Grupo</label>
                            <select value={selectedGroupId || ''} onChange={(e) => setSelectedGroupId(Number(e.target.value))} style={{ width: '100%', fontSize: '1.1rem', fontWeight: 'bold', color: 'var(--text-color)', background: 'transparent', border: 'none', outline: 'none' }}>
                                {groups.map(g => <option key={g.id} value={g.id}>{g.nombre}</option>)}
                            </select>
                        </div>
                        <button onClick={() => setIsCreatingGroup(!isCreatingGroup)} style={{ color: 'var(--text-color-light)', padding: '5px' }}><i className="fas fa-plus-circle text-xl"></i></button>
                    </div>
                    <div style={{ backgroundColor: 'var(--card-bg-color)', padding: '12px', borderRadius: '12px', borderLeft: '5px solid #8b5cf6', boxShadow: 'var(--shadow)', display: 'flex', alignItems: 'center', gap: '12px' }}>
                        <div style={{ flex: 1 }}>
                            <label style={{ display: 'block', fontSize: '0.75rem', fontWeight: '700', color: 'var(--text-color-light)', textTransform: 'uppercase' }}>Mes</label>
                            <input type="month" value={currentMonth} onChange={(e) => setCurrentMonth(e.target.value)} style={{ width: '100%', fontSize: '1rem', fontWeight: 'bold', color: 'var(--text-color)', background: 'transparent', border: 'none', outline: 'none' }} />
                        </div>
                    </div>
                </div>

                {isCreatingGroup && (
                    <div className="flex gap-2 animate-fadeIn p-4 bg-blue-50 rounded-xl border border-blue-100">
                        <input autoFocus type="text" placeholder="Nuevo grupo..." value={newGroupName} onChange={(e) => setNewGroupName(e.target.value)} className="flex-1 p-2 rounded-lg border border-blue-200 focus:outline-none" />
                        <button onClick={handleCreateGroup} className="bg-blue-600 text-white px-4 rounded-lg font-bold">Crear</button>
                    </div>
                )}

                {selectedGroupId && (
                    <div style={{ display: 'flex', gap: '10px' }}>
                        <button onClick={handleSharePDF} disabled={isSharing} style={{ flex: 1, backgroundColor: '#ef4444', color: 'white', padding: '12px', borderRadius: '12px', border: 'none', display: 'flex', flexDirection: 'column', alignItems: 'center', gap: '5px' }}>
                            <i className="fas fa-file-pdf text-xl"></i><span style={{ fontSize: '0.8rem', fontWeight: 'bold' }}>PDF A4</span>
                        </button>
                        <button onClick={handleCopyText} style={{ flex: 1, backgroundColor: '#64748b', color: 'white', padding: '12px', borderRadius: '12px', border: 'none', display: 'flex', flexDirection: 'column', alignItems: 'center', gap: '5px' }}>
                            <i className="fas fa-copy text-xl"></i><span style={{ fontSize: '0.8rem', fontWeight: 'bold' }}>Copiar</span>
                        </button>
                    </div>
                )}

                {selectedGroupId && (
                    <div style={{ backgroundColor: 'var(--card-bg-color)', padding: '5px', borderRadius: '12px', boxShadow: 'var(--shadow)', display: 'flex', alignItems: 'center', border: '1px solid var(--border-color)' }}>
                        <div style={{ padding: '10px', color: 'var(--text-color-light)' }}><i className="fas fa-search"></i></div>
                        <div style={{ flex: 1, position: 'relative' }}>
                            <input type="text" value={addSearchTerm} onChange={(e) => { setAddSearchTerm(e.target.value); setShowSuggestions(true); }} placeholder="Buscar o escribir nombre..." style={{ width: '100%', padding: '10px 0', backgroundColor: 'transparent', border: 'none', color: 'var(--text-color)', outline: 'none', fontWeight: '500' }} />
                            {showSuggestions && addSearchTerm && (
                                <div className="absolute top-full left-0 right-0 bg-white border border-gray-100 rounded-xl mt-2 shadow-xl z-50 overflow-hidden text-gray-800">
                                    {filteredSuggestions.map(p => (
                                        <div key={p.id} onClick={() => { handleAddMember(p.nombre); setAddSearchTerm(''); setShowSuggestions(false); }} className="px-4 py-3 hover:bg-gray-50 cursor-pointer border-b border-gray-50 flex items-center gap-3">
                                            <div style={{ backgroundColor: getAvatarColor(p.nombre) }} className="w-6 h-6 rounded-full flex items-center justify-center text-xs text-white font-bold">{p.nombre.charAt(0)}</div>
                                            <span className="font-medium">{p.nombre}</span>
                                        </div>
                                    ))}
                                    <div onClick={() => { handleAddMember(addSearchTerm); setAddSearchTerm(''); setShowSuggestions(false); }} className="px-4 py-3 bg-purple-50 hover:bg-purple-100 cursor-pointer flex items-center gap-3 text-purple-700">
                                        <i className="fas fa-pen text-xs"></i><span className="font-semibold">Crear: "{addSearchTerm}"</span>
                                    </div>
                                </div>
                            )}
                        </div>
                    </div>
                )}
            </div>

            {loading ? <div style={{ textAlign: 'center', padding: '5rem 0', color: 'var(--text-color-light)' }}>Cargando...</div> : (
                <div ref={listContainerRef} className="rounded-2xl shadow-xl overflow-hidden border border-[var(--border-color)] bg-[var(--card-bg-color)]">
                    <div className="p-4 border-b border-[var(--border-color)] flex justify-between items-center lg:hidden bg-[var(--light-gray)]">
                        <h3 className="font-bold text-[var(--text-color)]">Listado ({filteredMembers.length})</h3>
                    </div>
                    {filteredMembers.map((m) => {
                        const report = reports[m.publicador_nombre];
                        const hasReport = report !== undefined;
                        const statusColor = hasReport ? '#10b981' : 'var(--border-color)';
                        return (
                            <div key={m.id} onClick={() => setEditingMember(m)} style={{ display: 'flex', alignItems: 'center', padding: '16px', borderBottom: '1px solid var(--border-color)', cursor: 'pointer', backgroundColor: 'var(--card-bg-color)', position: 'relative' }}>
                                <div style={{ position: 'absolute', left: 0, top: 0, bottom: 0, width: '6px', backgroundColor: statusColor }}></div>
                                <div style={{ width: '42px', height: '42px', borderRadius: '50%', backgroundColor: getAvatarColor(m.publicador_nombre), color: 'white', display: 'flex', alignItems: 'center', justifyContent: 'center', fontWeight: 'bold', fontSize: '1.1rem', marginRight: '15px', marginLeft: '12px' }}>{m.publicador_nombre.charAt(0)}</div>
                                <div style={{ flex: 1 }}>
                                    <div style={{ fontWeight: '700', color: 'var(--text-color)', fontSize: '1rem' }}>{m.publicador_nombre}</div>
                                    <div style={{ fontSize: '0.85rem', color: hasReport ? '#059669' : 'var(--text-color-light)', fontWeight: hasReport ? '700' : '400' }}>{hasReport ? `Informó: ${report.horas === 0 ? 'Predicó' : report.horas + 'h'}` : 'Pendiente'}</div>
                                </div>
                                <div style={{ color: 'var(--text-color-light)' }}><i className="fas fa-chevron-right"></i></div>
                            </div>
                        );
                    })}
                    {filteredMembers.length === 0 && <div style={{ padding: '3rem', textAlign: 'center', color: 'var(--text-color-light)' }}>Grupo vacío</div>}
                </div>
            )}

            {/* --- Plantilla PDF (2 Columnas, Forzado a Blanco/Negro para soporte Dark Mode) --- */}
            <div style={{ display: 'none' }}>
                <div ref={printRef} style={{ width: '210mm', minHeight: '297mm', padding: '15mm', backgroundColor: '#ffffff', color: '#000000', fontFamily: 'Arial, sans-serif', boxSizing: 'border-box', position: 'relative' }}>
                    <div style={{ borderBottom: '2px solid #1e3a8a', paddingBottom: '10px', marginBottom: '15px', display: 'flex', justifyContent: 'space-between', alignItems: 'flex-end' }}>
                        <div>
                            <h1 style={{ margin: 0, fontSize: '16pt', color: '#1e3a8a', fontWeight: 'bold' }}>INFORME DE ACTIVIDAD</h1>
                            <p style={{ margin: '4px 0 0 0', fontSize: '10pt', color: '#475569' }}>{groups.find(g => g.id === selectedGroupId)?.nombre} • Congregación Central</p>
                        </div>
                        <div style={{ textAlign: 'right' }}>
                            <p style={{ margin: 0, fontSize: '11pt', fontWeight: 'bold', textTransform: 'capitalize', color: '#000' }}>{formatMonth(currentMonth)}</p>
                        </div>
                    </div>

                    <div style={{ display: 'flex', gap: '10px', marginBottom: '20px' }}>
                        {[{l:'Publicadores',v:totalReports}, {l:'Informes',v:submittedReports}, {l:'Horas',v:totalHours}, {l:'Estudios',v:totalStudies}].map((s,i)=>(
                            <div key={i} style={{ flex: 1, border: '1px solid #cbd5e1', borderRadius: '6px', padding: '8px', textAlign: 'center', backgroundColor: '#f8fafc' }}>
                                <span style={{ display: 'block', fontSize: '8pt', color: '#64748b', fontWeight: 'bold', textTransform: 'uppercase' }}>{s.l}</span>
                                <span style={{ fontSize: '12pt', fontWeight: 'bold', color: '#1e293b' }}>{s.v}</span>
                            </div>
                        ))}
                    </div>

                    <div style={{ display: 'flex', gap: '10mm', alignItems: 'flex-start' }}>
                        {[col1, col2].map((colMembers, colIndex) => (
                            <div key={colIndex} style={{ flex: 1 }}>
                                <table style={{ width: '100%', borderCollapse: 'collapse', fontSize: '9pt' }}>
                                    <thead>
                                        <tr style={{ backgroundColor: '#f1f5f9', borderBottom: '2px solid #1e3a8a' }}>
                                            <th style={{ padding: '5px', textAlign: 'left', color: '#1e3a8a', fontWeight: 'bold', width: '55%' }}>Nombre</th>
                                            <th style={{ padding: '5px', textAlign: 'center', color: '#1e3a8a', fontWeight: 'bold', width: '15%' }}>H</th>
                                            <th style={{ padding: '5px', textAlign: 'left', color: '#1e3a8a', fontWeight: 'bold', width: '30%' }}>Notas</th>
                                        </tr>
                                    </thead>
                                    <tbody>
                                        {colMembers.map((m, idx) => {
                                            const r = reports[m.publicador_nombre];
                                            return (
                                                <tr key={m.id} style={{ backgroundColor: idx % 2 === 0 ? 'transparent' : '#f8fafc', borderBottom: '1px solid #e2e8f0' }}>
                                                    <td style={{ padding: '4px 5px', fontWeight: '500', color: '#000' }}>{m.publicador_nombre}</td>
                                                    <td style={{ padding: '4px 5px', textAlign: 'center', color: '#000' }}>{r ? (r.horas === 0 ? 'P' : r.horas) : '-'}</td>
                                                    <td style={{ padding: '4px 5px', fontSize: '8pt', color: '#475569' }}>{r?.estudios ? `${r.estudios} est. ` : ''}{r?.notas || ''}</td>
                                                </tr>
                                            );
                                        })}
                                    </tbody>
                                </table>
                            </div>
                        ))}
                    </div>

                    <div style={{ position: 'absolute', bottom: '15mm', left: '15mm', right: '15mm', borderTop: '1px solid #cbd5e1', paddingTop: '10px', display: 'flex', justifyContent: 'space-between', fontSize: '8pt', color: '#94a3b8' }}>
                        <span>Generado el {new Date().toLocaleDateString()}</span>
                        <span>Firma del Superintendente</span>
                    </div>
                </div>
            </div>

            {statusMessage && (
                <div style={{ position: 'fixed', bottom: '20px', right: '20px', backgroundColor: statusMessage.type === 'error' ? '#ef4444' : '#10b981', color: 'white', padding: '12px 20px', borderRadius: '12px', boxShadow: '0 10px 25px -5px rgba(0,0,0,0.2)', fontWeight: 'bold', zIndex: 1000 }}>
                    {statusMessage.text}
                </div>
            )}
        </div>
    );
};

export default GrupoCongregacion;

import React, { useState, useEffect, useRef } from 'react';
import { supabase } from '../lib/supabase';

// Declaración de librerías externas cargadas en index.html
declare const html2canvas: any;
declare const html2pdf: any;

type Publisher = {
    id: number;
    nombre: string;
};

type Group = {
    id: number;
    nombre: string;
};

type GroupMember = {
    id: number;
    grupo_id: number;
    publicador_nombre: string;
};

type MinistryReport = {
    horas: number | '';
    estudios: number | '';
    notas?: string;
};

type VisitData = {
    date: string;
    notes: string;
};

type ReportsMap = Record<string, MinistryReport>;
type VisitsMap = Record<string, VisitData>;

// Helper for avatar colors (HEX codes to ensure they appear)
const getAvatarColor = (name: string) => {
    const colors = [
        '#ef4444', '#f97316', '#f59e0b', '#22c55e', '#14b8a6', 
        '#3b82f6', '#6366f1', '#a855f7', '#ec4899'
    ];
    let hash = 0;
    for (let i = 0; i < name.length; i++) {
        hash = name.charCodeAt(i) + ((hash << 5) - hash);
    }
    return colors[Math.abs(hash) % colors.length];
};

const formatMonth = (dateStr: string) => {
    if (!dateStr) return '';
    const [year, month] = dateStr.split('-');
    const date = new Date(parseInt(year), parseInt(month) - 1);
    return date.toLocaleDateString('es-ES', { month: 'long', year: 'numeric' });
};

// --- MODAL COMPONENT ---
const EditMemberModal: React.FC<{
    member: GroupMember;
    reportEntry: MinistryReport | undefined;
    visitData: VisitData;
    onClose: () => void;
    onReportChange: (name: string, field: keyof MinistryReport, value: string | number) => void;
    onVisitChange: (name: string, field: keyof VisitData, value: string) => void;
    onSave: (name: string) => void;
    onDelete: (id: number, name: string) => void;
    onRemoveReport: (name: string) => void;
}> = ({ member, reportEntry, visitData, onClose, onReportChange, onVisitChange, onSave, onDelete, onRemoveReport }) => {
    const pName = member.publicador_nombre;
    const visitDate = visitData.date;
    const hasReport = reportEntry !== undefined;

    const [didPreach, setDidPreach] = useState<boolean>(
        reportEntry ? (reportEntry.horas !== '' || reportEntry.estudios === 0) : true
    );

    useEffect(() => {
        if (reportEntry && (reportEntry.horas !== '' && Number(reportEntry.horas) >= 0)) {
            setDidPreach(true);
        }
    }, [reportEntry]);

    const handleToggleActive = (e: React.ChangeEvent<HTMLInputElement>) => {
        if (e.target.checked) {
            onReportChange(pName, 'horas', 0);
            setDidPreach(true);
        } else {
            onRemoveReport(pName);
        }
    };

    const handlePreachToggle = (e: React.ChangeEvent<HTMLInputElement>) => {
        const isChecked = e.target.checked;
        setDidPreach(isChecked);
        if (!isChecked) {
            onReportChange(pName, 'horas', 0);
        }
    };

    let visitLabel = 'N/A';
    let visitColor = 'var(--text-color-light)';
    let visitBg = 'var(--bg-color)';

    if (visitDate) {
        const daysSince = (new Date().getTime() - new Date(visitDate).getTime()) / (1000 * 3600 * 24);
        if (daysSince < 90) { visitLabel = 'Al día'; visitColor = '#15803d'; visitBg = '#dcfce7'; } 
        else if (daysSince < 180) { visitLabel = 'Atención'; visitColor = '#b45309'; visitBg = '#fef3c7'; } 
        else { visitLabel = 'Urgente'; visitColor = '#b91c1c'; visitBg = '#fee2e2'; }
    }

    return (
        <div style={{
            position: 'fixed', top: 0, left: 0, right: 0, bottom: 0,
            backgroundColor: 'rgba(0,0,0,0.6)', zIndex: 99999,
            display: 'flex', alignItems: 'flex-end', justifyContent: 'center'
        }} onClick={onClose}>
            <div style={{
                backgroundColor: 'var(--card-bg-color)', width: '100%', maxWidth: '500px',
                borderTopLeftRadius: '20px', borderTopRightRadius: '20px',
                overflow: 'hidden', display: 'flex', flexDirection: 'column',
                maxHeight: '90vh', animation: 'slideUp 0.3s ease-out',
                color: 'var(--text-color)'
            }} onClick={e => e.stopPropagation()}>

                <div style={{ padding: '15px 20px', borderBottom: '1px solid var(--border-color)', display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
                    <div style={{ display: 'flex', alignItems: 'center', gap: '15px' }}>
                        <div style={{
                            width: '40px', height: '40px', borderRadius: '50%',
                            backgroundColor: getAvatarColor(pName), color: 'white',
                            display: 'flex', alignItems: 'center', justifyContent: 'center',
                            fontWeight: 'bold', fontSize: '1.2rem'
                        }}>
                            {pName.charAt(0)}
                        </div>
                        <h3 style={{ margin: 0, fontSize: '1.2rem', color: 'var(--text-color)' }}>{pName}</h3>
                    </div>
                    <button onClick={onClose} style={{ border: 'none', background: 'transparent', fontSize: '1.5rem', color: 'var(--text-color-light)', cursor: 'pointer' }}>&times;</button>
                </div>

                <div style={{ padding: '20px', overflowY: 'auto', backgroundColor: 'var(--bg-color)' }}>

                    {/* Informe Section */}
                    <div style={{ backgroundColor: 'var(--card-bg-color)', padding: '20px', borderRadius: '16px', marginBottom: '15px', boxShadow: '0 2px 8px rgba(0,0,0,0.04)' }}>
                        <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '15px', paddingBottom:'10px', borderBottom:'1px solid var(--border-color)' }}>
                            <h4 style={{ margin: 0, color: '#3b82f6', display: 'flex', alignItems: 'center', gap: '8px', fontSize: '1rem' }}>
                                <i className="fas fa-briefcase"></i> Informe del Mes
                            </h4>
                            <label style={{ display: 'flex', alignItems: 'center', gap: '10px', cursor: 'pointer' }}>
                                <span style={{ fontSize: '0.85rem', color: hasReport ? '#3b82f6' : 'var(--text-color-light)', fontWeight: '600' }}>
                                    {hasReport ? 'Entregado' : 'Sin entregar'}
                                </span>
                                <div style={{ position: 'relative', width: '44px', height: '24px' }}>
                                    <input type="checkbox" checked={hasReport} onChange={handleToggleActive} style={{ opacity: 0, width: 0, height: 0 }} />
                                    <span style={{
                                        position: 'absolute', cursor: 'pointer', top: 0, left: 0, right: 0, bottom: 0,
                                        backgroundColor: hasReport ? '#3b82f6' : 'var(--border-color)', transition: '.4s', borderRadius: '34px'
                                    }}></span>
                                    <span style={{
                                        position: 'absolute', content: '""', height: '18px', width: '18px', left: hasReport ? '22px' : '4px', bottom: '3px',
                                        backgroundColor: 'white', transition: '.4s', borderRadius: '50%', boxShadow: '0 2px 4px rgba(0,0,0,0.2)'
                                    }}></span>
                                </div>
                            </label>
                        </div>

                        {hasReport && (
                            <div style={{ display: 'flex', flexDirection: 'column', gap: '15px', animation: 'fadeIn 0.3s ease-in' }}>

                                <label style={{ display: 'flex', alignItems: 'center', gap: '12px', padding: '10px', backgroundColor: 'var(--bg-color)', borderRadius: '10px', border: '1px solid var(--border-color)', cursor: 'pointer' }}>
                                    <input 
                                        type="checkbox" 
                                        checked={didPreach} 
                                        onChange={handlePreachToggle}
                                        style={{ width: '20px', height: '20px', accentColor: '#3b82f6' }} 
                                    />
                                    <span style={{ fontSize: '0.95rem', fontWeight: '500', color: 'var(--text-color)' }}>Participó en la predicación</span>
                                </label>

                                <div style={{ display: 'flex', gap: '15px' }}>
                                    {didPreach && (
                                        <div style={{ flex: 1, animation: 'fadeIn 0.2s' }}>
                                            <label style={{ display: 'block', fontSize: '0.75rem', fontWeight:'700', color: 'var(--text-color-light)', marginBottom: '6px', textTransform:'uppercase' }}>Horas</label>
                                            <input 
                                                type="number" step="0.5" min="0"
                                                value={reportEntry?.horas === 0 ? '' : (reportEntry?.horas || '')} 
                                                onChange={(e) => onReportChange(pName, 'horas', e.target.value)}
                                                placeholder="0"
                                                style={{ width: '100%', padding: '12px', fontSize: '1.2rem', fontWeight:'bold', borderRadius: '10px', border: '2px solid var(--border-color)', backgroundColor:'var(--bg-color)', color:'var(--text-color)', textAlign: 'center' }}
                                            />
                                        </div>
                                    )}

                                    <div style={{ flex: 1 }}>
                                        <label style={{ display: 'block', fontSize: '0.75rem', fontWeight:'700', color: 'var(--text-color-light)', marginBottom: '6px', textTransform:'uppercase' }}>Cursos</label>
                                        <input 
                                            type="number" min="0" 
                                            value={reportEntry?.estudios || ''} 
                                            onChange={(e) => onReportChange(pName, 'estudios', e.target.value)}
                                            placeholder="0"
                                            style={{ width: '100%', padding: '12px', fontSize: '1.2rem', fontWeight:'bold', borderRadius: '10px', border: '2px solid var(--border-color)', backgroundColor:'var(--bg-color)', color:'var(--text-color)', textAlign: 'center' }}
                                        />
                                    </div>
                                </div>

                                <div>
                                    <label style={{ display: 'block', fontSize: '0.75rem', fontWeight:'700', color: 'var(--text-color-light)', marginBottom: '6px', textTransform:'uppercase' }}>Notas</label>
                                    <input
                                        type="text"
                                        value={reportEntry?.notas || ''}
                                        onChange={(e) => onReportChange(pName, 'notas', e.target.value)}
                                        style={{ width: '100%', padding: '12px', borderRadius: '10px', border: '1px solid var(--border-color)', backgroundColor:'var(--bg-color)', color:'var(--text-color)', boxSizing: 'border-box', fontSize:'0.95rem' }}
                                        placeholder="Observaciones..."
                                    />
                                </div>
                            </div>
                        )}
                        {!hasReport && (
                            <div style={{ padding: '20px', textAlign: 'center', color: 'var(--text-color-light)', backgroundColor: 'var(--bg-color)', borderRadius: '10px', fontSize:'0.9rem' }}>
                                Sin actividad registrada.
                            </div>
                        )}
                    </div>

                    {/* Pastoreo Section */}
                    <div style={{ backgroundColor: 'var(--card-bg-color)', padding: '20px', borderRadius: '16px', boxShadow: '0 2px 8px rgba(0,0,0,0.04)' }}>
                        <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '15px' }}>
                            <h4 style={{ margin: 0, color: '#ec4899', display: 'flex', alignItems: 'center', gap: '8px', fontSize: '1rem' }}>
                                <i className="fas fa-heart"></i> Pastoreo
                            </h4>
                            <span style={{ backgroundColor: visitBg, color: visitColor, padding: '4px 10px', borderRadius: '20px', fontSize: '0.75rem', fontWeight: '700', textTransform:'uppercase', letterSpacing:'0.05em' }}>
                                {visitLabel}
                            </span>
                        </div>
                        <div style={{ display: 'flex', flexDirection: 'column', gap: '15px' }}>
                            <div>
                                <label style={{ display: 'block', fontSize: '0.75rem', fontWeight:'700', color: 'var(--text-color-light)', marginBottom: '6px', textTransform:'uppercase' }}>Última Visita</label>
                                <input 
                                    type="date" 
                                    value={visitDate}
                                    onChange={(e) => onVisitChange(pName, 'date', e.target.value)}
                                    style={{ width: '100%', padding: '12px', borderRadius: '10px', border: '1px solid var(--border-color)', backgroundColor:'var(--bg-color)', boxSizing: 'border-box', color:'var(--text-color)', fontWeight:'500' }}
                                />
                            </div>
                            <div>
                                <label style={{ display: 'block', fontSize: '0.75rem', fontWeight:'700', color: 'var(--text-color-light)', marginBottom: '6px', textTransform:'uppercase' }}>Apuntes Privados</label>
                                <input
                                    type="text"
                                    value={visitData.notes || ''}
                                    onChange={(e) => onVisitChange(pName, 'notes', e.target.value)}
                                    style={{ width: '100%', padding: '12px', borderRadius: '10px', border: '1px solid var(--border-color)', backgroundColor:'var(--bg-color)', boxSizing: 'border-box', fontSize:'0.95rem', color: 'var(--text-color)' }}
                                    placeholder="Nota de visita..."
                                />
                            </div>
                        </div>
                    </div>

                </div>

                <div style={{ padding: '15px 20px', borderTop: '1px solid var(--border-color)', display: 'flex', gap: '15px', backgroundColor:'var(--card-bg-color)' }}>
                    <button 
                        onClick={() => { if(window.confirm('¿Eliminar del grupo?')) { onDelete(member.id, pName); onClose(); } }}
                        style={{ width:'50px', display:'flex', alignItems:'center', justifyContent:'center', borderRadius: '12px', border: '1px solid #fecaca', backgroundColor: '#fef2f2', color: '#ef4444', cursor: 'pointer' }}
                    >
                        <i className="fas fa-trash-alt" style={{fontSize:'1.1rem'}}></i>
                    </button>
                    <button 
                        onClick={() => { onSave(pName); onClose(); }}
                        style={{ flex: 1, padding: '14px', borderRadius: '12px', border: 'none', backgroundColor: '#2563eb', color: 'white', fontWeight: '600', cursor: 'pointer', fontSize: '1rem', boxShadow:'0 4px 6px -1px rgba(37, 99, 235, 0.2)' }}
                    >
                        Guardar
                    </button>
                </div>
            </div>
        </div>
    );
};

// --- COMPONENTE PRINCIPAL ---
const GrupoCongregacion: React.FC = () => {
    // Data State
    const [groups, setGroups] = useState<Group[]>([]);
    const [selectedGroupId, setSelectedGroupId] = useState<number | null>(null);
    const [members, setMembers] = useState<GroupMember[]>([]);
    const [masterPublishers, setMasterPublishers] = useState<Publisher[]>([]); 

    // UI State
    const [isMobile, setIsMobile] = useState(window.innerWidth < 1024);
    const [loading, setLoading] = useState(true);
    const [currentMonth, setCurrentMonth] = useState<string>('');
    const [reports, setReports] = useState<ReportsMap>({});
    const [visits, setVisits] = useState<VisitsMap>({});
    const [searchTerm, setSearchTerm] = useState('');
    const [addSearchTerm, setAddSearchTerm] = useState(''); 
    const [showSuggestions, setShowSuggestions] = useState(false);
    const [isCreatingGroup, setIsCreatingGroup] = useState(false);
    const [newGroupName, setNewGroupName] = useState('');
    const [statusMessage, setStatusMessage] = useState<{ text: string; type: 'success' | 'error' | 'info' } | null>(null);
    const [isSharing, setIsSharing] = useState(false);

    const [editingMember, setEditingMember] = useState<GroupMember | null>(null);

    const suggestionsRef = useRef<HTMLDivElement>(null);
    const listContainerRef = useRef<HTMLDivElement>(null);
    const printRef = useRef<HTMLDivElement>(null);

    // Initial Load
    useEffect(() => {
        const handleResize = () => setIsMobile(window.innerWidth < 1024);
        window.addEventListener('resize', handleResize);

        const now = new Date();
        const yyyy = now.getFullYear();
        const mm = String(now.getMonth() + 1).padStart(2, '0');
        setCurrentMonth(`${yyyy}-${mm}`);

        fetchGroups();
        fetchMasterPublishers();

        const handleClickOutside = (event: MouseEvent) => {
            if (suggestionsRef.current && !suggestionsRef.current.contains(event.target as Node)) {
                setShowSuggestions(false);
            }
        };
        document.addEventListener('mousedown', handleClickOutside);
        return () => {
            document.removeEventListener('mousedown', handleClickOutside);
            window.removeEventListener('resize', handleResize);
        }
    }, []);

    // Load Data Functions
    const fetchGroups = async () => {
        const { data, error } = await supabase.from('grupos').select('*').order('nombre');
        if (data) {
            setGroups(data);
            if (data.length > 0 && !selectedGroupId) {
                const defaultGroup = data.find(g => g.nombre.includes('5')) || data[0];
                setSelectedGroupId(defaultGroup.id);
            }
        }
    };

    const fetchMasterPublishers = async () => {
        const { data } = await supabase.from('publicadores').select('id, nombre').order('nombre');
        if (data) setMasterPublishers(data);
    };

    const fetchMembers = async () => {
        if (!selectedGroupId) return;
        setLoading(true);
        const { data } = await supabase.from('miembros_grupo').select('*').eq('grupo_id', selectedGroupId).order('publicador_nombre');
        setMembers(data || []);
        setLoading(false);
    };

    useEffect(() => { fetchMembers(); }, [selectedGroupId]);

    useEffect(() => {
        if (!currentMonth || members.length === 0) return;
        const fetchData = async () => {
            const memberNames = members.map(m => m.publicador_nombre);
            if (memberNames.length === 0) { setReports({}); setVisits({}); return; }

            const { data: reportsData } = await supabase.from('informes_ministerio').select('publicador_nombre, horas, notas').eq('mes', currentMonth).in('publicador_nombre', memberNames);
            const newReports: ReportsMap = {};
            if (reportsData) reportsData.forEach((r: any) => { newReports[r.publicador_nombre] = { horas: r.horas, estudios: '', notas: r.notas || '' }; });
            setReports(newReports);

            const { data: visitsData } = await supabase.from('visitas_pastoral').select('publicador_nombre, fecha_visita, notas').in('publicador_nombre', memberNames);
            const newVisits: VisitsMap = {};
            if (visitsData) visitsData.forEach((v: any) => { newVisits[v.publicador_nombre] = { date: v.fecha_visita, notes: v.notas || '' }; });
            setVisits(newVisits);
        };
        fetchData();
    }, [currentMonth, members]);

    const handleCreateGroup = async () => {
        if (!newGroupName.trim()) return;
        const { data, error } = await supabase.from('grupos').insert([{ nombre: newGroupName.trim() }]).select();
        if (!error && data) {
            setGroups(prev => [...prev, data[0]].sort((a,b) => a.nombre.localeCompare(b.nombre)));
            setSelectedGroupId(data[0].id);
            setIsCreatingGroup(false);
            setNewGroupName('');
        }
    };

    const handleAddMember = async (name: string) => { 
        if (!selectedGroupId || !name.trim()) return;
        const { error } = await supabase.from('miembros_grupo').insert([{ grupo_id: selectedGroupId, publicador_nombre: name.trim() }]);
        if(!error) { setAddSearchTerm(''); fetchMembers(); }
    };

    const handleDeleteMember = async (id: number, name: string) => {
        const { error } = await supabase.from('miembros_grupo').delete().eq('id', id);
        if (!error) { fetchMembers(); if(editingMember?.id === id) setEditingMember(null); }
    };

    const handleReportChange = (name: string, field: keyof MinistryReport, value: string | number) => {
        setReports(prev => {
            const currentEntry = prev[name] || { horas: '', estudios: '', notas: '' };
            const newValue = (field === 'horas' || field === 'estudios') ? (value === '' ? '' : Number(value)) : value;
            return { ...prev, [name]: { ...currentEntry, [field]: newValue } };
        });
    };

    const handleRemoveReport = (name: string) => {
        setReports(prev => { const next = { ...prev }; delete next[name]; return next; });
    };

    const handleVisitChange = (name: string, field: keyof VisitData, value: string) => {
        setVisits(prev => {
            const currentEntry = prev[name] || { date: '', notes: '' };
            return { ...prev, [name]: { ...currentEntry, [field]: value } };
        });
    };

    const handleSaveRow = async (publisherName: string) => {
        setStatusMessage({ text: 'Guardando...', type: 'info' });
        try {
            const reportEntry = reports[publisherName];
            const { data: existingReport } = await supabase.from('informes_ministerio').select('id').eq('publicador_nombre', publisherName).eq('mes', currentMonth).maybeSingle();
            const reportData = { publicador_nombre: publisherName, mes: currentMonth, horas: reportEntry?.horas === '' ? 0 : reportEntry?.horas, notas: reportEntry?.notas || '' };

            if (reportEntry) {
                if (existingReport) await supabase.from('informes_ministerio').update(reportData).eq('id', existingReport.id);
                else await supabase.from('informes_ministerio').insert([reportData]);
            } else if (existingReport) {
                await supabase.from('informes_ministerio').delete().eq('id', existingReport.id);
            }

            const visitData = visits[publisherName];
            if (visitData && (visitData.date || visitData.notes)) {
                const { data: existingVisit } = await supabase.from('visitas_pastoral').select('id').eq('publicador_nombre', publisherName).maybeSingle();
                const visitPayload = { publicador_nombre: publisherName, fecha_visita: visitData.date, notas: visitData.notes };
                if (existingVisit) await supabase.from('visitas_pastoral').update(visitPayload).eq('id', existingVisit.id);
                else await supabase.from('visitas_pastoral').insert([visitPayload]);
            }
            setStatusMessage({ text: 'Guardado', type: 'success' });
            setTimeout(() => setStatusMessage(null), 2000);
        } catch (error) {
            setStatusMessage({ text: 'Error', type: 'error' });
        }
    };

    const filteredMembers = members.filter(m => m.publicador_nombre.toLowerCase().includes(searchTerm.toLowerCase()));
    const filteredSuggestions = masterPublishers.filter(p => p.nombre.toLowerCase().includes(addSearchTerm.toLowerCase()) && !members.some(m => m.publicador_nombre === p.nombre)).slice(0, 6);

    const totalReports = members.length;
    const submittedReports = members.filter(m => reports[m.publicador_nombre] !== undefined).length;
    const pendingReports = totalReports - submittedReports;
    const totalHours = Object.values(reports).reduce((sum: number, r: MinistryReport) => sum + (Number(r.horas) || 0), 0);
    const totalStudies = Object.values(reports).reduce((sum: number, r: MinistryReport) => sum + (Number(r.estudios) || 0), 0);

    const handleSharePDF = async () => {
        if (!printRef.current) return;
        setIsSharing(true);

        // Clonar para no afectar el DOM original
        const element = printRef.current.cloneNode(true) as HTMLElement;

        // Estilos CRÍTICOS para asegurar que se renderice bien para la captura
        // Usamos position fixed/absolute pero dentro de viewport inicial para evitar cortes
        element.style.display = 'block';
        element.style.position = 'fixed';
        element.style.top = '0';
        element.style.left = '0';
        element.style.zIndex = '-9999'; // Detrás de todo pero visible para el canvas
        element.style.width = '210mm'; // Ancho A4 exacto
        element.style.height = 'auto';
        element.style.minHeight = '297mm';
        element.style.backgroundColor = '#ffffff'; // Fondo blanco explícito
        element.style.color = '#000000'; // Texto negro explícito

        // Forzar color negro en todos los hijos por si acaso hereda tema oscuro (texto blanco)
        const allElements = element.querySelectorAll('*');
        allElements.forEach((el) => {
            if (el instanceof HTMLElement) {
                el.style.color = '#000000';
                el.style.borderColor = '#000000';
            }
        });

        document.body.appendChild(element);

        // Pequeña espera para asegurar que el navegador renderice el elemento en el DOM
        await new Promise(resolve => setTimeout(resolve, 100));

        const groupName = groups.find(g => g.id === selectedGroupId)?.nombre || 'Grupo';
        const opt = {
            margin: 0,
            filename: `Informe_${groupName}_${currentMonth}.pdf`,
            image: { type: 'jpeg', quality: 0.98 },
            html2canvas: { 
                scale: 2, 
                useCORS: true, 
                letterRendering: true,
                scrollY: 0,
                scrollX: 0,
                windowWidth: 1000 // Asegura un ancho de ventana suficiente para layout de escritorio
            },
            jsPDF: { unit: 'mm', format: 'a4', orientation: 'portrait' }
        };

        html2pdf().from(element).set(opt).save()
            .then(() => {
                if (document.body.contains(element)) document.body.removeChild(element);
                setIsSharing(false);
            })
            .catch((err: any) => {
                console.error("PDF generation failed:", err);
                if (document.body.contains(element)) document.body.removeChild(element);
                setIsSharing(false);
                alert('Error al generar PDF');
            });
    };

    const handleCopyText = () => {
        const groupName = groups.find(g => g.id === selectedGroupId)?.nombre || 'Grupo';
        let text = `*Informe ${groupName} - ${currentMonth}*\n`;
        text += `📊 Total: ${totalReports} | ✅ Entregados: ${submittedReports} | ⏳ Pendientes: ${pendingReports}\n\n`;
        filteredMembers.forEach(m => {
            const r = reports[m.publicador_nombre];
            if (r) text += `✅ ${m.publicador_nombre}: ${r.horas ? `${r.horas}h` : 'Predicó'}${r.estudios ? ` (${r.estudios} est.)` : ''}\n`;
            else text += `⏳ ${m.publicador_nombre}\n`;
        });
        navigator.clipboard.writeText(text).then(() => {
            setStatusMessage({ text: 'Copiado al portapapeles', type: 'success' });
            setTimeout(() => setStatusMessage(null), 3000);
        });
    };

    // Calculate members for 2 columns for PDF
    const pdfMembers = members; 
    const midPoint = Math.ceil(pdfMembers.length / 2);
    const col1 = pdfMembers.slice(0, midPoint);
    const col2 = pdfMembers.slice(midPoint);

    return (
        <div className="container mx-auto px-4 py-8 group-container relative bg-[var(--bg-color)] min-h-screen">
            <h1 style={{ fontSize: '1.8rem', fontWeight: '800', textAlign: 'center', marginBottom: '1.5rem', color: 'var(--primary-color)', textTransform: 'uppercase', letterSpacing: '0.5px' }}>Gestión del Grupo</h1>

            {editingMember && (
                <EditMemberModal 
                    member={editingMember}
                    reportEntry={reports[editingMember.publicador_nombre]}
                    visitData={visits[editingMember.publicador_nombre] || { date: '', notes: '' }}
                    onClose={() => setEditingMember(null)}
                    onReportChange={handleReportChange}
                    onVisitChange={handleVisitChange}
                    onSave={handleSaveRow}
                    onDelete={handleDeleteMember}
                    onRemoveReport={handleRemoveReport}
                />
            )}

            <div style={{ display: 'flex', flexDirection: 'column', gap: '20px', marginBottom: '25px' }}>
                {/* Stats */}
