                        <div>
                            <h1 style={{ margin: 0, fontSize: '16pt', color: '#1e3a8a', fontWeight: 'bold' }}>INFORME DE ACTIVIDAD</h1>
                            <p style={{ margin: '4px 0 0 0', fontSize: '10pt', color: '#475569' }}>{groups.find(g => g.id === selectedGroupId)?.nombre} • Congregación Central</p>
                        </div>
                        <div style={{ textAlign: 'right' }}>
                            <p style={{ margin: 0, fontSize: '11pt', fontWeight: 'bold', textTransform: 'capitalize', color: '#000' }}>{formatMonth(currentMonth)}</p>
                        </div>
                    </div>

                    <div style={{ display: 'flex', gap: '10px', marginBottom: '20px' }}>
                        {[{l:'Publicadores',v:totalReports}, {l:'Informes',v:submittedReports}, {l:'Horas',v:totalHours}, {l:'Estudios',v:totalStudies}].map((s,i)=>(
                            <div key={i} style={{ flex: 1, border: '1px solid #cbd5e1', borderRadius: '6px', padding: '8px', textAlign: 'center', backgroundColor: '#f8fafc' }}>
                                <span style={{ display: 'block', fontSize: '8pt', color: '#64748b', fontWeight: 'bold', textTransform: 'uppercase' }}>{s.l}</span>
                                <span style={{ fontSize: '12pt', fontWeight: 'bold', color: '#1e293b' }}>{s.v}</span>
                            </div>
                        ))}
                    </div>

                    <div style={{ display: 'flex', gap: '10mm', alignItems: 'flex-start' }}>
                        {[col1, col2].map((colMembers, colIndex) => (
                            <div key={colIndex} style={{ flex: 1 }}>
                                <table style={{ width: '100%', borderCollapse: 'collapse', fontSize: '9pt' }}>
                                    <thead>
                                        <tr style={{ backgroundColor: '#f1f5f9', borderBottom: '2px solid #1e3a8a' }}>
                                            <th style={{ padding: '5px', textAlign: 'left', color: '#1e3a8a', fontWeight: 'bold', width: '55%' }}>Nombre</th>
                                            <th style={{ padding: '5px', textAlign: 'center', color: '#1e3a8a', fontWeight: 'bold', width: '15%' }}>H</th>
                                            <th style={{ padding: '5px', textAlign: 'left', color: '#1e3a8a', fontWeight: 'bold', width: '30%' }}>Notas</th>
                                        </tr>
                                    </thead>
                                    <tbody>
                                        {colMembers.map((m, idx) => {
                                            const r = reports[m.publicador_nombre];
                                            return (
                                                <tr key={m.id} style={{ backgroundColor: idx % 2 === 0 ? 'transparent' : '#f8fafc', borderBottom: '1px solid #e2e8f0' }}>
                                                    <td style={{ padding: '4px 5px', fontWeight: '500', color: '#000' }}>{m.publicador_nombre}</td>
                                                    <td style={{ padding: '4px 5px', textAlign: 'center', color: '#000' }}>{r ? (r.horas === 0 ? 'P' : r.horas) : '-'}</td>
                                                    <td style={{ padding: '4px 5px', fontSize: '8pt', color: '#475569' }}>{r?.estudios ? `${r.estudios} est. ` : ''}{r?.notas || ''}</td>
                                                </tr>
                                            );
                                        })}
                                    </tbody>
                                </table>
                            </div>
                        ))}
                    </div>

                    <div style={{ position: 'absolute', bottom: '15mm', left: '15mm', right: '15mm', borderTop: '1px solid #cbd5e1', paddingTop: '10px', display: 'flex', justifyContent: 'space-between', fontSize: '8pt', color: '#94a3b8' }}>
                        <span>Generado el {new Date().toLocaleDateString()}</span>
                        <span>Firma del Superintendente</span>
                    </div>
                </div>
            </div>

            {statusMessage && (
                <div style={{ position: 'fixed', bottom: '20px', right: '20px', backgroundColor: statusMessage.type === 'error' ? '#ef4444' : '#10b981', color: 'white', padding: '12px 20px', borderRadius: '12px', boxShadow: '0 10px 25px -5px rgba(0,0,0,0.2)', fontWeight: 'bold', zIndex: 1000 }}>
                    {statusMessage.text}
                </div>
            )}
        </div>
    );
};

export default GrupoCongregacion;

