                                    </tbody>
                                </table>
                            </div>
                        ))}
                    </div>

                    <div style={{ position: 'absolute', bottom: '15mm', left: '15mm', right: '15mm', borderTop: '1px solid #cbd5e1', paddingTop: '10px', display: 'flex', justifyContent: 'space-between', fontSize: '8pt', color: '#94a3b8' }}>
                        <span>Generado el {new Date().toLocaleDateString()}</span>
