// Declaración de librerías externas cargadas en index.html
declare const html2canvas: any;
declare const html2pdf: any;

type Publisher = {
    id: number;
    nombre: string;
};

type Group = {
    id: number;
    nombre: string;
};

type GroupMember = {
    id: number;
    grupo_id: number;
    publicador_nombre: string;
};

type MinistryReport = {
    horas: number | '';
    estudios: number | '';
    notas?: string;
};

type VisitData = {
    date: string;
    notes: string;
};

type ReportsMap = Record<string, MinistryReport>;
type VisitsMap = Record<string, VisitData>;

// Helper for avatar colors (HEX codes to ensure they appear)
const getAvatarColor = (name: string) => {
    const colors = [
        '#ef4444', '#f97316', '#f59e0b', '#22c55e', '#14b8a6', 
        '#3b82f6', '#6366f1', '#a855f7', '#ec4899'
    ];
    let hash = 0;
    for (let i = 0; i < name.length; i++) {
        hash = name.charCodeAt(i) + ((hash << 5) - hash);
    }
    return colors[Math.abs(hash) % colors.length];
};

const formatMonth = (dateStr: string) => {
    if (!dateStr) return '';
    const [year, month] = dateStr.split('-');
    const date = new Date(parseInt(year), parseInt(month) - 1);
    return date.toLocaleDateString('es-ES', { month: 'long', year: 'numeric' });
};

// --- MODAL COMPONENT ---
const EditMemberModal: React.FC<{
    member: GroupMember;
    reportEntry: MinistryReport | undefined;
    visitData: VisitData;
    onClose: () => void;
    onReportChange: (name: string, field: keyof MinistryReport, value: string | number) => void;
    onVisitChange: (name: string, field: keyof VisitData, value: string) => void;
    onSave: (name: string) => void;
    onDelete: (id: number, name: string) => void;
    onRemoveReport: (name: string) => void;
}> = ({ member, reportEntry, visitData, onClose, onReportChange, onVisitChange, onSave, onDelete, onRemoveReport }) => {
    const pName = member.publicador_nombre;
    const visitDate = visitData.date;
    const hasReport = reportEntry !== undefined;

    // Logic to determine if checkbox is checked
    const [didPreach, setDidPreach] = useState<boolean>(
        reportEntry ? (reportEntry.horas !== '' || reportEntry.estudios !== '') : true
    );

    useEffect(() => {
        if (reportEntry && ((reportEntry.horas !== '' && Number(reportEntry.horas) > 0) || (reportEntry.estudios !== '' && Number(reportEntry.estudios) > 0))) {
            setDidPreach(true);
        }
