                                                onChange={(e) => onReportChange(pName, 'horas', e.target.value)}
                                                placeholder="0"
                                                style={{ width: '100%', padding: '12px', fontSize: '1.2rem', fontWeight:'bold', borderRadius: '10px', border: '2px solid var(--border-color)', backgroundColor:'var(--bg-color)', color:'var(--text-color)', textAlign: 'center' }}
                                            />
                                        </div>
                                    )}

                                    <div style={{ flex: 1 }}>
                                        <label style={{ display: 'block', fontSize: '0.75rem', fontWeight:'700', color: 'var(--text-color-light)', marginBottom: '6px', textTransform:'uppercase' }}>Cursos (Opcional)</label>
                                        <input 
                                            type="number" min="0" 
                                            value={reportEntry?.estudios || ''} 
                                            onChange={(e) => onReportChange(pName, 'estudios', e.target.value)}
                                            placeholder="0"
                                            style={{ width: '100%', padding: '12px', fontSize: '1.2rem', fontWeight:'bold', borderRadius: '10px', border: '2px solid var(--border-color)', backgroundColor:'var(--bg-color)', color:'var(--text-color)', textAlign: 'center' }}
                                        />
                                    </div>
                                </div>

                                <div>
                                    <label style={{ display: 'block', fontSize: '0.75rem', fontWeight:'700', color: 'var(--text-color-light)', marginBottom: '6px', textTransform:'uppercase' }}>Notas</label>
                                    <input
                                        type="text"
                                        value={reportEntry?.notas || ''}
                                        onChange={(e) => onReportChange(pName, 'notas', e.target.value)}
                                        style={{ width: '100%', padding: '12px', borderRadius: '10px', border: '1px solid var(--border-color)', backgroundColor:'var(--bg-color)', color:'var(--text-color)', boxSizing: 'border-box', fontSize:'0.95rem' }}
                                        placeholder="Observaciones..."
                                    />
                                </div>
                            </div>
                        )}
                        {!hasReport && (
                            <div style={{ padding: '20px', textAlign: 'center', color: 'var(--text-color-light)', backgroundColor: 'var(--bg-color)', borderRadius: '10px', fontSize:'0.9rem' }}>
                                Sin actividad registrada.
                            </div>
                        )}
                    </div>

                    {/* Pastoreo Section */}
                    <div style={{ backgroundColor: 'var(--card-bg-color)', padding: '20px', borderRadius: '16px', boxShadow: '0 2px 8px rgba(0,0,0,0.04)' }}>
                        <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '15px' }}>
                            <h4 style={{ margin: 0, color: '#ec4899', display: 'flex', alignItems: 'center', gap: '8px', fontSize: '1rem' }}>
                                <i className="fas fa-heart"></i> Pastoreo
                            </h4>
                            <span style={{ backgroundColor: visitBg, color: visitColor, padding: '4px 10px', borderRadius: '20px', fontSize: '0.75rem', fontWeight: '700', textTransform:'uppercase', letterSpacing:'0.05em' }}>
                                {visitLabel}
                            </span>
                        </div>
                        <div style={{ display: 'flex', flexDirection: 'column', gap: '15px' }}>
                            <div>
                                <label style={{ display: 'block', fontSize: '0.75rem', fontWeight:'700', color: 'var(--text-color-light)', marginBottom: '6px', textTransform:'uppercase' }}>Última Visita</label>
                                <input 
                                    type="date" 
                                    value={visitDate}
                                    onChange={(e) => onVisitChange(pName, 'date', e.target.value)}
                                    style={{ width: '100%', padding: '12px', borderRadius: '10px', border: '1px solid var(--border-color)', backgroundColor:'var(--bg-color)', boxSizing: 'border-box', color:'var(--text-color)', fontWeight:'500' }}
                                />
                            </div>
                            <div>
                                <label style={{ display: 'block', fontSize: '0.75rem', fontWeight:'700', color: 'var(--text-color-light)', marginBottom: '6px', textTransform:'uppercase' }}>Apuntes Privados</label>
                                <input
                                    type="text"
                                    value={visitData.notes || ''}
                                    onChange={(e) => onVisitChange(pName, 'notes', e.target.value)}
                                    style={{ width: '100%', padding: '12px', borderRadius: '10px', border: '1px solid var(--border-color)', backgroundColor:'var(--bg-color)', boxSizing: 'border-box', fontSize:'0.95rem', color: 'var(--text-color)' }}
                                    placeholder="Nota de visita..."
                                />
                            </div>
                        </div>
                    </div>

                </div>

                <div style={{ padding: '15px 20px', borderTop: '1px solid var(--border-color)', display: 'flex', gap: '15px', backgroundColor:'var(--card-bg-color)' }}>
                    <button 
                        onClick={() => { if(window.confirm('¿Eliminar del grupo?')) { onDelete(member.id, pName); onClose(); } }}
                        style={{ width:'50px', display:'flex', alignItems:'center', justifyContent:'center', borderRadius: '12px', border: '1px solid #fecaca', backgroundColor: '#fef2f2', color: '#ef4444', cursor: 'pointer' }}
                    >
                        <i className="fas fa-trash-alt" style={{fontSize:'1.1rem'}}></i>
                    </button>
                    <button 
                        onClick={() => { onSave(pName); onClose(); }}
                        style={{ flex: 1, padding: '14px', borderRadius: '12px', border: 'none', backgroundColor: '#2563eb', color: 'white', fontWeight: '600', cursor: 'pointer', fontSize: '1rem', boxShadow:'0 4px 6px -1px rgba(37, 99, 235, 0.2)' }}
                    >
                        Guardar
                    </button>
                </div>
            </div>
        </div>
    );
};

// --- COMPONENTE PRINCIPAL ---
const GrupoCongregacion: React.FC = () => {
    // Data State
    const [groups, setGroups] = useState<Group[]>([]);
    const [selectedGroupId, setSelectedGroupId] = useState<number | null>(null);
    const [members, setMembers] = useState<GroupMember[]>([]);
    const [masterPublishers, setMasterPublishers] = useState<Publisher[]>([]); 

    // UI State
    const [isMobile, setIsMobile] = useState(window.innerWidth < 1024);
    const [loading, setLoading] = useState(true);
    const [currentMonth, setCurrentMonth] = useState<string>('');
    const [reports, setReports] = useState<ReportsMap>({});
    const [visits, setVisits] = useState<VisitsMap>({});
    const [searchTerm, setSearchTerm] = useState('');
    const [addSearchTerm, setAddSearchTerm] = useState(''); 
    const [showSuggestions, setShowSuggestions] = useState(false);
    const [isCreatingGroup, setIsCreatingGroup] = useState(false);
    const [newGroupName, setNewGroupName] = useState('');
    const [statusMessage, setStatusMessage] = useState<{ text: string; type: 'success' | 'error' | 'info' } | null>(null);
    const [isSharing, setIsSharing] = useState(false);

    const [editingMember, setEditingMember] = useState<GroupMember | null>(null);

    const suggestionsRef = useRef<HTMLDivElement>(null);
    const listContainerRef = useRef<HTMLDivElement>(null);
    const printRef = useRef<HTMLDivElement>(null);

    // Initial Load
    useEffect(() => {
        const handleResize = () => setIsMobile(window.innerWidth < 1024);
        window.addEventListener('resize', handleResize);

        const now = new Date();
        const yyyy = now.getFullYear();
        const mm = String(now.getMonth() + 1).padStart(2, '0');
        setCurrentMonth(`${yyyy}-${mm}`);

        fetchGroups();
        fetchMasterPublishers();

        const handleClickOutside = (event: MouseEvent) => {
            if (suggestionsRef.current && !suggestionsRef.current.contains(event.target as Node)) {
                setShowSuggestions(false);
            }
        };
        document.addEventListener('mousedown', handleClickOutside);
        return () => {
            document.removeEventListener('mousedown', handleClickOutside);
            window.removeEventListener('resize', handleResize);
        }
    }, []);

    // Load Data Functions
    const fetchGroups = async () => {
        const { data, error } = await supabase.from('grupos').select('*').order('nombre');
        if (data) {
            setGroups(data);
            if (data.length > 0 && !selectedGroupId) {
                const defaultGroup = data.find(g => g.nombre.includes('5')) || data[0];
                setSelectedGroupId(defaultGroup.id);
            }
        }
    };

    const fetchMasterPublishers = async () => {
        const { data } = await supabase.from('publicadores').select('id, nombre').order('nombre');
        if (data) setMasterPublishers(data);
    };

    const fetchMembers = async () => {
        if (!selectedGroupId) return;
        setLoading(true);
        const { data } = await supabase.from('miembros_grupo').select('*').eq('grupo_id', selectedGroupId).order('publicador_nombre');
        setMembers(data || []);
        setLoading(false);
    };

    useEffect(() => { fetchMembers(); }, [selectedGroupId]);

    const fetchReportData = useCallback(async () => {
        if (!currentMonth || members.length === 0) return;

        const memberNames = members.map(m => m.publicador_nombre);
        if (memberNames.length === 0) { setReports({}); setVisits({}); return; }

        // Fetch Reports - REMOVED 'estudios' column to prevent error
        const { data: reportsData } = await supabase.from('informes_ministerio')
            .select('publicador_nombre, horas, notas') 
            .eq('mes', currentMonth)
            .in('publicador_nombre', memberNames);

        // Use a functional update to preserve existing studies/notes if the fetch is incomplete but we don't want to clobber local edits violently,
        // although typically fetch is authoritative.
        // Given the "hours missing" issue, we want to ensure we populate strictly from DB but handle 0s correctly.

        const newReports: ReportsMap = {};
        if (reportsData) {
            reportsData.forEach((r: any) => { 
                // Keep existing estudios if in memory? No, difficult to reconcile.
                // Reset studies to empty as it's not in DB.
                newReports[r.publicador_nombre] = { 
                    horas: r.horas, 
                    estudios: '', 
                    notas: r.notas || '' 
                }; 
            });
        }

        // Merge with existing state to avoid completely losing transient data like 'estudios' 
        // if we want to support it for the session
        setReports(prev => {
            const next = { ...prev };
            // Clear current month's known entries first to ensure we reflect deletions? 
            // Actually, safest is to overwrite with fetched data where it exists.
            memberNames.forEach(name => {
                // If data was fetched, use it.
                if (newReports[name]) {
                    next[name] = {
                        ...newReports[name],
                        // Preserve local 'estudios' if it exists in previous state, since DB doesn't have it
                        estudios: prev[name]?.estudios || ''
                    };
                } else {
                    // If not fetched, it might not exist in DB.
                    // But if we just saved it?
                    // We will trust handleSaveRow's optimistic update for the "just saved" row if fetch failed to return it immediately.
                    // However, if we are loading initial data, we should clear it.
                    // Let's assume if it's not in reportsData, it's not in DB.
                    // So we delete it from next, UNLESS we preserve it? 
                    // Better to clean up stale data.
                    delete next[name];
                }
            });
            return next;
        });

        // Fetch Visits
        const { data: visitsData } = await supabase.from('visitas_pastoral').select('publicador_nombre, fecha_visita, notas').in('publicador_nombre', memberNames);
        const newVisits: VisitsMap = {};
        if (visitsData) {
            visitsData.forEach((v: any) => { 
                newVisits[v.publicador_nombre] = { 
                    date: v.fecha_visita, 
                    notes: v.notas || '' 
                }; 
            });
        }
        setVisits(newVisits);
    }, [currentMonth, members]);

    useEffect(() => {
        fetchReportData();
    }, [fetchReportData]);

    const handleCreateGroup = async () => {
        if (!newGroupName.trim()) return;
        const { data, error } = await supabase.from('grupos').insert([{ nombre: newGroupName.trim() }]).select();
        if (!error && data) {
            setGroups(prev => [...prev, data[0]].sort((a,b) => a.nombre.localeCompare(b.nombre)));
            setSelectedGroupId(data[0].id);
            setIsCreatingGroup(false);
            setNewGroupName('');
        }
    };

    const handleAddMember = async (name: string) => { 
        if (!selectedGroupId || !name.trim()) return;
        const { error } = await supabase.from('miembros_grupo').insert([{ grupo_id: selectedGroupId, publicador_nombre: name.trim() }]);
        if(!error) { setAddSearchTerm(''); fetchMembers(); }
    };

    const handleDeleteMember = async (id: number, name: string) => {
        const { error } = await supabase.from('miembros_grupo').delete().eq('id', id);
        if (!error) { fetchMembers(); if(editingMember?.id === id) setEditingMember(null); }
    };

    const handleReportChange = (name: string, field: keyof MinistryReport, value: string | number) => {
        setReports(prev => {
            const currentEntry = prev[name] || { horas: '', estudios: '', notas: '' };
            const newValue = (field === 'horas' || field === 'estudios') ? (value === '' ? '' : Number(value)) : value;
            return { ...prev, [name]: { ...currentEntry, [field]: newValue } };
        });
    };

    const handleRemoveReport = (name: string) => {
        setReports(prev => { const next = { ...prev }; delete next[name]; return next; });
    };

    const handleVisitChange = (name: string, field: keyof VisitData, value: string) => {
        setVisits(prev => {
            const currentEntry = prev[name] || { date: '', notes: '' };
            return { ...prev, [name]: { ...currentEntry, [field]: value } };
        });
    };

    const handleSaveRow = async (publisherName: string) => {
        setStatusMessage({ text: 'Guardando...', type: 'info' });
        try {
            const reportEntry = reports[publisherName];

            // Handle Ministry Report
            // First check if a report exists
            const { data: existingReport, error: fetchError } = await supabase
                .from('informes_ministerio')
                .select('id')
                .eq('publicador_nombre', publisherName)
                .eq('mes', currentMonth)
                .maybeSingle();

            if (fetchError) throw fetchError;

            if (reportEntry) {
                const reportData = { 
                    publicador_nombre: publisherName, 
                    mes: currentMonth, 
                    // Make hours optional: empty string becomes 0 or handled by DB default
                    horas: reportEntry.horas === '' ? 0 : reportEntry.horas,
                    // estudios: removed from payload
                    notas: reportEntry.notas || '' 
                };

                let error;
                let savedData;

                if (existingReport) {
                    const res = await supabase.from('informes_ministerio').update(reportData).eq('id', existingReport.id).select();
                    error = res.error;
                    savedData = res.data;
                } else {
                    const res = await supabase.from('informes_ministerio').insert([reportData]).select();
                    error = res.error;
                    savedData = res.data;
                }

                if (error) throw error;

                // Optimistically update local state with saved data to prevent UI flicker
                if (savedData && savedData.length > 0) {
                    const saved = savedData[0];
                    setReports(prev => ({
                        ...prev,
                        [publisherName]: {
                            ...prev[publisherName],
                            horas: saved.horas,
                            notas: saved.notas || '',
                            // Preserve local estudios
                            estudios: prev[publisherName]?.estudios || ''
                        }
                    }));
                }

            } else if (existingReport) {
                // If local report entry is removed/null but exists in DB, delete it
                const { error } = await supabase.from('informes_ministerio').delete().eq('id', existingReport.id);
                if (error) throw error;

                setReports(prev => {
                    const next = { ...prev };
                    delete next[publisherName];
                    return next;
                });
            }

            // Handle Pastoral Visits
            const visitData = visits[publisherName];
            if (visitData && (visitData.date || visitData.notes)) {
                const { data: existingVisit, error: visitFetchError } = await supabase.from('visitas_pastoral').select('id').eq('publicador_nombre', publisherName).maybeSingle();

                if (visitFetchError) throw visitFetchError;

                const visitPayload = { publicador_nombre: publisherName, fecha_visita: visitData.date, notas: visitData.notes };

                let visitError;
                if (existingVisit) {
                    const res = await supabase.from('visitas_pastoral').update(visitPayload).eq('id', existingVisit.id);
                    visitError = res.error;
                } else {
                    const res = await supabase.from('visitas_pastoral').insert([visitPayload]);
                    visitError = res.error;
                }

                if (visitError) throw visitError;
            }

            setStatusMessage({ text: 'Guardado correctamente', type: 'success' });

            // Background refresh to ensure consistency
            fetchReportData(); 

            setTimeout(() => setStatusMessage(null), 2000);
        } catch (error: any) {
            console.error("Error saving data:", error);
            setStatusMessage({ text: `Error: ${error.message || 'No se pudo guardar'}`, type: 'error' });
        }
    };

    const filteredMembers = members.filter(m => m.publicador_nombre.toLowerCase().includes(searchTerm.toLowerCase()));
    const filteredSuggestions = masterPublishers.filter(p => p.nombre.toLowerCase().includes(addSearchTerm.toLowerCase()) && !members.some(m => m.publicador_nombre === p.nombre)).slice(0, 6);

    const totalReports = members.length;
    const submittedReports = members.filter(m => reports[m.publicador_nombre] !== undefined).length;
    const pendingReports = totalReports - submittedReports;
    const totalHours = Object.values(reports).reduce((sum: number, r: MinistryReport) => sum + (Number(r.horas) || 0), 0);
    const totalStudies = Object.values(reports).reduce((sum: number, r: MinistryReport) => sum + (Number(r.estudios) || 0), 0);

    const handleSharePDF = async () => {
        if (!printRef.current) return;
        setIsSharing(true);

        // 1. Clonar el elemento de referencia
        const element = printRef.current.cloneNode(true) as HTMLElement;

        // 2. Crear un contenedor temporal en el body
        const container = document.createElement('div');
        // ESTILO CRÍTICO: Position Fixed en 0,0 para evitar desplazamientos por scroll
        container.style.position = 'fixed';
        container.style.top = '0';
        container.style.left = '0';
        container.style.zIndex = '99999'; // Encima de todo para que se vea durante la captura
        container.style.width = '210mm';
        container.style.minHeight = '297mm';
        container.style.background = '#ffffff';
        container.style.margin = '0';
        container.style.padding = '0';

        container.appendChild(element);
        document.body.appendChild(container);

        // 3. Forzar estilos en el clon para impresión
        element.style.display = 'block';
        element.style.width = '100%';
        element.style.height = 'auto';
        element.style.backgroundColor = '#ffffff';
        element.style.color = '#000000';

        // Forzar negro en todos los textos para evitar problemas con Dark Mode
        const allNodes = element.querySelectorAll('*');
        allNodes.forEach((node) => {
            if (node instanceof HTMLElement) {
                node.style.color = '#000000';
                node.style.borderColor = '#000000';
            }
        });

        // 4. Scroll al inicio para evitar offsets
        const scrollX = window.scrollX;
        const scrollY = window.scrollY;
        window.scrollTo(0, 0);

        // 5. Esperar un momento para asegurar el renderizado
        await new Promise(resolve => setTimeout(resolve, 500));

        const groupName = groups.find(g => g.id === selectedGroupId)?.nombre || 'Grupo';
        const opt = {
            margin: 0,
            filename: `Informe_${groupName}_${currentMonth}.pdf`,
            image: { type: 'jpeg', quality: 0.98 },
            html2canvas: { 
                scale: 2, 
                useCORS: true, 
                letterRendering: true,
                scrollY: 0, 
                scrollX: 0,
                x: 0, // Forzar coordenada X
                y: 0, // Forzar coordenada Y
                windowWidth: container.offsetWidth, // Usar ancho explícito
                windowHeight: container.offsetHeight
            },
            jsPDF: { unit: 'mm', format: 'a4', orientation: 'portrait' }
        };

        html2pdf().from(element).set(opt).save()
            .then(() => {
                if (document.body.contains(container)) document.body.removeChild(container);
                window.scrollTo(scrollX, scrollY); // Restaurar scroll
                setIsSharing(false);
            })
            .catch((err: any) => {
                console.error("PDF generation failed:", err);
                if (document.body.contains(container)) document.body.removeChild(container);
                window.scrollTo(scrollX, scrollY);
                setIsSharing(false);
                alert('Error al generar PDF. Por favor intente nuevamente.');
            });
    };

    const handleCopyText = () => {
        const groupName = groups.find(g => g.id === selectedGroupId)?.nombre || 'Grupo';
        let text = `*Informe ${groupName} - ${currentMonth}*\n`;
        text += `📊 Total: ${totalReports} | ✅ Entregados: ${submittedReports} | ⏳ Pendientes: ${pendingReports}\n\n`;
        filteredMembers.forEach(m => {
            const r = reports[m.publicador_nombre];
            if (r) text += `✅ ${m.publicador_nombre}: ${r.horas ? `${r.horas}h` : 'Predicó'}${r.estudios ? ` (${r.estudios} est.)` : ''}\n`;
            else text += `⏳ ${m.publicador_nombre}\n`;
        });
        navigator.clipboard.writeText(text).then(() => {
            setStatusMessage({ text: 'Copiado al portapapeles', type: 'success' });
            setTimeout(() => setStatusMessage(null), 3000);
        });
    };

    // Calculate members for 2 columns for PDF
    const pdfMembers = members; 
    const midPoint = Math.ceil(pdfMembers.length / 2);
    const col1 = pdfMembers.slice(0, midPoint);
    const col2 = pdfMembers.slice(midPoint);

    return (
        <div className="container mx-auto px-4 py-8 group-container relative bg-[var(--bg-color)] min-h-screen">
            <h1 style={{ fontSize: '1.8rem', fontWeight: '800', textAlign: 'center', marginBottom: '1.5rem', color: 'var(--primary-color)', textTransform: 'uppercase', letterSpacing: '0.5px' }}>Gestión del Grupo</h1>

            {editingMember && (
                <EditMemberModal 
                    member={editingMember}
                    reportEntry={reports[editingMember.publicador_nombre]}
                    visitData={visits[editingMember.publicador_nombre] || { date: '', notes: '' }}
                    onClose={() => setEditingMember(null)}
                    onReportChange={handleReportChange}
                    onVisitChange={handleVisitChange}
                    onSave={handleSaveRow}
                    onDelete={handleDeleteMember}
                    onRemoveReport={handleRemoveReport}
                />
            )}

            <div style={{ display: 'flex', flexDirection: 'column', gap: '20px', marginBottom: '25px' }}>
                {/* Stats */}
                <div style={{ display: 'flex', gap: '10px', overflowX: 'auto', paddingBottom: '5px' }}>
                    {[{l:'Total',v:totalReports,c:'#3b82f6'}, {l:'Listos',v:submittedReports,c:'#10b981'}, {l:'Faltan',v:pendingReports,c:'#f97316'}].map((s,i)=>(
                        <div key={i} style={{ flex: 1, minWidth: '90px', backgroundColor: s.c, borderRadius: '12px', padding: '15px', color: 'white', textAlign: 'center', boxShadow: '0 4px 6px rgba(0,0,0,0.1)' }}>
                            <div style={{ fontSize: '0.8rem', textTransform: 'uppercase', opacity: 0.8, fontWeight: 'bold' }}>{s.l}</div>
                            <div style={{ fontSize: '1.8rem', fontWeight: '900', lineHeight: 1 }}>{s.v}</div>
                        </div>
                    ))}
                </div>

                <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                    <div style={{ backgroundColor: 'var(--card-bg-color)', padding: '12px', borderRadius: '12px', borderLeft: '5px solid #3b82f6', boxShadow: 'var(--shadow)', display: 'flex', alignItems: 'center', gap: '12px' }}>
                        <div style={{ flex: 1 }}>
                            <label style={{ display: 'block', fontSize: '0.75rem', fontWeight: '700', color: 'var(--text-color-light)', textTransform: 'uppercase' }}>Grupo</label>
                            <select value={selectedGroupId || ''} onChange={(e) => setSelectedGroupId(Number(e.target.value))} style={{ width: '100%', fontSize: '1.1rem', fontWeight: 'bold', color: 'var(--text-color)', background: 'transparent', border: 'none', outline: 'none' }}>
                                {groups.map(g => <option key={g.id} value={g.id}>{g.nombre}</option>)}
                            </select>
                        </div>
                        <button onClick={() => setIsCreatingGroup(!isCreatingGroup)} style={{ color: 'var(--text-color-light)', padding: '5px' }}><i className="fas fa-plus-circle text-xl"></i></button>
                    </div>
                    <div style={{ backgroundColor: 'var(--card-bg-color)', padding: '12px', borderRadius: '12px', borderLeft: '5px solid #8b5cf6', boxShadow: 'var(--shadow)', display: 'flex', alignItems: 'center', gap: '12px' }}>
                        <div style={{ flex: 1 }}>
                            <label style={{ display: 'block', fontSize: '0.75rem', fontWeight: '700', color: 'var(--text-color-light)', textTransform: 'uppercase' }}>Mes</label>
                            <input type="month" value={currentMonth} onChange={(e) => setCurrentMonth(e.target.value)} style={{ width: '100%', fontSize: '1rem', fontWeight: 'bold', color: 'var(--text-color)', background: 'transparent', border: 'none', outline: 'none' }} />
                        </div>
                    </div>
                </div>

                {isCreatingGroup && (
                    <div className="flex gap-2 animate-fadeIn p-4 bg-blue-50 rounded-xl border border-blue-100">
