        <div style={{ padding: '10px', color: 'var(--text-color-light)' }}><i className="fas fa-search"></i></div>
        <div style={{ flex: 1, position: 'relative' }}>
            <input type="text" value={searchTerm} onChange={(e) => { onSearchChange(e.target.value); setShowSuggestions(true); }} placeholder="Buscar o escribir nombre..." style={{ width: '100%', padding: '10px 0', backgroundColor: 'transparent', border: 'none', color: 'var(--text-color)', outline: 'none', fontWeight: '500' }} />
            {showSuggestions && searchTerm && (
                <div className="absolute top-full left-0 right-0 bg-white border border-gray-100 rounded-xl mt-2 shadow-xl z-50 overflow-hidden text-gray-800">
                    {filteredSuggestions.map(p => (
                        <div key={p.id} onClick={() => { onAdd(p.nombre); setShowSuggestions(false); }} className="px-4 py-3 hover:bg-gray-50 cursor-pointer border-b border-gray-50 flex items-center gap-3">
                            <div style={{ backgroundColor: getAvatarColor(p.nombre) }} className="w-6 h-6 rounded-full flex items-center justify-center text-xs text-white font-bold">{p.nombre.charAt(0)}</div>
                            <span className="font-medium">{p.nombre}</span>
                        </div>
                    ))}
                    <div onClick={() => { onAdd(searchTerm); setShowSuggestions(false); }} className="px-4 py-3 bg-purple-50 hover:bg-purple-100 cursor-pointer flex items-center gap-3 text-purple-700">
                        <i className="fas fa-pen text-xs"></i><span className="font-semibold">Crear: "{searchTerm}"</span>
                    </div>
                </div>
            )}
        </div>
    </div>
);

