interface EditMemberModalProps {
    member: GroupMember;
    reportEntry: MinistryReport | undefined;
    visitData: VisitData;
    onClose: () => void;
    onReportChange: (name: string, field: keyof MinistryReport, value: string | number) => void;
    onVisitChange: (name: string, field: keyof VisitData, value: string) => void;
    onSave: (name: string) => void;
    onDelete: (id: number, name: string) => void;
    onRemoveReport: (name: string) => void;
}

const EditMemberModal: React.FC<EditMemberModalProps> = ({ member, reportEntry, visitData, onClose, onReportChange, onVisitChange, onSave, onDelete, onRemoveReport }) => {
    const pName = member.publicador_nombre;
    const [didPreach, setDidPreach] = useState<boolean>(
        reportEntry ? (reportEntry.horas !== '' || reportEntry.estudios !== '') : true
    );
    const hasReport = reportEntry !== undefined;

    useEffect(() => {
        if (reportEntry && ((reportEntry.horas !== '' && Number(reportEntry.horas) > 0) || (reportEntry.estudios !== '' && Number(reportEntry.estudios) > 0))) {
            setDidPreach(true);
        }
    }, [reportEntry]);

    const handleToggleActive = (e: React.ChangeEvent<HTMLInputElement>) => {
        if (e.target.checked) {
            onReportChange(pName, 'horas', '');
            setDidPreach(true);
        } else {
            onRemoveReport(pName);
        }
    };

    const handlePreachToggle = (e: React.ChangeEvent<HTMLInputElement>) => {
        setDidPreach(e.target.checked);
        if (!e.target.checked) {
            onReportChange(pName, 'horas', '');
