                            <h4 style={{ margin: 0, color: '#3b82f6', display: 'flex', alignItems: 'center', gap: '8px', fontSize: '1rem' }}><i className="fas fa-briefcase"></i> Informe del Mes</h4>
                            <label style={{ display: 'flex', alignItems: 'center', gap: '10px', cursor: 'pointer' }}>
                                <span style={{ fontSize: '0.85rem', color: hasReport ? '#3b82f6' : 'var(--text-color-light)', fontWeight: '600' }}>{hasReport ? 'Entregado' : 'Sin entregar'}</span>
                                <div style={{ position: 'relative', width: '44px', height: '24px' }}>
                                    <input type="checkbox" checked={hasReport} onChange={handleToggleActive} style={{ opacity: 0, width: 0, height: 0 }} />
                                    <span style={{ position: 'absolute', cursor: 'pointer', top: 0, left: 0, right: 0, bottom: 0, backgroundColor: hasReport ? '#3b82f6' : 'var(--border-color)', transition: '.4s', borderRadius: '34px' }}></span>
                                    <span style={{ position: 'absolute', content: '""', height: '18px', width: '18px', left: hasReport ? '22px' : '4px', bottom: '3px', backgroundColor: 'white', transition: '.4s', borderRadius: '50%', boxShadow: '0 2px 4px rgba(0,0,0,0.2)' }}></span>
