                            <div>
                                <label style={{ display: 'block', fontSize: '0.75rem', fontWeight:'700', color: 'var(--text-color-light)', marginBottom: '6px', textTransform:'uppercase' }}>Última Visita</label>
                                <input type="date" value={visitData.date} onChange={(e) => onVisitChange(pName, 'date', e.target.value)} style={{ width: '100%', padding: '12px', borderRadius: '10px', border: '1px solid var(--border-color)', backgroundColor:'var(--bg-color)', boxSizing: 'border-box', color:'var(--text-color)', fontWeight:'500' }} />
                            </div>
                            <div>
                                <label style={{ display: 'block', fontSize: '0.75rem', fontWeight:'700', color: 'var(--text-color-light)', marginBottom: '6px', textTransform:'uppercase' }}>Apuntes Privados</label>
                                <input type="text" value={visitData.notes || ''} onChange={(e) => onVisitChange(pName, 'notes', e.target.value)} style={{ width: '100%', padding: '12px', borderRadius: '10px', border: '1px solid var(--border-color)', backgroundColor:'var(--bg-color)', boxSizing: 'border-box', fontSize:'0.95rem', color: 'var(--text-color)' }} placeholder="Nota de visita..." />
                            </div>
                        </div>
                    </div>
                </div>
                <div style={{ padding: '15px 20px', borderTop: '1px solid var(--border-color)', display: 'flex', gap: '15px', backgroundColor:'var(--card-bg-color)' }}>
