import React, { useState, useEffect, useRef } from 'react';
import PrintTemplate from './PrintTemplate';
import { GroupMember, ReportsMap } from './types';

declare const html2pdf: any;
declare const html2canvas: any;

interface PreviewModalProps {
    onClose: () => void;
    groupName: string;
    month: string;
    stats: { total: number; submitted: number; noStudies: number };
    col1: GroupMember[];
    col2: GroupMember[];
    reports: ReportsMap;
}

const PreviewModal: React.FC<PreviewModalProps> = ({ onClose, groupName, month, stats, col1, col2, reports }) => {
    const [isProcessing, setIsProcessing] = useState(false);
    const [scale, setScale] = useState(1);
    const [contentHeight, setContentHeight] = useState(0);
    const [generatedFile, setGeneratedFile] = useState<File | null>(null);
    const containerRef = useRef<HTMLDivElement>(null);
    const contentRef = useRef<HTMLDivElement>(null);

    // Calculate scale on mount and resize to fit mobile screens
    useEffect(() => {
        const calculateScale = () => {
            if (containerRef.current && contentRef.current) {
                // A4 width in px (approx at 96 DPI is 794px for 210mm)
                // We add padding buffer (30px total) to ensure it doesn't touch edges
                const availableWidth = containerRef.current.offsetWidth - 30; 
                const contentWidth = 794; 

                // If screen is smaller than content, scale down. Max scale 1.
                const newScale = Math.min(1, availableWidth / contentWidth);
                setScale(newScale);

                // Capture height to adjust wrapper and prevent huge whitespace below transformed element
                setContentHeight(contentRef.current.offsetHeight);
            }
        };

        // Initial calculation with a small delay to ensure DOM render
        setTimeout(calculateScale, 100);

        window.addEventListener('resize', calculateScale);
        return () => window.removeEventListener('resize', calculateScale);
    }, []);

    const handleDownloadPDF = () => {
        setIsProcessing(true);
        const element = document.getElementById('print-preview-content');
        if (!element) return;

        // Clone to ensure we capture full size without scaling transforms affecting PDF
        const clone = element.cloneNode(true) as HTMLElement;
        const container = document.createElement('div');
        container.style.position = 'absolute';
        container.style.left = '-9999px';
        container.style.top = '0';
        container.style.width = '210mm'; // Ensure A4 width context
        container.appendChild(clone);
        document.body.appendChild(container);

        const opt = { 
            margin: 0, 
            filename: `Informe_${groupName.replace(/\s+/g, '_')}_${month}.pdf`, 
            image: { type: 'jpeg', quality: 0.98 }, 
            html2canvas: { scale: 2, useCORS: true }, 
            jsPDF: { unit: 'mm', format: 'a4', orientation: 'portrait' } 
        };

        html2pdf().from(clone).set(opt).save()
            .then(() => {
                document.body.removeChild(container);
                setIsProcessing(false);
            })
            .catch(() => {
                document.body.removeChild(container);
                setIsProcessing(false);
            });
    };

    const handleShareWhatsApp = async () => {
        // 1. If file is already generated, share immediately (User Gesture guaranteed here)
        if (generatedFile) {
            if (navigator.canShare && navigator.canShare({ files: [generatedFile] })) {
                try {
                    await navigator.share({
                        files: [generatedFile],
                        title: `Informe ${groupName}`,
                        text: `Resumen de actividad - ${month}`
                    });
                } catch (error) {
                    console.error("Error sharing:", error);
                }
            } else {
                const link = document.createElement('a');
                link.download = generatedFile.name;
                link.href = URL.createObjectURL(generatedFile);
                link.click();
            }
            return;
        }

        // 2. Otherwise, generate the file
        setIsProcessing(true);
        const element = document.getElementById('print-preview-content');
        if (!element || typeof html2canvas === 'undefined') {
            alert('Error: Librerías no cargadas.');
            setIsProcessing(false);
            return;
        }

        try {
            const clone = element.cloneNode(true) as HTMLElement;
            const container = document.createElement('div');

            container.style.position = 'fixed';
            container.style.left = '-9999px';
            container.style.top = '0';
            container.style.width = '210mm';
            container.style.zIndex = '-1000';
            container.style.backgroundColor = '#ffffff';

            container.appendChild(clone);
            document.body.appendChild(container);

            const canvas = await html2canvas(clone, { 
                scale: 3, 
                useCORS: true,
                backgroundColor: '#ffffff',
                logging: false,
                windowWidth: 794 
            });

            document.body.removeChild(container);

            const blob = await new Promise<Blob | null>(resolve => canvas.toBlob(resolve, 'image/png'));

            if (!blob) {
                setIsProcessing(false);
                return;
            }

            const file = new File([blob], `Informe_${month}.png`, { type: 'image/png' });
            setGeneratedFile(file);
            setIsProcessing(false);

            // 3. Try to share immediately. 
            if (navigator.canShare && navigator.canShare({ files: [file] })) {
                try {
                    await navigator.share({
                        files: [file],
                        title: `Informe ${groupName}`,
                        text: `Resumen de actividad - ${month}`
                    });
                } catch (error) {
                    console.log("Auto-share attempt finished.");
                }
            } else {
                const link = document.createElement('a');
                link.download = file.name;
                link.href = URL.createObjectURL(file);
                link.click();
                alert("Tu dispositivo no soporta compartir directamente. Se ha descargado la imagen.");
            }

        } catch (error) {
            console.error("Error generating image:", error);
            setIsProcessing(false);
        }
    };

    return (
        <div style={{ position: 'fixed', top: 0, left: 0, right: 0, bottom: 0, backgroundColor: 'rgba(20, 20, 20, 0.95)', zIndex: 10000, display: 'flex', flexDirection: 'column', padding: '10px' }}>

            {/* Toolbar */}
            <div style={{ width: '100%', display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '10px', color: 'white', padding: '0 10px' }}>
                <h2 style={{ margin: 0, fontSize: '1.1rem', fontWeight: 'bold' }}>Vista Previa</h2>
                <button onClick={onClose} style={{ background: 'rgba(255,255,255,0.15)', border: 'none', color: 'white', width: '36px', height: '36px', borderRadius: '50%', cursor: 'pointer', fontSize: '1.2rem', display: 'flex', alignItems: 'center', justifyContent: 'center' }}>&times;</button>
            </div>

            {/* Scrollable Preview Area */}
            <div ref={containerRef} style={{ flex: 1, overflowY: 'auto', overflowX: 'hidden', width: '100%', display: 'flex', flexDirection: 'column', alignItems: 'center', position: 'relative' }}>
                {/* 
                    Wrapper controls layout height based on scale to remove whitespace.
                    The inner div applies the scale transform.
                */}
                <div style={{ 
                    height: contentHeight > 0 ? `${contentHeight * scale}px` : 'auto', 
                    width: '100%', 
                    display: 'flex', 
                    justifyContent: 'center',
                    marginBottom: '20px',
                    transition: 'height 0.2s ease'
                }}>
                    <div ref={contentRef} style={{ 
                        transform: `scale(${scale})`, 
                        transformOrigin: 'top center',
                        boxShadow: '0 10px 30px rgba(0,0,0,0.5)',
                        backgroundColor: 'white' 
                    }}>
                        <PrintTemplate 
                            elementId="print-preview-content"
                            groupName={groupName} 
                            month={month} 
                            stats={stats} 
                            col1={col1} 
                            col2={col2} 
                            reports={reports} 
                        />
                    </div>
                </div>
            </div>

            {/* Actions */}
            <div style={{ width: '100%', padding: '10px', display: 'flex', gap: '10px', justifyContent: 'center', backgroundColor: 'rgba(0,0,0,0.2)', borderRadius: '12px' }}>
                <button 
                    onClick={handleDownloadPDF} 
                    disabled={isProcessing}
                    style={{ flex: 1, maxWidth: '200px', padding: '12px', borderRadius: '10px', border: 'none', backgroundColor: '#ef4444', color: 'white', fontWeight: 'bold', fontSize: '0.9rem', cursor: 'pointer', display: 'flex', alignItems: 'center', justifyContent: 'center', gap: '6px' }}
                >
                    {isProcessing ? <i className="fas fa-spinner fa-spin"></i> : <i className="fas fa-file-pdf"></i>}
                    PDF
                </button>
                <button 
                    onClick={handleShareWhatsApp} 
                    disabled={isProcessing}
                    style={{ flex: 1, maxWidth: '200px', padding: '12px', borderRadius: '10px', border: 'none', backgroundColor: '#25D366', color: 'white', fontWeight: 'bold', fontSize: '0.9rem', cursor: 'pointer', display: 'flex', alignItems: 'center', justifyContent: 'center', gap: '6px' }}
                >
                    {isProcessing 
                        ? <><i className="fas fa-spinner fa-spin"></i> Generando...</>
                        : generatedFile 
                            ? <><i className="fas fa-paper-plane"></i> Enviar Ahora</>
                            : <><i className="fab fa-whatsapp"></i> WhatsApp</>
                    }
                </button>
            </div>
        </div>
    );
};

