export default MemberItem;

import { useState, useEffect, useCallback } from 'react';
import { supabase } from '../../lib/supabase';
import { Group, GroupMember, Publisher, MinistryReport, VisitData, ReportsMap, VisitsMap } from './types';

export const useGroupManager = () => {
    const [groups, setGroups] = useState<Group[]>([]);
    const [selectedGroupId, setSelectedGroupId] = useState<number | null>(null);
    const [members, setMembers] = useState<GroupMember[]>([]);
    const [masterPublishers, setMasterPublishers] = useState<Publisher[]>([]);
    const [reports, setReports] = useState<ReportsMap>({});
    const [visits, setVisits] = useState<VisitsMap>({});
    const [loading, setLoading] = useState(true);
    const [currentMonth, setCurrentMonth] = useState<string>('');
    const [statusMessage, setStatusMessage] = useState<{ text: string; type: 'success' | 'error' | 'info' } | null>(null);

    // Initial Load
    useEffect(() => {
        const now = new Date();
        const prevMonthDate = new Date(now.getFullYear(), now.getMonth() - 1, 1);

        const yyyy = prevMonthDate.getFullYear();
        const mm = String(prevMonthDate.getMonth() + 1).padStart(2, '0');
        setCurrentMonth(`${yyyy}-${mm}`);

        fetchGroups();
        fetchMasterPublishers();
    }, []);

    // Load Data
    const fetchGroups = async () => {
        try {
            const { data, error } = await supabase.from('grupos').select('*').order('nombre');
            if (error) throw error;
            if (data) {
                setGroups(data);
                if (data.length > 0 && !selectedGroupId) {
                    const defaultGroup = data.find(g => g.nombre.includes('5')) || data[0];
                    setSelectedGroupId(defaultGroup.id);
                }
            }
        } catch (e: any) {
            console.error("Error fetching groups:", e);
            setStatusMessage({ text: `Error grupos: ${e.message || JSON.stringify(e)}`, type: 'error' });
        }
    };

    const fetchMasterPublishers = async () => {
        try {
            const { data, error } = await supabase.from('publicadores').select('id, nombre').order('nombre');
            if (error) throw error;
            if (data) setMasterPublishers(data);
        } catch (e: any) {
            console.error("Error fetching publishers:", e);
        }
    };

    const fetchMembers = useCallback(async () => {
        if (!selectedGroupId) return;
        setLoading(true);
        try {
            const { data, error } = await supabase.from('miembros_grupo').select('*').eq('grupo_id', selectedGroupId).order('publicador_nombre');
            if (error) throw error;
            const validMembers = (data || []).filter((m: any) => m.publicador_nombre && typeof m.publicador_nombre === 'string');
            setMembers(validMembers);
        } catch (e: any) {
            console.error("Error fetching members:", e);
            setStatusMessage({ text: `Error miembros: ${e.message || JSON.stringify(e)}`, type: 'error' });
        } finally {
            setLoading(false);
        }
    }, [selectedGroupId]);

    useEffect(() => { fetchMembers(); }, [fetchMembers]);

    const fetchReportData = useCallback(async () => {
        if (!currentMonth || members.length === 0) return;

        // Debug info to console
        console.log(`[Debug] Fetching data. Month: "${currentMonth}", Members Count: ${members.length}`);

        try {
            const memberNames = members.map(m => m.publicador_nombre).filter(Boolean);
            if (memberNames.length === 0) {
                console.warn("[Debug] No valid member names to fetch.");
                return;
            }

            // 1. REPORTS QUERY
            const { data: reportsData, error: reportsError } = await supabase
                .from('informes_ministerio')
                .select('*')
                .eq('mes', currentMonth)
                .in('publicador_nombre', memberNames);

            if (reportsError) {
                console.error("[Supabase Reports Error]", reportsError);
                throw new Error(`DB Reports: ${reportsError.message} (${reportsError.code})`);
            }

            const newReports: ReportsMap = {};
            if (reportsData) {
                reportsData.forEach((r: any) => { 
                    if (!r.publicador_nombre) return;

                    let estudiosVal: number | '' = '';
                    let notasVal = r.notas || '';

                    if (r.estudios !== undefined && r.estudios !== null) {
                        estudiosVal = r.estudios;
                    } else {
                        const match = notasVal.match(/\{\{estudios:(\d+)\}\}/);
                        if (match) {
                            estudiosVal = parseInt(match[1], 10);
                            notasVal = notasVal.replace(match[0], '').trim();
                        }
                    }

                    newReports[r.publicador_nombre] = { 
                        horas: (r.horas !== null && r.horas !== undefined) ? r.horas : '', 
                        estudios: (estudiosVal !== null && estudiosVal !== undefined) ? estudiosVal : '',
                        notas: notasVal 
                    }; 
                });
            }

            setReports(prev => {
                const next = { ...prev };
                memberNames.forEach(name => {
                    if (newReports[name]) next[name] = newReports[name];
                    else delete next[name];
                });
                return next;
            });

            // 2. VISITS QUERY
            const { data: visitsData, error: visitsError } = await supabase
                .from('visitas_pastoral')
                .select('publicador_nombre, fecha_visita, notas')
                .in('publicador_nombre', memberNames);

            if (visitsError) {
                console.error("[Supabase Visits Error]", visitsError);
                throw new Error(`DB Visits: ${visitsError.message}`);
            }

            const newVisits: VisitsMap = {};
            if (visitsData) {
                visitsData.forEach((v: any) => { 
                    if (v.publicador_nombre) {
                        newVisits[v.publicador_nombre] = { date: v.fecha_visita, notes: v.notas || '' }; 
                    }
                });
            }
            setVisits(newVisits);

        } catch (e: any) {
            console.error("CRITICAL FETCH ERROR:", e);
            // Show detailed error in UI so user can report it
            setStatusMessage({ 
                text: `Error de carga: ${e.message || 'Desconocido'}. Revise consola.`, 
                type: 'error' 
            });
        }
    }, [currentMonth, members]);

    useEffect(() => { fetchReportData(); }, [fetchReportData]);

    // Actions
    const createGroup = async (name: string) => {
        if (!name.trim()) return;
        const { data, error } = await supabase.from('grupos').insert([{ nombre: name.trim() }]).select();
        if (!error && data) {
            setGroups(prev => [...prev, data[0]].sort((a,b) => a.nombre.localeCompare(b.nombre)));
            setSelectedGroupId(data[0].id);
            return true;
        } else if (error) {
            setStatusMessage({ text: `Error crear grupo: ${error.message}`, type: 'error' });
        }
        return false;
    };

    const addMember = async (name: string) => {
        if (!selectedGroupId || !name.trim()) return;
        const { error } = await supabase.from('miembros_grupo').insert([{ grupo_id: selectedGroupId, publicador_nombre: name.trim() }]);
        if (error) setStatusMessage({ text: `Error añadir: ${error.message}`, type: 'error' });
        else fetchMembers();
    };

    const deleteMember = async (id: number) => {
        const { error } = await supabase.from('miembros_grupo').delete().eq('id', id);
        if (error) setStatusMessage({ text: `Error borrar: ${error.message}`, type: 'error' });
        else fetchMembers();
    };

    const saveRow = async (publisherName: string) => {
        setStatusMessage({ text: 'Guardando...', type: 'info' });
        try {
            const reportEntry = reports[publisherName];

            const { data: existingReport, error: fetchError } = await supabase.from('informes_ministerio').select('id').eq('publicador_nombre', publisherName).eq('mes', currentMonth).maybeSingle();
            if (fetchError) throw new Error(`FetchCheck: ${fetchError.message}`);

            if (reportEntry) {
                const reportData = { 
                    publicador_nombre: publisherName, 
                    mes: currentMonth, 
                    horas: reportEntry.horas === '' ? 0 : reportEntry.horas, 
                    estudios: reportEntry.estudios === '' ? 0 : reportEntry.estudios,
                    notas: reportEntry.notas || '' 
                };

                // Fallback logic handled implicitly by Supabase usually, but if columns missing, we try-catch the specific insert
                let query = existingReport 
                    ? supabase.from('informes_ministerio').update(reportData).eq('id', existingReport.id).select()
                    : supabase.from('informes_ministerio').insert([reportData]).select();

                let { data: savedData, error } = await query;

                if (error) {
                    // Try fallback if 'estudios' column missing
                    if (error.message && error.message.includes('estudios')) {
                        console.warn("Fallback save triggered");
                        let fallbackNotes = reportData.notas;
                        if (reportData.estudios > 0) {
                            fallbackNotes = `${fallbackNotes} {{estudios:${reportData.estudios}}}`.trim();
                        }
                        const fallbackData = { ...reportData, notas: fallbackNotes };
                        delete (fallbackData as any).estudios;

                        query = existingReport 
                            ? supabase.from('informes_ministerio').update(fallbackData).eq('id', existingReport.id).select()
                            : supabase.from('informes_ministerio').insert([fallbackData]).select();

                        const retry = await query;
                        savedData = retry.data;
                        error = retry.error;
                    }
                }

                if (error) throw new Error(`SaveReport: ${error.message}`);

                if (savedData && savedData.length > 0) {
                    let returnedNotes = savedData[0].notas || '';
                    const match = returnedNotes.match(/\{\{estudios:(\d+)\}\}/);
                    if (match) returnedNotes = returnedNotes.replace(match[0], '').trim();

                    setReports(prev => ({ 
                        ...prev, 
                        [publisherName]: { 
                            ...prev[publisherName], 
                            horas: savedData[0].horas, 
                            estudios: reportEntry.estudios,
                            notas: returnedNotes
                        } 
                    }));
                }
            } else if (existingReport) {
                const { error: delError } = await supabase.from('informes_ministerio').delete().eq('id', existingReport.id);
                if (delError) throw new Error(`DelReport: ${delError.message}`);
                setReports(prev => { const n = { ...prev }; delete n[publisherName]; return n; });
            }

            const visitData = visits[publisherName];
            if (visitData && (visitData.date || visitData.notes)) {
                const { data: existingVisit, error: vCheckErr } = await supabase.from('visitas_pastoral').select('id').eq('publicador_nombre', publisherName).maybeSingle();
                if (vCheckErr) throw new Error(`CheckVisit: ${vCheckErr.message}`);

                const visitPayload = { publicador_nombre: publisherName, fecha_visita: visitData.date, notas: visitData.notes };
                const query = existingVisit
                    ? supabase.from('visitas_pastoral').update(visitPayload).eq('id', existingVisit.id)
                    : supabase.from('visitas_pastoral').insert([visitPayload]);
                const { error: vSaveErr } = await query;
                if (vSaveErr) throw new Error(`SaveVisit: ${vSaveErr.message}`);
            }

            setStatusMessage({ text: 'Guardado correctamente', type: 'success' });
            setTimeout(() => setStatusMessage(null), 2000);
        } catch (error: any) {
            console.error("Save Error Details:", error);
            setStatusMessage({ text: `Error al guardar: ${error.message}`, type: 'error' });
        }
    };

    const updateLocalReport = (name: string, field: keyof MinistryReport, value: string | number) => {
        setReports(prev => {
            const currentEntry = prev[name] || { horas: '', estudios: '', notas: '' };
            const newValue = (field === 'horas' || field === 'estudios') ? (value === '' ? '' : Number(value)) : value;
            return { ...prev, [name]: { ...currentEntry, [field]: newValue } };
        });
    };

    const removeLocalReport = (name: string) => {
        setReports(prev => { const next = { ...prev }; delete next[name]; return next; });
    };

    const updateLocalVisit = (name: string, field: keyof VisitData, value: string) => {
        setVisits(prev => {
            const currentEntry = prev[name] || { date: '', notes: '' };
            return { ...prev, [name]: { ...currentEntry, [field]: value } };
        });
    };

    return {
        groups, selectedGroupId, setSelectedGroupId, createGroup,
        members, masterPublishers, addMember, deleteMember,
        reports, visits, currentMonth, setCurrentMonth,
        loading, statusMessage,
        updateLocalReport, removeLocalReport, updateLocalVisit, saveRow
    };
};

import React, { useState, useEffect, useRef, useMemo } from 'react';
import { useGroupManager } from './congregation/useGroupManager';
import { GroupMember, MinistryReport } from './congregation/types';
import StatCards from './congregation/StatCards';
import ControlPanel from './congregation/ControlPanel';
import ActionButtons from './congregation/ActionButtons';
import AddMemberInput from './congregation/AddMemberInput';
import MemberItem from './congregation/MemberItem';
import EditMemberModal from './congregation/EditMemberModal';
import PreviewModal from './congregation/PreviewModal';

const GrupoCongregacion: React.FC = () => {
    // Logic extraction
    const { 
        groups, selectedGroupId, setSelectedGroupId, createGroup,
        members, masterPublishers, addMember, deleteMember,
        reports, visits, currentMonth, setCurrentMonth,
        loading, statusMessage, updateLocalReport, removeLocalReport, updateLocalVisit, saveRow 
    } = useGroupManager();

    // UI Local State
    const [searchTerm, setSearchTerm] = useState('');
    const [addSearchTerm, setAddSearchTerm] = useState('');
    const [showSuggestions, setShowSuggestions] = useState(false);
    const [isCreatingGroup, setIsCreatingGroup] = useState(false);
    const [newGroupName, setNewGroupName] = useState('');
    const [showPreview, setShowPreview] = useState(false);
    const [editingMember, setEditingMember] = useState<GroupMember | null>(null);

    const suggestionsRef = useRef<HTMLDivElement>(null);

    useEffect(() => {
        const handleClickOutside = (event: MouseEvent) => {
            if (suggestionsRef.current && !suggestionsRef.current.contains(event.target as Node)) setShowSuggestions(false);
        };
        document.addEventListener('mousedown', handleClickOutside);
        return () => document.removeEventListener('mousedown', handleClickOutside);
    }, []);

    const handleCreateGroup = async () => {
        if (await createGroup(newGroupName)) {
            setIsCreatingGroup(false);
            setNewGroupName('');
        }
    };

    const handleAddMember = (name: string) => {
        addMember(name);
        setAddSearchTerm('');
    };

    const handleDeleteMember = (id: number, name: string) => {
        deleteMember(id);
        if(editingMember?.id === id) setEditingMember(null);
    };

    // Filter Logic - Added check for m.publicador_nombre being defined
    const filteredMembers = useMemo(() => members.filter(m => m.publicador_nombre && m.publicador_nombre.toLowerCase().includes(searchTerm.toLowerCase())), [members, searchTerm]);
    const filteredSuggestions = useMemo(() => masterPublishers.filter(p => p.nombre.toLowerCase().includes(addSearchTerm.toLowerCase()) && !members.some(m => m.publicador_nombre === p.nombre)).slice(0, 6), [masterPublishers, addSearchTerm, members]);

    // Calculations
    const submittedReports = members.filter(m => reports[m.publicador_nombre] !== undefined).length;

    // Count publishers who do NOT have a study (either no report, or report with 0/empty studies)
    const noStudiesCount = members.filter(m => {
        const r = reports[m.publicador_nombre];
        return !r || !r.estudios || r.estudios === 0 || r.estudios === '';
    }).length;

    // Open Preview
    const handleOpenPreview = () => {
        setShowPreview(true);
    };

    const handleCopyText = () => {
        const groupName = groups.find(g => g.id === selectedGroupId)?.nombre || 'Grupo';
        let text = `*Informe ${groupName} - ${currentMonth}*\n📊 Total: ${members.length} | ✅ Listos: ${submittedReports} | 📉 Sin Est.: ${noStudiesCount}\n\n`;
        filteredMembers.forEach(m => {
            const r = reports[m.publicador_nombre];
            text += r ? `✅ ${m.publicador_nombre}: ${r.horas ? `${r.horas}h` : 'Predicó'}${r.estudios ? ` (${r.estudios} est.)` : ''}\n` : `⏳ ${m.publicador_nombre}\n`;
        });
        navigator.clipboard.writeText(text);
    };

    // Columns for PDF
    const midPoint = Math.ceil(members.length / 2);

    return (
        <div className="container mx-auto px-4 py-8 group-container relative bg-[var(--bg-color)] min-h-screen">
            <h1 style={{ fontSize: '1.8rem', fontWeight: '800', textAlign: 'center', marginBottom: '1.5rem', color: 'var(--primary-color)', textTransform: 'uppercase', letterSpacing: '0.5px' }}>Gestión del Grupo</h1>

            {editingMember && (
                <EditMemberModal 
                    member={editingMember}
                    reportEntry={reports[editingMember.publicador_nombre]}
                    visitData={visits[editingMember.publicador_nombre] || { date: '', notes: '' }}
                    onClose={() => setEditingMember(null)}
                    onReportChange={updateLocalReport}
                    onVisitChange={updateLocalVisit}
                    onSave={saveRow}
                    onDelete={handleDeleteMember}
                    onRemoveReport={removeLocalReport}
                />
            )}

            {showPreview && (
                <PreviewModal 
                    onClose={() => setShowPreview(false)}
                    groupName={groups.find(g => g.id === selectedGroupId)?.nombre || ''}
                    month={currentMonth}
                    stats={{total: members.length, submitted: submittedReports, noStudies: noStudiesCount}}
                    col1={members.slice(0, midPoint)} 
                    col2={members.slice(midPoint)} 
                    reports={reports}
                />
            )}

            <div style={{ display: 'flex', flexDirection: 'column', gap: '20px', marginBottom: '25px' }}>
                <StatCards total={members.length} submitted={submittedReports} noStudies={noStudiesCount} />
                <ControlPanel 
                    groups={groups} selectedGroupId={selectedGroupId} onGroupChange={setSelectedGroupId}
                    currentMonth={currentMonth} onMonthChange={setCurrentMonth}
                    isCreating={isCreatingGroup} setIsCreating={setIsCreatingGroup}
                    newGroupName={newGroupName} setNewGroupName={setNewGroupName} onCreateGroup={handleCreateGroup}
                />
                {selectedGroupId && <ActionButtons onSharePDF={handleOpenPreview} onCopy={handleCopyText} isSharing={false} />}
                {selectedGroupId && (
                    <AddMemberInput 
                        searchTerm={addSearchTerm} onSearchChange={setAddSearchTerm} 
                        showSuggestions={showSuggestions} setShowSuggestions={setShowSuggestions}
                        filteredSuggestions={filteredSuggestions} onAdd={handleAddMember}
                    />
                )}
            </div>

            {loading ? <div style={{ textAlign: 'center', padding: '5rem 0', color: 'var(--text-color-light)' }}>Cargando...</div> : (
                <div className="rounded-2xl shadow-xl overflow-hidden border border-[var(--border-color)] bg-[var(--card-bg-color)]">
                    <div className="p-4 border-b border-[var(--border-color)] flex justify-between items-center lg:hidden bg-[var(--light-gray)]">
                        <h3 className="font-bold text-[var(--text-color)]">Listado ({filteredMembers.length})</h3>
                    </div>
                    {filteredMembers.map(m => (
                        <MemberItem key={m.id} member={m} report={reports[m.publicador_nombre]} onClick={() => setEditingMember(m)} />
                    ))}
                    {filteredMembers.length === 0 && <div style={{ padding: '3rem', textAlign: 'center', color: 'var(--text-color-light)' }}>Grupo vacío</div>}
                </div>
            )}

            {statusMessage && (
                <div style={{ 
                    position: 'fixed', 
                    bottom: '20px', 
                    right: '20px', 
                    left: '20px', 
                    backgroundColor: statusMessage.type === 'error' ? '#ef4444' : '#10b981', 
                    color: 'white', 
                    padding: '16px 20px', 
                    borderRadius: '12px', 
                    boxShadow: '0 10px 25px -5px rgba(0,0,0,0.3)', 
                    fontWeight: 'bold', 
                    zIndex: 1000,
                    maxWidth: '400px',
                    marginLeft: 'auto',
                    marginRight: 'auto',
                    textAlign: 'center',
                    wordBreak: 'break-word',
                    fontSize: '0.9rem'
                }}>
                    {statusMessage.text}
                </div>
            )}
        </div>
    );
};

export default GrupoCongregacion;

import { useState, useEffect, useCallback } from 'react';
import { supabase } from '../../lib/supabase';
import { Group, GroupMember, Publisher, MinistryReport, VisitData, ReportsMap, VisitsMap } from './types';

export const useGroupManager = () => {
    const [groups, setGroups] = useState<Group[]>([]);
    const [selectedGroupId, setSelectedGroupId] = useState<number | null>(null);
    const [members, setMembers] = useState<GroupMember[]>([]);
    const [masterPublishers, setMasterPublishers] = useState<Publisher[]>([]);
    const [reports, setReports] = useState<ReportsMap>({});
    const [visits, setVisits] = useState<VisitsMap>({});
    const [loading, setLoading] = useState(true);
    const [currentMonth, setCurrentMonth] = useState<string>('');
    const [statusMessage, setStatusMessage] = useState<{ text: string; type: 'success' | 'error' | 'info' } | null>(null);

    // Initial Load
    useEffect(() => {
        const now = new Date();
        const prevMonthDate = new Date(now.getFullYear(), now.getMonth() - 1, 1);

        const yyyy = prevMonthDate.getFullYear();
        const mm = String(prevMonthDate.getMonth() + 1).padStart(2, '0');
        setCurrentMonth(`${yyyy}-${mm}`);

        fetchGroups();
        fetchMasterPublishers();
    }, []);

    // Load Data
    const fetchGroups = async () => {
        try {
            const { data, error } = await supabase.from('grupos').select('*').order('nombre');
            if (error) throw error;
            if (data) {
                setGroups(data);
                if (data.length > 0 && !selectedGroupId) {
                    const defaultGroup = data.find(g => g.nombre.includes('5')) || data[0];
                    setSelectedGroupId(defaultGroup.id);
                }
            }
        } catch (e: any) {
            console.error("Error fetching groups:", e);
            setStatusMessage({ text: `Error grupos: ${e.message || JSON.stringify(e)}`, type: 'error' });
        }
    };

    const fetchMasterPublishers = async () => {
        try {
            const { data, error } = await supabase.from('publicadores').select('id, nombre').order('nombre');
            if (error) throw error;
            if (data) setMasterPublishers(data);
        } catch (e: any) {
            console.error("Error fetching publishers:", e);
        }
    };

    const fetchMembers = useCallback(async () => {
        if (!selectedGroupId) return;
        setLoading(true);
        try {
            const { data, error } = await supabase.from('miembros_grupo').select('*').eq('grupo_id', selectedGroupId).order('publicador_nombre');
            if (error) throw error;
            const validMembers = (data || []).filter((m: any) => m.publicador_nombre && typeof m.publicador_nombre === 'string');
            setMembers(validMembers);
        } catch (e: any) {
            console.error("Error fetching members:", e);
            setStatusMessage({ text: `Error miembros: ${e.message || JSON.stringify(e)}`, type: 'error' });
        } finally {
            setLoading(false);
        }
    }, [selectedGroupId]);

    useEffect(() => { fetchMembers(); }, [fetchMembers]);

    const fetchReportData = useCallback(async () => {
        if (!currentMonth || members.length === 0) return;

        // Debug info to console
        console.log(`[Debug] Fetching data. Month: "${currentMonth}", Members Count: ${members.length}`);

        try {
            const memberNames = members.map(m => m.publicador_nombre).filter(Boolean);
            if (memberNames.length === 0) {
                console.warn("[Debug] No valid member names to fetch.");
                return;
            }

            // 1. REPORTS QUERY
            const { data: reportsData, error: reportsError } = await supabase
                .from('informes_ministerio')
                .select('*')
                .eq('mes', currentMonth)
                .in('publicador_nombre', memberNames);

            if (reportsError) {
                console.error("[Supabase Reports Error]", reportsError);
                throw new Error(`DB Reports: ${reportsError.message} (${reportsError.code})`);
            }

            const newReports: ReportsMap = {};
            if (reportsData) {
                reportsData.forEach((r: any) => { 
                    if (!r.publicador_nombre) return;

                    let estudiosVal: number | '' = '';
                    let notasVal = r.notas || '';

                    if (r.estudios !== undefined && r.estudios !== null) {
                        estudiosVal = r.estudios;
                    } else {
                        const match = notasVal.match(/\{\{estudios:(\d+)\}\}/);
                        if (match) {
                            estudiosVal = parseInt(match[1], 10);
                            notasVal = notasVal.replace(match[0], '').trim();
                        }
                    }

                    newReports[r.publicador_nombre] = { 
                        horas: (r.horas !== null && r.horas !== undefined) ? r.horas : '', 
                        estudios: (estudiosVal !== null && estudiosVal !== undefined) ? estudiosVal : '',
                        notas: notasVal 
                    }; 
                });
            }

            setReports(prev => {
                const next = { ...prev };
                memberNames.forEach(name => {
                    if (newReports[name]) next[name] = newReports[name];
                    else delete next[name];
                });
                return next;
            });

            // 2. VISITS QUERY
            const { data: visitsData, error: visitsError } = await supabase
                .from('visitas_pastoral')
                .select('publicador_nombre, fecha_visita, notas')
                .in('publicador_nombre', memberNames);

            if (visitsError) {
                console.error("[Supabase Visits Error]", visitsError);
                throw new Error(`DB Visits: ${visitsError.message}`);
            }

            const newVisits: VisitsMap = {};
            if (visitsData) {
                visitsData.forEach((v: any) => { 
                    if (v.publicador_nombre) {
                        newVisits[v.publicador_nombre] = { date: v.fecha_visita, notes: v.notas || '' }; 
                    }
                });
            }
            setVisits(newVisits);

        } catch (e: any) {
            console.error("CRITICAL FETCH ERROR:", e);
            // Show detailed error in UI so user can report it
            setStatusMessage({ 
                text: `Error de carga: ${e.message || 'Desconocido'}. Revise consola.`, 
                type: 'error' 
            });
        }
    }, [currentMonth, members]);

    useEffect(() => { fetchReportData(); }, [fetchReportData]);

    // Actions
    const createGroup = async (name: string) => {
        if (!name.trim()) return;
        const { data, error } = await supabase.from('grupos').insert([{ nombre: name.trim() }]).select();
        if (!error && data) {
            setGroups(prev => [...prev, data[0]].sort((a,b) => a.nombre.localeCompare(b.nombre)));
            setSelectedGroupId(data[0].id);
            return true;
        } else if (error) {
            setStatusMessage({ text: `Error crear grupo: ${error.message}`, type: 'error' });
        }
        return false;
    };

    const addMember = async (name: string) => {
        if (!selectedGroupId || !name.trim()) return;
        const { error } = await supabase.from('miembros_grupo').insert([{ grupo_id: selectedGroupId, publicador_nombre: name.trim() }]);
        if (error) setStatusMessage({ text: `Error añadir: ${error.message}`, type: 'error' });
        else fetchMembers();
    };

    const deleteMember = async (id: number) => {
        const { error } = await supabase.from('miembros_grupo').delete().eq('id', id);
        if (error) setStatusMessage({ text: `Error borrar: ${error.message}`, type: 'error' });
        else fetchMembers();
    };

    const saveRow = async (publisherName: string) => {
        setStatusMessage({ text: 'Guardando...', type: 'info' });
        try {
            const reportEntry = reports[publisherName];

            const { data: existingReport, error: fetchError } = await supabase.from('informes_ministerio').select('id').eq('publicador_nombre', publisherName).eq('mes', currentMonth).maybeSingle();
            if (fetchError) throw new Error(`FetchCheck: ${fetchError.message}`);

            if (reportEntry) {
                const reportData = { 
                    publicador_nombre: publisherName, 
                    mes: currentMonth, 
                    horas: reportEntry.horas === '' ? 0 : reportEntry.horas, 
                    estudios: reportEntry.estudios === '' ? 0 : reportEntry.estudios,
                    notas: reportEntry.notas || '' 
                };

                // Fallback logic handled implicitly by Supabase usually, but if columns missing, we try-catch the specific insert
                let query = existingReport 
                    ? supabase.from('informes_ministerio').update(reportData).eq('id', existingReport.id).select()
                    : supabase.from('informes_ministerio').insert([reportData]).select();

                let { data: savedData, error } = await query;

                if (error) {
                    // Try fallback if 'estudios' column missing
                    if (error.message && error.message.includes('estudios')) {
                        console.warn("Fallback save triggered");
                        let fallbackNotes = reportData.notas;
                        if (reportData.estudios > 0) {
                            fallbackNotes = `${fallbackNotes} {{estudios:${reportData.estudios}}}`.trim();
                        }
                        const fallbackData = { ...reportData, notas: fallbackNotes };
                        delete (fallbackData as any).estudios;

                        query = existingReport 
                            ? supabase.from('informes_ministerio').update(fallbackData).eq('id', existingReport.id).select()
                            : supabase.from('informes_ministerio').insert([fallbackData]).select();

                        const retry = await query;
                        savedData = retry.data;
                        error = retry.error;
                    }
                }

                if (error) throw new Error(`SaveReport: ${error.message}`);

                if (savedData && savedData.length > 0) {
                    let returnedNotes = savedData[0].notas || '';
                    const match = returnedNotes.match(/\{\{estudios:(\d+)\}\}/);
                    if (match) returnedNotes = returnedNotes.replace(match[0], '').trim();

                    setReports(prev => ({ 
                        ...prev, 
                        [publisherName]: { 
                            ...prev[publisherName], 
                            horas: savedData[0].horas, 
                            estudios: reportEntry.estudios,
                            notas: returnedNotes
                        } 
                    }));
                }
            } else if (existingReport) {
                const { error: delError } = await supabase.from('informes_ministerio').delete().eq('id', existingReport.id);
                if (delError) throw new Error(`DelReport: ${delError.message}`);
                setReports(prev => { const n = { ...prev }; delete n[publisherName]; return n; });
            }

            const visitData = visits[publisherName];
            if (visitData && (visitData.date || visitData.notes)) {
                const { data: existingVisit, error: vCheckErr } = await supabase.from('visitas_pastoral').select('id').eq('publicador_nombre', publisherName).maybeSingle();
                if (vCheckErr) throw new Error(`CheckVisit: ${vCheckErr.message}`);

                const visitPayload = { publicador_nombre: publisherName, fecha_visita: visitData.date, notas: visitData.notes };
                const query = existingVisit
                    ? supabase.from('visitas_pastoral').update(visitPayload).eq('id', existingVisit.id)
                    : supabase.from('visitas_pastoral').insert([visitPayload]);
                const { error: vSaveErr } = await query;
                if (vSaveErr) throw new Error(`SaveVisit: ${vSaveErr.message}`);
            }

            setStatusMessage({ text: 'Guardado correctamente', type: 'success' });
            setTimeout(() => setStatusMessage(null), 2000);
        } catch (error: any) {
            console.error("Save Error Details:", error);
            setStatusMessage({ text: `Error al guardar: ${error.message}`, type: 'error' });
        }
    };

    const updateLocalReport = (name: string, field: keyof MinistryReport, value: string | number) => {
        setReports(prev => {
            const currentEntry = prev[name] || { horas: '', estudios: '', notas: '' };
            const newValue = (field === 'horas' || field === 'estudios') ? (value === '' ? '' : Number(value)) : value;
            return { ...prev, [name]: { ...currentEntry, [field]: newValue } };
        });
    };

    const removeLocalReport = (name: string) => {
        setReports(prev => { const next = { ...prev }; delete next[name]; return next; });
    };

    const updateLocalVisit = (name: string, field: keyof VisitData, value: string) => {
        setVisits(prev => {
            const currentEntry = prev[name] || { date: '', notes: '' };
            return { ...prev, [name]: { ...currentEntry, [field]: value } };
        });
    };

    return {
        groups, selectedGroupId, setSelectedGroupId, createGroup,
        members, masterPublishers, addMember, deleteMember,
        reports, visits, currentMonth, setCurrentMonth,
        loading, statusMessage,
        updateLocalReport, removeLocalReport, updateLocalVisit, saveRow
    };
};

